--
-- PKG_RINF_CONTROLLO_V082  (Package Body) 
--
CREATE OR REPLACE PACKAGE BODY APPL_RINF_EVO."PKG_RINF_CONTROLLO_V082" As
-- 
-- V. 24/07/2023 
-- 
   id_file              UTL_FILE.FILE_TYPE;
   nome_file            Varchar2 (500);
   v_trans              Varchar2 (200);
   n_caricamento        Number;
   n_acquisizione       Number;
   data_caricamento     Date;
   data_scarico         Date;
   data_riferimento     Date;
   data_mdr_gis         Date;
   p_errlog             Number;
--
-- ------------------------------------------------------------------------------------------------   
--                          FUNCTION GetAP
--  Verifica se il parametro in esame è Applicabile (Y) o meno (N) 
-- ------------------------------------------------------------------------------------------------   
--
 Function GetAP (p_numero_parametro Varchar2, p_tipo_dominio Number, p_valore Varchar2)
--
  RETURN Varchar2    Is
  appl Varchar2(1000);
--
  BEGIN
       Select Decode(VALORE, 'NA', 'N', 'Y') Into appl 
--       Select VALORE into appl
         From Rinf_Anagrafiche_Evo.DOMINIO_PARAMETRO d,
              Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI p
        Where d.CODICE_PARAMETRO = p.CODICE_PARAMETRO 
          And CODICE_TIPO_DOMINIO = p_tipo_dominio 
          And p.NUMERO_PARAMETRO_MULTIPLO = p_numero_parametro 
          And d.CODIFICA_VALORE = p_valore;
--
--       Select Decode(appl, 'NA', 'N', 'Y') Into appl From  Dual;
--   
       Return  appl;
 -- 
 EXCEPTION 
    When NO_DATA_FOUND  Then 
	     appl := 'Y';
         Return  appl;
 END GetAP;
-- 
-- ------------------------------------------------------------------------------------------------   
--                           FUNCTION GetAPMultipla
-- Per le tabelle multiple, restituisce l'applicabilità alla tabella padre, nel caso l'applicabilità sia gestita come valore 'NA'
-- ------------------------------------------------------------------------------------------------   
--
 Function GetAPMultipla (p_nome_tabella Varchar2, p_caratteristica Varchar2, 
                         p_colonna_chiave Varchar2, p_Sede_Tecnica Varchar2)
   RETURN Varchar2  Is
      appl Number;
      sqlstringa Varchar2(3000);
      c empcur;
 BEGIN
--
    sqlstringa := 'Select count(*) From  Rinf_Staging_Evo.'||p_nome_tabella||' ';
    sqlstringa := sqlstringa||' Where '||p_colonna_chiave||' = '''||p_Sede_Tecnica||'''';
    sqlstringa := sqlstringa||' And CODICE_CARATTERISTICA  '||' = '''||  p_caratteristica||'''';
    sqlstringa := sqlstringa||' And VALORE_CARATTERISTICA = ''NA''';
 --  
    Open c For  sqlstringa;
    Fetch c Into appl;
    Close c;
 --  
    If appl = 0 Then  Return 'Y';
    Else              Return 'N';
    End If;
--
 EXCEPTION 
   When OTHERS Then
        Return  'Y';
--
 END GetAPMultipla;
-- ------------------------------------------------------------------------------------------------   
--                           FUNCTION GetAPMultipla_numdec
-- Per le tabelle multiple, restituisce l'applicabilità alla tabella padre, nel caso l'applicabilità sia gestita come valore 'NA'
-- ------------------------------------------------------------------------------------------------   
--
 Function GetAPMultipla_numdec (p_nome_tabella Varchar2, p_caratteristica Varchar2, 
                         p_colonna_chiave Varchar2, p_Sede_Tecnica Varchar2)
   RETURN Varchar2  Is
      appl Number;
      sqlstringa Varchar2(3000);
      c empcur;
 BEGIN
--
     sqlstringa := 'Select count(*) From  Rinf_Staging_Evo.'||p_nome_tabella||' ';
    sqlstringa := sqlstringa||' Where '||p_colonna_chiave||' = '''||p_Sede_Tecnica||'''';
    sqlstringa := sqlstringa||' And CODICE_CARATTERISTICA  '||' = '''||  p_caratteristica||''''; 
 --    sqlstringa := sqlstringa||' And (Trim(To_Number(VALORE_CARATTERISTICA, ''S9999.999'')) = +9999.999';
 --    sqlstringa := sqlstringa||'  Or  Trim(To_Number(VALORE_CARATTERISTICA, ''S9999.999'')) = -9999.999)';
    sqlstringa := sqlstringa||'  And Trim(To_Number(VALORE_CARATTERISTICA, ''9999.999'')) = 9999.999';

 --  
    Open c For  sqlstringa;
    Fetch c Into appl;
    Close c;
 --  
    If appl = 0 Then  Return 'Y';
    Else              Return 'N';
    End If;
--
 EXCEPTION 
   When OTHERS Then
        Return  'Y';
--
 END GetAPMultipla_numdec;
--
-- ------------------------------------------------------------------------------------------------   
--                         FUNCTION GetPARValue
-- ------------------------------------------------------------------------------------------------   
--
 Function GetPARValue (p_numero_parametro Varchar2, p_tipo_dominio Number, p_valore Varchar2)
    RETURN Varchar2  Is
       p_valore_ret Varchar2(100);
 BEGIN
       Select valore into p_valore_ret
        From  Rinf_Anagrafiche_Evo.DOMINIO_PARAMETRO d,
              Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI p
       Where  d.CODICE_PARAMETRO = p.CODICE_PARAMETRO 
		  And CODICE_TIPO_DOMINIO = p_tipo_dominio 
		  And p.NUMERO_PARAMETRO_MULTIPLO = p_numero_parametro   --numero_parametro è stato sostituito con numero_parametro_multiplo perchè non prendeva i parametri 1.2.2.0.3.3.A e 1.2.2.0.3.3.B
          And d.CODIFICA_VALORE = p_valore;
--	   
       If p_valore_ret = 'NA' Then 
              p_valore_ret := Null;
       Else 
	          p_valore_ret := p_valore;
       End If;
--
       Return p_valore_ret;
--
 EXCEPTION 
   When OTHERS Then
        Return p_valore;
 END GetPARValue;

--
-- ------------------------------------------------------------------------------------------------   
--                      FUNCTION GetValue_InteraRete
-- ------------------------------------------------------------------------------------------------   
-- 
 Function GetValue_InteraRete (p_numero_parametro Varchar2)
    RETURN Varchar2    Is
  appl Varchar2(1000);
--
  BEGIN
       Select CODIFICA_VALORE Into appl 
         From Rinf_Anagrafiche_Evo.DOMINIO_PARAMETRO d,
              Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI p
        Where d.CODICE_PARAMETRO = p.CODICE_PARAMETRO 
          And p.NUMERO_PARAMETRO_MULTIPLO = p_numero_parametro;
--		  And d.VALORE = d.CODIFICA_VALORE;

       Return  appl;
 -- 
 EXCEPTION 
    When NO_DATA_FOUND  Then 
	     appl := Null;
         Return  appl;
 END GetValue_InteraRete;
--
-- ------------------------------------------------------------------------------------------------   
--                      FUNCTION GetDirezioneMarcia
-- ------------------------------------------------------------------------------------------------   
--
 Function GetDirezioneMarcia (p_Sede_Tecnica Varchar2, p_tipo_binario Varchar2)
   Return Varchar2 Is
     s_tipo_tratta Varchar2(30);
     p_valore_ret Varchar2(1);
     n_binari Number;
--
  BEGIN
    Select SOL_1_1_0_0_0_6 into s_tipo_tratta 
      From Rinf_Lavorazione_Evo.SEZIONI_LINEA
     Where SEDE_TECNICA = Substr(p_Sede_Tecnica, 1, 6);

-- Se una tratta è di tipo Link (Collegamento)
      If s_tipo_tratta = 'L' Then
          Select count(*) into n_binari
            From Rinf_Staging_Evo.CLASSE_R16000_TR
           Where SEDE_TECNICA = Substr(p_Sede_Tecnica, 1, 6);
--		  
          If n_binari = 1 Then
              p_valore_ret := 'B';
          Else
             Select
               Case When Mod(Substr(p_Sede_Tecnica, 13), 2) > 0 Then 'N'
                    Else 'O'
               End Case
                  into p_valore_ret
               From dual;
          End If;
      Else
      --13/09/2016 Modificato In seguito alla mail di Galli con l'aggiunta di Blocco Radio tra i banalizzati
         Select
         Case When(Instr(Upper(A.DESCRIZIONE),'BANALIZZA') > 0  Or Instr(Upper(A.DESCRIZIONE),'BLOCCO RADIO') > 0) Then 'B'
              When Instr(Upper(A.DESCRIZIONE),'BANALIZZA') = 0 And Instr(Upper(A.DESCRIZIONE),'BLOCCO RADIO') = 0 And p_tipo_binario = 'U' Then 'B'
              When Instr(Upper(A.DESCRIZIONE),'BANALIZZA') = 0 And Instr(Upper(A.DESCRIZIONE),'BLOCCO RADIO') = 0 And p_tipo_binario = 'D' Then 'N'
              When Instr(Upper(A.DESCRIZIONE),'BANALIZZA') = 0 And Instr(Upper(A.DESCRIZIONE),'BLOCCO RADIO') = 0 And p_tipo_binario = 'P' Then 'O'
         End Case
            Into p_valore_ret
         From 
             (Select Max(CODICE_TIPO_BLOCCO) CODICE_TIPO_BLOCCO 
			        From Rinf_Anagrafiche_Evo.TRATTE_PIC
                   Where SEDE_TECNICA = Substr(p_Sede_Tecnica, 1, 6)) p,
              Rinf_Anagrafiche_Evo.ANAG_TIPO_BLOCCO a
         Where p.CODICE_TIPO_BLOCCO = a.CODICE_TIPO 
		   And a.DATA_SCADENZA Is Null;
      End If;
--	  
    Return p_valore_ret;
 --
 EXCEPTION
      When OTHERS Then
      Return to_char(SQLCODE);
--	  
 END GetDirezioneMarcia;
--
-- ------------------------------------------------------------------------------------------------   
--                              FUNCTION GetTipoLocalita 
-- ------------------------------------------------------------------------------------------------   
--
 Function GetTipoLocalita (p_Sede_Tecnica Varchar2)
--
  Return Varchar2 Is
--
 TYPE tipo_loca_t IS RECORD
 (CODICE_TIPO       Rinf_Anagrafiche_Evo.LOCALITA_ROMAN.TIPO_LOCALITA%Type,
  F_MERCI           Rinf_Anagrafiche_Evo.LOCALITA_PIC.FLAG_SERVIZIO_MERCI%Type,
  F_VIAGGIATORI     Rinf_Anagrafiche_Evo.LOCALITA_PIC.FLAG_SERVIZIO_VIAGGIATORI%Type,
  METALLO           Rinf_Anagrafiche_Evo.LOCALITA_PIC.CASSIFICAZIONE_IAP%Type,
  SOTTOTIPOLOGIA    Rinf_Anagrafiche_Evo.LOCALITA_PIC.TIPO_PUNTOORARIO%Type,
  S_DEFINIZIONE     Rinf_Staging_Evo.CLASSE_R03000.DEFINIZIONE%Type          );
  a_tipo_loca tipo_loca_t;
--
  p_valore_ret Varchar2(200);
 BEGIN
--
-- 19/01/2016 aggiunta selezione data scadenza massima per gestire la molteplicità di record.
-- Ad esempio, nel caso di un record con scadenza sysdate ed uno con scadenza Nulla,
-- deve essere preso in considerazione quello con scadenza Nulla. 
-- Nel caso di due record con data scadenza valorizzata, viene considerato quello con data maggiore

 Select Distinct r.TIPO_LOCALITA,
                 p.FLAG_SERVIZIO_MERCI,
                 p.FLAG_SERVIZIO_VIAGGIATORI,
                 p.CASSIFICAZIONE_IAP,
                 P.TIPO_PUNTOORARIO,
                 Upper(s.DEFINIZIONE) DEFINIZIONE
            Into a_tipo_loca
            From Rinf_Anagrafiche_Evo.LOCALITA_PIC p,
                 Rinf_Anagrafiche_Evo.LOCALITA_ROMAN r,
                 Rinf_Staging_Evo.CLASSE_R03000 s,
              (  Select CODICE_LOCALITA_PIC,
                        Max(Nvl(DATA_SCADENZA, To_Date('01019999', 'DDMMYYYY'))) DATA_VAL_ROMAN
                  From Rinf_Anagrafiche_Evo.LOCALITA_ROMAN
                 Group By CODICE_LOCALITA_PIC
			   ) dr,
              (  Select COD_LOCALITA_IN_RETE,
                        Max(Nvl(DATA_SCADENZA, To_Date('01019999', 'DDMMYYYY')))  DATA_VAL_PIC
                   From Rinf_Anagrafiche_Evo.LOCALITA_PIC
                  Group By COD_LOCALITA_IN_RETE
			   ) dp
           Where p.COD_LOCALITA_IN_RETE = p_Sede_Tecnica
             And p.COD_LOCALITA_IN_RETE = s.SEDE_TECNICA
             And r.CODICE_LOCALITA_PIC = P.CODICE_LOCALITA_PIC
             And r.CODICE_LOCALITA_PIC = dr.CODICE_LOCALITA_PIC
             And p.COD_LOCALITA_IN_RETE = dp.COD_LOCALITA_IN_RETE
             And Nvl (r.DATA_SCADENZA, To_Date('01019999', 'DDMMYYYY')) = dr.DATA_VAL_ROMAN
             And Nvl (p.DATA_SCADENZA, To_Date('01019999', 'DDMMYYYY')) = dp.DATA_VAL_PIC;
-- 
    If a_tipo_loca.s_definizione In ('BICOCCA', 'CASTELGUELFO', 'LECCO MAGGIANICO') Then
         p_valore_ret := 'freight terminal';
    Else
--
--Capotronco 1
        Case When a_tipo_loca.CODICE_TIPO = 1 And Nvl(a_tipo_loca.F_MERCI, 0) = 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) <> 1
             Then p_valore_ret := 'freight terminal';
--			
             When a_tipo_loca.CODICE_TIPO = 1 And Nvl(a_tipo_loca.F_MERCI, 0) = 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') ='C' Or Nvl(a_tipo_loca.METALLO,'H') = 'D')
             Then  p_valore_ret := 'small station';
--			
             When a_tipo_loca.CODICE_TIPO = 1 And Nvl(a_tipo_loca.F_MERCI, 0) <> 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'C' Or Nvl(a_tipo_loca.METALLO, 'H') = 'D')
             Then  p_valore_ret := 'passenger terminal';
--			
             When a_tipo_loca.CODICE_TIPO = 1 And Nvl(a_tipo_loca.F_MERCI,0) = 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'A' Or Nvl(a_tipo_loca.METALLO, 'H') = 'B' Or Nvl(a_tipo_loca.METALLO, 'H') = 'C')
             Then  p_valore_ret := 'station';
--			
             When a_tipo_loca.CODICE_TIPO = 1 And Nvl(a_tipo_loca.F_MERCI,0) <> 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'A' Or Nvl(a_tipo_loca.METALLO, 'H') = 'B')
             Then  p_valore_ret := 'station';
--			
--Capotronco DU 2
             When a_tipo_loca.CODICE_TIPO = 2
             Then p_valore_ret := 'small station';
--			
--Stazione di diramazione 3
             When a_tipo_loca.CODICE_TIPO = 3 And Nvl(a_tipo_loca.F_MERCI, 0) = 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) <> 1
             Then p_valore_ret := 'freight terminal';
--			
             When a_tipo_loca.CODICE_TIPO = 3 And Nvl(a_tipo_loca.F_MERCI, 0) = 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'C' Or Nvl(a_tipo_loca.METALLO, 'H') = 'D')
             Then  p_valore_ret := 'small station';
--			
             When a_tipo_loca.CODICE_TIPO = 3 And Nvl(a_tipo_loca.F_MERCI, 0) <> 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'C' Or Nvl(a_tipo_loca.METALLO, 'H') = 'D')
             Then  p_valore_ret := 'passenger terminal';
--
             When a_tipo_loca.CODICE_TIPO = 3 And Nvl(a_tipo_loca.F_MERCI, 0) = 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'A' Or Nvl(a_tipo_loca.METALLO, 'H') = 'B' Or Nvl(a_tipo_loca.METALLO, 'H') = 'C')
             Then  p_valore_ret := 'station';
--
             When a_tipo_loca.CODICE_TIPO = 3 And Nvl(a_tipo_loca.F_MERCI, 0) <> 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'A' Or Nvl(a_tipo_loca.METALLO, 'H') = 'B')
             Then  p_valore_ret := 'station';
--
             When a_tipo_loca.CODICE_TIPO = 3 And Nvl(a_tipo_loca.F_MERCI, 0) <> 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) <> 1
             Then  p_valore_ret := 'junction';
--
--DIR MOV 4
             When a_tipo_loca.CODICE_TIPO = 4 And Nvl(a_tipo_loca.F_MERCI, 0) = 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) <> 1
             Then p_valore_ret := 'freight terminal';
--
             When a_tipo_loca.CODICE_TIPO = 4 And Nvl(a_tipo_loca.F_MERCI, 0) = 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'C' Or Nvl(a_tipo_loca.METALLO, 'H') = 'D')
             Then  p_valore_ret := 'small station';
--
             When a_tipo_loca.CODICE_TIPO = 4 And Nvl(a_tipo_loca.F_MERCI, 0) <> 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'C' Or Nvl(a_tipo_loca.METALLO, 'H') = 'D')
             Then  p_valore_ret := 'passenger terminal';
--
             When a_tipo_loca.CODICE_TIPO = 4 And Nvl(a_tipo_loca.F_MERCI, 0) = 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'A' Or Nvl(a_tipo_loca.METALLO, 'H') = 'B' Or Nvl(a_tipo_loca.METALLO, 'H') = 'C')
             Then  p_valore_ret := 'station';
--
             When a_tipo_loca.CODICE_TIPO = 4 And Nvl(a_tipo_loca.F_MERCI, 0) <> 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) = 1 And
                    (NVL(a_tipo_loca.METALLO, 'H') = 'A' Or Nvl(a_tipo_loca.METALLO, 'H') = 'B')
             Then  p_valore_ret := 'station';
--
             When a_tipo_loca.CODICE_TIPO = 4 And Nvl(a_tipo_loca.F_MERCI, 0) <> 1 And Nvl(a_tipo_loca.F_VIAGGIATORI, 0) <> 1
             Then  p_valore_ret := 'junction';
--
-- Dir UN 5
             When a_tipo_loca.CODICE_TIPO = 5  Then p_valore_ret := 'small station';
--
--Fermate NO INCR. 7
             When a_tipo_loca.CODICE_TIPO = 7  Then p_valore_ret := 'passenger stop';
--
--Fermate DEV. IMM. 8
             When a_tipo_loca.CODICE_TIPO = 8  Then p_valore_ret := 'passenger stop';
--
--località servizio 9
             When a_tipo_loca.CODICE_TIPO = 9  Then p_valore_ret := 'junction';
--
--Bivio 10
             When a_tipo_loca.CODICE_TIPO = 10 And  a_tipo_loca.sottotipologia =  4 Then p_valore_ret := 'switch';
--
             When a_tipo_loca.CODICE_TIPO = 10 And  a_tipo_loca.sottotipologia <> 4 Then p_valore_ret := 'junction' ;

             Else p_valore_ret := 'station';

         End Case;
    End If;
    Return p_valore_ret;
--
 EXCEPTION
     When OTHERS Then
           Return Null;
 END GetTipoLocalita;
--
-- ------------------------------------------------------------------------------------------------   
--                          FUNCTION GetLatLonFromKM
-- ------------------------------------------------------------------------------------------------   
--
 Function GetLatLonFromKM (p_sol Varchar2, p_km Number, p_dato Number)
    RETURN Number  Is
      n_lat   Number;
      n_lon   Number;
 BEGIN
--  Se p_dato=1 restituisco la LATITUDINE
--  Se p_dato=2 restituisco la LONGITUDINE
--  Se p_dato=3 restituisco il FLAG_CALCOLATO

   Select p.x, p.y  INTO n_lon, n_lat
     From Rinf_Gis_Evo.TRAT_RETE t,
          TABLE (
             SDO_UTIL.GETVERTICES (
                SDO_LRS.LOCATE_PT  (
                   SDO_LRS.CONVERT_TO_LRS_GEOM (t.GEOMETRY, TR_SAPPROGIN, TR_SAPPROGOUT),
                                p_km )
								  )
				) p
    Where  OR_ID = p_sol
      And VERSIONE_MDR = (Select Max(VERSIONE_MDR) From Rinf_Gis_Evo.ANAG_MDR);
--
   Case
      When p_dato = 1 Then RETURN n_lat;
      When p_dato = 2 Then RETURN n_lon;
      When p_dato = 3 Then RETURN 1;
   End Case;
--
   EXCEPTION
       When OTHERS Then
        Case When p_dato = 1 Then RETURN  Null;
             When p_dato = 2 Then RETURN  Null;
             When p_dato = 3 Then RETURN  0;
       End Case;
--	   
   END GetLatLonFromKM;
