--
--                                  PROCEDURE SetNewLoadingID
-- corretta il 02/02/2023 per la gestione del codice_caricamento
-- ------------------------------------------------------------------------------------------------   
--  


     Procedure SetNewLoadingID (n_caricamento Out Number, p_error Out Number)     Is
      n_righe   Number;
	  n_record  Number;
--   

/***
   BEGIN
      p_error := 0;
--
      Select Count(*) Into n_righe 
	    From Rinf_Staging_Evo.ANAG_CARICAMENTI;
--
--      dbms_output.put_line ('n_righe: '||n_righe);
 -- n_righe = 0 se si tratta del primo caricamento
      If n_righe = 0 Then
         n_caricamento := 1;
--		
         Insert Into Rinf_Staging_Evo.ANAG_CARICAMENTI 
		         (CODICE_CARICAMENTO, DATA_CARICAMENTO, DATA_ACQUISIZIONE)
          Values (1, Sysdate, Sysdate);
--	     dbms_output.put_line ('Inserimento in ANAG_CARICAMENTI: '|| n_caricamento);
--			  
      Else -- (n_righe > 0)

              Select Max(CODICE_CARICAMENTO) +1
                Into n_caricamento
                From Rinf_Staging_Evo.ANAG_CARICAMENTI;
--
              n_caricamento := Nvl(n_caricamento, 1);
--
              Insert Into Rinf_Staging_Evo.ANAG_CARICAMENTI (CODICE_CARICAMENTO, DATA_CARICAMENTO, DATA_ACQUISIZIONE)
                   Values (n_caricamento, Sysdate, Sysdate);


--           Else

              n_caricamento := -1;
              p_error := -1;
              dbms_output.put_line ('Errore nella select Rinf_Staging_Evo.ANAG_CARICAMENTI - CODICE_ESITO = Null: '||n_record);

              Select Max(CODICE_CARICAMENTO) 
                    Into n_caricamento
               From Rinf_Staging_Evo.ANAG_CARICAMENTI;
           End If;


--
--      dbms_output.put_line ('n_caricamento: '||n_record);
--      dbms_output.put_line ('p_error: '||p_error);

      End If;
***/
   BEGIN
        p_error := 0;
        Select Max(CODICE_CARICAMENTO) +1 Into n_caricamento 
	      From Rinf_Staging_Evo.ANAG_CARICAMENTI;
--
--      dbms_output.put_line ('n_righe: '||n_righe);
--
         Insert Into Rinf_Staging_Evo.ANAG_CARICAMENTI 
		         (CODICE_CARICAMENTO, DATA_CARICAMENTO)
          Values (n_caricamento, Sysdate);
--	     dbms_output.put_line ('Inserimento in ANAG_CARICAMENTI: '|| n_caricamento);
--			  
--	
   EXCEPTION
      When OTHERS  Then
           p_error := SQLCODE;
           Dbms_Output.Put_Line ('SetNewLoadingID - Errore: ' || Substr(SQLERRM, 1, 300));
   END SetNewLoadingID;
