-- ------------------------------------------------------------------------------------------------   
--                                  PROCEDURE SetLoadingResult
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetLoadingResult (n_caricamento Number, n_esito Number, 
                               s_data_scarico Varchar2, p_error Out Number )    Is
   BEGIN
      p_error:=0;
--	  
      Update Rinf_Staging_Evo.ANAG_CARICAMENTI
         Set CODICE_ESITO = n_esito,
--> correzione del 26/01/2023
             DATA_ACQUISIZIONE = Sysdate,
-->
             DATA_SCARICO = To_Date(s_data_scarico, 'DD/MM/YYYY')
       Where CODICE_CARICAMENTO = n_caricamento;
--	   
  EXCEPTION
       When OTHERS Then 
	        p_error := SQLCODE;
   END SetLoadingResult;
