--                                   PROCEDURE SetBadLogOfLoading
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetBadLogOfLoading (n_caricamento Number, p_file In RAW, p_error Out Number)    Is
   BEGIN
      p_error := 0;
      PKG_RINF_SECUREFILE_V082.WriteBadAcquisitionLog (n_caricamento, p_file);
   EXCEPTION
      When OTHERS  Then
         Dbms_Output.Put_Line ( 'SetBadLogOfLoading - Severe error! ' || SQLCODE || ' - ' || SQLERRM);
         p_error:= SQLCODE;
   END SetBadLogOfLoading;
