  Procedure GetAquisitionList (p_cursor Out empcur)     Is
   BEGIN
      Open p_cursor For
         Select CODICE_ACQUISIZIONE,
                DATA_ACQUISIZIONE,
                DESCRIZIONE_DSS,
                CODICE_ESITO,
                ESITO,
                STEP
           From V_ACQUISIZIONE_DATI_V082
         Union
         Select CODICE_CARICAMENTO,
                DATA_CARICAMENTO,
                Null,
                CODICE_ESITO,
                ESITO,
                STEP
           From V_CARICAMENTO_DATI
          Where CODICE_ESITO = 0
       Order by DATA_ACQUISIZIONE Desc, step Desc;
--		 
   END GetAquisitionList;
