-- ------------------------------------------------------------------------------------------------   
--                             PROCEDURE GetLogOfAcquisition
-- ------------------------------------------------------------------------------------------------   
--
   Procedure GetLogOfAcquisition (p_codice_acquisizione   In     Number,
                                  p_step                  In     Number,
                                  p_cursor                Out    empcur )    Is
      n_Step Number;
   BEGIN
--
     If p_step = -1 Then
          Select count(*) into n_Step 
	   	    From V_ACQUISIZIONE_DATI_V082 
	       Where CODICE_ACQUISIZIONE = p_codice_acquisizione;
--		
           If n_Step = 0 Then
                n_Step := 1;
           Else
                n_Step := 2;
           End If;
     Else
           n_Step := p_Step;
     End If;
--
     Case When n_Step = 2 Then
           Open p_cursor For
            Select CODICE_ACQUISIZIONE,
                   DATA_ACQUISIZIONE,
                   DESCRIZIONE_DSS,
                   CODICE_ESITO,
                   ESITO,
                   ESTENSIONE_FILE,
                   FILE_LOG
              From V_ACQUISIZIONE_DATI_SF_V082
             Where CODICE_ACQUISIZIONE = p_codice_acquisizione ;
          When n_Step = 1 Then
           Open p_cursor For
            Select CODICE_CARICAMENTO CODICE_ACQUISIZIONE,
                   DATA_CARICAMENTO DATA_ACQUISIZIONE,
                   Null DESCRIZIONE_DSS,
                   CODICE_ESITO,
                   ESITO,
                   ESTENSIONE_FILE,
                   FILE_LOG
              From V_CARICAMENTO_DATI_SF_V082
             Where CODICE_CARICAMENTO = p_codice_acquisizione;
          Else
           Open p_cursor For
            Select f.CODICE_ACQUISIZIONE,
                   a.DATA_ACQUISIZIONE,
                   'Datawarehouse' DESCRIZIONE_DSS,
                   1 CODICE_ESITO,
                   'Positivo' ESITO,
                   'log' ESTENSIONE_FILE,
                   DOCUMENT FILE_LOG
            From  Docs_Rinf_Evo.ACQUISIZIONE_DATI_SF f,
                  Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI a
            Where a.CODICE_ACQUISIZIONE = f.CODICE_ACQUISIZIONE 
             And  f.CODICE_ACQUISIZIONE = p_codice_acquisizione
             And  CODICE_LOG = p_step;
      End Case;
--	  
   END GetLogOfAcquisition;
--
