--            PROCEDURE GetAcquisitionDetDTPOP
-- ------------------------------------------------------------------------------------------------   
--
   Procedure GetAcquisitionDetDTPOP (p_codice_acquisizione   In     Number,
                                     p_dtp                   In     Varchar2,
                                     p_cursor                Out    empcur )    Is
   BEGIN
      Open p_cursor For
         Select CODICE_ACQUISIZIONE,
                CODICE_DTP,
                DTP,
                CODICE_SOL_PO,
                DESCRIZIONE,
                1 ESITO
           From V_DETTAGLIO_OP_ACCETTATE_V082
          Where CODICE_ACQUISIZIONE = p_codice_acquisizione
            And CODICE_DTP = p_dtp
         Union
         Select CODICE_ACQUISIZIONE,
                CODICE_DTP,
                DTP,
                CODICE_SOL_PO,
                DESCRIZIONE,
                0 ESITO
           From V_DETTAGLIO_OP_SCARTATE_V082
          Where CODICE_ACQUISIZIONE = p_codice_acquisizione
            And CODICE_DTP = p_dtp;
--				
   END GetAcquisitionDetDTPOP;
