-- ------------------------------------------------------------------------------------------------   
--                                   PROCEDURE SetOPClear
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetOPClear (p_error Out Number)     Is
   BEGIN
      p_error := 0;
--
      Delete From  Rinf_Lavorazione_Evo.PAR_1_2_3_2_DOC_norme;                  -- nuova Re.777/2019
--
      Delete From  Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_SD_PO;
--
      Delete From  Rinf_Lavorazione_Evo.REL_GALLERIE_RACCORDO_PO;
--
      Delete From  Rinf_Lavorazione_Evo.GALLERIE_RACCORDO_PO;
--
      Delete From  Rinf_Lavorazione_Evo.PAR_1_2_1_0_2_1_CAT_TEN_PO;          --multipla 082 agosto da Galli
--
      Delete From  Rinf_Lavorazione_Evo.PAR_1_2_1_0_2_2_CAT_LINEA;           --multipla 082 agosto
--
      Delete From  Rinf_Lavorazione_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL;          --multipla ma errata sull'AG
--
      Delete From  Rinf_Lavorazione_Evo.PAR_1_2_2_0_0_3_CAT_TEN_SD;          --multipla ma errata sull'AG
--
      Delete From  Rinf_Lavorazione_Evo.DICHIARAZIONI_RACCORDO_PO;
--
      Delete From  Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO;
--
      -- Delete From  Rinf_Lavorazione_Evo.DICHIARAZIONI_MARCIAP_BIN_PO;  eliminate In 0.82
--
      Delete From  Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO;
--
      Delete From  Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_BIN_PO;
--
      Delete From  Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO;
--
      Delete From  Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO;
--
      Delete From  Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_PO;
--
      Delete From  Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA;
--
      Delete From  Rinf_Lavorazione_Evo.BINARI_CORSA_PO;
--
      Delete From  Rinf_Lavorazione_Evo.PAR_1_2_0_0_0_3_TAF_TAP;
--
      Delete From  Rinf_Lavorazione_Evo.PUNTI_OPERATIVI;
--
      COMMIT;
--	  
   EXCEPTION
      When OTHERS   Then
           p_error := SQLCODE;
           Dbms_Output.Put_Line ('SetOPClear - Errore: ' || Substr(SQLERRM, 1, 300));
  END SetOPClear;

