-- ------------------------------------------------------------------------------------------------   
--                                 PROCEDURE NuoviOP
-- ------------------------------------------------------------------------------------------------   
--
 Procedure NuoviOP (p_error Out Number)     Is
      TYPE dtp_ogg_rt IS RECORD
      (  ID_DTP     Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
         C_SOL_OP   Varchar2 (300),
         D_SOL_OP   Varchar2 (500)     );
      TYPE dtp_ogg_t IS TABLE OF dtp_ogg_rt;
      l_dtp_ogg   dtp_ogg_t;
--	  
   Begin
       p_error := 0;
--
 Select CODICE_DTP      id_dtp, 
	    SEDE_TECNICA    c_sol_op, 
		DEFINIZIONE     d_sol_op
   Bulk Collect Into l_dtp_ogg
   From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI  
  Where SEDE_TECNICA in 
(Select SEDE_TECNICA   
   From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
     Minus
 Select SEDE_TECNICA 
   From Rinf_Pubblicati_Evo.PUNTI_OPERATIVI 
  Where CODICE_VERSIONE = (Select Max(CODICE_VERSIONE) From Rinf_Pubblicati_Evo.VERSIONE_RINF))
  order by CODICE_DTP, SEDE_TECNICA;

--
     Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '   ');
--
      For i In 1 .. l_dtp_ogg.COUNT  Loop 
--	  
        Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Punti Operativi presenti nella fornitura e non ancora nel Rinf: '
--->       Dbms_Output.Put_Line('Punti Operativi presenti nella fornitura e non ancora nel Rinf: '
            || l_dtp_ogg (i).ID_DTP   || '       '
            || l_dtp_ogg (i).C_SOL_OP || '       '
            || l_dtp_ogg (i).D_SOL_OP   );

      End Loop ;
--	  
    Exception
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('NuoviOP - Errore:  ' || Substr(SQLERRM, 1, 300));
 END NuoviOP;  
