--                          PROCEDURE SetAcquisitionOP_PIC
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionOP_PIC (p_error Out Number)     Is
   BEGIN
      p_error := 0;

      Update Rinf_Lavorazione_Evo.PUNTI_OPERATIVI l
         Set (CODICE_MIR) =
                (Select Distinct CODICE_LOCALITA_MIR
                   From Rinf_Anagrafiche_Evo.LOCALITA_PIC p
                  Where p.COD_LOCALITA_IN_RETE = l.SEDE_TECNICA);
   EXCEPTION
      When OTHERS Then
           p_error := SQLCODE;
           Dbms_Output.Put_Line ('PROCEDURE SetAcquisitionOP_PIC - Errore: ' || Substr(SQLERRM, 1, 300));
   END SetAcquisitionOP_PIC;
--   
-- ------------------------------------------------------------------------------------------------   
--                       PROCEDURE SetOPLogConfine
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetOPLogConfine(p_error Out Number)   Is
      TYPE dtp_ogg_rt IS RECORD
      (  ID_DTP     Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
         C_SOL_OP   Rinf_Staging_Evo.CLASSE_R03000.SEDE_TECNICA%Type,
         D_SOL_OP   Rinf_Staging_Evo.CLASSE_R03000.DEFINIZIONE%Type  );
      TYPE dtp_ogg_t IS TABLE OF dtp_ogg_rt;
      l_dtp_ogg   dtp_ogg_t;
--
  BEGIN
-- 15/11/2017 Inserito il default NO se il campo è Nullo
-- Questa procedura scrive nel log eventuali PO che hanno il tipo località di confine a Null
      p_error := 0;
--	  
     Select s.CODICE_DTP      id_dtp, 
	        s.SEDE_TECNICA    c_sol_op,
			s.DEFINIZIONE     d_sol_op
       Bulk Collect Into      l_dtp_ogg
       From Rinf_Staging_Evo.CLASSE_R03000 s
      Where TIPO_LOCALITA_CONFINE Is Null
      Order by 1,2;
--
      If l_dtp_ogg.COUNT <> 0 Then
           Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '   ');
           Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '--------------------------------> Elenco Punti Operativi con caratteristica Tipo località di Confine non valorizzata   ');
--> loop
           For i In 1 .. l_dtp_ogg.COUNT    Loop 
                   Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                              'Punto Operativo:  ' || l_dtp_ogg(i).ID_DTP || '       ' || l_dtp_ogg(i).C_SOL_OP || '       ' || l_dtp_ogg(i).D_SOL_OP);
           End Loop ;
--> end loop
           Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '   ');
      End If;
--
  EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetOPLogConfine - Errore:' || Substr(SQLERRM, 1, 300));
  END SetOPLogConfine;
--
-- ------------------------------------------------------------------------------------------------   
--                  PROCEDURE SetAcquisitionOP_PO
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionOP_PO (n_acquisizione Number, p_error Out Number)    Is
      i           Number;
      sqlstring   Varchar2 (5000);
--
      TYPE dtp_op_rt IS RECORD
      (  ID_DTP      Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
         ID_OP       Rinf_Staging_Evo.CLASSE_R03000.SEDE_TECNICA%Type,
         DESC_OP     Rinf_Staging_Evo.CLASSE_R03000.DEFINIZIONE%Type  );
      TYPE dtp_op_t  IS TABLE OF dtp_op_rt;
      l_dtp_op      dtp_op_t;
--
   BEGIN
      p_error := 0;
-- ATTENZIONE: se si cambiano le condizioni della Where, bisogna cambiare le corrispondenti nella procedura SetLogOfAcquisition(04/09/2015)
        Select CODICE_DTP, SEDE_TECNICA, DEFINIZIONE
          Bulk Collect Into l_dtp_op
          From Rinf_Staging_Evo.CLASSE_R03000
         Where STATO_SISTEMA = 'CREA' 
		   And STATO_UTENTE  = 'ESER IPIC' 
--  22/10/2015 Modifica apportata a seguito mail Schillaci-Loretoni
--  15/11/2017 Inserito il default NO se il campo è Nullo
	       And Nvl(TIPO_LOCALITA_CONFINE, 'NO') In ('NO','AL','AF')
           And CODICE_DTP <> 'DG00'
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,'--------------------------------> '|| 'Caricamento PUNTI OPERATIVI');
         Dbms_Output.Put_Line ('Caricamento PUNTI OPERATIVI');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,  'Totale PUNTI OPERATIVI da caricare:     '|| To_Char(l_dtp_op.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'  '               );
         Dbms_Output.Put_Line ( 'Totale PUNTI OPERATIVI da caricare: ' || To_Char(l_dtp_op.COUNT));
--
         Forall i In 1 .. l_dtp_op.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.PUNTI_OPERATIVI 
			       (  SEDE_TECNICA,
                      CODICE_MIR,
                      DEFINIZIONE,
                      STATO_SISTEMA,
                      STATO_UTENTE,
                      LOCALITA_CONTENITORE,
                      KM_INIZIO,
                      PO_1_2_0_0_0_2,
                      PO_1_2_0_0_0_3_AP,
                      PO_1_2_0_0_0_4,
                      PO_1_2_0_0_0_6,
                      LATITUDINE,
                      LONGITUDINE,
                      CODICE_LINEA_TECNICA,
                      CODICE_DTP,
                      CODICE_UT,
                      NUOVA_CLASSIFICAZIONE_STAZIONE,
                      TIPO_LOCALITA_CONFINE,
                      GRUPPO_AUTORIZZATIVO,
				      PO_1_2_0_0_0_4_1_AP,   ---> nuovo Reg.777/2019
     			      PO_1_2_0_0_0_4_1,      ---> nuovo Reg.777/2019
				      PO_1_2_3_1_AP,          ---> nuovo Reg.777/2019
				      PO_1_2_3_1,            ---> nuovo Reg.777/2019
				      PO_1_2_3_2_AP          ---> nuovo Reg.777/2019
                    )
               Select SEDE_TECNICA,
                      p.CODICE_LOCALITA_MIR,
                      DEFINIZIONE,
                      STATO_SISTEMA,
                      STATO_UTENTE,
                      LOCALITA_CONTENITORE,
                      Abs(KM_INIZIO),
                      Decode(p.CODICE_LOCALITA_MIR, Null, 'IT00000', 'IT' || Substr(p.CODICE_LOCALITA_MIR, 2) ) PO_1_2_0_0_0_2,
                      Decode(p.CODICE_LOCALITA_MIR, Null, 'NYA', 'Y') PO_1_2_0_0_0_3_AP,
                      GetTIPOLocalita(l_dtp_op(i).ID_OP)  PO_1_2_0_0_0_4,
                      --   Round (Abs(KM_INIZIO), 3) PO_1_2_0_0_0_6,        17/05/2016 eliminato il valore assoluto perchè la CUI ammette progressive negative
                      Round (KM_INIZIO, 3) PO_1_2_0_0_0_6,
                      g.LATITUDINE,
                      g.LONGITUDINE,
                      CODICE_LINEA_TECNICA,
                      CODICE_DTP,
                      CODICE_UT,
                      NUOVA_CLASSIFICAZIONE_STAZIONE,
                      TIPO_LOCALITA_CONFINE,
                      GRUPPO_AUTORIZZATIVO,
			          PKG_RINF_APPLICABILITA.GetAP_1_2_0_0_0_4_1 (PO_1_2_0_0_0_4_1) PO_1_2_0_0_0_4_1_AP,
	                  PO_1_2_0_0_0_4_1,                                       ---> nuovo
		              PKG_RINF_APPLICABILITA.GetAP_1_2_3_1(PO_1_2_3_1) PO_1_2_3_1_AP,     --[AP=Y]
   	                  PO_1_2_3_1,
		              PKG_RINF_APPLICABILITA.GetAP_1_2_3_2 (PO_1_2_3_1) PO_1_2_3_2_AP
--
                From  Rinf_Staging_Evo.CLASSE_R03000 l,
                      Rinf_Anagrafiche_Evo.LOCALITA_PIC p,
                     (Select OR_ID, b.y LATITUDINE, b.X LONGITUDINE
                        From Rinf_Gis_Evo.LOCA_RETE a,
                             Table(Sdo_Util.GETVERTICES(a.geometry)) b
                       Where VERSIONE_MDR = (Select max(VERSIONE_MDR) From  Rinf_Gis_Evo.ANAG_MDR)
					  ) g,                                                         --15/11/2017 Gestione Storicizzazione MDR
                     (Select COD_LOCALITA_IN_RETE,
                             Max (Nvl (DATA_SCADENZA, To_Date ('01019999', 'DDMMYYYY'))) DATA_VAL_PIC
                       From  Rinf_Anagrafiche_Evo.LOCALITA_PIC
                       Group By COD_LOCALITA_IN_RETE
					  ) dp
                 Where l.SEDE_TECNICA = g.OR_ID (+) 
				   And l.SEDE_TECNICA = P.COD_LOCALITA_IN_RETE (+) 
				   And Nvl(p.DATA_INIZIO_VALIDITA, To_Date('01011999','DDMMYYYY')) <= DATA_RIFERIMENTO 
				   And Nvl(p.DATA_FINE_VALIDITA, To_Date('01012999','DDMMYYYY')) >= DATA_RIFERIMENTO 
				   And p.COD_LOCALITA_IN_RETE = dp.COD_LOCALITA_IN_RETE 
				   And Nvl(p.DATA_SCADENZA, To_Date ('01019999', 'DDMMYYYY')) = dp.DATA_VAL_PIC 
				   And CODICE_DTP = l_dtp_op(i).ID_DTP
                   And SEDE_TECNICA = l_dtp_op(i).ID_OP;
-- Nella query sopra:
-- 19/01/2016 aggiunta selezione data scadenza massima per gestire la molteplicità di record,
-- ad esempio nel caso di un record con scadenza sysdate ed uno con scadenza Nulla,
-- deve essere preso In considerazione quello Nullo. Nel caso di due record con data scadenza valorizzata, viene considerato quello con data maggiore

--       SetAcquisitionOP_PIC (p_error); --23/07/2015 ridondante
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------');		
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori:     ' || SQL%BULK_EXCEPTIONS.COUNT);		   
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT Loop 
--> loop			   
                  Pkg_Rinf_Utility.SETLINEINTOFILE (  id_file, 
				        'DTP: '    || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: '    || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_op
                     || ' DEFINIZIONE OP: '|| l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_op
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: '|| l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' OP: ' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_op
                                      || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, NOME_SOL_PO,SEDE_TECNICA, CLASSE, CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ','''  || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_op || ''',';
                  sqlstring := sqlstring || ''''    || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_op;
                  sqlstring := sqlstring || ''',''' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_op    || ''',''R03000'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_PO - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;

--  15/11/2017 inserita la chiamata alla procedura che scrive nel log eventuali PO con tipo località di confine non valorizzato
      SetOPLogConfine(p_error);
--	  
   END SetAcquisitionOP_PO;
--   
-- ------------------------------------------------------------------------------------------------   
--                PROCEDURE SetAcquisitionOP_BorderPoint 
--                Località (Punti Operativi) di confine
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetAcquisitionOP_BorderPoint (n_acquisizione Number, p_error Out Number)    Is
      i           Number;
      sqlstring   Varchar2 (5000);
      Type dtp_op_rt Is Record
      (  ID_DTP        Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
         ID_OP         Rinf_Staging_Evo.CLASSE_R03000.SEDE_TECNICA%Type,
         DESC_OP       Rinf_Staging_Evo.CLASSE_R03000.DEFINIZIONE%Type,
         TIPOCONF_OP   Rinf_Staging_Evo.CLASSE_R03000.TIPO_LOCALITA_CONFINE%Type );
      TYPE dtp_op_t IS TABLE OF dtp_op_rt;
      l_dtp_op    dtp_op_t;
   BEGIN
      p_error := 0;
--
        Select CODICE_DTP, SEDE_TECNICA, DEFINIZIONE, TIPO_LOCALITA_CONFINE
              Bulk Collect Into l_dtp_op
          From 
           ( Select CODICE_DTP, l.SEDE_TECNICA, l.DEFINIZIONE, TIPO_LOCALITA_CONFINE
              From Rinf_Staging_Evo.CLASSE_R03000 l,
                   Rinf_Anagrafiche_Evo.LOCALITA_CONFINE c
              Where c.SEDE_TECNICA = l.SEDE_TECNICA 
--    22/10/2015 Modifica apportata a seguito mail Schillaci-Loretoni
--    15/11/2017 Inserito il default NO se il campo è Nullo
                 And STATO_SISTEMA = 'CREA'
                 And Upper(STATO_UTENTE) In ('ESER IPIC', 'CONC IPIC', 'MODI IPIC')
                 And Nvl(TIPO_LOCALITA_CONFINE, 'NO') = 'NA'                         -- confini nazionali
           Union
             Select CODICE_DTP, l.SEDE_TECNICA, l.DEFINIZIONE, TIPO_LOCALITA_CONFINE
              From  Rinf_Staging_Evo.CLASSE_R03000 l
--    22/10/2015 Modifica apportata a seguito mail Schillaci-Loretoni
              Where STATO_SISTEMA = 'CREA' 
                And Upper(STATO_UTENTE) In ('ESER IPIC', 'CONC IPIC', 'MODI IPIC')
                And Nvl(TIPO_LOCALITA_CONFINE, 'NO') = 'RE'                          -- confini regionali
           Union
             Select CODICE_DTP, l.SEDE_TECNICA, l.DEFINIZIONE, TIPO_LOCALITA_CONFINE
               From Rinf_Staging_Evo.CLASSE_R03000 l
--     22/10/2015 Modifica apportata a seguito mail Schillaci-Loretoni
               Where STATO_SISTEMA = 'CREA' 
                 And Upper(STATO_UTENTE) In ('CONC IPIC', 'MODI IPIC') 
                 And Nvl(TIPO_LOCALITA_CONFINE, 'NO') = 'AF'                        -- altri tipi di confine
            )
           Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento PUNTI OPERATIVI Border Point');
         Dbms_Output.Put_Line ('Caricamento PUNTI OPERATIVI');
--  
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale PUNTI OPERATIVI Border Point da caricare:     ' || To_Char(l_dtp_op.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,' '               );
         Dbms_Output.Put_Line ( 'Totale PUNTI OPERATIVI Border Point da caricare: ' || To_Char(l_dtp_op.COUNT));
--
         Forall i In 1 .. l_dtp_op.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.PUNTI_OPERATIVI 
			      (   SEDE_TECNICA,
                      CODICE_MIR,
                      DEFINIZIONE,
                      STATO_SISTEMA,
                      STATO_UTENTE,
                      LOCALITA_CONTENITORE,
                      KM_INIZIO,
                      PO_1_2_0_0_0_2,
                      PO_1_2_0_0_0_3_AP,
                      PO_1_2_0_0_0_4,
                      PO_1_2_0_0_0_6,
                      LATITUDINE,
                      LONGITUDINE,
                      CODICE_LINEA_TECNICA,
                      CODICE_DTP,
                      CODICE_UT,
                      NUOVA_CLASSIFICAZIONE_STAZIONE,
                      TIPO_LOCALITA_CONFINE,
                      GRUPPO_AUTORIZZATIVO,
  				      PO_1_2_0_0_0_4_1_AP,  ---> nuovo
   	         		  PO_1_2_0_0_0_4_1,   ---> nuovo
				      PO_1_2_3_1_AP,    ---> nuovo
     				  PO_1_2_3_1,    ---> nuovo
				      PO_1_2_3_2_AP  ---> nuovo
                        )
               Select l.SEDE_TECNICA,
                      P.CODICE_LOCALITA_MIR CODICE_LOCALITA_MIR,
                      l.DEFINIZIONE,
                      STATO_SISTEMA,
                      STATO_UTENTE,
                      LOCALITA_CONTENITORE,
                      Nvl( PO_1_2_0_0_0_6, Abs(KM_INIZIO)) KM_INIZIO,
                      Nvl(c.PO_1_2_0_0_0_2, Decode(p.CODICE_LOCALITA_MIR, Null,'IT00000','IT' || Substr (p.CODICE_LOCALITA_MIR, 2))) PO_1_2_0_0_0_2,
                      'Y' PO_1_2_0_0_0_3_AP,
                      Case When l_dtp_op (i).TIPOCONF_OP = 'NA' Then 'border point'
-- 16/11/2017 Inserita la nuova tipologia domestic border point  (mail Schillaci 16/11/2017 16:39)
                           When l_dtp_op (i).TIPOCONF_OP = 'RE' Then 'domestic border point'
                           Else GetTIPOLocalita(l_dtp_op (i).ID_OP)
                      End PO_1_2_0_0_0_4,
                      Nvl( PO_1_2_0_0_0_6, Round (Abs(KM_INIZIO), 3)) PO_1_2_0_0_0_6,
-- Modifica del 20/05/2020 per visualizzare le coordiante dei Border Point Nazionali
                      Case When l_dtp_op (i).tipoconf_op = 'NA' and c.LATITUDINE Is Not Null 
					       Then c.LATITUDINE    -- Round(c.LATITUDINE) ? verificare
						   Else g.LATITUDINE
                       End LATITUDINE,
--
                      Case When l_dtp_op (i).tipoconf_op = 'NA' and c.LONGITUDINE Is Not Null 
					       Then c.LONGITUDINE    -- Round(c.LONGITUDINE) ? verificare
						   Else g.LONGITUDINE
                       End LONGITUDINE,
--
--                      g.LATITUDINE,
--                      g.LONGITUDINE,                      
                      CODICE_LINEA_TECNICA,
                      CODICE_DTP,
                      CODICE_UT,
                      NUOVA_CLASSIFICAZIONE_STAZIONE,
                      TIPO_LOCALITA_CONFINE,
                      GRUPPO_AUTORIZZATIVO,
			          PKG_RINF_APPLICABILITA.GetAP_1_2_0_0_0_4_1 (PO_1_2_0_0_0_4_1) PO_1_2_0_0_0_4_1_AP,
--	                  Null PO_1_2_0_0_0_4_1_AP,                               ---> nuovo
	                  PO_1_2_0_0_0_4_1,                                       ---> nuovo
		              PKG_RINF_APPLICABILITA.GetAP_1_2_3_1(PO_1_2_3_1) PO_1_2_3_1_AP,     --[AP=Y]
                      PO_1_2_3_1,
		              PKG_RINF_APPLICABILITA.GetAP_1_2_3_2 (PO_1_2_3_1) PO_1_2_3_2_AP
                 From Rinf_Staging_Evo.CLASSE_R03000 l,
                      Rinf_Anagrafiche_Evo.LOCALITA_PIC p,
                      (Select OR_ID, b.Y LATITUDINE, b.X LONGITUDINE
                       From Rinf_Gis_Evo.LOCA_RETE a,
                            TABLE(SDO_UTIL.GETVERTICES(a.geometry)) b
                       Where  VERSIONE_MDR = (Select Max(VERSIONE_MDR) From  Rinf_Gis_Evo.ANAG_MDR)
					   ) g,
                      Rinf_Anagrafiche_Evo.LOCALITA_CONFINE c
                Where l.SEDE_TECNICA = g.OR_ID (+)
                  And l.SEDE_TECNICA = p.COD_LOCALITA_IN_RETE (+) 
                  And l.SEDE_TECNICA = c.SEDE_TECNICA (+) 
-- and p. data_scadenza is Null                                                                   
                  And l.CODICE_DTP = l_dtp_op (i).ID_DTP  
                  And l.SEDE_TECNICA = l_dtp_op (i).ID_OP;
--
         --SetAcquisitionOP_PIC (p_error);
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381    Then
               Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,'--------------------------------');
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori:     ' || SQL%BULK_EXCEPTIONS.COUNT);		   
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT   Loop 
--> loop			   
                    Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,
                        'DTP: ' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_op
                     || ' DEFINIZIONE OP: ' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_op
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));

                    Dbms_Output.Put_Line ( 'DTP: ' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_op
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--
                   sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, NOME_SOL_PO,SEDE_TECNICA, CLASSE, CODICE_ERRORE, CODICE_DTP)';
                   sqlstring := sqlstring || 'VALUES ( ';
                   sqlstring := sqlstring || n_acquisizione|| ',''' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_op  || ''',';
                   sqlstring := sqlstring || '''' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_op;
                   sqlstring := sqlstring || ''',''' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_op || ''',''R03000'', ';
                   sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                   sqlstring := sqlstring|| '''' || l_dtp_op (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
--			   
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_BorderPoint - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionOP_BorderPoint;
