-- ------------------------------------------------------------------------------------------------   
--                        PROCEDURE SetAcquisitionPO_TAF_TAP 
--                  PARAMETRO CODICE TAF/TAP DI PO - (PAR_1_2_0_0_0_3_TAF_TAP)
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionPO_TAF_TAP (n_acquisizione       Number,                   
                                       p_error          Out Number )     Is
      i             Number;
      sqlstring     Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_LOCALITA     Rinf_Lavorazione_Evo.PUNTI_OPERATIVI.SEDE_TECNICA%Type,
         ID_TAF_TAP      Rinf_Lavorazione_Evo.PAR_1_2_0_0_0_3_TAF_TAP.PO_1_2_0_0_0_3%Type,
         ID_DTP          Rinf_Lavorazione_Evo.PUNTI_OPERATIVI.CODICE_DTP%Type );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
   BEGIN
      p_error := 0;
--
      Select Distinct
            p.SEDE_TECNICA   id_localita,
            Decode (p.CODICE_MIR, Null, 'IT00000', 'IT' || Substr(p.CODICE_MIR, 2)) id_taf_tap,
            CODICE_DTP   id_dtp
       Bulk Collect Into l_op_track
       From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI p
      Where PO_1_2_0_0_0_3_AP = 'Y'
      Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento PARAMETRO CODICE TAF/TAP DI PO');
         Dbms_Output.Put_Line ( 'Caricamento PARAMETRO CODICE TAF/TAP DI PO');
-- 
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale VALORI PARAMETRO CODICE TAF/TAP DI PO da caricare: '|| To_Char(l_op_track.COUNT));
         Dbms_Output.Put_Line ('Totale PARAMETRO CODICE TAF/TAP DI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,' '               );
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
-- Questo è il codice corretto, al momento utilizziamo un codice di test per verificare il corretto funzionamento della molteplicità
            Insert Into Rinf_Lavorazione_Evo.PAR_1_2_0_0_0_3_TAF_TAP (
               SEDE_TECNICA,
               PO_1_2_0_0_0_3,
               KM_INIZIO,
               KM_FINE)
            Values (l_op_track(i).ID_LOCALITA, l_op_track(i).ID_TAF_TAP, 0, 0);

           --TEST
--           Insert Into Rinf_Lavorazione_Evo.PAR_1_2_0_0_0_3_TAF_TAP (
--               SEDE_TECNICA,
--               PO_1_2_0_0_0_3,
--               KM_INIZIO,
--               KM_FINE)
--           Select
--           SEDE_TECNICA,
--           l_op_track(i).id_taf_tap,
--           0,
--           0
--           From  Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
--           Where  SEDE_TECNICA=l_op_track(i).id_localita
--           Union
--           Select
--           SEDE_TECNICA,
--           'IT9'||Substr(l_op_track(i).id_taf_tap,4),
--           0,
--           0
--           From  Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
--           Where  SEDE_TECNICA=l_op_track(i).id_localita;

      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT Loop 
--> loop				  
                  Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' CODICE TAF/TAP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_taf_tap
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' CODICE TAF/TAP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_taf_tap
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',''R03000'', ';
                  sqlstring := sqlstring || '''ORA-'|| SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionPO_TAF_TAP - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionPO_TAF_TAP;
