-- ------------------------------------------------------------------------------------------------   
--                       PROCEDURE SetAcquisitionOP_SD_TUNNEL_EC
--                   Dichiarazioni Gallerie Dei Binari Secondari (Raccordi) dei Po
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionOP_SD_TUNNEL_EC (n_acquisizione       Number,
                                            p_error          Out Number )     Is
      i            Number;
      sqlstring    Varchar2 (30000);
      TYPE op_track_rt IS RECORD
       ( ID_LOCALITA   Rinf_Staging_Evo.CLASSE_R16100.SEDE_TECNICA%Type,
         ID_TUNNEL     Rinf_Staging_Evo.CLASSE_R25350_LO.PO_TR_TUNNEL_1_2_1_0_5_2%Type,
         ID_DTP        Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type      );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
   BEGIN
      p_error := 0;
--
        Select Distinct 
		       Null                          id_localita,
               l.PO_SD_TUNNEL_1_2_2_0_5_2    id_tunnel,
               Null                          id_dtp
           Bulk Collect Into l_op_track
          From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA b,
               Rinf_Lavorazione_Evo.GALLERIE_RACCORDO_PO l
         Where l.PO_SD_TUNNEL_1_2_2_0_5_2 = b.IDENTIFICATIVO_GALLERIA
           And CODICE_CARATTERISTICA In ('R25350_LO_0220', 'R25350_LO_0230','R25350_LO_0221', 'R25350_LO_0231')
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento DICHIARAZIONI GALLERIE DEI BINARI SECONDARI DEI PO');
         Dbms_Output.Put_Line ('Caricamento DICHIARAZIONI GALLERIE DEI BINARI SECONDARI DEI PO');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale DICHIARAZIONI GALLERIE DEI BINARI SECONDARI DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
         Dbms_Output.Put_Line ( 'Totale DICHIARAZIONI GALLERIE DEI BINARI SECONDARI DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_SD_PO 
	               ( PO_SD_TUNNEL_1_2_2_0_5_2,
                     TIPO_DICHIARAZIONE,
                     PO_SD_TUNNEL_1_2_2_0_5_3O4_AP,
                     PO_SD_TUNNEL_1_2_2_0_5_3O4,
                     KM_INIZIO,
                     KM_FINE,
                     LATITUDINE_INIZIO,
                     LONGITUDINE_INIZIO,
                     LATITUDINE_FINE,
                     LONGITUDINE_FINE,
                     FLAG_CALCOLATO  )	
              Select appl.IDENTIFICATIVO_GALLERIA,
                     'EC',
                     appl.VALORE_CARATTERISTICA,
                     Nvl(val.VALORE_CARATTERISTICA, ' '),
                     Nvl(KM_INIZIO, 0),
                     KM_FINE,
                     LATITUDINE_INIZIO,
                     LONGITUDINE_INIZIO,
                     LATITUDINE_FINE,
                     LONGITUDINE_FINE,
                     0 FLAG_CALCOLATO
                From (Select CODICE_CARATTERISTICA,
                             IDENTIFICATIVO_GALLERIA,
                             VALORE_CARATTERISTICA
                        From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA
                       Where CODICE_CARATTERISTICA In ('R25350_LO_0221')
					  ) appl,
                     (Select CODICE_CARATTERISTICA,
                             IDENTIFICATIVO_GALLERIA,
                             VALORE_CARATTERISTICA,
                             KM_INIZIO,
                             KM_FINE,
                             LATITUDINE_INIZIO,
                             LONGITUDINE_INIZIO,
                             LATITUDINE_FINE,
                             LONGITUDINE_FINE
                        From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA
                       Where CODICE_CARATTERISTICA In ('R25350_LO_0220')
					  ) val
                Where appl.IDENTIFICATIVO_GALLERIA = l_op_track(i).ID_TUNNEL
                  And appl.IDENTIFICATIVO_GALLERIA = val.IDENTIFICATIVO_GALLERIA(+)
           Union
              Select appl.IDENTIFICATIVO_GALLERIA,
                     'EI',
                     appl.VALORE_CARATTERISTICA,
                     Nvl(val.VALORE_CARATTERISTICA,' '),
                     Nvl(KM_INIZIO, 0),
                     KM_FINE,
                     LATITUDINE_INIZIO,
                     LONGITUDINE_INIZIO,
                     LATITUDINE_FINE,
                     LONGITUDINE_FINE,
                     0 FLAG_CALCOLATO
                From (
				      Select CODICE_CARATTERISTICA,
                             IDENTIFICATIVO_GALLERIA,
                             VALORE_CARATTERISTICA
                        From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA
                       Where CODICE_CARATTERISTICA In ('R25350_LO_0231')
					  ) appl,
                     (
					   Select CODICE_CARATTERISTICA,
                              IDENTIFICATIVO_GALLERIA,
                              VALORE_CARATTERISTICA,
                              KM_INIZIO,
                              KM_FINE,
                              LATITUDINE_INIZIO,
                              LONGITUDINE_INIZIO,
                              LATITUDINE_FINE,
                              LONGITUDINE_FINE
                         From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA
                        Where CODICE_CARATTERISTICA In ('R25350_LO_0230')
					  ) val
                  Where appl.IDENTIFICATIVO_GALLERIA = l_op_track(i).ID_TUNNEL
                    And appl.IDENTIFICATIVO_GALLERIA = val.IDENTIFICATIVO_GALLERIA(+);
--
      EXCEPTION
         When OTHERS  Then
            IF SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--> loop				
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: '  || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ('DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: '|| l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_MULTIPLA'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_SD_TUNNEL_EC - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionOP_SD_TUNNEL_EC;
--
-- ------------------------------------------------------------------------------------------------   
--                             PROCEDURE SetAcquisitionOP_SIDING_TUNNEL
--                       GALLERIE_BINARI_PO (gallerie dei binari di circolazione dei Punti Operativi)
--                       GALLERIE_RACCORDO_PO (gallerie dei binari di raccordo dei Punti Operativi)
-- N.B. Po_TR_Tunnel_1_2_1_0_5_2 è l'identificativo della galleria dei binari di circolazione
--      Po_SD_Tunnel_1_2_2_0_5_2 è l'identificativo della galleria dei binari di raccordo
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionOP_SIDING_TUNNEL (n_acquisizione       Number,
                                             p_error          Out Number )     Is
      i            Number;
      sqlstring    Varchar2 (3000);
      TYPE op_track_rt IS RECORD
       ( ID_LOCALITA   Rinf_Staging_Evo.CLASSE_R16100.SEDE_TECNICA%Type,
         ID_SIDING     Rinf_Staging_Evo.CLASSE_R16100.PO_SD_1_2_2_0_0_2%Type,                  -- identificativo del Raccordo
         ID_TUNNEL     Rinf_Staging_Evo.CLASSE_R25350_LO.PO_SD_TUNNEL_1_2_2_0_5_2%Type,        -- identificativo della galleria del raccordo
         ID_DTP        Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type    );
      TYPE op_track_t IS TABLE OF op_track_rt;
      L_OP_TRACK   op_track_t;
   BEGIN
      p_error := 0;
-- 10/03/2016 inserita join con l'anagrafica dei binari di raccordo per avere la certezza di caricare le gallerie dei binari di raccordo
-- inserito il controllo che si tratti di una galleria principale

        Select Null                          id_localita,
               Null                          id_binario,
               PO_SD_TUNNEL_1_2_2_0_5_2      id_tunnel,
               Null                          id_dtp
          Bulk Collect Into l_op_track
          From Rinf_Staging_Evo.CLASSE_R25350_LO g,
               Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA m,
               Rinf_Staging_Evo.CLASSE_R16100 b
         Where b.PO_SD_1_2_2_0_0_2 = m.VALORE_CARATTERISTICA 
          And  m.IDENTIFICATIVO_GALLERIA = g.PO_TR_TUNNEL_1_2_1_0_5_2 
          And  CODICE_CARATTERISTICA = 'R25350_LO_3010' 
          And  Nvl(PO_SD_TUNNEL_1_2_2_0_5_5, 0) >= 100                     -- sono considerate solo le gallerie con lunghezza > 100 metri
          And  (GALLERIA_PRINCIPALE Is Null  Or  GALLERIA_PRINCIPALE <> PO_TR_TUNNEL_1_2_1_0_5_2)
         Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'-------------------------------->  '|| 'Caricamento GALLERIE BINARI SECONDARI DEI PO');
         Dbms_Output.Put_Line ( 'Caricamento GALLERIE BINARI SECONDARI DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale GALLERIE BINARI SECONDARI DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,' ' );
--		 
         Dbms_Output.Put_Line ( 'Totale GALLERIE BINARI SECONDARI DEI PO da caricare: '|| To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.GALLERIE_RACCORDO_PO 
			         (PO_SD_TUNNEL_1_2_2_0_5_1,
                      PO_SD_TUNNEL_1_2_2_0_5_2,
                      PO_SD_TUNNEL_1_2_2_0_5_2_D,
--                      PO_SD_TUNNEL_1_2_2_0_5_5_AP,         -- AP=Y 
                      PO_SD_TUNNEL_1_2_2_0_5_5,
                      PO_SD_TUNNEL_1_2_2_0_5_6_AP,         
                      PO_SD_TUNNEL_1_2_2_0_5_6,
                      PO_SD_TUNNEL_1_2_2_0_5_7_AP,
                      PO_SD_TUNNEL_1_2_2_0_5_7,
                      PO_SD_TUNNEL_1_2_2_0_5_8_AP,
                      PO_SD_TUNNEL_1_2_2_0_5_8
				      )
               Select Lpad(Nvl(PO_SD_TUNNEL_1_2_2_0_5_1, 83), 4, '0') PO_SD_TUNNEL_1_2_2_0_5_1,
                      PO_SD_TUNNEL_1_2_2_0_5_2,
                      PO_SD_TUNNEL_1_2_2_0_5_2_D,
--                      PO_SD_TUNNEL_1_2_2_0_5_5_AP,
                      Trunc(PO_SD_TUNNEL_1_2_2_0_5_5),                           --01/10/2015 da test ERA-CUI è emerso che deve essere un intero
                      PKG_RINF_APPLICABILITA.GetAP_1_2_2_0_5_6 (PO_SD_TUNNEL_1_2_2_0_5_5) PO_SD_TUNNEL_1_2_2_0_5_6_AP,
--
--                      Case When PKG_RINF_APPLICABILITA.GetAP_1_2_2_0_5_6 (PO_SD_TUNNEL_1_2_2_0_5_5) = 'N' and PO_SD_TUNNEL_1_2_2_0_5_6 = 'N' 
--						     Then Null
--						     Else PO_SD_TUNNEL_1_2_2_0_5_6
--					  End PO_SD_TUNNEL_1_2_2_0_5_6,
					  PO_SD_TUNNEL_1_2_2_0_5_6,
--
                      PKG_RINF_APPLICABILITA.GetAP_1_2_2_0_5_7 (PO_SD_TUNNEL_1_2_2_0_5_5) PO_SD_TUNNEL_1_2_2_0_5_7_AP,
                      PO_SD_TUNNEL_1_2_2_0_5_7,
                      PKG_RINF_APPLICABILITA.GetAP_1_2_2_0_5_8 (PO_SD_TUNNEL_1_2_2_0_5_5, Upper(PO_SD_TUNNEL_1_2_2_0_5_7)) PO_TR_TUNNEL_1_2_2_0_5_8_AP,         --charStrg anomala  17/05/2016 reinserito con eliminazione NA In INE e aggiunta di NC come valore ammissibile
                      --vecchia PO_SD_TUNNEL_1_2_2_0_5_8
                      --GetAP ('1.2.2.0.5.8',0,PO_SD_TUNNEL_1_2_2_0_5_8) PO_SD_TUNNEL_1_2_2_0_5_8_AP,            --charStrg anomala
                      GetPARValue ('1.2.2.0.5.8', 0, PO_SD_TUNNEL_1_2_2_0_5_8) PO_SD_TUNNEL_1_2_2_0_5_8
                 From Rinf_Staging_Evo.CLASSE_R25350_LO
                Where PO_SD_TUNNEL_1_2_2_0_5_2 = l_op_track(i).ID_TUNNEL;
--				
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT   Loop 
--> loop			   
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: '|| l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
 --
                  Dbms_Output.Put_Line ( 'DTP: '|| l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                      || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                                      || ' Errore: '  || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_OP_SD'', ';
                  sqlstring := sqlstring || '''ORA-'|| SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring|| '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_SIDING_TUNNEL - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--
--  -------------------------------------------------------------------------------------
--                          REL_GALLERIE_BINARI_PO
--   10/03/2016 E' necessario associare le gallerie su più tratte a tutti i binari delle gallerie secondarie
--              viene diviso in due passi, nel primo vengono escluse le relazioni delle gallerie secondarie, 
--              che vengono inserite nel secondo passo con il codice della galleria principale.
--   -------------------------------------------------------------------------------------
--  Passo 1: gallerie mono tratta e principale
        Select o.SEDE_TECNICA            id_localita,
               l.PO_SD_1_2_2_0_0_2       id_binario,
               b.IDENTIFICATIVO_GALLERIA id_tunnel,
               o.CODICE_DTP              id_dtp
          Bulk Collect Into l_op_track
          From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA b,
               Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO l,
               Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o,
               Rinf_Lavorazione_Evo.GALLERIE_RACCORDO_PO g
          Where l.PO_SD_1_2_2_0_0_2 = Upper(b.VALORE_CARATTERISTICA)
            And l.SEDE_TECNICA = o.SEDE_TECNICA
            And g.PO_SD_TUNNEL_1_2_2_0_5_2 = b.IDENTIFICATIVO_GALLERIA
            And CODICE_CARATTERISTICA = 'R25350_LO_3010'
         Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '||'Caricamento RELAZIONE GALLERIE-BINARI SECONDARI DEI PO');
         Dbms_Output.Put_Line ( 'Caricamento RELAZIONE GALLERIE-BINARI SECONDARI DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale RELAZIONE GALLERIE-BINARI SECONDARI DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,' '               );
         Dbms_Output.Put_Line ( 'Totale RELAZIONE GALLERIE-BINARI SECONDARI DEI PO da caricare: '|| To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.REL_GALLERIE_RACCORDO_PO 
			              ( PO_SD_TUNNEL_1_2_2_0_5_2,  PO_SD_1_2_2_0_0_2 )
                   Values (l_op_track(i).ID_TUNNEL,    l_op_track(i).ID_SIDING);
--			   
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--			   
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: '|| SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                      || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                                      || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--									  
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_3010_OP_SD'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_SIDING_TUNNEL - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--
--   Passo 2: gallerie secondarie: inserisco i binari associati alle gallerie secondarie come binari della galleria principale, se non già presente
--
      Select Distinct o.SEDE_TECNICA        id_localita,
                      l.PO_SD_1_2_2_0_0_2   id_binario,
                      r.ID_TUNNEL,
                      o.CODICE_DTP          id_dtp
        Bulk Collect Into l_op_track
        From Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO l,
             Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o,
             Rinf_Lavorazione_Evo.GALLERIE_RACCORDO_PO g,
             (Select s.GALLERIA_PRINCIPALE id_tunnel,
                     b.VALORE_CARATTERISTICA id_binario
                From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA b,
                     Rinf_Staging_Evo.CLASSE_R25350_LO s
               Where b.IDENTIFICATIVO_GALLERIA = s.PO_SD_TUNNEL_1_2_2_0_5_2
                 And s.GALLERIA_PRINCIPALE Is Not Null
                 And s.GALLERIA_PRINCIPALE <> s.PO_SD_TUNNEL_1_2_2_0_5_2
                 And CODICE_CARATTERISTICA = 'R25350_LO_3010'
             Minus
              Select PO_SD_TUNNEL_1_2_2_0_5_2, PO_SD_1_2_2_0_0_2
                From Rinf_Lavorazione_Evo.REL_GALLERIE_RACCORDO_PO
			  ) r
       Where r.ID_BINARIO = l.PO_SD_1_2_2_0_0_2
         And l.SEDE_TECNICA = o.SEDE_TECNICA
         And g.PO_SD_TUNNEL_1_2_2_0_5_2 = r.ID_TUNNEL
        Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento RELAZIONE GALLERIE-BINARI SECONDARI DEI PO delle GALLERIE SECONDARIE COME BINARI DELLA GALLERIA PRINCIPALE');
         Dbms_Output.Put_Line ('Caricamento RELAZIONE GALLERIE-BINARI SECONDARI DEI PO delle GALLERIE SECONDARIE COME BINARI DELLA GALLERIA PRINCIPALE');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale RELAZIONE GALLERIE-BINARI SECONDARI DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,' ' );
         Dbms_Output.Put_Line ( 'Totale RELAZIONE GALLERIE-BINARI SECONDARI DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.REL_GALLERIE_RACCORDO_PO 
			              ( PO_SD_TUNNEL_1_2_2_0_5_2,  PO_SD_1_2_2_0_0_2)
                   Values ( l_op_track(i).ID_TUNNEL,   l_op_track(i).ID_SIDING );
--
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT    Loop 
--> loop  
                Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: '|| l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: '|| l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                 Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                                     || ' Codice errore: ORA-'|| SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--									  
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel|| ''',''R25350_3010_OP_SD'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_SIDING_TUNNEL - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionOP_SIDING_TUNNEL;
--
-- ------------------------------------------------------------------------------------------------   
--                                DICHIARAZIONI_RACCORDO_PO
-- ------------------------------------------------------------------------------------------------   

   Procedure SetAcquisitionOP_SIDING_EC (n_acquisizione       Number,
                                         p_error          Out Number )   IS
      i            Number;
      sqlstring    Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_LOCALITA   Rinf_Staging_Evo.CLASSE_R16100.SEDE_TECNICA%Type,
         ID_SIDING     Rinf_Staging_Evo.CLASSE_R16100.PO_SD_1_2_2_0_0_2%Type,
         ID_DTP        Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type   );
      TYPE op_track_t IS TABLE OF op_track_rt;
      L_OP_TRACK   op_track_t;
   BEGIN
      p_error := 0;
--
        Select Distinct  l.SEDE_TECNICA         id_localita,
                         b.PO_SD_1_2_2_0_0_2    id_siding,
                         o.CODICE_DTP           id_dtp
          Bulk Collect Into l_op_track
          From Rinf_Staging_Evo.CLASSE_R16100_MULTIPLA b,
               Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO l,
               Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o
         Where l.PO_SD_1_2_2_0_0_2 = b.PO_SD_1_2_2_0_0_2
           And l.SEDE_TECNICA = o.SEDE_TECNICA
           And CODICE_CARATTERISTICA In ('R16100_0040', 'R16100_0050', 'R16100_0041', 'R16100_0051')
      Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento DICHIARAZIONI BINARI SECONDARI DEI PO');
         Dbms_Output.Put_Line ( 'Caricamento DICHIARAZIONI BINARI SECONDARI DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'Totale DICHIARAZIONI BINARI SECONDARI DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,' '  );
         Dbms_Output.Put_Line ('Totale DICHIARAZIONI BINARI SECONDARI DEI PO da caricare: '|| To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.DICHIARAZIONI_RACCORDO_PO 
			     ( PO_SD_1_2_2_0_0_2,
                   TIPO_DICHIARAZIONE,
                   PO_SD_1_2_2_0_1_1O2_AP,
                   PO_SD_1_2_2_0_1_1O2,
                   KM_INIZIO,
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO  )
            Select appl.PO_SD_1_2_2_0_0_2,
                   'EC',
                   appl.VALORE_CARATTERISTICA,
                   Nvl(val.VALORE_CARATTERISTICA, ' '),
                   Nvl(KM_INIZIO, 0),
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO
                 From (Select CODICE_CARATTERISTICA,
                              PO_SD_1_2_2_0_0_2,
                              VALORE_CARATTERISTICA
                         From Rinf_Staging_Evo.CLASSE_R16100_MULTIPLA
                        Where CODICE_CARATTERISTICA In ('R16100_0041')
					   ) appl,
                      (Select CODICE_CARATTERISTICA,
                              PO_SD_1_2_2_0_0_2,
                              VALORE_CARATTERISTICA,
                              KM_INIZIO,
                              KM_FINE,
                              LATITUDINE_INIZIO,
                              LONGITUDINE_INIZIO,
                              LATITUDINE_FINE,
                              LONGITUDINE_FINE,
                              0 FLAG_CALCOLATO
                         From Rinf_Staging_Evo.CLASSE_R16100_MULTIPLA
                        Where CODICE_CARATTERISTICA In ('R16100_0040')
					   ) val
              Where appl.PO_SD_1_2_2_0_0_2 = l_op_track (i).ID_SIDING
                And appl.PO_SD_1_2_2_0_0_2 = val.PO_SD_1_2_2_0_0_2(+)
           Union
            Select appl.PO_SD_1_2_2_0_0_2,
                   'EI',
                   appl.VALORE_CARATTERISTICA,
                   Nvl(val.VALORE_CARATTERISTICA,' '),
                   Nvl(KM_INIZIO,0),
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO
              From (Select CODICE_CARATTERISTICA,
                           PO_SD_1_2_2_0_0_2,
                           VALORE_CARATTERISTICA
                      From Rinf_Staging_Evo.CLASSE_R16100_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R16100_0051')
					 ) appl,
                   (Select CODICE_CARATTERISTICA,
                           PO_SD_1_2_2_0_0_2,
                           VALORE_CARATTERISTICA,
                           KM_INIZIO,
                           KM_FINE,
                           LATITUDINE_INIZIO,
                           LONGITUDINE_INIZIO,
                           LATITUDINE_FINE,
                           LONGITUDINE_FINE,
                           0 FLAG_CALCOLATO
                      From Rinf_Staging_Evo.CLASSE_R16100_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R16100_0050')
					) val
                 Where appl.PO_SD_1_2_2_0_0_2 = l_op_track(i).ID_SIDING
                   And appl.PO_SD_1_2_2_0_0_2 = val.PO_SD_1_2_2_0_0_2(+);
--				   
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ('Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT   Loop 
--> loop				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: '|| l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' SIDING: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_siding
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
-- 
                 Dbms_Output.Put_Line (  'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                      || ' SIDING: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_siding
                                      || ' Errore: '  || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_siding || ''',''R16100_MULTIPLA'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE  || ''',';
                  sqlstring := sqlstring || ''''  || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_SIDING_EC - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      End;
--	  
   END SetAcquisitionOP_SIDING_EC;
--
-- ------------------------------------------------------------------------------------------------   
--                     PROCEDURE SetAcquisitionOP_SIDING 
--                  Binari di raccordo (servizio) dei Punti Operativi
-- ------------------------------------------------------------------------------------------------   
-- 
 Procedure SetAcquisitionOP_SIDING (n_acquisizione     Number,
                                    p_error        Out Number )   Is
      i            Number;
      sqlstring    Varchar2 (3000);
      TYPE op_track_rt IS RECORD
       ( ID_LOCALITA   Rinf_Staging_Evo.CLASSE_R16100.SEDE_TECNICA%Type,
         ID_SIDING     Rinf_Staging_Evo.CLASSE_R16100.PO_SD_1_2_2_0_0_2%Type,
         ID_DTP        Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type        );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
   BEGIN
      p_error := 0;
--
        Select b.SEDE_TECNICA       id_localita,
               PO_SD_1_2_2_0_0_2    id_siding,
               l.CODICE_DTP         id_dtp
          Bulk Collect Into         l_op_track
          From Rinf_Staging_Evo.CLASSE_R16100 b, 
		       Rinf_Lavorazione_Evo.PUNTI_OPERATIVI l
         Where l.SEDE_TECNICA = b.SEDE_TECNICA
          --AND Substr(PO_SD_1_2_2_0_0_2, 8, 2) Not In ('AF', 'SM')         --23/07/2015 Richiesta Galli di includere tutte le tipologie di binari
            And Length(PO_SD_1_2_2_0_0_2) >= 14
          Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '||'Caricamento BINARI DI SERVIZIO DEI PO');
         Dbms_Output.Put_Line ('Caricamento BINARI DI SERVIZIO DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale BINARI DI SERVIZIO DEI PO da caricare: ' || TO_CHAR (l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,' '  );
         Dbms_Output.Put_Line ( 'Totale BINARI DI SERVIZIO DEI PO da caricare: ' || To_Char (l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO 
                     (  PO_SD_1_2_2_0_0_1,
                        PO_SD_1_2_2_0_0_2,
                        PO_SD_1_2_2_0_0_2_D,
                         --PO_SD_1_2_2_0_0_3_AP,                 --  Ap=Y - Fittizia Per Nya
                         --PO_SD_1_2_2_0_0_3,                    --  Multiplo
                         --PO_SD_1_2_2_0_2_1_AP,                 --  Ap=Y - Fittizia Per Nya
                        PO_SD_1_2_2_0_2_1,
                        PO_SD_1_2_2_0_3_1_AP,                    -- 0.82 Agosto Numerico
                        PO_SD_1_2_2_0_3_1,
                        PO_SD_1_2_2_0_3_2_AP,                    -- 0.82 Agosto Numerico
                        PO_SD_1_2_2_0_3_2,
                        PO_SD_1_2_2_0_3_3_AP,                    -- 0.82 Agosto Concatenato
                        PO_SD_1_2_2_0_3_3_A,
                        PO_SD_1_2_2_0_3_3_B,
                        --PO_SD_1_2_2_0_4_1_AP,                  --  Ap=Y - Fittizia Per Nya
                        PO_SD_1_2_2_0_4_1,
                        -- PO_SD_1_2_2_0_4_2_AP,                 --  Ap=Y - Fittizia Per Nya
                        PO_SD_1_2_2_0_4_2,
                         --PO_SD_1_2_2_0_4_3_AP,                 --  Ap=Y - Fittizia Per Nya
                        PO_SD_1_2_2_0_4_3,
                         --PO_SD_1_2_2_0_4_4_AP,                 --  Ap=Y - Fittizia Per Nya
                        PO_SD_1_2_2_0_4_4,
                         --PO_SD_1_2_2_0_4_5_AP,                 --  Ap=Y - Fittizia Per Nya
                        PO_SD_1_2_2_0_4_5,
                         --PO_SD_1_2_2_0_4_6_AP,                 --  Ap=Y - Fittizia Per Nya
                        PO_SD_1_2_2_0_4_6,
                        SEDE_TECNICA,
  				        PO_SD_1_2_2_0_6_1_AP,                    ---> Nuovo Reg.777/2019
                        PO_SD_1_2_2_0_6_1                        ---> Nuovo Reg.777/2019
                       )
                 Select Lpad(Nvl(PO_SD_1_2_2_0_0_1, 83), 4, '0') PO_SD_1_2_2_0_0_1,
                        PO_SD_1_2_2_0_0_2,
                        PO_SD_1_2_2_0_0_2_D,
                        -- PO_SD_1_2_2_0_0_3_AP,
                        -- PO_SD_1_2_2_0_0_3,                    -- multiplo
                        -- PO_SD_1_2_2_0_2_1_AP,
                        PO_SD_1_2_2_0_2_1,
                        GetAP ('1.2.2.0.3.1', 2, Trim(To_Char(PO_SD_1_2_2_0_3_1, '99.9'))) PO_SD_1_2_2_0_3_1_AP,          -- 0.82 Agosto Numerico Con Virgola 9.9         --17/05/2016 modificato a 99.9 a seguito di aggiornamento In INE (mail Schillaci 20/05/2016)
                        GetPARValue ('1.2.2.0.3.1', 2, Trim(To_Char(PO_SD_1_2_2_0_3_1, '99999.9'))) PO_SD_1_2_2_0_3_1,    -- invece di dominio 2 metto dominio 0 altrimenti non verrebbe fuori Nullo quando 9.9; nella formattazionemetto tanti 9999 altrimenit va In Errore: se stringa non è N.N
						GetAP ('1.2.2.0.3.2', 2, To_Char(PO_SD_1_2_2_0_3_2)) PO_SD_1_2_2_0_3_2_AP,                        -- 0.82 Agosto Numerico
--                        GetPARValue ('1.2.2.0.3.2', 2, To_Char(PO_SD_1_2_2_0_3_2)) PO_SD_1_2_2_0_3_2,
                        PO_SD_1_2_2_0_3_2,
                        PKG_RINF_APPLICABILITA.GetAP_1_2_2_0_3_3 (PO_SD_1_2_2_0_3_3_A, PO_SD_1_2_2_0_3_3_B) PO_SD_1_2_2_0_3_3_AP,                                                                                              --0.82 AGOSTO CONCATENATO
--                          GetPARValue ('1.2.2.0.3.3.A', 2, To_Char(PO_SD_1_2_2_0_3_3_A)) PO_SD_1_2_2_0_3_3_A,
--                          GetPARValue ('1.2.2.0.3.3.B', 2, To_Char(PO_SD_1_2_2_0_3_3_B)) PO_SD_1_2_2_0_3_3_B,
                        PO_SD_1_2_2_0_3_3_A,
                        PO_SD_1_2_2_0_3_3_B,
                        -- PO_SD_1_2_2_0_4_1_AP,
                        PO_SD_1_2_2_0_4_1,
                        -- PO_SD_1_2_2_0_4_2_AP,
                        PO_SD_1_2_2_0_4_2,
                        -- PO_SD_1_2_2_0_4_3_AP,
                        PO_SD_1_2_2_0_4_3,
                        -- PO_SD_1_2_2_0_4_4_AP,
                        PO_SD_1_2_2_0_4_4,
                        -- PO_SD_1_2_2_0_4_5_AP,
                        PO_SD_1_2_2_0_4_5,
                        -- PO_SD_1_2_2_0_4_6_AP,
                        PO_SD_1_2_2_0_4_6,
                        SEDE_TECNICA,
 				        PKG_RINF_APPLICABILITA.GetAP_1_2_2_0_6_1 (PO_SD_1_2_2_0_6_1) PO_SD_1_2_2_0_6_1_AP,                  ---> nuovo Reg.777/2019
                        PO_SD_1_2_2_0_6_1                                                                                       ---> nuovo Reg.777/2019
                   From Rinf_Staging_Evo.CLASSE_R16100
                  Where SEDE_TECNICA = l_op_track(i).ID_LOCALITA
                    And PO_SD_1_2_2_0_0_2 = l_op_track(i).ID_SIDING;
--					 
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ('Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--> loop			   
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' SIDING: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_siding
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                      || ' SIDING: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_siding
                                      || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--									  
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_siding || ''',''R16100'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_SIDING - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionOP_SIDING;
--
-- ------------------------------------------------------------------------------------------------   
--                       PROCEDURE SetAcquisitionOP_TRACK_TUNNEL
--  BINARI delle GALLERIE dei Punti Operativi (GALLERIE_BINARI_PO) - gallerie dei binari di circolazione
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionOP_TRACK_TUNNEL (n_acquisizione       Number,
                                            p_error          Out Number )   Is
      i            Number;
      sqlstring    Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_LOCALITA   Rinf_Staging_Evo.CLASSE_R16000_LO.SEDE_TECNICA%Type,
         ID_BINARIO    Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2%Type,
         ID_TUNNEL     Rinf_Staging_Evo.CLASSE_R25350_LO.PO_TR_TUNNEL_1_2_1_0_5_2%Type,
         ID_DTP        Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type                      );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
   BEGIN
      p_error := 0;
--        
        Select Null                       id_localita,
               Null                       id_binario,
               PO_TR_TUNNEL_1_2_1_0_5_2   id_tunnel,
               Null                       id_dtp
          Bulk Collect Into l_op_track
          From Rinf_Staging_Evo.CLASSE_R25350_LO b
         Where PO_TR_TUNNEL_1_2_1_0_5_2 Is Not Null
           And Nvl(PO_TR_TUNNEL_1_2_1_0_5_5, 0) >= 100                          -- escluse le "gallerie" con lunghezza inferiore a 100 m 
-- 10/03/2016 inserito controllo che la galleria non sia secondaria
          And (GALLERIA_PRINCIPALE Is Null  Or  GALLERIA_PRINCIPALE = PO_TR_TUNNEL_1_2_1_0_5_2)
          Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento GALLERIE BINARI DI CIRCOLAZIONE DEI PO');
         Dbms_Output.Put_Line ( 'Caricamento GALLERIE BINARI DI CIRCOLAZIONE DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale GALLERIE BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || TO_CHAR (l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,' ' );
         Dbms_Output.Put_Line ( 'Totale GALLERIE BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || TO_CHAR (l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO 
			         (  PO_TR_TUNNEL_1_2_1_0_5_1,
                        PO_TR_TUNNEL_1_2_1_0_5_2,
                        PO_TR_TUNNEL_1_2_1_0_5_2_D,
                        -- PO_TR_TUNNEL_1_2_1_0_5_5_AP,         --DA RICONTROLLARE NUOVA 0.82 AGOSTO
                        PO_TR_TUNNEL_1_2_1_0_5_5,
                        PO_TR_TUNNEL_1_2_1_0_5_6_AP,         
                        PO_TR_TUNNEL_1_2_1_0_5_6,
                        PO_TR_TUNNEL_1_2_1_0_5_7_AP,
                        PO_TR_TUNNEL_1_2_1_0_5_7,
                        PO_TR_TUNNEL_1_2_1_0_5_8_AP,
                        PO_TR_TUNNEL_1_2_1_0_5_8,
			            PO_TR_TUNNEL_1_2_1_0_5_9_AP,           -- nuovo Reg.777/2019  [AP=NA]
                        PO_TR_TUNNEL_1_2_1_0_5_9               -- nuovo Reg.777/2019
   			  )
                 Select Lpad(Nvl(PO_TR_TUNNEL_1_2_1_0_5_1, 83), 4, '0') PO_TR_TUNNEL_1_2_1_0_5_1,
                        PO_TR_TUNNEL_1_2_1_0_5_2,
                        PO_TR_TUNNEL_1_2_1_0_5_2_D,
--                      PO_TR_TUNNEL_1_2_1_0_5_5_AP,
                        Trunc(PO_TR_TUNNEL_1_2_1_0_5_5), --01/10/2015 da test CUI è emerso che deve essere un intero
                        PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_5_6 (PO_TR_TUNNEL_1_2_1_0_5_5) PO_TR_TUNNEL_1_2_1_0_5_6_AP,
-- 
--                        Case When PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_5_6 (PO_TR_TUNNEL_1_2_1_0_5_5) = 'N' and PO_TR_TUNNEL_1_2_1_0_5_6 = 'N' 
--						     Then Null
--						     Else PO_TR_TUNNEL_1_2_1_0_5_6
--						End  PO_TR_TUNNEL_1_2_1_0_5_6,
                        PO_TR_TUNNEL_1_2_1_0_5_6,
--
                        PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_5_7 (PO_TR_TUNNEL_1_2_1_0_5_5) PO_TR_TUNNEL_1_2_1_0_5_7_AP,
                        PO_TR_TUNNEL_1_2_1_0_5_7,
                        PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_5_8 (PO_TR_TUNNEL_1_2_1_0_5_5, Upper(PO_TR_TUNNEL_1_2_1_0_5_7)) PO_TR_TUNNEL_1_2_1_0_5_8_AP,         --charStrg anomala 17/05/2016 reinserito con eliminazione NA In INE e aggiunta di NC come valore ammissibile
--                      vecchia PO_TR_TUNNEL_1_2_1_0_5_8
--                      GetAP ('1.2.1.0.5.8',0, PO_TR_TUNNEL_1_2_1_0_5_8) PO_TR_TUNNEL_1_2_1_0_5_8_AP,            --charStrg anomala
                        GetPARValue ('1.2.1.0.5.8', 0, PO_TR_TUNNEL_1_2_1_0_5_8) PO_TR_TUNNEL_1_2_1_0_5_8,
                        PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_5_9 (PO_TR_TUNNEL_1_2_1_0_5_7) PO_TR_TUNNEL_1_2_1_0_5_9_AP , 
                        PO_TR_TUNNEL_1_2_1_0_5_9
                   From Rinf_Staging_Evo.CLASSE_R25350_LO
                  Where PO_TR_TUNNEL_1_2_1_0_5_2 = l_op_track(i).ID_TUNNEL;
--				
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--> loop				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--
                  Dbms_Output.Put_Line (  'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                       || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                       || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                                       || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_OP_TR'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_TRACK_TUNNEL.1 - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--
-- -------------------------------------------------------------------------------------
--        Relazione GALLERIE BINARI dei Punti Operativi (REL_GALLERIE_BINARI_PO)
-- -------------------------------------------------------------------------------------
-- 10/03/2016 E' necessario associare le gallerie su più tratte a tutti i binari delle tratte secondarie
--        viene diviso In due passi, nel primo vengono escluse le relazioni delle gallerie secondarie, che vengno inserite
--        nel secondo passo con il codice della galleria principale.
--
--        Passo 1: gallerie mono tratta e principale
        Select Distinct
               o.SEDE_TECNICA              id_localita,
               l.PO_TRACK_1_2_1_0_0_2      id_binario,
               b.IDENTIFICATIVO_GALLERIA   id_tunnel,
               o.CODICE_DTP                id_dtp
          Bulk Collect Into                l_op_track
          From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA b,
               Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
               Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
               Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o,
               Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO g
         Where l.PO_TRACK_1_2_1_0_0_2 = Upper(b.VALORE_CARATTERISTICA)
           And r.SEDE_TECNICA = o.SEDE_TECNICA
           And l.PO_TRACK_1_2_1_0_0_2 = r.PO_TRACK_1_2_1_0_0_2
           And g.PO_TR_TUNNEL_1_2_1_0_5_2 = b.IDENTIFICATIVO_GALLERIA
           And CODICE_CARATTERISTICA = 'R25350_LO_3010'
         Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DEI PO');
         Dbms_Output.Put_Line ( 'Caricamento RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || TO_CHAR (l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,' ' );
         Dbms_Output.Put_Line ( 'Totale RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DEI PO da caricare: '|| TO_CHAR (l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO 
			              (PO_TR_TUNNEL_1_2_1_0_5_2, PO_TRACK_1_2_1_0_0_2 )
                   Values (l_op_track(i).ID_TUNNEL,  l_op_track(i).ID_BINARIO);
--
      EXCEPTION
--	  
         When OTHERS Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--> loop 
                   Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_3010_OP_TR'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_TRACK_TUNNEL.2 - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--
--  Passo 2: gallerie secondarie: inserisco i binari associati alle gallerie secondarie come binari della galleria principale, se non già presente
--
      Select Distinct 
	         o.SEDE_TECNICA          id_localita,
             l.PO_TRACK_1_2_1_0_0_2  id_binario,
             r.ID_TUNNEL,
             o.CODICE_DTP            id_dtp
        Bulk Collect Into            l_op_track
        From Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
             Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
             Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o,
             Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO g,
             (Select s.GALLERIA_PRINCIPALE id_tunnel,
                     b.VALORE_CARATTERISTICA id_binario
                From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA b,
                     Rinf_Staging_Evo.CLASSE_R25350_LO s
               Where b.IDENTIFICATIVO_GALLERIA = s.PO_TR_TUNNEL_1_2_1_0_5_2
                 And s.GALLERIA_PRINCIPALE Is Not Null
                 And s.GALLERIA_PRINCIPALE <> s.PO_TR_TUNNEL_1_2_1_0_5_2
                 And CODICE_CARATTERISTICA = 'R25350_LO_3010'
             Minus
              Select PO_TR_TUNNEL_1_2_1_0_5_2, PO_TRACK_1_2_1_0_0_2
                From Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO
			  ) r
        Where r.id_binario = l.PO_TRACK_1_2_1_0_0_2
          And r.SEDE_TECNICA = o.SEDE_TECNICA
          And l.PO_TRACK_1_2_1_0_0_2 = r.PO_TRACK_1_2_1_0_0_2
          And g.PO_TR_TUNNEL_1_2_1_0_5_2 = r.ID_TUNNEL
        Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DEI PO delle GALLERIE SECONDARIE COME BINARI DELLA GALLERIA PRINCIPALE');
         Dbms_Output.Put_Line ( 'Caricamento RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DEI PO delle GALLERIE SECONDARIE COME BINARI DELLA GALLERIA PRINCIPALE');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || TO_CHAR (l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
         Dbms_Output.Put_Line ('Totale RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || TO_CHAR (l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO 
			              (PO_TR_TUNNEL_1_2_1_0_5_2, PO_TRACK_1_2_1_0_0_2 )
                  Values  ( l_op_track(i).ID_TUNNEL,  l_op_track(i).ID_BINARIO );
--			   
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--> loop				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: '|| l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_3010_OP_TR'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_TRACK_TUNNEL.3 - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--
-- 08/02/2017 Aggiunto il log sulle gallerie senza coordinate e senza binari
--
      PKG_RINF_ACQUISIZIONI.SetGallerieLog 
	           (   n_caricamento,
                   n_acquisizione,
