-- ------------------------------------------------------------------------------------------------   
--                            PROCEDURE SetAcquisitionOP_TRK_TUNNEL_EC
--  DICHIARAZIONI Certificati EC/EI per i binari delle GALLERIE dei PO(DICHIARAZIONI_GALLERIE_BIN_PO)
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionOP_TRK_TUNNEL_EC (n_acquisizione       Number,
                                             p_error          Out Number )   Is
      i            Number;
      sqlstring    Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_LOCALITA   Rinf_Staging_Evo.CLASSE_R16000_LO.SEDE_TECNICA%Type,
         ID_TUNNEL     Rinf_Staging_Evo.CLASSE_R25350_LO.PO_TR_TUNNEL_1_2_1_0_5_2%Type,
         ID_DTP        Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type                );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
   BEGIN
      p_error := 0;

        Select Distinct  
		       Null                          id_localita,
               l.PO_TR_TUNNEL_1_2_1_0_5_2    id_tunnel,
               Null                          id_dtp
          Bulk Collect Into                  l_op_track
          From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA b,
               Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO l
         Where l.PO_TR_TUNNEL_1_2_1_0_5_2 = b.IDENTIFICATIVO_GALLERIA
           And CODICE_CARATTERISTICA In ('R25350_LO_0140', 'R25350_LO_0150', 'R25350_LO_0141', 'R25350_LO_0151')
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '||'Caricamento DICHIARAZIONI GALLERIE DEI BINARI DI CIRCOLAZIONE DEI PO');
         Dbms_Output.Put_Line ( 'Caricamento DICHIARAZIONI GALLERIE DEI BINARI DI CIRCOLAZIONE DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale DICHIARAZIONI GALLERIE DEI BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ');
         Dbms_Output.Put_Line ('Totale DICHIARAZIONI GALLERIE DEI BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--
            Insert Into Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_BIN_PO 
			   (  PO_TR_TUNNEL_1_2_1_0_5_2,
                   TIPO_DICHIARAZIONE,
                   PO_TR_TUNNEL_1_2_1_0_5_3O4_AP,
                   PO_TR_TUNNEL_1_2_1_0_5_3O4,
                   KM_INIZIO,
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO		)
            Select appl.IDENTIFICATIVO_GALLERIA,
                   'EC',
                   appl.VALORE_CARATTERISTICA,
                   Nvl(val.VALORE_CARATTERISTICA, ' '),
                   Nvl(KM_INIZIO, 0),
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO
              From (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_GALLERIA,
                           VALORE_CARATTERISTICA
                      From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R25350_LO_0141')
					) appl,
                   (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_GALLERIA,
                           VALORE_CARATTERISTICA,
                           KM_INIZIO,
                           KM_FINE,
                           LATITUDINE_INIZIO,
                           LONGITUDINE_INIZIO,
                           LATITUDINE_FINE,
                           LONGITUDINE_FINE,
                           0 FLAG_CALCOLATO
                      From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R25350_LO_0140')
					) val
              Where   appl.IDENTIFICATIVO_GALLERIA = l_op_track(i).ID_TUNNEL
                  And appl.IDENTIFICATIVO_GALLERIA = val.IDENTIFICATIVO_GALLERIA(+)
--				  
                       Union
--
            Select appl.IDENTIFICATIVO_GALLERIA,
                   'EI',
                   appl.VALORE_CARATTERISTICA,
                   Nvl(val.VALORE_CARATTERISTICA, ' '),
                   Nvl(KM_INIZIO,0),
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO
              From (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_GALLERIA,
                           VALORE_CARATTERISTICA
                      From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R25350_LO_0151')
					) appl,
                   (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_GALLERIA,
                           VALORE_CARATTERISTICA,
                           KM_INIZIO,
                           KM_FINE,
                           LATITUDINE_INIZIO,
                           LONGITUDINE_INIZIO,
                           LATITUDINE_FINE,
                           LONGITUDINE_FINE,
                           0 FLAG_CALCOLATO
                      From Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R25350_LO_0150')
					 ) val
              Where appl.IDENTIFICATIVO_GALLERIA = l_op_track(i).ID_TUNNEL
                And appl.IDENTIFICATIVO_GALLERIA = val.IDENTIFICATIVO_GALLERIA(+);
--
  EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ('Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--> loop				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  Dbms_Output.Put_Line ('DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                     || ' TUNNEL: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_MULTIPLA'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop 				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_TRK_TUNNEL_EC - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionOP_TRK_TUNNEL_EC;
