--   PROCEDURE SetPulisciOP_TRACK_PLATF
--   IS
--   -- Questa procedura elimina i dati dei binari non di corsa dei marciapiedi
--   -- per evitare che si verificano errori di chiave esterna nel cariamento dei marciapiedi
--   -- con conseguente mancato caricamento delle OP
--   BEGIN
--
--     Delete From  Rinf_Staging_Evo.CLASSE_R24700_PULITA;
--     Insert Into Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     Select * From  Rinf_Staging_Evo.CLASSE_R24700;
--
--
----- Eliminzione binari non presenti nell'anagrafica dei binari di corsa PO
--
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET BINARIO_1=Null
--     Where 
--     BINARIO_1 IN
--     (Select BINARIO_1 From  Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     MINUS
--     Select PO_TRACK_1_2_1_0_0_2 From  Rinf_Lavorazione_Evo.BINARI_CORSA_PO);
--     
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET BINARIO_2=Null
--     Where 
--     BINARIO_2 IN
--     (Select BINARIO_2 From  Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     MINUS
--     Select PO_TRACK_1_2_1_0_0_2 From  Rinf_Lavorazione_Evo.BINARI_CORSA_PO);
--     
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET BINARIO_3=Null
--     Where 
--     BINARIO_3 IN
--     (Select BINARIO_3 From  Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     MINUS
--     Select PO_TRACK_1_2_1_0_0_2 From  Rinf_Lavorazione_Evo.BINARI_CORSA_PO);
--     
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET BINARIO_4=Null
--     Where 
--     BINARIO_4 IN
--     (Select BINARIO_4 From  Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     MINUS
--     Select PO_TRACK_1_2_1_0_0_2 From  Rinf_Lavorazione_Evo.BINARI_CORSA_PO);
--
--   --- Elimino l'attribuzione più volte allo stesso binario
--
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET BINARIO_2=Null
--     Where 
--     BINARIO_1 =BINARIO_2;
--    
--      UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET BINARIO_3=Null
--     Where 
--     BINARIO_1 =BINARIO_3;
--    
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET BINARIO_3=Null
--     Where 
--     BINARIO_2 =BINARIO_3;
--    
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET BINARIO_4=Null
--     Where 
--     BINARIO_3 =BINARIO_4;
--
--
--   ---Shifting dei codici dei binari
--
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET
--     BINARIO_1=BINARIO_2,
--     BINARIO_2=Null
--     Where 
--     BINARIO_1 Is Null And BINARIO_2 Is Not Null;
--     
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET
--     BINARIO_1=BINARIO_3,
--     BINARIO_3=Null
--     Where 
--     BINARIO_1 Is Null And BINARIO_3 Is Not Null;
--
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET
--     BINARIO_2=BINARIO_3,
--     BINARIO_3=Null
--     Where 
--     BINARIO_1 Is Not Null And BINARIO_2 Is Null And BINARIO_3 Is Not Null;
--
--
--     UPDATE Rinf_Staging_Evo.CLASSE_R24700_PULITA
--     SET
--     BINARIO_3=BINARIO_4,
--     BINARIO_4=Null
--     Where 
--     BINARIO_1 Is Not Null And BINARIO_2 Is Not Null And BINARIO_3 IS  Null And BINARIO_4 IS  NOT Null;
--
--   END SetPulisciOP_TRACK_PLATF;

-- ------------------------------------------------------------------------------------------------   
--                       PROCEDURE SetAcquisitionOP_TRACK_PLATF
--                      Marciapiedi dei binari di Punto Operativo (MARCIAPIEDI_BINARI_PO)
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetAcquisitionOP_TRACK_PLATF (n_acquisizione       Number,
                                         p_error          Out Number )   Is 
   i            Number;
   sqlstring    Varchar2 (3000);
   TYPE op_track_rt IS RECORD
   (  id_localita_1     Rinf_Staging_Evo.CLASSE_R16000_LO.SEDE_TECNICA%Type,
      desc_localita_1   Rinf_Staging_Evo.CLASSE_R03000.DEFINIZIONE%Type,
      id_localita_2     Rinf_Staging_Evo.CLASSE_R16000_LO.SEDE_TECNICA%Type,
      desc_localita_2   Rinf_Staging_Evo.CLASSE_R03000.DEFINIZIONE%Type,
      id_localita_3     Rinf_Staging_Evo.CLASSE_R16000_LO.SEDE_TECNICA%Type,
      desc_localita_3   Rinf_Staging_Evo.CLASSE_R03000.DEFINIZIONE%Type,
      id_localita_4     Rinf_Staging_Evo.CLASSE_R16000_LO.SEDE_TECNICA%Type,                --aggiunto da Alessio (28/10/2016)
      desc_localita_4   Rinf_Staging_Evo.CLASSE_R03000.DEFINIZIONE%Type,                --aggiunto da Alessio (28/10/2016)
      id_binario_1      Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2%Type,
      desc_binario_1    Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2_D%Type,
      id_binario_2      Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2%Type,
      desc_binario_2    Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2_D%Type,
      id_binario_3      Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2%Type,
      desc_binario_3    Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2_D%Type,
      id_binario_4      Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2%Type,                --aggiunto da Alessio (28/10/2016)
      desc_binario_4    Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2_D%Type,                --aggiunto da Alessio (28/10/2016)
      id_platform       Rinf_Staging_Evo.CLASSE_R24700.PO_TR_PLATFORM_1_2_1_0_6_2%Type,
      desc_platform     Rinf_Staging_Evo.CLASSE_R24700.PO_TR_PLATFORM_1_2_1_0_6_2_D%Type,
      id_dtp_1          Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
      id_dtp_2          Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
      id_dtp_3          Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
      id_dtp_4          Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type                              --aggiunto da Alessio (28/10/2016)
   );
   TYPE op_track_t IS TABLE OF op_track_rt;
   L_OP_TRACK   op_track_t;
--
 BEGIN
   p_error := 0;
-- ----------------------------------------------------------------------------------
-- Eseguo una preelaborazione, pulisco i marciapiedi dai codici dei binari non validi
-- ----------------------------------------------------------------------------------
   PKG_RINF_ACQUISIZIONI.SetPulisciOP_TRACK_PLATF (n_caricamento, n_acquisizione, data_caricamento, data_scarico,  p_error);

   If p_error = 0  Then
        Select b1.SEDE_TECNICA              id_localita_1,
               b1.DEFINIZIONE               desc_localita_1,
               b2.SEDE_TECNICA              id_localita_2,
               b2.DEFINIZIONE               desc_localita_2,
               b3.SEDE_TECNICA              id_localita_3,
               b3.DEFINIZIONE               desc_localita_3,
               b4.SEDE_TECNICA              id_localita_4,                --aggiunto da Alessio (28/10/2016)
               b4.DEFINIZIONE               desc_localita_4,                --aggiunto da Alessio (28/10/2016)
               B1.PO_TRACK_1_2_1_0_0_2      id_binario_1,
               B1.PO_TRACK_1_2_1_0_0_2_d    desc_binario_1,
               B2.PO_TRACK_1_2_1_0_0_2      id_binario_2,
               B2.PO_TRACK_1_2_1_0_0_2_d    desc_binario_2,
               B3.PO_TRACK_1_2_1_0_0_2      id_binario_3,
               B3.PO_TRACK_1_2_1_0_0_2_d    desc_binario_3,
               B4.PO_TRACK_1_2_1_0_0_2      id_binario_4,                --aggiunto da Alessio (28/10/2016)
               B4.PO_TRACK_1_2_1_0_0_2_d    desc_binario_4,                --aggiunto da Alessio (28/10/2016)
               PO_TR_PLATFORM_1_2_1_0_6_2   id_platform,
               PO_TR_PLATFORM_1_2_1_0_6_2_D desc_platform,
               b1.CODICE_DTP                id_dtp_1,
               b2.CODICE_DTP                id_dtp_2,
               b3.CODICE_DTP                id_dtp_3,
               b4.CODICE_DTP                id_dtp_4                --aggiunto da Alessio (28/10/2016)
          Bulk Collect Into                 l_op_track
          From Rinf_Staging_Evo.CLASSE_R24700_PULITA p,      --ho sostituito Rinf_Staging_Evo.CLASSE_R24700 con quella pulita
               (Select p.SEDE_TECNICA,
                       p.DEFINIZIONE,
                       p.CODICE_DTP,
                       b.PO_TRACK_1_2_1_0_0_2,
                       PO_TRACK_1_2_1_0_0_2_d
                  From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                       Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                       Rinf_Lavorazione_Evo.PUNTI_OPERATIVI p
                 Where p.SEDE_TECNICA = r.SEDE_TECNICA
                   And r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
			    ) b1,
               (Select p.SEDE_TECNICA,
                       p.DEFINIZIONE,
                       p.CODICE_DTP,
                       b.PO_TRACK_1_2_1_0_0_2,
                       PO_TRACK_1_2_1_0_0_2_d
                  From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                       Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                       Rinf_Lavorazione_Evo.PUNTI_OPERATIVI p
                 Where p.SEDE_TECNICA = r.SEDE_TECNICA
                   And r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
				) b2,
               (Select p.SEDE_TECNICA,
                       p.DEFINIZIONE,
                       p.CODICE_DTP,
                       b.PO_TRACK_1_2_1_0_0_2,
                       PO_TRACK_1_2_1_0_0_2_d
                  From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                       Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                       Rinf_Lavorazione_Evo.PUNTI_OPERATIVI p
                 Where p.SEDE_TECNICA = r.SEDE_TECNICA
                   And r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
			    ) b3,
               (Select p.SEDE_TECNICA,
                       p.DEFINIZIONE,
                       p.CODICE_DTP,
                       b.PO_TRACK_1_2_1_0_0_2,
                       PO_TRACK_1_2_1_0_0_2_d
                  From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                       Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                       Rinf_Lavorazione_Evo.PUNTI_OPERATIVI p
                 Where p.SEDE_TECNICA = r.SEDE_TECNICA
                   And r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
				) b4
         Where P.BINARIO_1 = B1.PO_TRACK_1_2_1_0_0_2
           And P.BINARIO_2 = B2.PO_TRACK_1_2_1_0_0_2(+)
           And P.BINARIO_3 = B3.PO_TRACK_1_2_1_0_0_2(+)
           And P.BINARIO_4 = B4.PO_TRACK_1_2_1_0_0_2(+)
         Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '--------------------------------> ' || 'Caricamento MARCIAPIEDI BINARI DI CIRCOLAZIONE DEI PO');
         Dbms_Output.Put_Line ( 'Caricamento MARCIAPIEDI BINARI DI CIRCOLAZIONE DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale MARCIAPIEDI BINARI DI CIRCOLAZIONE DEI PO da caricare: '|| To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, ' ');
         Dbms_Output.Put_Line ('Totale MARCIAPIEDI BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO 
                 (      PO_TR_PLATFORM_1_2_1_0_6_1,
                        PO_TR_PLATFORM_1_2_1_0_6_2,
                        PO_TR_PLATFORM_1_2_1_0_6_2_D,
                        -- PO_TR_PLATFORM_1_2_1_0_6_3_AP,           --  AP=Y - Fittizia Per NYA
                        -- PO_TR_PLATFORM_1_2_1_0_6_3,              --  multipla 0.82 agosto
                        -- PO_TR_PLAT_1_2_1_0_6_4_B1_AP,            --  AP=Y - Fittizia Per NYA
                        PO_TR_PLATFORM_1_2_1_0_6_4_B1,
                        -- PO_TR_PLAT_1_2_1_0_6_4_B2_AP,            --  AP=Y - Fittizia Per NYA
                        PO_TR_PLATFORM_1_2_1_0_6_4_B2,
                        -- PO_TR_PLAT_1_2_1_0_6_4_B3_AP,            --  AP=Y - Fittizia Per NYA
                        PO_TR_PLATFORM_1_2_1_0_6_4_B3,
                        -- PO_TR_PLAT_1_2_1_0_6_5_B1_AP,            --  AP=Y - Fittizia Per NYA
                        PO_TR_PLATFORM_1_2_1_0_6_5_B1,
                        -- PO_TR_PLAT_1_2_1_0_6_5_B2_AP,            --  AP=Y - Fittizia Per NYA
                        PO_TR_PLATFORM_1_2_1_0_6_5_B2,
                        -- PO_TR_PLAT_1_2_1_0_6_5_B3_AP,            --  AP=Y - Fittizia Per NYA
                        PO_TR_PLATFORM_1_2_1_0_6_5_B3,
                        -- PO_TR_PLATFORM_1_2_1_0_6_6_AP,           --  AP=Y - Fittizia Per NYA
                        PO_TR_PLATFORM_1_2_1_0_6_6,
                        -- PO_TR_PLATFORM_1_2_1_0_6_7_AP,           --  AP=Y - Fittizia Per NYA
                        PO_TR_PLATFORM_1_2_1_0_6_7,
                        BINARIO_1,
                        BINARIO_2,
                        BINARIO_3,
                        BINARIO_4,
                        PO_TR_PLATFORM_1_2_1_0_6_4_B4,
                        PO_TR_PLATFORM_1_2_1_0_6_5_B4,
                        GRUPPO_AUTORIZZATIVO   )
                 Select Lpad(Nvl(PO_TR_PLATFORM_1_2_1_0_6_1, 83), 4, '0')
                        PO_TR_PLATFORM_1_2_1_0_6_1,
                        PO_TR_PLATFORM_1_2_1_0_6_2,
                        PO_TR_PLATFORM_1_2_1_0_6_2_D,
                        --PO_TR_PLATFORM_1_2_1_0_6_3_AP,
                        --PO_TR_PLATFORM_1_2_1_0_6_3,
                        --PO_TR_PLAT_1_2_1_0_6_4_B1_AP,
                        PO_TR_PLATFORM_1_2_1_0_6_4_B1,
                        --PO_TR_PLAT_1_2_1_0_6_4_B2_AP,
                        PO_TR_PLATFORM_1_2_1_0_6_4_B2,
                        --PO_TR_PLAT_1_2_1_0_6_4_B3_AP,
                        PO_TR_PLATFORM_1_2_1_0_6_4_B3,
                        --PO_TR_PLAT_1_2_1_0_6_5_B1_AP,
                        PO_TR_PLATFORM_1_2_1_0_6_5_B1,
                        --PO_TR_PLAT_1_2_1_0_6_5_B2_AP,
                        PO_TR_PLATFORM_1_2_1_0_6_5_B2,
                        --PO_TR_PLAT_1_2_1_0_6_5_B3_AP,
                        PO_TR_PLATFORM_1_2_1_0_6_5_B3,
                        -- PO_TR_PLATFORM_1_2_1_0_6_6_AP,
                        PO_TR_PLATFORM_1_2_1_0_6_6,
                        --PO_TR_PLATFORM_1_2_1_0_6_7_AP,
                        PO_TR_PLATFORM_1_2_1_0_6_7,
                        BINARIO_1,
                        BINARIO_2,
                        BINARIO_3,
                        BINARIO_4,
                        PO_TR_PLATFORM_1_2_1_0_6_4_B4,
                        PO_TR_PLATFORM_1_2_1_0_6_5_B4,
                        GRUPPO_AUTORIZZATIVO
                   From Rinf_Staging_Evo.CLASSE_R24700_PULITA
                  Where PO_TR_PLATFORM_1_2_1_0_6_2 = l_op_track(i).ID_PLATFORM
                    And PO_TR_PLATFORM_1_2_1_0_6_2 In
                      ( Select PO_TR_PLATFORM_1_2_1_0_6_2
                          From Rinf_Staging_Evo.CLASSE_R24700_PULITA
                         Where PO_TR_PLATFORM_1_2_1_0_6_2 = l_op_track(i).ID_PLATFORM
                       Minus
                        Select PO_TR_PLATFORM_1_2_1_0_6_2
                          From  Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
						);
--
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT   Loop 
--> loop				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp_1
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita_1
                     || ' NOME OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_localita_1
                     || ' PLATFORM: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_platform
                     || ' NOME PLATFORM: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_platform
                     || ' Errore: ' || SQLERRM (-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp_1
                                      || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita_1
                                      || ' PLATFORM: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_platform
                                      || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, NOME_SOL_PO,SEDE_TECNICA, NOME_SEDE_TECNICA,CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita_1 || ''',';
                  sqlstring := sqlstring || '''' || REPLACE ( l_op_track ( SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_localita_1, '''',   '''''') || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_platform || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_platform || ''',''R24700'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp_1 || ''')';
--
                  If     l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita_2   Is Not Null 
                     And l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita_2 <> l_op_track ( SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita_1
                   Then
                     Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,  'DTP: ' || l_op_track (  SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp_2
                        || ' OP: ' || l_op_track ( SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita_2
                        || 'NOME OP: ' || l_op_track (  SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_localita_2
                        || ' PLATFORM: ' || l_op_track ( SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_platform
                        || 'NOME PLATFORM: ' || l_op_track (  SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_platform
                        || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--
                     sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, NOME_SOL_PO,SEDE_TECNICA, NOME_SEDE_TECNICA,CLASSE,CODICE_ERRORE, CODICE_DTP)';
                     sqlstring := sqlstring || 'VALUES ( ';
                     sqlstring := sqlstring || n_acquisizione || ','''|| l_op_track ( SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita_2 || ''',';
                     sqlstring := sqlstring || ''''|| REPLACE ( l_op_track ( SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_localita_2, '''',  '''''') || ''',';
                     sqlstring := sqlstring || '''' || l_op_track ( SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_platform || ''',';
                     sqlstring := sqlstring || '''' || l_op_track ( SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_platform || ''',''R24700'', ';
                     sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                     sqlstring := sqlstring || '''' || l_op_track ( SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp_2 || ''')';
                  End If;
--
                  Dbms_Output.Put_Line (sqlstring);
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_TRACK_PLATF - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
   Else
      p_error := SQLCODE;
      Dbms_Output.Put_Line ('SetAcquisitionOP_TRACK_PLATF.1 - Errore: ' || Substr(SQLERRM, 1, 300));
   End If;
--  
END SetAcquisitionOP_TRACK_PLATF;
--
-- ------------------------------------------------------------------------------------------------   
--                      PROCEDURE SetAcquisitionOP_TRACK_EC
--                  DICHIARAZIONI dei BINARI di Punto Oprativo  (DICHIARAZIONI_BINARIO_PO)
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionOP_TRACK_EC (n_acquisizione       Number,
                                        p_error          Out Number )   Is
      i            Number;
      sqlstring    Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_LOCALITA     Rinf_Staging_Evo.CLASSE_R16000_LO.SEDE_TECNICA%Type,
         DESC_LOCALITA   Rinf_Staging_Evo.CLASSE_R03000.DEFINIZIONE%Type,
         ID_BINARIO      Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2%Type,
         DESC_BINARIO    Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2_D%Type,
         ID_DTP          Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type    );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
   BEGIN
      p_error := 0;
--
        Select Distinct 
		        o.SEDE_TECNICA            id_localita,
                o.DEFINIZIONE             desc_localita,
                l.PO_TRACK_1_2_1_0_0_2    id_binario,
                PO_TRACK_1_2_1_0_0_2_D    desc_binario,
                o.CODICE_DTP              id_dtp
           Bulk Collect Into             l_op_track
           From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA b,
                Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
                Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o
          Where l.PO_TRACK_1_2_1_0_0_2 = b.IDENTIFICATIVO_BINARIO
            And r.SEDE_TECNICA = o.SEDE_TECNICA
            And r.PO_TRACK_1_2_1_0_0_2 = l.PO_TRACK_1_2_1_0_0_2
            And CODICE_CARATTERISTICA In ('R16000_LO_1080', 'R16000_LO_1090','R16000_LO_1081', 'R16000_LO_1091')
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '||'Caricamento DICHIARAZIONI BINARI DI CIRCOLAZIONE DEI PO');
         Dbms_Output.Put_Line ( 'Caricamento DICHIARAZIONI BINARI DI CIRCOLAZIONE DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale DICHIARAZIONI BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,' '  );
         Dbms_Output.Put_Line ( 'Totale DICHIARAZIONI BINARI DI CIRCOLAZIONE DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--
            Insert Into Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_PO 
			         (  PO_TRACK_1_2_1_0_0_2,
                        TIPO_DICHIARAZIONE,
                        PO_TRACK_1_2_1_0_1_1O2_AP,
                        PO_TRACK_1_2_1_0_1_1O2,
                        KM_INIZIO,
                        KM_FINE,
                        LATITUDINE_INIZIO,
                        LONGITUDINE_INIZIO,
                        LATITUDINE_FINE,
                        LONGITUDINE_FINE,
                        FLAG_CALCOLATO	)
                 Select PO_TRACK_1_2_1_0_0_2,
                        TIPO_DICHIARAZIONE,
                        PO_TRACK_1_2_1_0_1_1O2_AP,
                        PO_TRACK_1_2_1_0_1_1O2,
                        KM_INIZIO,
                        KM_FINE,
                        LATITUDINE_INIZIO,
                        LONGITUDINE_INIZIO,
                        LATITUDINE_FINE,
                        LONGITUDINE_FINE,
                        0 FLAG_CALCOLATO
                  From (Select appl.IDENTIFICATIVO_BINARIO          PO_TRACK_1_2_1_0_0_2,
                               'EC'                                 TIPO_DICHIARAZIONE,
                               appl.VALORE_CARATTERISTICA           PO_TRACK_1_2_1_0_1_1O2_AP,
                               Nvl (val.VALORE_CARATTERISTICA, ' ') PO_TRACK_1_2_1_0_1_1O2,
                               Nvl (KM_INIZIO, 0)                   KM_INIZIO,
                               KM_FINE,
                               LATITUDINE_INIZIO,
                               LONGITUDINE_INIZIO,
                               LATITUDINE_FINE,
                               LONGITUDINE_FINE
                           From (Select CODICE_CARATTERISTICA,
                                        IDENTIFICATIVO_BINARIO,
                                        VALORE_CARATTERISTICA
                                   From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA
                                  Where CODICE_CARATTERISTICA In ('R16000_LO_1081')
					             ) appl,
                                (Select CODICE_CARATTERISTICA,
                                        IDENTIFICATIVO_BINARIO,
                                        VALORE_CARATTERISTICA,
                                        KM_INIZIO,
                                        KM_FINE,
                                        LATITUDINE_INIZIO,
                                        LONGITUDINE_INIZIO,
                                        LATITUDINE_FINE,
                                        LONGITUDINE_FINE
                                   From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA
                                  Where CODICE_CARATTERISTICA In ('R16000_LO_1080')
						        ) val
                   Where  appl.IDENTIFICATIVO_BINARIO = l_op_track(i).ID_BINARIO
                     And  appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+)
               Union
                Select appl.IDENTIFICATIVO_BINARIO,
                       'EI',
                       appl.VALORE_CARATTERISTICA,
                       Nvl (val.VALORE_CARATTERISTICA, ' '),
                       Nvl (KM_INIZIO, 0),
                       KM_FINE,
                       LATITUDINE_INIZIO,
                       LONGITUDINE_INIZIO,
                       LATITUDINE_FINE,
                       LONGITUDINE_FINE
                    From (Select CODICE_CARATTERISTICA,
                                 IDENTIFICATIVO_BINARIO,
                                 VALORE_CARATTERISTICA
                            From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA
                           Where CODICE_CARATTERISTICA In ('R16000_LO_1091')
				          ) appl,
                          ( Select CODICE_CARATTERISTICA,
                                   IDENTIFICATIVO_BINARIO,
                                   VALORE_CARATTERISTICA,
                                   KM_INIZIO,
                                   KM_FINE,
                                   LATITUDINE_INIZIO,
                                   LONGITUDINE_INIZIO,
                                   LATITUDINE_FINE,
                                   LONGITUDINE_FINE
                              From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA
                             Where CODICE_CARATTERISTICA In ('R16000_LO_1090')
				          ) val
                      Where appl.IDENTIFICATIVO_BINARIO = l_op_track(i).ID_BINARIO
                      And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO (+)
		              ) dic
                  Where (PO_TRACK_1_2_1_0_0_2,
                         TIPO_DICHIARAZIONE,
                         PO_TRACK_1_2_1_0_1_1O2,
                         KM_INIZIO) 
					in
                       ( 
					     (Select appl.IDENTIFICATIVO_BINARIO          PO_TRACK_1_2_1_0_0_2,
                                'EC'                                  TIPO_DICHIARAZIONE,
                                 Nvl (val.VALORE_CARATTERISTICA, ' ') PO_TRACK_1_2_1_0_1_1O2,
                                 Nvl (KM_INIZIO, 0)                   KM_INIZIO
                           From (Select CODICE_CARATTERISTICA,
                                         IDENTIFICATIVO_BINARIO,
                                         VALORE_CARATTERISTICA
                                    From  Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA
                                    Where CODICE_CARATTERISTICA In ('R16000_LO_1081')
								 ) appl,
                                (Select CODICE_CARATTERISTICA,
                                        IDENTIFICATIVO_BINARIO,
                                        VALORE_CARATTERISTICA,
                                        KM_INIZIO,
                                        KM_FINE
                                   From  Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA
                                   Where CODICE_CARATTERISTICA In ('R16000_LO_1080')
								) val
                           Where appl.IDENTIFICATIVO_BINARIO = l_op_track (i).ID_BINARIO
                             And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+)
                           Union
                          Select appl.IDENTIFICATIVO_BINARIO,
                                'EI',
                                Nvl (val.VALORE_CARATTERISTICA, ' '),
                                Nvl (KM_INIZIO, 0)
                           From (Select CODICE_CARATTERISTICA,
                                         IDENTIFICATIVO_BINARIO,
                                         VALORE_CARATTERISTICA
                                    From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA
                                   Where CODICE_CARATTERISTICA In ('R16000_LO_1091')
					            ) appl,
                               ( Select CODICE_CARATTERISTICA,
                                         IDENTIFICATIVO_BINARIO,
                                         VALORE_CARATTERISTICA,
                                         KM_INIZIO,
                                         KM_FINE,
                                         LATITUDINE_INIZIO,
                                         LONGITUDINE_INIZIO,
                                         LATITUDINE_FINE,
                                         LONGITUDINE_FINE
                                    From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA
                                   Where CODICE_CARATTERISTICA In ('R16000_LO_1090')
					            ) val
                             Where appl.IDENTIFICATIVO_BINARIO = l_op_track(i).ID_BINARIO
                             And  appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+)
						  )
                         Minus
                        Select PO_TRACK_1_2_1_0_0_2,
                               TIPO_DICHIARAZIONE,
                               PO_TRACK_1_2_1_0_1_1O2,
                               KM_INIZIO
                         From  Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_PO
			            );
--
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || 'NOME OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_localita
                     || ' BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || 'NOME BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_binario
                     || ' Errore: '  || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, NOME_SOL_PO,SEDE_TECNICA,NOME_SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_binario || ''',''R16000_MULTIPLA'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  --Dbms_Output.Put_Line (sqlstring);
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_TRACK_EC - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      End;
--
-- 26/01/2017 E' necessario recuperare le informazioni delle dichiarazioni dei binari di fermata da quelle dei binari di corsa SOL
         p_error := 0;
--
        Select Distinct 
		       o.SEDE_TECNICA            id_localita,
               o.DEFINIZIONE             desc_localita,
               l.PO_TRACK_1_2_1_0_0_2    d_binario,
               PO_TRACK_1_2_1_0_0_2_D    desc_binario,
               o.CODICE_DTP              id_dtp
          Bulk Collect Into              l_op_track
          From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA b,
               Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
               Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
               Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o
         Where l.PO_TRACK_1_2_1_0_0_2 = b.IDENTIFICATIVO_BINARIO
           And r.SEDE_TECNICA = o.SEDE_TECNICA
           And r.PO_TRACK_1_2_1_0_0_2 = l.PO_TRACK_1_2_1_0_0_2
           And CODICE_CARATTERISTICA In ('R16000_TR_0030', 'R16000_TR_0040','R16000_TR_0031', 'R16000_TR_0041')
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento DICHIARAZIONI BINARI DI FERMATA DEI PO');
         Dbms_Output.Put_Line ( 'Caricamento DICHIARAZIONI BINARI DI FERMATA DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale DICHIARAZIONI BINARI DI FERMATA DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
         Dbms_Output.Put_Line ( 'Totale DICHIARAZIONI BINARI DI FERMATA DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--
            Insert Into Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_PO 
			         (  PO_TRACK_1_2_1_0_0_2,
                        TIPO_DICHIARAZIONE,
                        PO_TRACK_1_2_1_0_1_1O2_AP,
                        PO_TRACK_1_2_1_0_1_1O2,
                        KM_INIZIO,
                        KM_FINE,
                        LATITUDINE_INIZIO,
                        LONGITUDINE_INIZIO,
                        LATITUDINE_FINE,
                        LONGITUDINE_FINE,
