                        PO_TRACK_1_2_1_0_1_1O2_AP,
                        PO_TRACK_1_2_1_0_1_1O2,
                        KM_INIZIO,
                        KM_FINE,
                        LATITUDINE_INIZIO,
                        LONGITUDINE_INIZIO,
                        LATITUDINE_FINE,
                        LONGITUDINE_FINE,
                        0 FLAG_CALCOLATO
                  From (Select appl.IDENTIFICATIVO_BINARIO PO_TRACK_1_2_1_0_0_2,
                               'EC' TIPO_DICHIARAZIONE,
                               appl.VALORE_CARATTERISTICA PO_TRACK_1_2_1_0_1_1O2_AP,
                               Nvl (val.VALORE_CARATTERISTICA, ' ') PO_TRACK_1_2_1_0_1_1O2,
                               Nvl (KM_INIZIO, 0) KM_INIZIO,
                               KM_FINE,
                               LATITUDINE_INIZIO,
                               LONGITUDINE_INIZIO,
                               LATITUDINE_FINE,
                               LONGITUDINE_FINE
                          From (Select CODICE_CARATTERISTICA,
                                       IDENTIFICATIVO_BINARIO,
                                       VALORE_CARATTERISTICA
                                  From  Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                                 Where  CODICE_CARATTERISTICA In ('R16000_TR_0031')
								 ) appl,
                               (Select CODICE_CARATTERISTICA,
                                       IDENTIFICATIVO_BINARIO,
                                       VALORE_CARATTERISTICA,
                                       KM_INIZIO,
                                       KM_FINE,
                                       LATITUDINE_INIZIO,
                                       LONGITUDINE_INIZIO,
                                       LATITUDINE_FINE,
                                       LONGITUDINE_FINE
                                  From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                                 Where CODICE_CARATTERISTICA In ('R16000_TR_0030')
								 ) val
                           Where appl.IDENTIFICATIVO_BINARIO = l_op_track(i).ID_BINARIO
                             And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+)
                       Union
                        Select appl.IDENTIFICATIVO_BINARIO,
                               'EI',
                               appl.VALORE_CARATTERISTICA,
                               Nvl (val.VALORE_CARATTERISTICA, ' '),
                               Nvl (KM_INIZIO, 0),
                               KM_FINE,
                               LATITUDINE_INIZIO,
                               LONGITUDINE_INIZIO,
                               LATITUDINE_FINE,
                               LONGITUDINE_FINE
                          From (Select CODICE_CARATTERISTICA,
                                       IDENTIFICATIVO_BINARIO,
                                       VALORE_CARATTERISTICA
                                  From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                                 Where CODICE_CARATTERISTICA In ('R16000_TR_0041')
								) appl,
                               (Select CODICE_CARATTERISTICA,
                                       IDENTIFICATIVO_BINARIO,
                                       VALORE_CARATTERISTICA,
                                       KM_INIZIO,
                                       KM_FINE,
                                       LATITUDINE_INIZIO,
                                       LONGITUDINE_INIZIO,
                                       LATITUDINE_FINE,
                                       LONGITUDINE_FINE
                                  From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                                 Where CODICE_CARATTERISTICA In ('R16000_TR_0040')
								 ) val
                           Where appl.IDENTIFICATIVO_BINARIO = l_op_track(i).ID_BINARIO
                             And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+)
							 ) dic
                 Where (PO_TRACK_1_2_1_0_0_2,
                        TIPO_DICHIARAZIONE,
                        PO_TRACK_1_2_1_0_1_1O2,
                        KM_INIZIO) In
                          ( 
						    (Select appl.IDENTIFICATIVO_BINARIO PO_TRACK_1_2_1_0_0_2,
                                    'EC' TIPO_DICHIARAZIONE,
                                    Nvl (val.VALORE_CARATTERISTICA, ' ') PO_TRACK_1_2_1_0_1_1O2,
                                    Nvl (KM_INIZIO, 0) KM_INIZIO
                               From (Select CODICE_CARATTERISTICA,
                                            IDENTIFICATIVO_BINARIO,
                                            VALORE_CARATTERISTICA
                                       From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                                      Where CODICE_CARATTERISTICA In ('R16000_TR_0031')
									 ) appl,
                                    (Select CODICE_CARATTERISTICA,
                                            IDENTIFICATIVO_BINARIO,
                                            VALORE_CARATTERISTICA,
                                            KM_INIZIO,
                                            KM_FINE
                                       From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                                      Where CODICE_CARATTERISTICA In ('R16000_TR_0030')
									 ) val
                              Where appl.IDENTIFICATIVO_BINARIO = l_op_track(i).ID_BINARIO
                                And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+)
                            Union
                             Select appl.IDENTIFICATIVO_BINARIO,
                                    'EI',
                                    Nvl (val.VALORE_CARATTERISTICA, ' '),
                                    Nvl (KM_INIZIO, 0)
                               From (Select CODICE_CARATTERISTICA,
                                            IDENTIFICATIVO_BINARIO,
                                            VALORE_CARATTERISTICA
                                       From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                                      Where CODICE_CARATTERISTICA In ('R16000_TR_0041')
									 ) appl,
                                    (Select CODICE_CARATTERISTICA,
                                            IDENTIFICATIVO_BINARIO,
                                            VALORE_CARATTERISTICA,
                                            KM_INIZIO,
                                            KM_FINE,
                                            LATITUDINE_INIZIO,
                                            LONGITUDINE_INIZIO,
                                            LATITUDINE_FINE,
                                            LONGITUDINE_FINE
                                       From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                                      Where CODICE_CARATTERISTICA In ('R16000_TR_0040')
									 ) val
                              Where appl.IDENTIFICATIVO_BINARIO = l_op_track(i).ID_BINARIO
                                And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+)
							 )
                            Minus
                             Select PO_TRACK_1_2_1_0_0_2,
                                    TIPO_DICHIARAZIONE,
                                    PO_TRACK_1_2_1_0_1_1O2,
                                    KM_INIZIO
                               From Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_PO
					      );
