-- --------------------------------------------------------------------------------------
-- Inserisco i binari di tratta Per i PO di fermata (CLASSE_R16000_LO_TR)
-- --------------------------------------------------------------------------------------
--
        Select Distinct l.SEDE_TECNICA     id_localita,
               l.DEFINIZIONE               desc_localita,
               PO_TRACK_1_2_1_0_0_2        id_binario,
               PO_TRACK_1_2_1_0_0_2_D      desc_binario,
               l.CODICE_DTP                id_dtp
          Bulk Collect Into l_op_track
          From Rinf_Staging_Evo.CLASSE_R16000_LO_TR b,
               Rinf_Lavorazione_Evo.PUNTI_OPERATIVI l,
               Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA m
         Where m.IDENTIFICATIVO_BINARIO = b.PO_TRACK_1_2_1_0_0_2
           And CODICE_CARATTERISTICA = 'R16000_LO_SFER'
           And l.SEDE_TECNICA = VALORE_CARATTERISTICA
           And b.PO_TRACK_1_2_1_0_0_2 Is Not Null
           And Length(b.PO_TRACK_1_2_1_0_0_2) >= 14
         Order by 1;

--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento BINARI DI FERMATA DEI PO');
         Dbms_Output.Put_Line ('Caricamento BINARI DI FERMATA DEI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale BINARI DI FERMATA DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
         Dbms_Output.Put_Line ( 'Totale BINARI DI FERMATA DEI PO da caricare: ' || To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.BINARI_CORSA_PO (
                      PO_TRACK_1_2_1_0_0_1,
                      PO_TRACK_1_2_1_0_0_2,
                      PO_TRACK_1_2_1_0_0_2_D,
                      --PO_TRACK_1_2_1_0_2_1_AP,       --  AP=Y - FITTIZIA PER NYA
                      --PO_TRACK_1_2_1_0_2_1,          -- IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO DA GALLI
                      PO_TRACK_1_2_1_0_2_2_AP,           --
                      --PO_TRACK_1_2_1_0_2_2,          -- IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO
                      PO_TRACK_1_2_1_0_2_3_AP,         -- EX FITTIZIA PER NYA
                      --PO_TRACK_1_2_1_0_2_3,          -- da relazione TRATTE_CORRIDOI
                      --PO_TRACK_1_2_1_0_3_1_AP,       -- AP=Y - FITTIZIA PER NYA
                      PO_TRACK_1_2_1_0_3_1,
                      PO_TRACK_1_2_1_0_3_2_AP,         -- 0.82 AGOSTO
                      PO_TRACK_1_2_1_0_3_2,
                      PO_TRACK_1_2_1_0_3_3_AP,         -- 0.82 AGOSTO
                      PO_TRACK_1_2_1_0_3_3,
                      --PO_TRACK_1_2_1_0_4_1_AP,       --  AP=Y - FITTIZIA PER NYA
                      PO_TRACK_1_2_1_0_4_1,
					  PO_TRACK_1_2_1_0_3_4_AP,             ---> nuovo parametro Reg.777/2019  - AP=Y
                      PO_TRACK_1_2_1_0_3_4_SUP,            ---> nuovo parametro Reg.777/2019
                      PO_TRACK_1_2_1_0_3_4_INF,            ---> nuovo parametro Reg.777/2019
                      PO_TRACK_1_2_1_0_3_5_AP,             ---> nuovo parametro Reg.777/2019  - AP=N
                      PO_TRACK_1_2_1_0_3_5_A,              ---> nuovo parametro Reg.777/2019
                      PO_TRACK_1_2_1_0_3_5_B,              ---> nuovo parametro Reg.777/2019
                      PO_TRACK_1_2_1_0_3_6_AP,             ---> nuovo parametro Reg.777/2019  - AP=N
                      PO_TRACK_1_2_1_0_3_6                 ---> nuovo parametro Reg.777/2019

					  )
               Select Distinct Lpad(Nvl(PO_TRACK_1_2_1_0_0_1,83), 4, '0') PO_TRACK_1_2_1_0_0_1,
                      PO_TRACK_1_2_1_0_0_2,
                      PO_TRACK_1_2_1_0_0_2_D,
                      --PO_TRACK_1_2_1_0_2_1_AP,
                      --PO_TRACK_1_2_1_0_2_1,
                      'Y' PO_TRACK_1_2_1_0_2_2_AP,         -- Sempre applicabile da xls Loretoni 24/11/2014
                      --PO_TRACK_1_2_1_0_2_2,              -- IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO
 --->                      PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_2_3(PO_TRACK_1_2_1_0_0_2) PO_TRACK_1_2_1_0_2_3_AP,     --->    modifica del 15/03/2021
                      PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_2_3(sol.SEDE_TECNICA) PO_TRACK_1_2_1_0_2_3_AP,       -- Gestito A Parte Perchè Parametro PIC
                      --PO_TRACK_1_2_1_0_2_3,
                      --PO_TRACK_1_2_1_0_3_1_AP,
                      PO_TRACK_1_2_1_0_3_1,
                      PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_3_2(Upper(PO_TRACK_1_2_1_0_3_1)) PO_TRACK_1_2_1_0_3_2_AP,       --0.82 AGOSTO
                      PO_TRACK_1_2_1_0_3_2,
                      PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_3_3(Upper(PO_TRACK_1_2_1_0_3_1), Upper(PO_TRACK_1_2_1_0_3_2)) PO_TRACK_1_2_1_0_3_3_AP,                --0.82 AGOSTO
                      PO_TRACK_1_2_1_0_3_3,
                      -- PO_TRACK_1_2_1_0_4_1_AP,
                      PO_TRACK_1_2_1_0_4_1,
--->
    				  Null PO_TRACK_1_2_1_0_3_4_AP,
                      SOL_TRACK_1_1_1_1_3_1_1_SUP ,
                      SOL_TRACK_1_1_1_1_3_1_1_INF,
--->                      
                      PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_3_5 PO_TRACK_1_2_1_0_3_5_AP,         ---> nuovo parametro Reg.777/2019 - AP=N
					  Null,
					  Null,
                      PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_3_6 PO_TRACK_1_2_1_0_3_6_AP,         ---> nuovo parametro Reg.777/2019 - AP=N
					  Null
                 From Rinf_Staging_Evo.CLASSE_R16000_LO_TR b,
                      Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA m,
					  Rinf_Staging_Evo.CLASSE_R16000_TR sol                                    ---> aggiunto per la valorizzazione dei parametri delle sagome dalle tratte
                Where m.IDENTIFICATIVO_BINARIO  =  b.PO_TRACK_1_2_1_0_0_2
                  And CODICE_CARATTERISTICA = 'R16000_LO_SFER'
				  And sol.SOL_TRACK_1_1_1_0_0_1(+) = b.PO_TRACK_1_2_1_0_0_2
                  And VALORE_CARATTERISTICA = l_op_track(i).ID_LOCALITA
                  And PO_TRACK_1_2_1_0_0_2 = l_op_track(i).ID_BINARIO
                  And PO_TRACK_1_2_1_0_0_2 In
                          (Select PO_TRACK_1_2_1_0_0_2 
				             From Rinf_Staging_Evo.CLASSE_R16000_LO_TR b,
                                  Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA m,
								  Rinf_Staging_Evo.CLASSE_R16000_TR sol
                            Where m.IDENTIFICATIVO_BINARIO  =  b.PO_TRACK_1_2_1_0_0_2
                              And CODICE_CARATTERISTICA = 'R16000_LO_SFER'
							  And sol.SOL_TRACK_1_1_1_0_0_1(+) = b.PO_TRACK_1_2_1_0_0_2
                              And VALORE_CARATTERISTICA = l_op_track(i).ID_LOCALITA
                              And PO_TRACK_1_2_1_0_0_2 = l_op_track(i).ID_BINARIO
                           Minus
                            Select PO_TRACK_1_2_1_0_0_2 
				              From Rinf_Lavorazione_Evo.BINARI_CORSA_PO
							);
--
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For Indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' NOME OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_localita
                     || ' BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' NOME BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_binario
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                      || ' BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                                      || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, NOME_SOL_PO,SEDE_TECNICA, NOME_SEDE_TECNICA,CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''';
                  sqlstring := sqlstring || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',''';
                  sqlstring := sqlstring || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_binario || ''',''R16000'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--				  
                  Dbms_Output.Put_Line (sqlstring);
                  EXECUTE IMMEDIATE sqlstring;
--
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_TRACK.2 - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--
-- --------------------------------------------------------------------------------------
-- Inserisco le relazioni binari-PO
-- --------------------------------------------------------------------------------------
--
        Select Distinct
               ID_LOCALITA,
               DESC_LOCALITA,
               ID_BINARIO,
               DESC_BINARIO,
               ID_DTP
          Bulk Collect Into l_op_track
          From ( Select b.SEDE_TECNICA id_localita,
                        l.DEFINIZIONE desc_localita,
                        b.PO_TRACK_1_2_1_0_0_2 id_binario,
                        b.PO_TRACK_1_2_1_0_0_2_D desc_binario,
                        l.CODICE_DTP id_dtp
                   From Rinf_Staging_Evo.CLASSE_R16000_LO b, 
			            Rinf_Lavorazione_Evo.PUNTI_OPERATIVI l,
		   			    Rinf_Lavorazione_Evo.BINARI_CORSA_PO c
                  Where l.SEDE_TECNICA = b.SEDE_TECNICA
                    And b.PO_TRACK_1_2_1_0_0_2 = c.PO_TRACK_1_2_1_0_0_2
                    And b.PO_TRACK_1_2_1_0_0_2 Is Not Null
                    And Length(b.PO_TRACK_1_2_1_0_0_2) >= 14
               Union
                 Select l.SEDE_TECNICA id_localita,
                        l.DEFINIZIONE desc_localita,
                        b.PO_TRACK_1_2_1_0_0_2 id_binario,
                        b.PO_TRACK_1_2_1_0_0_2_D desc_binario,
                        l.CODICE_DTP id_dtp
                   From Rinf_Staging_Evo.CLASSE_R16000_LO_TR b,
                        Rinf_Lavorazione_Evo.PUNTI_OPERATIVI l,
                        Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA m,
                        Rinf_Lavorazione_Evo.BINARI_CORSA_PO c
                  Where m.IDENTIFICATIVO_BINARIO = b.PO_TRACK_1_2_1_0_0_2
                    And CODICE_CARATTERISTICA ='R16000_LO_SFER'
                    And l.SEDE_TECNICA = VALORE_CARATTERISTICA
                    And b.PO_TRACK_1_2_1_0_0_2 = c.PO_TRACK_1_2_1_0_0_2
                    And b.PO_TRACK_1_2_1_0_0_2 Is Not Null
                    And Length(b.PO_TRACK_1_2_1_0_0_2) >=14  
				)
            Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '||'Caricamento RELAZIONE TRA BINARI E PO');
         Dbms_Output.Put_Line ('Caricamento RELAZIONE TRA BINARI E PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale RELAZIONE TRA BINARI E PO da caricare: '|| To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
         Dbms_Output.Put_Line ( 'Totale RELAZIONE TRA BINARI E PO da caricare: ' || To_Char(l_op_track.COUNT));
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA 
			            (PO_TRACK_1_2_1_0_0_2,     SEDE_TECNICA)
                 Values (l_op_track(i).ID_BINARIO, l_op_track(i).ID_LOCALITA);
--
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT   Loop 
--> loop				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' NOME OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_localita
                     || ' BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' NOME BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).desc_binario
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
