-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetAcquisitionPO_TK_CAT_TEN (n_acquisizione     Number,                   
                                         p_error       Out Number )   Is
      i             Number;
	  sqlstring     Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_LOCALITA     Rinf_Staging_Evo.CLASSE_R16000_LO.SEDE_TECNICA%Type,
         ID_BINARIO      Rinf_Staging_Evo.CLASSE_R16000_LO.PO_TRACK_1_2_1_0_0_2%Type,
         ID_DTP          Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type     );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
  BEGIN
      p_error := 0;
--
          Select Distinct 
		            o.SEDE_TECNICA         id_localita,
                    l.PO_TRACK_1_2_1_0_0_2 id_binario,
                    o.CODICE_DTP           id_dtp
               Bulk Collect Into           l_op_track
               From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA b,
                    Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
                    Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                    Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o
              Where l.PO_TRACK_1_2_1_0_0_2 = b.IDENTIFICATIVO_BINARIO
                And r.PO_TRACK_1_2_1_0_0_2 = l.PO_TRACK_1_2_1_0_0_2
                And r.SEDE_TECNICA = o.SEDE_TECNICA
                And CODICE_CARATTERISTICA = 'R16000_LO_1100'
              Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento PARAMETRO CATEGORIA TEN DEL BINARIO DI PO');
         Dbms_Output.Put_Line ( 'Caricamento PARAMETRO CATEGORIA TEN DEL BINARIO DI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale VALORI PARAMETRO CATEGORIA TEN DEL BINARIO DI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Dbms_Output.Put_Line ( 'Totale VALORI PARAMETRO CATEGORIA TEN DEL BINARIO DI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.PAR_1_2_1_0_2_1_CAT_TEN_PO (
                  PO_TRACK_1_2_1_0_0_2,
                  PO_TRACK_1_2_1_0_2_1,
                  KM_INIZIO,
                  KM_FINE,
                  LATITUDINE_INIZIO,
                  LONGITUDINE_INIZIO,
                  LATITUDINE_FINE,
                  LONGITUDINE_FINE,
                  FLAG_CALCOLATO)
           Select val.IDENTIFICATIVO_BINARIO,
                  val.VALORE_CARATTERISTICA,
                  KM_INIZIO,
                  KM_FINE,
                  LATITUDINE_INIZIO,
                  LONGITUDINE_INIZIO,
                  LATITUDINE_FINE,
                  LONGITUDINE_FINE,
                  0 FLAG_CALCOLATO
             From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA val
            Where val.IDENTIFICATIVO_BINARIO = l_op_track(i).ID_BINARIO
              And val.CODICE_CARATTERISTICA = 'R16000_LO_1100'
             And (val.IDENTIFICATIVO_BINARIO, val.VALORE_CARATTERISTICA) In
                         (Select val.IDENTIFICATIVO_BINARIO, val.VALORE_CARATTERISTICA
                            From Rinf_Staging_Evo.CLASSE_R16000_LO_MULTIPLA val
                           Where val.IDENTIFICATIVO_BINARIO = l_op_track(i).ID_BINARIO
                             And val.CODICE_CARATTERISTICA = 'R16000_LO_1100'
                         Minus
                          Select PO_TRACK_1_2_1_0_0_2, PO_TRACK_1_2_1_0_2_1
                            From Rinf_Lavorazione_Evo.PAR_1_2_1_0_2_1_CAT_TEN_PO
				          );
--
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
 				        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                      || ' BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                                      || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario || ''',''R16000_LO_MULTIPLA'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionPO_TK_CAT_TEN - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionPO_TK_CAT_TEN;
