--                          PAR_1_2_1_0_6_3_CAT_TEN_PL
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetAcquisitionPO_PL_CAT_TEN (n_acquisizione       Number,                   
                                        p_error          Out Number )   Is
      i             Number;
      sqlstring     Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_LOCALITA       Rinf_Staging_Evo.CLASSE_R03000.SEDE_TECNICA%Type,
         ID_MARCIAPIEDE    Rinf_Staging_Evo.CLASSE_R24700_MULTIPLA.PO_TR_PLATFORM_1_2_1_0_6_2%Type,
         ID_DTP            Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type  );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
   BEGIN
      p_error := 0;
--
        Select Distinct 
	           ID_LOCALITA,
               ID_PLATFORM,
               ID_DTP
          Bulk Collect Into l_op_track
          From 
          (Select o.SEDE_TECNICA               id_localita,
                  m.PO_TR_PLATFORM_1_2_1_0_6_2 id_platform,
                  o.CODICE_DTP                 id_dtp
             From Rinf_Staging_Evo.CLASSE_R24700_MULTIPLA b,
                  Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
                  Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                  Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o,
                  Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO m
            Where l.PO_TRACK_1_2_1_0_0_2 = m.BINARIO_1
              And b.PO_TR_PLATFORM_1_2_1_0_6_2 = m.PO_TR_PLATFORM_1_2_1_0_6_2
              And r.SEDE_TECNICA = o.SEDE_TECNICA
              And r.PO_TRACK_1_2_1_0_0_2 = l.PO_TRACK_1_2_1_0_0_2
              And CODICE_CARATTERISTICA ='R24700_0060'
         Union
           Select o.SEDE_TECNICA               id_localita,
                  m.PO_TR_PLATFORM_1_2_1_0_6_2 id_platform,
                  o.CODICE_DTP                 id_dtp
             From Rinf_Staging_Evo.CLASSE_R24700_MULTIPLA b,
                  Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
                  Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                  Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o,
                  Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO m
            Where l.PO_TRACK_1_2_1_0_0_2 = m.BINARIO_2
              And b.PO_TR_PLATFORM_1_2_1_0_6_2 = m.PO_TR_PLATFORM_1_2_1_0_6_2
              And r.SEDE_TECNICA = o.SEDE_TECNICA
              And r.PO_TRACK_1_2_1_0_0_2 = l.PO_TRACK_1_2_1_0_0_2
              And CODICE_CARATTERISTICA = 'R24700_0060'
          Union
           Select o.SEDE_TECNICA               id_localita,
                  m.PO_TR_PLATFORM_1_2_1_0_6_2 id_platform,
                  o.CODICE_DTP                 id_dtp
             From Rinf_Staging_Evo.CLASSE_R24700_MULTIPLA b,
                  Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
                  Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                  Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o,
                  Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO m
            Where l.PO_TRACK_1_2_1_0_0_2 = m.BINARIO_3
              And b.PO_TR_PLATFORM_1_2_1_0_6_2 = m.PO_TR_PLATFORM_1_2_1_0_6_2
              And r.SEDE_TECNICA = o.SEDE_TECNICA
              And r.PO_TRACK_1_2_1_0_0_2 = l.PO_TRACK_1_2_1_0_0_2
              And CODICE_CARATTERISTICA = 'R24700_0060'
          Union
           Select o.SEDE_TECNICA               id_localita,
                  m.PO_TR_PLATFORM_1_2_1_0_6_2 id_platform,
                  o.CODICE_DTP                 id_dtp
             From Rinf_Staging_Evo.CLASSE_R24700_MULTIPLA b,
                  Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
                  Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                  Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o,
                  Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO m
            Where l.PO_TRACK_1_2_1_0_0_2 = m.BINARIO_4
              And b.PO_TR_PLATFORM_1_2_1_0_6_2 = m.PO_TR_PLATFORM_1_2_1_0_6_2
              And r.SEDE_TECNICA = o.SEDE_TECNICA
              And r.PO_TRACK_1_2_1_0_0_2 = l.PO_TRACK_1_2_1_0_0_2
              And CODICE_CARATTERISTICA = 'R24700_0060')
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '||'Caricamento PARAMETRO CATEGORIA TEN DEL MARCIAPIEDE');
         Dbms_Output.Put_Line ( 'Caricamento PARAMETRO CATEGORIA TEN DEL MARCIAPIEDE');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale VALORI PARAMETRO CATEGORIA TEN DEL MARCIAPIEDE da caricare: '|| To_Char(l_op_track.COUNT));
         Dbms_Output.Put_Line ('Totale VALORI PARAMETRO CATEGORIA TEN DEL MARCIAPIEDE da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' '   );
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--
            Insert Into Rinf_Lavorazione_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL 
			          ( PO_TR_PLATFORM_1_2_1_0_6_2,
                        PO_TR_PLATFORM_1_2_1_0_6_3,
                        KM_INIZIO,
                        KM_FINE,
                        LATITUDINE_INIZIO,
                        LONGITUDINE_INIZIO,
                        LATITUDINE_FINE,
                        LONGITUDINE_FINE,
                        FLAG_CALCOLATO  )
                 Select val.PO_TR_PLATFORM_1_2_1_0_6_2,
                        val.VALORE_CARATTERISTICA,
                        KM_INIZIO,
                        KM_FINE,
                        LATITUDINE_INIZIO,
                        LONGITUDINE_INIZIO,
                        LATITUDINE_FINE,
                        LONGITUDINE_FINE,
                        0 FLAG_CALCOLATO
                   From Rinf_Staging_Evo.CLASSE_R24700_MULTIPLA val
                  Where val.PO_TR_PLATFORM_1_2_1_0_6_2 = l_op_track(i).ID_MARCIAPIEDE
                    And val.CODICE_CARATTERISTICA = 'R24700_0060'
                    And          (val.PO_TR_PLATFORM_1_2_1_0_6_2, val.VALORE_CARATTERISTICA) In
                          (Select val.PO_TR_PLATFORM_1_2_1_0_6_2, val.VALORE_CARATTERISTICA
                             From Rinf_Staging_Evo.CLASSE_R24700_MULTIPLA val
                            Where val.PO_TR_PLATFORM_1_2_1_0_6_2 = l_op_track(i).ID_MARCIAPIEDE
                              And val.CODICE_CARATTERISTICA = 'R24700_0060'
                           Minus
                            Select PO_TR_PLATFORM_1_2_1_0_6_2, PO_TR_PLATFORM_1_2_1_0_6_3
                             From  Rinf_Lavorazione_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL  
				           );
--
      EXCEPTION
         When OTHERS   Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT    Loop 
--				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_marciapiede
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ('DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' BINARIO: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_marciapiede
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_marciapiede || ''',''R24700_MULTIPLA'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionPO_PL_CAT_TEN - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      End;
--	  
   END SetAcquisitionPO_PL_CAT_TEN;
