      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
   BEGIN
      p_error := 0;
--
        Select Distinct 
	           l.SEDE_TECNICA      id_localita,
               b.PO_SD_1_2_2_0_0_2 id_binario,
               o.CODICE_DTP        id_dtp
          Bulk Collect Into               l_op_track
          From Rinf_Staging_Evo.CLASSE_R16100_MULTIPLA b,
               Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO l,
               Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o
