                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario || ''',''R16100_MULTIPLA'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
