--                        PROCEDURE SetAcquisitionOP_FermataTunnel
--                   GALLERIE_BINARI_PO/ REL_GALLERIE_BINARI_PO /DICHIARAZIONI_GALLERIE_BIN_PO
--   Questa procedura recupera dall'anagrafica delle gallerie di SOL le gallerie dei binari di fermata dei PO
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetAcquisitionOP_FermataTunnel (n_acquisizione Number, p_error Out Number)    Is
   i             Number;
   sqlstring     Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_LOCALITA     Rinf_Staging_Evo.CLASSE_R03000.SEDE_TECNICA%Type,
         ID_BINARIO      Rinf_Staging_Evo.CLASSE_R16000_LO_TR.PO_TRACK_1_2_1_0_0_2%Type,
         ID_GALLERIA     Rinf_Staging_Evo.CLASSE_R25350_TR.SOL_TUNNEL_1_1_1_1_8_2%Type,
         ID_DTP          Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type    );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_op_track   op_track_t;
   BEGIN
      p_error := 0;
--
       Select Distinct p.SEDE_TECNICA           id_localita,
                       r.PO_TRACK_1_2_1_0_0_2   id_binario,
                       b.SOL_TUNNEL_1_1_1_1_8_2 id_galleria,
                       p.CODICE_DTP             id_dtp
          Bulk Collect Into                     l_op_track
                  From Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                       Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL b,
                       Rinf_Lavorazione_Evo.PUNTI_OPERATIVI p
                 Where b.SOL_TRACK_1_1_1_0_0_1 = r.PO_TRACK_1_2_1_0_0_2 
	               And p.SEDE_TECNICA = r.SEDE_TECNICA
                Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento GALLERIE DEI BINARI DI FERMATA DI PO');
         Dbms_Output.Put_Line ( 'Caricamento GALLERIE DEI BINARI DI FERMATA DI PO');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale GALLERIE DEI BINARI DI FERMATA DI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Dbms_Output.Put_Line ( 'Totale GALLERIE DEI BINARI DI FERMATA DI PO da caricare: ' || To_Char(l_op_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' '  );
--
         Forall i In 1 .. l_op_track.COUNT SAVE EXCEPTIONS
--		 
--  Mapping dei campi delle gallerie PO con i campi delle Galleria SOL, la numerazione dei parametri è sfalzata
--  perchè le gall. SOL hanno più informazioni delle gall PO
            Insert Into Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO 
                  (   PO_TR_TUNNEL_1_2_1_0_5_1,
                      PO_TR_TUNNEL_1_2_1_0_5_2,
                      PO_TR_TUNNEL_1_2_1_0_5_2_D,
                      PO_TR_TUNNEL_1_2_1_0_5_5_AP,
                      PO_TR_TUNNEL_1_2_1_0_5_5,
                      PO_TR_TUNNEL_1_2_1_0_5_6_AP,
                      PO_TR_TUNNEL_1_2_1_0_5_6,
                      PO_TR_TUNNEL_1_2_1_0_5_7_AP,
                      PO_TR_TUNNEL_1_2_1_0_5_7,
                      PO_TR_TUNNEL_1_2_1_0_5_8_AP,
                      PO_TR_TUNNEL_1_2_1_0_5_8,
    				  PO_TR_TUNNEL_1_2_1_0_5_9_AP,
					  PO_TR_TUNNEL_1_2_1_0_5_9,
                      GALLERIA_PRINCIPALE,
                      CONFIGURAZIONE_GALLERIA,
                      GRUPPO_AUTORIZZATIVO    )
               Select SOL_TUNNEL_1_1_1_1_8_1,
                      SOL_TUNNEL_1_1_1_1_8_2,
                      SOL_TUNNEL_1_1_1_1_8_2_D,
                      SOL_TUNNEL_1_1_1_1_8_7_AP,
                      SOL_TUNNEL_1_1_1_1_8_7,
                      SOL_TUNNEL_1_1_1_1_8_9_AP,
                      SOL_TUNNEL_1_1_1_1_8_9,
                      SOL_TUNNEL_1_1_1_1_8_10_AP,
                      SOL_TUNNEL_1_1_1_1_8_10,
                      SOL_TUNNEL_1_1_1_1_8_11_AP,
                      SOL_TUNNEL_1_1_1_1_8_11,
                      PKG_RINF_APPLICABILITA.GetAP_1_2_1_0_5_9 (SOL_TUNNEL_1_1_1_1_8_10) PO_TR_TUNNEL_1_2_1_0_5_9_AP , 
					  Null PO_TR_TUNNEL_1_2_1_0_5_9,
                      GALLERIA_PRINCIPALE,
                      CONFIGURAZIONE_GALLERIA,
                      GRUPPO_AUTORIZZATIVO
                 From Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL
                Where SOL_TUNNEL_1_1_1_1_8_2 = l_op_track(i).ID_GALLERIA
                  And SOL_TUNNEL_1_1_1_1_8_2 In
                    (Select l_op_track(i).ID_GALLERIA From dual
                      Minus
                     Select PO_TR_TUNNEL_1_2_1_0_5_2 
					 From  Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO
					 ); --30/05/2016 inserita condizione che assicura l'univocitè del codice galleria
--
      EXCEPTION
         When OTHERS Then
            IF SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--> loop				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' OP: '|| l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                     || ' GALLERIA: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_galleria
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' OP: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita
                                      || ' GALLERIA: ' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_galleria
                                      || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_localita || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_galleria || ''',''R25350_TR'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_op_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionOP_FermataTunnel - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;

--  Relazioni tra Gallerie e Binari
--
       Select Distinct 
	           p.SEDE_TECNICA           id_localita,
               r.PO_TRACK_1_2_1_0_0_2   id_binario,
               b.SOL_TUNNEL_1_1_1_1_8_2 id_galleria,
               p.CODICE_DTP             id_dtp
          Bulk Collect Into             l_op_track
          From Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
               Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL b,
               Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO g,
               Rinf_Lavorazione_Evo.PUNTI_OPERATIVI p
         Where b.SOL_TRACK_1_1_1_0_0_1 = r.PO_TRACK_1_2_1_0_0_2 
           And g.PO_TR_TUNNEL_1_2_1_0_5_2 = b.SOL_TUNNEL_1_1_1_1_8_2 
           And p.SEDE_TECNICA = r.SEDE_TECNICA;
--
      BEGIN
