-- ------------------------------------------------------------------------------------------------   
--            ************   PROCEDURE SetAcquisitionOP   *************
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetAcquisitionOP (n_acquisizione     Number, 
                             p_error        Out Number )    Is
  BEGIN
   p_error := 0;

   SetAcquisitionOP_PO (n_acquisizione, p_error);

   If p_error = 0 Then
      SetAcquisitionOP_BorderPoint (n_acquisizione, p_error);  --23/07/2015 caricamento delle località di confine

      If p_error = 0 Then
         COMMIT;
         SetAcquisitionOP_Multipla (p_error);
 /*
    If p_error = 0 Then
         COMMIT;
         SetAcquisitionPO_DOC_NORME (p_error);
*/
--
         If p_error = 0 Then
            COMMIT;
            SetAcquisitionPO_TAF_TAP(n_acquisizione, p_error);
--
             If p_error = 0 Then
                COMMIT;
                SetAcquisitionOP_TRACK (n_acquisizione, p_error);
--
                If p_error = 0 Then
                   COMMIT;
                   SetAcquisitionOP_TRACK_EC (n_acquisizione, p_error);
--
                   If p_error = 0 Then
                      COMMIT;
                      SetAcquisitionOP_TRACK_TUNNEL (n_acquisizione, p_error);
--
                      If p_error = 0 Then
                         COMMIT;
                         SetAcquisitionOP_TRK_TUNNEL_EC (n_acquisizione, p_error);
--
                         If p_error = 0 Then
                            COMMIT;
                            SetAcquisitionOP_TRACK_PLATF (n_acquisizione, p_error);
--
                            If p_error = 0 Then
                               COMMIT;
                               SetAcquisitionOP_SIDING (n_acquisizione, p_error);
--
                               If p_error = 0 Then
                                  COMMIT;
                                  SetAcquisitionOP_SIDING_EC (n_acquisizione,  p_error);
--
                                  If p_error = 0 Then
                                     COMMIT;
                                     SetAcquisitionOP_SIDING_TUNNEL (n_acquisizione, p_error);
--
                                     If p_error = 0 Then
                                        COMMIT;
                                        SetAcquisitionOP_SD_TUNNEL_EC (n_acquisizione, p_error);
--
                                        If p_error = 0 Then
                                           COMMIT;
                                           SetAcquisitionPO_TK_CAT_TEN (n_acquisizione, p_error);
--
                                           If p_error = 0 Then
                                              COMMIT;
                                              SetAcquisitionPO_TK_CAT_LINEA (n_acquisizione, p_error);
--
                                              If p_error = 0 Then
                                                 COMMIT;
                                                 SetAcquisitionPO_PL_CAT_TEN (n_acquisizione, p_error);
--
                                                 If p_error = 0 Then
                                                    COMMIT;
                                                    SetAcquisitionPO_SD_CAT_TEN (n_acquisizione, p_error);
--
                                                    If p_error = 0 Then
                                                       COMMIT;
--
                                                    End If;
                                                 End If;
                                              End If;
                                           End If;
                                        End If;
                                     End If;
                                  End If;
                               End If;
                            End If;
                         End If;
                      End If;
                   End If;
                End If;
             End If;
          End If;
-- End If;
      End If;
   End If;
--   
END SetAcquisitionOP;
