-- ------------------------------------------------------------------------------------------------   
--                          FUNCTION GetLOTAF_TAP
--      Restituisce il codice TAF/TAP del Punto Operativo a partire dal codice MIR
-- ------------------------------------------------------------------------------------------------   
--
 Function GetLOTAF_TAP(s_SEDE_TECNICA Varchar2)
    RETURN Varchar2 Is
      CODICE_TAF_TAP Varchar2(10);
 BEGIN
--
 Select 'IT'||Substr(CODICE_MIR, 2) into CODICE_TAF_TAP
 From  Rinf_Staging_Evo.CLASSE_R03000
 Where SEDE_TECNICA = s_SEDE_TECNICA;

 If CODICE_TAF_TAP Is Null Then
     Select 'IT'||Substr(CODICE_MIR, 2) into CODICE_TAF_TAP
      From  Rinf_Controllati_Evo.PUNTI_OPERATIVI
      Where SEDE_TECNICA = s_SEDE_TECNICA;
 End If;
 --
    RETURN  CODICE_TAF_TAP;
 END GetLOTAF_TAP;
