-- ------------------------------------------------------------------------------------------------   
--                      PROCEDURE SetAcquisitionSOL_SOL
--                        Tratte (SEZIONI_LINEA)
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionSOL_SOL (n_acquisizione       Number,
                                    p_error          Out Number  )    Is
      i           Number;
      sqlstring   Varchar2(5000);
      TYPE dtp_sol_rt IS RECORD
      (  ID_DTP   Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type,
         ID_SOL   Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type  );
      TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
      l_dtp_sol   dtp_sol_t;
   BEGIN
      p_error := 0;
--
--  ATTENZIONE: se si cambiano le condizioni della Where, cambiare le corrispondenti nella procedura SetLogOfAcquisition(04/09/2015)
        Select codice_dtp, SEDE_TECNICA
          Bulk Collect Into l_dtp_sol
          From Rinf_Staging_Evo.CLASSE_R13000
         Where STATO_SISTEMA =  'CREA'     
           And STATO_UTENTE  =  'ESER IPIC' 
		   And CODICE_DTP   <>  'DG00'
        Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,'--------------------------------> '|| 'Caricamento SEZIONI DI LINEA');
         Dbms_Output.Put_Line ('Caricamento SEZIONI DI LINEA');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale SEZIONI DI LINEA da caricare: ' || To_Char(l_dtp_sol.Count));
         Dbms_Output.Put_Line ( 'Totale SEZIONI DI LINEA da caricare: '|| To_Char(l_dtp_sol.Count));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' '  );
--
         Forall i In 1 .. l_dtp_sol.Count Save EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.SEZIONI_LINEA 
			        ( SEDE_TECNICA,
                      DEFINIZIONE,
                      STATO_SISTEMA,
                      STATO_UTENTE,
                      LOCALITA_CONTENITORE,
                      LOCALITA_INIZIO,
                      LOCALITA_FINE,
                      KM_INIZIO,
                      KM_FINE,
                      SOL_1_1_0_0_0_1,
                      --SOL_1_1_0_0_0_2,              --da PIC LINEE_COMM
                      --SOL_1_1_0_0_0_2_D,
                      SOL_1_1_0_0_0_3,
                      SOL_1_1_0_0_0_4,
                      SOL_1_1_0_0_0_5,
                      SOL_1_1_0_0_0_6,
                      REGIME_CIRCOLAZIONE,
                      CODICE_LINEA_TECNICA,
                      CODICE_DTP,
                      CODICE_UT 	)
               Select t.SEDE_TECNICA,
                      t.DEFINIZIONE,
                      t.STATO_SISTEMA,
                      t.STATO_UTENTE,
                      t.LOCALITA_CONTENITORE,
                      t.LOCALITA_INIZIO,
                      t.LOCALITA_FINE,
                      t.KM_INIZIO,
                      t.KM_FINE,
                      Lpad(Nvl(t.SOL_1_1_0_0_0_1, 83), 4, '0'),
                      --SOL_1_1_0_0_0_2,
                      --SOL_1_1_0_0_0_2_D,
                      --GetLOTAF_TAP(LOCALITA_INIZIO),
                      i.PO_1_2_0_0_0_2 SOL_1_1_0_0_0_3,
                      --GetLOTAF_TAP(LOCALITA_FINE),
                      f.PO_1_2_0_0_0_2 SOL_1_1_0_0_0_4,
                      Nvl(r.LUNGHEZZA, t.SOL_1_1_0_0_0_5) SOL_1_1_0_0_0_5,   --  la lunghezza della tratta la prendo da Roman
                      --t.SOL_1_1_0_0_0_6,                                   --  al momento calcolato da noi, a regime ci arriva valorizzato da IN.RETE
                      Case When t.LOCALITA_CONTENITORE Is Null 
					       Then  'R'
                           Else  'L'
                      End SOL_1_1_0_0_0_6,
                      t.REGIME_CIRCOLAZIONE,
                      t.CODICE_LINEA_TECNICA,
                      t.CODICE_DTP,
                      t.CODICE_UT
                 From Rinf_Staging_Evo.CLASSE_R13000 t,
--				 
                     (Select p.SEDE_TECNICA, Sum(p.LUNGHEZZA)/1000 LUNGHEZZA
                         From  Rinf_Anagrafiche_Evo.TRATTE_PIC p,
                              (Select SEDE_TECNICA, Max(Nvl(DATA_SCADENZA, To_Date('01019999', 'DDMMYYYY'))) DATA_VAL_PIC
                                From  Rinf_Anagrafiche_Evo.TRATTE_PIC
                                Group By SEDE_TECNICA
							   ) dp
                         Where  p.FLAG_DISPARI = 1
                           And  Nvl(p.DATA_INIZIO_VALIDITA, to_date('31121900','ddmmyyyy')) <= data_riferimento
                           And  Nvl(p.DATA_FINE_VALIDITA,   to_date('31129999','ddmmyyyy')) > data_riferimento 
                           And  dp.SEDE_TECNICA = p.SEDE_TECNICA 
                           And  Nvl(p.DATA_SCADENZA, To_Date('01019999', 'DDMMYYYY')) = dp.DATA_VAL_PIC
                          group by p.SEDE_TECNICA
						 ) r,
                       Rinf_Lavorazione_Evo.PUNTI_OPERATIVI i,
                       Rinf_Lavorazione_Evo.PUNTI_OPERATIVI f
                Where  t.LOCALITA_INIZIO = i.SEDE_TECNICA
                   And t.LOCALITA_FINE   = f.SEDE_TECNICA
                   And t.LOCALITA_INIZIO Is Not Null
                   And t.LOCALITA_FINE   Is Not Null
                   And t.SEDE_TECNICA = r.SEDE_TECNICA (+)
                   And t.CODICE_DTP   = l_dtp_sol(i).ID_DTP
                   And t.SEDE_TECNICA = l_dtp_sol(i).ID_SOL;
--
--  Nella query sopra:
--  19/01/2016 aggiunta selezione data scadenza massima per gestire la molteplicità dei record,
--  ad esempio nel caso di un record con scadenza sysdate ed uno con scadenza Nulla,
--  deve essere preso in considerazione quello con scadenza Null. 
--  Nel caso di due record con data scadenza valorizzata, viene considerato quello con data maggiore
--
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.Count);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.Count);
--> loop
               For indx In 1 .. SQL%BULK_EXCEPTIONS.Count  Loop 

                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).Error_Index).id_dtp
                     || ' SOL: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).Error_Index).id_sol
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).Error_Index).id_dtp
                                     || ' SOL: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).Error_Index).id_sol
                                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).Error_Code);
--									 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE, CODICE_ERRORE, CODICE_DTP) ';
                  sqlstring := sqlstring || 'Values ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).Error_Index).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).Error_Index).id_sol || ''',''R13000'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).Error_Index).id_dtp || ''')';

                  EXECUTE IMMEDIATE sqlstring;
--> end loop			  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_SOL - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionSOL_SOL;
--
-- ------------------------------------------------------------------------------------------------   
--                  PROCEDURE SetAcquisitionSOL_TRACK
--          Binari di circolazione delle tratte (BINARI_CORSA_SOL)
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetAcquisitionSOL_TRACK (n_acquisizione       Number,
                                     p_error          Out Number  )   Is
      i           Number;
      sqlstring   Varchar2(5000);
      TYPE dtp_sol_rt IS RECORD
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOl_TRACK_1_1_1_0_0_1%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type );
      TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
      l_dtp_sol   dtp_sol_t;
   BEGIN
      p_error := 0;
--
      Select s.SEDE_TECNICA        id_sol,
             SOl_TRACK_1_1_1_0_0_1 id_binario,     ---> corretto il 18/03/2020 (era id_sol)
             s.CODICE_DTP          id_dtp
        Bulk Collect Into l_dtp_sol
        From Rinf_Staging_Evo.CLASSE_R16000_TR c, 
		     Rinf_Lavorazione_Evo.SEZIONI_LINEA s
       Where s.SEDE_TECNICA = c.SEDE_TECNICA
         And SOl_TRACK_1_1_1_0_0_1 Is Not Null
         And Length(SOl_TRACK_1_1_1_0_0_1) >= 14
       Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,'--------------------------------> '|| 'Caricamento BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA');
         Dbms_Output.Put_Line ('Caricamento BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA da caricare: ' || To_Char(l_dtp_sol.Count));
         Dbms_Output.Put_Line ( 'Totale BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA da caricare: ' || To_Char(l_dtp_sol.Count));
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, ' ' );
