                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_2_9(Upper(SOL_TRACK_1_1_1_3_2_1)) SOL_TRACK_1_1_1_3_2_9_AP,
--                GetAPMultipla ('CLASSE_R16000_TR_MULTIPLA', 'R16000_TR_0633', 'IDENTIFICATIVO_BINARIO', SOL_TRACK_1_1_1_0_0_1) SOL_TRACK_1_1_1_3_2_9_AP,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_2_10(Upper(SOL_TRACK_1_1_1_3_2_1)) SOL_TRACK_1_1_1_3_2_10_AP,	 
                SOL_TRACK_1_1_1_3_2_10,	 
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_3_1(Upper(SOL_TRACK_1_1_1_3_3_1)) SOL_TRACK_1_1_1_3_3_3_1_AP, 
 --               Case when PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_3_1 (Upper(SOL_TRACK_1_1_1_3_3_3_1)) = 'Y' Then   -- correzione del 5/5/2021
                Case when PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_3_1 (Upper(SOL_TRACK_1_1_1_3_3_1)) = 'Y' Then   -- correzione del 5/5/2021
                      Nvl(SOL_TRACK_1_1_1_3_3_3_1, PKG_RINF_CONTROLLO_V082.GetValue_InteraRete('1.1.1.3.3.3.1') ) 
                      Else Null 
			    End SOL_TRACK_1_1_1_3_3_3_1,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_3_2(Upper(SOL_TRACK_1_1_1_3_3_1), Upper(SOL_TRACK_1_1_1_3_2_1)) SOL_TRACK_1_1_1_3_3_3_2_AP,
                SOL_TRACK_1_1_1_3_3_3_2,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_3_3 SOL_TRACK_1_1_1_3_3_3_3_AP,      --AP=N
                SOL_TRACK_1_1_1_3_3_3_3,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_4(Upper(SOL_TRACK_1_1_1_3_3_1)) SOL_TRACK_1_1_1_3_3_4_AP,
                SOL_TRACK_1_1_1_3_3_4,
--                GetAPMultipla ('CLASSE_R16000_TR_MULTIPLA', 'R16000_TR_0664', 'IDENTIFICATIVO_BINARIO', SOL_TRACK_1_1_1_0_0_1)  SOL_TRACK_1_1_1_3_3_5_AP,
				PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_5(Upper(SOL_TRACK_1_1_1_3_3_1)) SOL_TRACK_1_1_1_3_3_5_AP,
				PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_6(Upper(SOL_TRACK_1_1_1_3_3_1)) SOL_TRACK_1_1_1_3_3_6_AP,
                SOL_TRACK_1_1_1_3_3_6,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_7(Upper(SOL_TRACK_1_1_1_3_3_1), Upper(SOL_TRACK_1_1_1_3_3_6))  SOL_TRACK_1_1_1_3_3_7_AP,
                SOL_TRACK_1_1_1_3_3_7,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_8(Upper(SOL_TRACK_1_1_1_3_3_1)) SOL_TRACK_1_1_1_3_3_8_AP,
                SOL_TRACK_1_1_1_3_3_8,
--                 GetAPMultipla('CLASSE_R16000_TR_MULTIPLA', 'R16000_TR_0668', 'IDENTIFICATIVO_BINARIO', SOL_TRACK_1_1_1_0_0_1)  SOL_TRACK_1_1_1_3_3_9_AP,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_9(Upper(SOL_TRACK_1_1_1_3_3_1)) SOL_TRACK_1_1_1_3_3_9_AP,
--                 GetAPMultipla('CLASSE_R16000_TR_MULTIPLA', 'R16000_TR_0669', 'IDENTIFICATIVO_BINARIO', SOL_TRACK_1_1_1_0_0_1)  SOL_TRACK_1_1_1_3_3_10_AP,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_3_10(Upper(SOL_TRACK_1_1_1_3_3_1)) SOL_TRACK_1_1_1_3_3_10_AP,
                GetAPMultipla('CLASSE_R16000_TR_MULTIPLA', 'R16000_TR_0693', 'IDENTIFICATIVO_BINARIO', SOL_TRACK_1_1_1_0_0_1)   SOL_TRACK_1_1_1_3_5_3_AP,         -- AP=Y
-->
--                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_7_1_1(Upper(SOL_TRACK_1_1_1_3_7_1))  SOL_TRACK_1_1_1_3_7_1_1_AP,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_7_1_1(SOL_TRACK_1_1_1_3_7_1_1)  SOL_TRACK_1_1_1_3_7_1_1_AP,
                GetPARValue('1.1.1.3.7.1.1', 2, SOL_TRACK_1_1_1_3_7_1_1) SOL_TRACK_1_1_1_3_7_1_1,
-->
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_7_1_2(SOL_TRACK_1_1_1_3_7_1_1, Upper(SOL_TRACK_1_1_1_3_7_1_2)) SOL_TRACK_1_1_1_3_7_1_2_AP,
                SOL_TRACK_1_1_1_3_7_1_2,
 --                GetAPMultipla('CLASSE_R16000_TR_MULTIPLA', 'R16000_TR_nnnn', 'IDENTIFICATIVO_BINARIO', SOL_TRACK_1_1_1_0_0_1) SOL_TRACK_1_1_1_3_7_1_3_AP,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_7_1_3(Upper(SOL_TRACK_1_1_1_3_7_1_2))  SOL_TRACK_1_1_1_3_7_1_3_AP,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_7_1_4 SOL_TRACK_1_1_1_3_7_1_4_AP,         --AP=N -->NYA
                SOL_TRACK_1_1_1_3_7_1_4,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_7_11_1(Upper(SOL_TRACK_1_1_1_3_7_1_1)) SOL_TRACK_1_1_1_3_7_11_1_AP,
  --               SOL_TRACK_1_1_1_3_7_11_1,          --PAR_1_1_1_3_7_11_1_CARMIN_ASSE
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_11_2 SOL_TRACK_1_1_1_3_11_2_AP,  --  AP=Y
                Nvl(SOL_TRACK_1_1_1_3_11_2, PKG_RINF_CONTROLLO_V082.GetValue_InteraRete('1.1.1.3.11.2')) SOL_TRACK_1_1_1_3_11_2,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_3_11_3('Y') SOL_TRACK_1_1_1_3_11_3_AP,
                Nvl(SOL_TRACK_1_1_1_3_11_3,  PKG_RINF_CONTROLLO_V082.GetValue_InteraRete('1.1.1.3.11.3')) SOL_TRACK_1_1_1_3_11_3,
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_4_1   SOL_TRACK_1_1_1_4_1_AP	,                          --AP=Y
                SOL_TRACK_1_1_1_4_1,	    
                PKG_RINF_APPLICABILITA.GetAP_1_1_1_4_2 (Upper(SOL_TRACK_1_1_1_4_1)) SOL_TRACK_1_1_1_4_2_AP	
               From Rinf_Staging_Evo.CLASSE_R16000_TR
              Where SEDE_TECNICA = l_dtp_sol(i).ID_SOL
                And SOL_TRACK_1_1_1_0_0_1 = l_dtp_sol(i).ID_BINARIO;
--				   
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'SetAcquisitionSOL_TRACK - Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--> loop 
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT Loop 
--				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' BINARIO: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' BINARIO: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE, CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario || ''',''R16000'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop 				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionSOL_TRACK;
--
-- ------------------------------------------------------------------------------------------------   
--                PROCEDURE SetAcquisitionSOL_TRACK_INF_EC
--                      DICHIARAZIONI_BINARIO_SOL_INF
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionSOL_TRACK_INF_EC (n_acquisizione     Number,
                                             p_error        Out Number )    Is
      i             Number;
      sqlstring     Varchar2 (3000);
      TYPE dtp_sol_rt IS RECORD
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOl_TRACK_1_1_1_0_0_1%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type  );
      TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
      L_SOL_TRACK   dtp_sol_t;
   BEGIN
      p_error := 0;
-- INFRASTRUTTURA
        Select Distinct s.SEDE_TECNICA        id_sol,
                        SOl_TRACK_1_1_1_0_0_1 id_binario,
                        s.CODICE_DTP          id_dtp
          Bulk Collect Into                   l_sol_track
          From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA c,
               Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA s
         Where s.SEDE_TECNICA = b.SEDE_TECNICA
           And SOl_TRACK_1_1_1_0_0_1 = c.IDENTIFICATIVO_BINARIO
           And CODICE_CARATTERISTICA In ('R16000_TR_0030', 'R16000_TR_0040','R16000_TR_0031', 'R16000_TR_0041')
          Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA INFRASTRUTTURA');
         Dbms_Output.Put_Line ( 'Caricamento DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA INFRASTRUTTURA');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA INFRASTRUTTURA da caricare: ' || To_Char (l_sol_track.Count));
         Dbms_Output.Put_Line ( 'Totale DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA INFRASTRUTTURA da caricare: ' || To_Char (l_sol_track.Count));
--
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' '  );
--
         Forall i In 1 .. l_sol_track.Count Save EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_SOL_INF 
			      ( SOL_TRACK_1_1_1_0_0_1,
                    TIPO_DICHIARAZIONE,
                    SOL_TRACK_1_1_1_1_1_1O2_AP,
                    SOL_TRACK_1_1_1_1_1_1O2,
                    KM_INIZIO,
                    KM_FINE,
                    LATITUDINE_INIZIO,
                    LONGITUDINE_INIZIO,
                    LATITUDINE_FINE,
                    LONGITUDINE_FINE,
                    FLAG_CALCOLATO   )
             Select appl.IDENTIFICATIVO_BINARIO,
                    'EC',
                    appl.VALORE_CARATTERISTICA,
                    Nvl(val.VALORE_CARATTERISTICA, ' '),
                    Nvl(KM_INIZIO, 0),
                    KM_FINE,
                    LATITUDINE_INIZIO,
                    LONGITUDINE_INIZIO,
                    LATITUDINE_FINE,
                    LONGITUDINE_FINE,
                    FLAG_CALCOLATO
               From (Select CODICE_CARATTERISTICA,
                            IDENTIFICATIVO_BINARIO,
                            VALORE_CARATTERISTICA
                       From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                      Where CODICE_CARATTERISTICA In ('R16000_TR_0031')
  					) appl,
                    (Select CODICE_CARATTERISTICA,
                            IDENTIFICATIVO_BINARIO,
                            VALORE_CARATTERISTICA,
                            KM_INIZIO,
                            KM_FINE,
 -- 29/01/2018 Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                            Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                 Then GetLatLonFromKm(l_sol_track (i).ID_SOL, KM_INIZIO, 1)
                                 Else LATITUDINE_INIZIO
                            End LATITUDINE_INIZIO,
                            Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                 Then GetLatLonFromKm(l_sol_track (i).ID_SOL, KM_INIZIO, 2)
                                 Else LONGITUDINE_INIZIO
                            End LONGITUDINE_INIZIO,
                            Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                                 Then GetLatLonFromKm(l_sol_track (i).ID_SOL, KM_FINE, 1)
                                 Else LATITUDINE_FINE
                            End LATITUDINE_FINE,
                            Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                                 Then GetLatLonFromKm(l_sol_track (i).ID_SOL, KM_FINE, 2)
                                 Else LONGITUDINE_FINE
                            End LONGITUDINE_FINE,
                            Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                 Then GetLatLonFromKm(l_sol_track (i).ID_SOL, KM_INIZIO, 3)
                                 Else 0
                            End FLAG_CALCOLATO
                       From  Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                      Where  CODICE_CARATTERISTICA In ('R16000_TR_0030')
  					) val
               Where appl.IDENTIFICATIVO_BINARIO = l_sol_track (i).ID_BINARIO
                 And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+)
            Union
             Select appl.IDENTIFICATIVO_BINARIO,
                    'EI',
                    appl.VALORE_CARATTERISTICA,
                    Nvl(val.VALORE_CARATTERISTICA, ' '),
                    Nvl(KM_INIZIO, 0),
                    KM_FINE,
                    LATITUDINE_INIZIO,
                    LONGITUDINE_INIZIO,
                    LATITUDINE_FINE,
                    LONGITUDINE_FINE,
                    FLAG_CALCOLATO
               From (Select CODICE_CARATTERISTICA,
                            IDENTIFICATIVO_BINARIO,
                            VALORE_CARATTERISTICA
                       From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                      Where CODICE_CARATTERISTICA In ('R16000_TR_0041')
  					) appl,
                    (Select CODICE_CARATTERISTICA,
                            IDENTIFICATIVO_BINARIO,
                            VALORE_CARATTERISTICA,
                            KM_INIZIO,
                            KM_FINE,
  -- 29/01/2018 Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                            Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                 Then GetLatLonFromKm(l_sol_track (i).id_sol, KM_INIZIO, 1)
                                 Else LATITUDINE_INIZIO
                            End LATITUDINE_INIZIO,
                            Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                 Then GetLatLonFromKm(l_sol_track (i).id_sol, KM_INIZIO, 2)
                                 Else LONGITUDINE_INIZIO
                            End LONGITUDINE_INIZIO,
                            Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                                 Then GetLatLonFromKm(l_sol_track (i).id_sol,KM_FINE, 1)
                                 Else LATITUDINE_FINE
                            End LATITUDINE_FINE,
                            Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                                 Then GetLatLonFromKm(l_sol_track (i).id_sol,KM_FINE, 2)
                                 Else LONGITUDINE_FINE
                            End LONGITUDINE_FINE,
                            Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                 Then GetLatLonFromKm(l_sol_track (i).id_sol,KM_INIZIO, 3)
                                 Else 0
                            End FLAG_CALCOLATO
                       From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                      Where CODICE_CARATTERISTICA In ('R16000_TR_0040')
					) val
             Where appl.IDENTIFICATIVO_BINARIO = l_sol_track (i).ID_BINARIO
               And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+);
--
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT Loop 
--> loop 				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                                      || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                                      || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario || ''',''R16000_MULTIPLA - INF'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop 				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_INF_EC - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionSOL_TRACK_INF_EC;
--
-- ------------------------------------------------------------------------------------------------   
--                   PROCEDURE SetAcquisitionSOL_TRACK_ENE_EC
--                        DICHIARAZIONI_BINARIO_SOL_ENE
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetAcquisitionSOL_TRACK_ENE_EC (n_acquisizione       Number,
                                             p_error          Out Number )   Is
      i             Number;
      sqlstring     Varchar2 (3000);
      TYPE dtp_sol_rt IS RECORD
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOl_TRACK_1_1_1_0_0_1%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type   );
      TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
      L_SOL_TRACK   dtp_sol_t;
   BEGIN
      p_error := 0;
 -- ENERGIA
        Select Distinct s.SEDE_TECNICA        id_sol,
                        SOl_TRACK_1_1_1_0_0_1 id_binario,
                        s.CODICE_DTP          id_dtp
          Bulk Collect Into                   l_sol_track
          From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA c,
               Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA s
         Where s.SEDE_TECNICA = b.SEDE_TECNICA
           And SOl_TRACK_1_1_1_0_0_1 = c.IDENTIFICATIVO_BINARIO
           And CODICE_CARATTERISTICA In ('R16000_TR_0320', 'R16000_TR_0330','R16000_TR_0321', 'R16000_TR_0331')
         Order by 1;

      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '||  'Caricamento DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA ENERGIA');
         Dbms_Output.Put_Line ( 'Caricamento DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA ENERGIA');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA ENERGIA da caricare: ' || To_Char(l_sol_track.COUNT));
--
         Dbms_Output.Put_Line ( 'Totale DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA ENERGIA da caricare: ' || To_Char(l_sol_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
--
         Forall i In 1 .. l_sol_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_SOL_ENE 
			      ( SOL_TRACK_1_1_1_0_0_1,
                    TIPO_DICHIARAZIONE,
                    SOL_TRACK_1_1_1_2_1_1O2_AP,
                    SOL_TRACK_1_1_1_2_1_1O2,
                    KM_INIZIO,
                    KM_FINE,
                    LATITUDINE_INIZIO,
                    LONGITUDINE_INIZIO,
                    LATITUDINE_FINE,
                    LONGITUDINE_FINE,
                    FLAG_CALCOLATO  )
                Select appl.IDENTIFICATIVO_BINARIO,
                    'EC',
                    appl.VALORE_CARATTERISTICA,
                    Nvl(val.VALORE_CARATTERISTICA,' '),
                    Nvl(KM_INIZIO,0),
                    KM_FINE,
                    LATITUDINE_INIZIO,
                    LONGITUDINE_INIZIO,
                    LATITUDINE_FINE,
                    LONGITUDINE_FINE,
                    FLAG_CALCOLATO
                From (Select CODICE_CARATTERISTICA,
                             IDENTIFICATIVO_BINARIO,
                             VALORE_CARATTERISTICA
                        From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                       Where CODICE_CARATTERISTICA In ('R16000_TR_0321')
					  ) appl,
                     (Select CODICE_CARATTERISTICA,
                             IDENTIFICATIVO_BINARIO,
                             VALORE_CARATTERISTICA,
                             KM_INIZIO,
                             KM_FINE,
     -- 29/01/2018 Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                             Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                  Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 1)
                                  Else LATITUDINE_INIZIO
                             End LATITUDINE_INIZIO,
                             Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                  Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 2)
                                  Else LONGITUDINE_INIZIO
                             End LONGITUDINE_INIZIO,
                             Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                                 Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 1)
                                 Else LATITUDINE_FINE
                             End LATITUDINE_FINE,
                             Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                                  Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 2)
                                  Else LONGITUDINE_FINE
                             End LONGITUDINE_FINE,
                             Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                  Then GetLatLonFromKm(l_sol_track(i).ID_SOL,KM_INIZIO, 3)
                                  Else 0
                             End FLAG_CALCOLATO
                      From  Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                     Where  CODICE_CARATTERISTICA In ('R16000_TR_0320')
					 ) val
             Where appl.IDENTIFICATIVO_BINARIO = l_sol_track(i).ID_BINARIO
               And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+)
             Union
            Select appl.IDENTIFICATIVO_BINARIO,
                   'EI',
                   appl.VALORE_CARATTERISTICA,
                   Nvl(val.VALORE_CARATTERISTICA, ' '),
                   Nvl(KM_INIZIO,0),
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO
              From (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_BINARIO,
                           VALORE_CARATTERISTICA
                      From  Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                     Where  CODICE_CARATTERISTICA In ('R16000_TR_0331')
					) appl,
                   (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_BINARIO,
                           VALORE_CARATTERISTICA,
                           KM_INIZIO,
                           KM_FINE,
                   -- 29/01/2018 Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 1)
                                Else LATITUDINE_INIZIO
                           End LATITUDINE_INIZIO,
                           Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 2)
                                Else LONGITUDINE_INIZIO
                           End LONGITUDINE_INIZIO,
                           Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 1)
                                Else LATITUDINE_FINE
                           End LATITUDINE_FINE,
                           Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 2)
                                Else LONGITUDINE_FINE
                           End LONGITUDINE_FINE,
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 3)
                                Else 0
                           End FLAG_CALCOLATO
                      From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R16000_TR_0330')
					 ) val
             Where appl.IDENTIFICATIVO_BINARIO = l_sol_track(i).ID_BINARIO
               And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+);
--
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT Loop 
--> loop 				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ('DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario || ''',''R16000_MULTIPLA - ENE'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop 				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_ENE_EC - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionSOL_TRACK_ENE_EC;
--
-- ------------------------------------------------------------------------------------------------   
--                   PROCEDURE SetAcquisitionSOL_TRACK_CCS_EC
--                 DICHIARAZIONI_BINARIO_SOL_CCS
-- ------------------------------------------------------------------------------------------------   

  Procedure SetAcquisitionSOL_TRACK_CCS_EC (n_acquisizione       Number,
                                            p_error          Out Number )   Is
      i             Number;
      sqlstring     Varchar2 (3000);
      TYPE dtp_sol_rt IS RECORD
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOl_TRACK_1_1_1_0_0_1%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type   );
      TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
      l_sol_track   dtp_sol_t;
   BEGIN
      p_error := 0;
--  CONTROLLO E SEGNALAMENTO
     Select Distinct 
	        s.SEDE_TECNICA        id_sol,
            SOl_TRACK_1_1_1_0_0_1 id_binario,
            s.CODICE_DTP          id_dtp
       Bulk Collect Into l_sol_track
       From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA c,
            Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
            Rinf_Lavorazione_Evo.SEZIONI_LINEA s
      Where s.SEDE_TECNICA = b.SEDE_TECNICA
        And SOl_TRACK_1_1_1_0_0_1 = c.IDENTIFICATIVO_BINARIO
        And CODICE_CARATTERISTICA In ('R16000_TR_0560','R16000_TR_0561')
      Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA CONTROLLO E SEGNALAMENTO');
         Dbms_Output.Put_Line ( 'Caricamento DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA CONTROLLO E SEGNALAMENTO');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA CONTROLLO E SEGNALAMENTO da caricare: ' || TO_CHAR (l_sol_track.COUNT));
         Dbms_Output.Put_Line ( 'Totale DICHIARAZIONI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA, VISTA CONTROLLO E SEGNALAMENTO da caricare: ' || TO_CHAR (l_sol_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' '  );
--
         Forall i In 1 .. l_sol_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_SOL_CCS 
			   (   SOL_TRACK_1_1_1_0_0_1,
                   TIPO_DICHIARAZIONE,
                   SOL_TRACK_1_1_1_3_1_1_AP,
                   SOL_TRACK_1_1_1_3_1_1,
                   KM_INIZIO,
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO )
            Select appl.IDENTIFICATIVO_BINARIO,
                   'EC',
                   appl.VALORE_CARATTERISTICA,
                   Nvl(val.VALORE_CARATTERISTICA, ' '),
                   Nvl(KM_INIZIO, 0),
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO
              From (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_BINARIO,
                           VALORE_CARATTERISTICA
                      From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R16000_TR_0561')
					) appl,
                   (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_BINARIO,
                           VALORE_CARATTERISTICA,
                           KM_INIZIO,
                           KM_FINE,
    -- 29/01/2018 Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 1)
                                Else LATITUDINE_INIZIO
                           End LATITUDINE_INIZIO,
                           Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 2)
                                Else LONGITUDINE_INIZIO
                           End LONGITUDINE_INIZIO,
                           Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                               Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 1)
                               Else LATITUDINE_FINE
                           End LATITUDINE_FINE,
                           Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 2)
                                Else LONGITUDINE_FINE
                           End LONGITUDINE_FINE,
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 3)
                                Else 0
                           End FLAG_CALCOLATO
                      From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R16000_TR_0560')   
					) val
             Where appl.IDENTIFICATIVO_BINARIO = l_sol_track(i).ID_BINARIO
               And appl.IDENTIFICATIVO_BINARIO = val.IDENTIFICATIVO_BINARIO(+);
--
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT
                 Loop 
--> loop 				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));

                  Dbms_Output.Put_Line ( 'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                                      || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                                      || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario || ''',''R16000_MULTIPLA - CCS'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop 				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_CCS_EC - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SetAcquisitionSOL_TRACK_CCS_EC;
--
-- ------------------------------------------------------------------------------------------------   
--                 PROCEDURE SetAcquisitionSOL_TRACK_TUNNEL 
--                          GALLERIE_BINARI_SOL
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionSOL_TRACK_TUNNEL (n_acquisizione       Number,
                                             p_error          Out Number )    Is
      i             Number;
      sqlstring     Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_SOL                 Rinf_Staging_Evo.CLASSE_R16000_TR.SEDE_TECNICA%Type,
         ID_BINARIO             Rinf_Staging_Evo.CLASSE_R16000_TR.SOL_TRACK_1_1_1_0_0_1%Type,
         ID_TUNNEL              Rinf_Staging_Evo.CLASSE_R25350_TR.SOL_TUNNEL_1_1_1_1_8_2%Type,
         ID_DTP                 Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type,     --);
         SOL_TRACK_1_1_1_1_2_5  Rinf_Lavorazione_Evo.BINARI_CORSA_SOL.SOL_TRACK_1_1_1_1_2_5%type);
      TYPE op_track_t IS TABLE OF op_track_rt;
      L_SOL_TRACK     op_track_t;
   BEGIN
      p_error := 0;
--
---------------------------------------------------------------------------------------------
--                     GALLERIE_BINARI_SOL
--  04/03/2016 vengono caricate soltanto le gallerie principali delle gallerie multiple
---------------------------------------------------------------------------------------------
        Select Null                   id_sol,
               Null                   id_binario,
               SOL_TUNNEL_1_1_1_1_8_2 id_tunnel,
               Null                   id_dtp,
               null                   SOL_TRACK_1_1_1_1_2_5
			   Bulk Collect Into l_sol_track
          From Rinf_Staging_Evo.CLASSE_R25350_TR b,
               Rinf_Anagrafiche_Evo.POSIZIONE_GALLERIE c
         Where b.SOL_TUNNEL_1_1_1_1_8_2 Is Not Null
           And b.SOL_TUNNEL_1_1_1_1_8_2 = c.CODICE_GALLERIA
           And ( LONGITUDINE_ORIGINE Is Not Null And LATITUDINE_ORIGINE Is Not Null And LONGITUDINE_DESTINAZIONE Is Not Null And LATITUDINE_DESTINAZIONE Is Not Null )
           And Nvl(SOL_TUNNEL_1_1_1_1_8_7, 0) >= 100  --quando avremo l'informazione della galleria di riferimento occorre recuperare la lunghezza dalla galleria principale
           And (GALLERIA_PRINCIPALE Is Null Or GALLERIA_PRINCIPALE = b.SOL_TUNNEL_1_1_1_1_8_2) --04/03/2016 per rendere più robusto il codice nel caso una galleria secondaria avesse una lunghezza diversa da zero
         Order by 3;
--
    BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento GALLERIE BINARI DI CIRCOLAZIONE DELLE SdL');
         Dbms_Output.Put_Line ( 'Caricamento GALLERIE BINARI DI CIRCOLAZIONE DELLE SdL');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale GALLERIE BINARI DI CIRCOLAZIONE DELLE SdL da caricare: ' || TO_CHAR (l_sol_track.COUNT));
         Dbms_Output.Put_Line ( 'Totale GALLERIE BINARI DI CIRCOLAZIONE DELLE SdL da caricare: ' || TO_CHAR (l_sol_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' '  );
--
         Forall i In 1 .. l_sol_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL 
			         (  SOL_TUNNEL_1_1_1_1_8_1,
                        SOL_TUNNEL_1_1_1_1_8_2,
                        SOL_TUNNEL_1_1_1_1_8_2_D,
--                        SOL_TUNNEL_1_1_1_1_8_3_AP,                 -- AP=Y - fittizia per NYA
                        SOL_TUNNEL_1_1_1_1_8_3,                     
--                        SOL_TUNNEL_1_1_1_1_8_4_AP,                 -- AP=Y - fittizia per NYA
                        SOL_TUNNEL_1_1_1_1_8_4,                     
--                        SOL_TUNNEL_1_1_1_1_8_7_AP,                 -- AP=Y - fittizia per NYA
                        SOL_TUNNEL_1_1_1_1_8_7,                     
                        SOL_TUNNEL_1_1_1_1_8_8_AP,                   -- AP modificata con il Reg.2019/777 (dipende dalla velocità)
                        SOL_TUNNEL_1_1_1_1_8_8,                      -- modificato con il Reg.2019/777
                        SOL_TUNNEL_1_1_1_1_8_9_AP,                   
                        SOL_TUNNEL_1_1_1_1_8_9,
                        SOL_TUNNEL_1_1_1_1_8_10_AP,
                        SOL_TUNNEL_1_1_1_1_8_10,
                        SOL_TUNNEL_1_1_1_1_8_11_AP,
                        SOL_TUNNEL_1_1_1_1_8_11,
						SOL_TUNNEL_1_1_1_1_8_8_1_AP,                 -- AP dipende dalla velocità
						SOL_TUNNEL_1_1_1_1_8_8_1,                    -- Nuovo parametro Reg.2019/777
						SOL_TUNNEL_1_1_1_1_8_8_2_AP,                 -- AP=N
						SOL_TUNNEL_1_1_1_1_8_8_2 	)                -- Nuovo parametro Reg.2019/777
--
                 Select Lpad(Nvl(SOL_TUNNEL_1_1_1_1_8_1, 83), 4, '0'),
                        SOL_TUNNEL_1_1_1_1_8_2,
                        SOL_TUNNEL_1_1_1_1_8_2_D,
                        --SOL_TUNNEL_1_1_1_1_8_3_AP,                 -- AP=Y - fittizia per NYA
                        'Latitude ('|| Trim(To_Char(Trunc(LATITUDINE_ORIGINE, 7), '999.9999999'))|| ') + Longitude ('|| Trim(To_Char(Trunc(LONGITUDINE_ORIGINE, 7),'S999.9999999'))|| ') + km ('||Trim(To_Char(Trunc(SOL_TUNNEL_1_1_1_1_8_3, 3),'9990.999'))||')' SOL_TUNNEL_1_1_1_1_8_3,
  --                     SOL_TUNNEL_1_1_1_1_8_4_AP,                  -- AP=Y - fittizia per NYA
                        'Latitude ('|| Trim(To_Char(Trunc(LATITUDINE_DESTINAZIONE, 7),'999.9999999'))|| ') + Longitude ('|| Trim(To_Char(Trunc(LONGITUDINE_DESTINAZIONE, 7),'S999.9999999'))|| ') + km ('||Trim(To_Char(Trunc(SOL_TUNNEL_1_1_1_1_8_4, 3),'9990.999'))||')' SOL_TUNNEL_1_1_1_1_8_4,
  --                      SOL_TUNNEL_1_1_1_1_8_7_AP,                 -- AP=Y - fittizia per NYA
                        Trunc(SOL_TUNNEL_1_1_1_1_8_7),               -- 01/10/2015 da test CUI è emerso che deve essere un intero
                        Null SOL_TUNNEL_1_1_1_1_8_8_AP,              -->>  AP da modificare. Ancora non sono associati i binari alla galleria - AP Modificata con il Reg.2019/777
                        Trunc(SOL_TUNNEL_1_1_1_1_8_8),
                        PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_9(SOL_TUNNEL_1_1_1_1_8_7) SOL_TUNNEL_1_1_1_1_8_9_AP,                -- Modificata da AP=Y a dipende dalla lunghezza della galleria
--                        Case When PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_10(SOL_TUNNEL_1_1_1_1_8_7) = 'N' and SOL_TUNNEL_1_1_1_1_8_9 = 'N' 
--						     Then Null
--						     Else SOL_TUNNEL_1_1_1_1_8_9
--							 End SOL_TUNNEL_1_1_1_1_8_9,
                        SOL_TUNNEL_1_1_1_1_8_9,
                        PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_10(SOL_TUNNEL_1_1_1_1_8_7) SOL_TUNNEL_1_1_1_1_8_10_AP,
                        SOL_TUNNEL_1_1_1_1_8_10,
                        PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_11 (SOL_TUNNEL_1_1_1_1_8_7, Upper(SOL_TUNNEL_1_1_1_1_8_10)) SOL_TUNNEL_1_1_1_1_8_11_AP,      --    17/05/2016 reinserito con eliminazione NA In INE e aggiunta di NC come valore ammissibile
                        GetPARValue ('1.1.1.1.8.11', 0, SOL_TUNNEL_1_1_1_1_8_11) SOL_TUNNEL_1_1_1_1_8_11,
                        Null SOL_TUNNEL_1_1_1_1_8_8_1_AP,            -->> AP da modificare. Ancora non sono associati i binari alla galleria
						SOL_TUNNEL_1_1_1_1_8_8_1,
						PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8_2 SOL_TUNNEL_1_1_1_1_8_8_2_AP,      -- AP=N
						SOL_TUNNEL_1_1_1_1_8_8_2 	
                   From Rinf_Staging_Evo.CLASSE_R25350_TR,
                        Rinf_Anagrafiche_Evo.POSIZIONE_GALLERIE 
                  Where SOL_TUNNEL_1_1_1_1_8_2 = l_sol_track (i).ID_TUNNEL
                    And SOL_TUNNEL_1_1_1_1_8_2 = CODICE_GALLERIA;
--
      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--> loop				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line (  'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                       || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                                       || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                                       || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_SOL_TR'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop 				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_TUNNEL - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      End;
--
--  ------------------------------------------------------------------------------------------------------
--      GALLERIA COMPOSTA: calcolo delle chilometriche e delle coordinate di una galleria su più tratte
--  ------------------------------------------------------------------------------------------------------
  BEGIN
-- Inizio galleria
  Update Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL a
     Set SOL_TUNNEL_1_1_1_1_8_3 =
          (Select Distinct 'Latitude (' || Trim ( To_Char (Trunc(LATITUDINE_ORIGINE, 7), '999.9999999'))
                    || ') + Longitude (' || Trim (  To_Char (Trunc(LONGITUDINE_ORIGINE, 7), 'S999.9999999'))
                  || ') + km (' || Trim (To_Char (Trunc(km.km_inizio, 3), '9990.999')) || ')'
              From ( Select Principale.SOL_TUNNEL_1_1_1_1_8_2 Principale,
                            Secondaria.SOL_TUNNEL_1_1_1_1_8_2 Secondaria,
                            Secondaria.SOL_TUNNEL_1_1_1_1_8_3 Km_Inizio,
                            Secondaria.SOL_TUNNEL_1_1_1_1_8_4 Km_Fine
                      From  Rinf_Staging_Evo.CLASSE_R25350_TR Principale,
                            Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria
                      Where (Principale.GALLERIA_PRINCIPALE Is Null  Or Principale.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2)
                        And (Secondaria.GALLERIA_PRINCIPALE Is Not Null  And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2)
                        And  Secondaria.GALLERIA_PRINCIPALE  = Principale.SOL_TUNNEL_1_1_1_1_8_2
                      Union
                    Select Principale.SOL_TUNNEL_1_1_1_1_8_2 Principale,
                           Principale.SOL_TUNNEL_1_1_1_1_8_2 Secondaria,
                           Principale.SOL_TUNNEL_1_1_1_1_8_3 Km_Inizio,
                           Principale.SOL_TUNNEL_1_1_1_1_8_4 Km_Fine
                      From Rinf_Staging_Evo.CLASSE_R25350_TR Principale
                     Where Principale.SOL_TUNNEL_1_1_1_1_8_2 In
                                    (Select GALLERIA_PRINCIPALE From Rinf_Staging_Evo.CLASSE_R25350_TR)
					) Gall,
                   ( Select Principale.SOL_TUNNEL_1_1_1_1_8_2,
                            Least ( Principale.SOL_TUNNEL_1_1_1_1_8_3, Min(Secondaria.SOL_TUNNEL_1_1_1_1_8_3) )  Km_Inizio,
                            Greatest (Principale.SOL_TUNNEL_1_1_1_1_8_4, Max (Secondaria.SOL_TUNNEL_1_1_1_1_8_4)) Km_Fine
                       From Rinf_Staging_Evo.CLASSE_R25350_TR Principale,
                            Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria
                         Where  ( Principale.GALLERIA_PRINCIPALE Is Null Or Principale.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2 )
                            And ( Secondaria.GALLERIA_PRINCIPALE Is Not Null  And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2 )
                            And Secondaria.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2
                       Group By Principale.SOL_TUNNEL_1_1_1_1_8_2,
                                Principale.SOL_TUNNEL_1_1_1_1_8_3,
                                Principale.SOL_TUNNEL_1_1_1_1_8_4
				    ) Km,
                    Rinf_Anagrafiche_Evo.POSIZIONE_GALLERIE Cord
              Where Gall.PRINCIPALE = Km.SOL_TUNNEL_1_1_1_1_8_2
               And ( Gall.PRINCIPALE, Gall.SECONDARIA) In 
			       (Select GALLERIA_PRINCIPALE, Min(SOL_TUNNEL_1_1_1_1_8_2)
                           From Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria 
						  Where Secondaria.GALLERIA_PRINCIPALE Is Not Null  And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2
                       Group By GALLERIA_PRINCIPALE, SOL_TUNNEL_1_1_1_1_8_3
					)
              And Gall.SECONDARIA = Cord.CODICE_GALLERIA
              And Gall.KM_INIZIO  = Km.KM_INIZIO
              And Gall.PRINCIPALE = a.SOL_TUNNEL_1_1_1_1_8_2)
--			  
     Where  a.SOL_TUNNEL_1_1_1_1_8_2  In
          (Select Gall.PRINCIPALE
             From (Select Principale.SOL_TUNNEL_1_1_1_1_8_2 principale,
                          Secondaria.SOL_TUNNEL_1_1_1_1_8_2 secondaria,
                          Secondaria.SOL_TUNNEL_1_1_1_1_8_3 km_inizio,
                          Secondaria.SOL_TUNNEL_1_1_1_1_8_4 km_fine
                     From Rinf_Staging_Evo.CLASSE_R25350_TR Principale,
                          Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria
                    Where ( Principale.GALLERIA_PRINCIPALE Is Null  Or  Principale.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2 )
                      And ( Secondaria.GALLERIA_PRINCIPALE Is Not Null  And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2 )
                      And   Secondaria.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2
                  Union
                   Select Principale.SOL_TUNNEL_1_1_1_1_8_2 principale,
                          Principale.SOL_TUNNEL_1_1_1_1_8_2 secondaria,
                          Principale.SOL_TUNNEL_1_1_1_1_8_3 km_inizio,
                          Principale.SOL_TUNNEL_1_1_1_1_8_4 km_fine
                     From Rinf_Staging_Evo.CLASSE_R25350_TR Principale
                    Where PRINCIPALE.SOL_TUNNEL_1_1_1_1_8_2 In
                             (Select GALLERIA_PRINCIPALE From Rinf_Staging_Evo.CLASSE_R25350_TR)
				    )  gall,
                  (Select Principale.SOL_TUNNEL_1_1_1_1_8_2,
                          Least (Principale.SOL_TUNNEL_1_1_1_1_8_3, Min (Secondaria.SOL_TUNNEL_1_1_1_1_8_3) ) km_inizio,
                          Greatest (Principale.SOL_TUNNEL_1_1_1_1_8_4, Max (Secondaria.SOL_TUNNEL_1_1_1_1_8_4) ) km_fine
                     From Rinf_Staging_Evo.CLASSE_R25350_TR Principale,
                          Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria
                    Where ( Principale.GALLERIA_PRINCIPALE Is Null  Or  Principale.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2 )
                      And ( Secondaria.GALLERIA_PRINCIPALE Is Not Null  And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2 )
                      And   Secondaria.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2
                 Group By Principale.SOL_TUNNEL_1_1_1_1_8_2,
                          Principale.SOL_TUNNEL_1_1_1_1_8_3,
                          Principale.SOL_TUNNEL_1_1_1_1_8_4
					)  km,
                  Rinf_Anagrafiche_Evo.POSIZIONE_GALLERIE  cord
--				  
            Where   gall.PRINCIPALE = km.SOL_TUNNEL_1_1_1_1_8_2
              And ( gall.PRINCIPALE, gall.SECONDARIA) In 
			             (Select GALLERIA_PRINCIPALE, Min(SOL_TUNNEL_1_1_1_1_8_2)
                           From  Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria 
						   Where Secondaria.GALLERIA_PRINCIPALE Is Not Null
                             And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2
                        Group By GALLERIA_PRINCIPALE, SOL_TUNNEL_1_1_1_1_8_3
						  )
              And gall.SECONDARIA = cord.CODICE_GALLERIA
              And gall.KM_INIZIO  = km.KM_INIZIO
		   );
--
-- Fine galleria
  Update Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL a
     Set SOL_TUNNEL_1_1_1_1_8_4 =
         (Select Distinct 'Latitude (' || Trim ( To_Char (Trunc (LATITUDINE_DESTINAZIONE, 7), '999.9999999'))
                   || ') + Longitude ('|| Trim ( To_Char (Trunc (LONGITUDINE_DESTINAZIONE, 7), 'S999.9999999'))
                   || ') + km ('  || Trim (To_Char (Trunc (km.km_fine, 3), '9990.999')) || ')'
            From ( Select Principale.SOL_TUNNEL_1_1_1_1_8_2 principale,
                          Secondaria.SOL_TUNNEL_1_1_1_1_8_2 secondaria,
                          Secondaria.SOL_TUNNEL_1_1_1_1_8_3 km_inizio,
                          Secondaria.SOL_TUNNEL_1_1_1_1_8_4 km_fine
                     From Rinf_Staging_Evo.CLASSE_R25350_TR Principale,
                          Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria
                    Where ( Principale.GALLERIA_PRINCIPALE Is Null  Or  Principale.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2 )
                      And ( Secondaria.GALLERIA_PRINCIPALE Is Not Null  And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2 )
                      And   Secondaria.GALLERIA_PRINCIPALE  = Principale.SOL_TUNNEL_1_1_1_1_8_2
                   Union
                   Select Principale.SOL_TUNNEL_1_1_1_1_8_2 principale,
                          Principale.SOL_TUNNEL_1_1_1_1_8_2 secondaria,
                          Principale.SOL_TUNNEL_1_1_1_1_8_3 km_inizio,
                          Principale.SOL_TUNNEL_1_1_1_1_8_4 km_fine
                     From Rinf_Staging_Evo.CLASSE_R25350_TR Principale
                    Where Principale.SOL_TUNNEL_1_1_1_1_8_2 In
                          (Select GALLERIA_PRINCIPALE From  Rinf_Staging_Evo.CLASSE_R25350_TR)
				   )  Gall,
                  ( Select PRINCIPALE.SOL_TUNNEL_1_1_1_1_8_2,
                           Least (Principale.SOL_TUNNEL_1_1_1_1_8_3, Min (Secondaria.SOL_TUNNEL_1_1_1_1_8_3) ) km_inizio,
                           Greatest (principale.SOL_TUNNEL_1_1_1_1_8_4, Max (secondaria.SOL_TUNNEL_1_1_1_1_8_4) ) km_fine
                      From Rinf_Staging_Evo.CLASSE_R25350_TR Principale,
                           Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria
                     Where ( Principale.GALLERIA_PRINCIPALE Is Null  Or  Principale.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2 )
                       And ( Secondaria.GALLERIA_PRINCIPALE Is Not Null And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2 )
                       And   Secondaria.GALLERIA_PRINCIPALE  = Principale.SOL_TUNNEL_1_1_1_1_8_2
                  Group By Principale.SOL_TUNNEL_1_1_1_1_8_2,
                           Principale.SOL_TUNNEL_1_1_1_1_8_3,
                           Principale.SOL_TUNNEL_1_1_1_1_8_4
			       )  Km,
                  Rinf_Anagrafiche_Evo.POSIZIONE_GALLERIE  cord
--				  
            Where Gall.PRINCIPALE = Km.SOL_TUNNEL_1_1_1_1_8_2
            And ( Gall.PRINCIPALE, Gall.SECONDARIA) In 
			             (Select GALLERIA_PRINCIPALE, Min(SOL_TUNNEL_1_1_1_1_8_2)
                            From Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria 
						   Where Secondaria.GALLERIA_PRINCIPALE Is Not Null
                             And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2
                        Group By GALLERIA_PRINCIPALE, SOL_TUNNEL_1_1_1_1_8_4
						  )
            And Gall.SECONDARIA = Cord.CODICE_GALLERIA
            And Gall.KM_FINE = Km.KM_FINE
            And Gall.PRINCIPALE = a.SOL_TUNNEL_1_1_1_1_8_2
	     )
     Where  a.SOL_TUNNEL_1_1_1_1_8_2 In
         ( Select Gall.PRINCIPALE
             From (Select Principale.SOL_TUNNEL_1_1_1_1_8_2 principale,
                          Secondaria.SOL_TUNNEL_1_1_1_1_8_2 secondaria,
                          Secondaria.SOL_TUNNEL_1_1_1_1_8_3 km_inizio,
                          Secondaria.SOL_TUNNEL_1_1_1_1_8_4 km_fine
                     From Rinf_Staging_Evo.CLASSE_R25350_TR Principale,
                          Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria
                    Where ( Principale.GALLERIA_PRINCIPALE Is Null  Or  Principale.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2 )
                      And ( Secondaria.GALLERIA_PRINCIPALE Is Not Null  And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2 )
                      And   Secondaria.GALLERIA_PRINCIPALE  = Principale.SOL_TUNNEL_1_1_1_1_8_2
                    Union
                   Select Principale.SOL_TUNNEL_1_1_1_1_8_2 principale,
                          Principale.SOL_TUNNEL_1_1_1_1_8_2 secondaria,
                          Principale.SOL_TUNNEL_1_1_1_1_8_3 km_inizio,
                          Principale.SOL_TUNNEL_1_1_1_1_8_4 km_fine
                     From Rinf_Staging_Evo.CLASSE_R25350_TR Principale
                    Where Principale.SOL_TUNNEL_1_1_1_1_8_2 In
                          (Select GALLERIA_PRINCIPALE From  Rinf_Staging_Evo.CLASSE_R25350_TR)
				    )  Gall,
                  (Select Principale.SOL_TUNNEL_1_1_1_1_8_2,
                          Least (Principale.SOL_TUNNEL_1_1_1_1_8_3, Min (Secondaria.SOL_TUNNEL_1_1_1_1_8_3) ) km_inizio,
                          Greatest (Principale.SOL_TUNNEL_1_1_1_1_8_4, Max (Secondaria.SOL_TUNNEL_1_1_1_1_8_4) ) km_fine
                     From Rinf_Staging_Evo.CLASSE_R25350_TR Principale,
                          Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria
                    Where ( Principale.GALLERIA_PRINCIPALE Is Null  Or  Principale.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2 )
                      And ( Secondaria.GALLERIA_PRINCIPALE Is Not Null  And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2 )
                      And   Secondaria.GALLERIA_PRINCIPALE = Principale.SOL_TUNNEL_1_1_1_1_8_2
                 Group By Principale.SOL_TUNNEL_1_1_1_1_8_2,
                          Principale.SOL_TUNNEL_1_1_1_1_8_3,
                          Principale.SOL_TUNNEL_1_1_1_1_8_4
					)  Km,
                  RINF_ANAGRAFICHE_EVO.POSIZIONE_GALLERIE  cord
            Where  Gall.PRINCIPALE = Km.SOL_TUNNEL_1_1_1_1_8_2
             And ( Gall.PRINCIPALE, Gall.SECONDARIA) In 
			              (Select GALLERIA_PRINCIPALE, Min(SOL_TUNNEL_1_1_1_1_8_2)
                             From Rinf_Staging_Evo.CLASSE_R25350_TR Secondaria
							Where Secondaria.GALLERIA_PRINCIPALE Is Not Null  And Secondaria.GALLERIA_PRINCIPALE <> Secondaria.SOL_TUNNEL_1_1_1_1_8_2
                         group by GALLERIA_PRINCIPALE, SOL_TUNNEL_1_1_1_1_8_4
						   )
             And Gall.SECONDARIA = Cord.CODICE_GALLERIA
             And Gall.KM_FINE = Km.KM_FINE
		);
--			
     EXCEPTION
     When OTHERS    Then
              Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,  'Errori nel calcolo delle chilometriche delle gallerie multiple');
     End;
--
-- -------------------------------------------------------------------------------------
--                  REL_GALLERIE_BINARI_SOL
-- -------------------------------------------------------------------------------------
-- 04/03/2016 E' necessario associare le gallerie su più tratte a tutti i binari delle tratte secondarie
--        Per questo motivo l'inserimento nella tabella Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL
--        viene diviso In due passi, nel primo vengono escluse le relazioni delle gallerie secondarie, che vengno inserite
--        nel secondo passo con il codice della galleria principale.
--
--   Passo 1: gallerie mono-tratta e principale
--
        Select Distinct
               o.SEDE_TECNICA            id_sol,
               l.SOL_TRACK_1_1_1_0_0_1   id_binario,
               b.IDENTIFICATIVO_GALLERIA id_tunnel,
               o.CODICE_DTP              id_dtp,
			   l.SOL_TRACK_1_1_1_1_2_5
          Bulk Collect Into l_sol_track
          From Rinf_Staging_Evo.CLASSE_R25350_TR_MULTIPLA b,
               Rinf_Lavorazione_Evo.BINARI_CORSA_SOL l,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA o,
               Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL g
         Where l.SOL_TRACK_1_1_1_0_0_1 = Upper(b.VALORE_CARATTERISTICA)
           And l.SEDE_TECNICA = o.SEDE_TECNICA
           And g.SOL_TUNNEL_1_1_1_1_8_2 = b.IDENTIFICATIVO_GALLERIA
           And CODICE_CARATTERISTICA = 'R25350_TR_3010'
      Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DELLE SdL');
         Dbms_Output.Put_Line ( 'Caricamento RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DELLE SdL');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DELLE SdL da caricare: '|| To_Char (l_sol_track.COUNT));
         Dbms_Output.Put_Line ( 'Totale RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DELLE SdL da caricare: ' || To_Char (l_sol_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' '  );
--
         Forall i In 1 .. l_sol_track.COUNT SAVE EXCEPTIONS
--		 

/* 
           Insert Into Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL 
			          ( SOL_TUNNEL_1_1_1_1_8_2, SOL_TRACK_1_1_1_0_0_1)
               Values (l_sol_track (i).ID_TUNNEL,  l_sol_track (i).ID_BINARIO);

*/	      
          -- Modfiche effettute il 10/03/2021 per gestire i parametri SOL_TUNNEL_1_1_1_1_8_8_AP e  SOL_TUNNEL_1_1_1_1_8_8_1_AP
          Insert Into Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL 
			          ( SOL_TUNNEL_1_1_1_1_8_2, SOL_TRACK_1_1_1_0_0_1, SOL_TUNNEL_1_1_1_1_8_8_AP, SOL_TUNNEL_1_1_1_1_8_8_1_AP)		   
               Select  l_sol_track(i).ID_TUNNEL, l_sol_track(i).ID_BINARIO,
			           PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8 (l_sol_track(i).SOL_TRACK_1_1_1_1_2_5) SOL_TUNNEL_1_1_1_1_8_8_AP,
					   PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8_1 (l_sol_track(i).SOL_TRACK_1_1_1_1_2_5) SOL_TUNNEL_1_1_1_1_8_8_1_AP from Dual;
--			   
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT   Loop 
--				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_3010_SOL_TR'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_TUNNEL.1 - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--
--  Passo 2: Gallerie Secondarie: inserisco i binari associati alle gallerie secondarie come binari della galleria principale, se non già presenti
        Select Distinct o.SEDE_TECNICA          id_sol,
                        l.SOL_TRACK_1_1_1_0_0_1 id_binario,
                        r.ID_TUNNEL,
                        o.CODICE_DTP            id_dtp,
						SOL_TRACK_1_1_1_1_2_5
          Bulk Collect Into  l_sol_track
          From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL l,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA o,
               Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL g,
               (Select s.GALLERIA_PRINCIPALE    id_tunnel,
                       b.VALORE_CARATTERISTICA  id_binario
                  From Rinf_Staging_Evo.CLASSE_R25350_TR_MULTIPLA b,
                       Rinf_Staging_Evo.CLASSE_R25350_TR s
                 Where b.IDENTIFICATIVO_GALLERIA = s.SOL_TUNNEL_1_1_1_1_8_2
                   And s.GALLERIA_PRINCIPALE Is Not Null  And s.GALLERIA_PRINCIPALE <> s.SOL_TUNNEL_1_1_1_1_8_2
                   And CODICE_CARATTERISTICA = 'R25350_TR_3010'
                 Minus
                Select SOL_TUNNEL_1_1_1_1_8_2, SOL_TRACK_1_1_1_0_0_1
                  From Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL
				)  r
           Where r.ID_BINARIO = l.SOL_TRACK_1_1_1_0_0_1
             And l.SEDE_TECNICA = o.SEDE_TECNICA
             And g.SOL_TUNNEL_1_1_1_1_8_2 = r.ID_TUNNEL
          Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,'--------------------------------> '|| 'Caricamento RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DELLE SdL delle GALLERIE SECONDARIE COME BINARI DELLA GALLERIA PRINCIPALE');
         Dbms_Output.Put_Line ('Caricamento RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DELLE SdL delle GALLERIE SECONDARIE COME BINARI DELLA GALLERIA PRINCIPALE');
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DELLE SdL delle GALLERIE SECONDARIE COME BINARI DELLA GALLERIA PRINCIPALE: '  || To_Char (l_sol_track.COUNT));
         Dbms_Output.Put_Line ('Totale RELAZIONE GALLERIE-BINARI DI CIRCOLAZIONE DELLE SdL delle GALLERIE SECONDARIE COME BINARI DELLA GALLERIA PRINCIPALE: '|| To_Char (l_sol_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
--
         Forall i In 1 .. l_sol_track.COUNT SAVE EXCEPTIONS
/*
            Insert Into Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL 
			           ( SOL_TUNNEL_1_1_1_1_8_2, SOL_TRACK_1_1_1_0_0_1)
               Values (l_sol_track(i).ID_TUNNEL, l_sol_track(i).ID_BINARIO);
*/
            -- Modfiche effettute il 10/03/2021 per gestire i parametri SOL_TUNNEL_1_1_1_1_8_8_AP e  SOL_TUNNEL_1_1_1_1_8_8_1_AP
            Insert Into Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL 
			           ( SOL_TUNNEL_1_1_1_1_8_2, SOL_TRACK_1_1_1_0_0_1, SOL_TUNNEL_1_1_1_1_8_8_AP, SOL_TUNNEL_1_1_1_1_8_8_1_AP)
               Select  l_sol_track(i).ID_TUNNEL, l_sol_track(i).ID_BINARIO,
			           PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8 (l_sol_track(i).SOL_TRACK_1_1_1_1_2_5) SOL_TUNNEL_1_1_1_1_8_8_AP,
					   PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8_1 (l_sol_track(i).SOL_TRACK_1_1_1_1_2_5) SOL_TUNNEL_1_1_1_1_8_8_1_AP from Dual;
--
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--> loop 				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ('DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                                     || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring :='Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_3010_SOL_TR'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--> end loop 				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_TUNNEL.2 - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;

--> *********  AGGIUNTO L'AGGIORNAMENTO DELL'APPLICABILITà DEI PARAMETRI 1.1.1.1.8.8 e 1.1.1.1.8.8.1 CHE DIPENDONO DALLA VELOCITà *********************
/*   Modifica del 09(03/2011 - gli attributi SOL_TUNNEL_1_1_1_1_8_8_AP e SOL_TUNNEL_1_1_1_1_8_8_1_AP sono stati aggiunti alla tabella REL_GALLERIE_BINARI_SOL 
     in quanto dipendono dalla velocità massima consentita prevista sul BINARIO della SOL: per una galleria ci potrebbero essre sia i binari dell'alta velocità 
	 che delle tratte merci
      BEGIN	 
Update Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL gb
   set SOL_TUNNEL_1_1_1_1_8_8_AP = (select distinct PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8 (SOL_TRACK_1_1_1_1_2_5) SOL_TUNNEL_1_1_1_1_8_8_AP
                                        from Rinf_lavorazione_evo.binari_corsa_sol	  b,				
                                             Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL g
                                       Where g.SOL_TRACK_1_1_1_0_0_1  = b.SOL_TRACK_1_1_1_0_0_1
                                       And g.SOL_TRACK_1_1_1_0_0_1 not in ('TR5474-BC-BC01', 'TR5474-BC-BC02')
                                         And g.SOL_TUNNEL_1_1_1_1_8_2 = gb.SOL_TUNNEL_1_1_1_1_8_2) ,
       SOL_TUNNEL_1_1_1_1_8_8_1_AP = (select distinct PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8_1 (SOL_TRACK_1_1_1_1_2_5) SOL_TUNNEL_1_1_1_1_8_8_1_AP
                                        from Rinf_lavorazione_evo.binari_corsa_sol	  b,				
                                             Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL g
                                       Where g.SOL_TRACK_1_1_1_0_0_1  = b.SOL_TRACK_1_1_1_0_0_1
                                       And g.SOL_TRACK_1_1_1_0_0_1 not in ('TR5474-BC-BC01', 'TR5474-BC-BC02')           -- Aggiornare quando la galleria avrà solo binari Alta Velocità
                                         And g.SOL_TUNNEL_1_1_1_1_8_2 = gb.SOL_TUNNEL_1_1_1_1_8_2)
   where exists 
                                     (select distinct SOL_TRACK_1_1_1_1_2_5
                                        from Rinf_lavorazione_evo.binari_corsa_sol	b,				
                                             Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL g
                                       Where g.SOL_TRACK_1_1_1_0_0_1  = b.SOL_TRACK_1_1_1_0_0_1
                                         And g.SOL_TUNNEL_1_1_1_1_8_2 = gb.SOL_TUNNEL_1_1_1_1_8_2
                                         And g.SOL_TRACK_1_1_1_0_0_1 not in ('TR5474-BC-BC01', 'TR5474-BC-BC02'));       -- Aggiornare quando la galleria avrà solo binari Alta Velocità
      EXCEPTION
          When OTHERS Then
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_TUNNEL - Errore UPD: ' || Substr(SQLERRM, 1, 300));
	  END;
--	  
*/
   END SetAcquisitionSOL_TRACK_TUNNEL;
--   
-- ------------------------------------------------------------------------------------------------   
--                  PROCEDURE SetAcquisitionSOL_BRANCHED_TUN
--   GALLERIE_DIRAMATE
--   10/01/2016 se la procedura  SetAcquisitionSOL_TRACK_TUNNEL non ha inserito In anagrafica
--   una delle gallerie diramate perchè non presente nei dati GIS, questa procedura provvede
--   all'inserimento, solo se la galleria è presente nei dati DWH
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionSOL_BRANCHED_TUN (n_acquisizione       Number,
                                             p_error          Out Number  )     Is
      i             Number;
      sqlstring     Varchar2 (3000);
      TYPE op_track_rt IS RECORD
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R16000_TR.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOL_TRACK_1_1_1_0_0_1%Type,
         ID_TUNNEL    Rinf_Staging_Evo.CLASSE_R25350_TR.SOL_TUNNEL_1_1_1_1_8_2%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type     );
      TYPE op_track_t IS TABLE OF op_track_rt;
      l_sol_track   op_track_t;
   BEGIN
      p_error := 0;
--
        Select Null                     id_sol,
               Null                     id_binario,
               b.SOL_TUNNEL_1_1_1_1_8_2 id_tunnel,
               Null                     id_dtp
          Bulk Collect Into l_sol_track
          From  Rinf_Staging_Evo.CLASSE_R25350_TR b
         Where b.SOL_TUNNEL_1_1_1_1_8_2 Is Not Null
           And b.SOL_TUNNEL_1_1_1_1_8_2 In
              (Select SOL_TUNNEL_1_1_1_1_8_2 From  Rinf_Anagrafiche_Evo.GALLERIE_DIRAMATE
               Minus
               Select SOL_TUNNEL_1_1_1_1_8_2 From  Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL
			   )
         Order by 3;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '||'Caricamento GALLERIE DIRAMATE DELLE SdL');
         Dbms_Output.Put_Line ('Caricamento GALLERIE DIRAMATE DELLE SdL');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale GALLERIE DIRAMATE DELLE SdL da caricare: ' || To_Char(l_sol_track.COUNT));
         Dbms_Output.Put_Line ( 'Totale GALLERIE DIRAMATE DELLE SdL da caricare: '|| To_Char(l_sol_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
--
         Forall i In 1 .. l_sol_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL 
			    (   SOL_TUNNEL_1_1_1_1_8_1,
                    SOL_TUNNEL_1_1_1_1_8_2,
                    SOL_TUNNEL_1_1_1_1_8_2_D,
                    --SOL_TUNNEL_1_1_1_1_8_3_AP,             --  AP=Y - FITTIZIA PER NYA
                    SOL_TUNNEL_1_1_1_1_8_3,
                    --SOL_TUNNEL_1_1_1_1_8_4_AP,             --  AP=Y - FITTIZIA PER NYA
                    SOL_TUNNEL_1_1_1_1_8_4,
                    --SOL_TUNNEL_1_1_1_1_8_7_AP,             --DA RICONTROLLARE NUOVO 0.82 AGOSTO
                    SOL_TUNNEL_1_1_1_1_8_7,
                    SOL_TUNNEL_1_1_1_1_8_8_AP,             --  Modificato con Reg.2019/777
                    SOL_TUNNEL_1_1_1_1_8_8,
                    SOL_TUNNEL_1_1_1_1_8_9_AP,             --  AP=Y - fittizia per NYA
                    SOL_TUNNEL_1_1_1_1_8_9,
                    SOL_TUNNEL_1_1_1_1_8_10_AP,
                    SOL_TUNNEL_1_1_1_1_8_10,
                    SOL_TUNNEL_1_1_1_1_8_11_AP,
                    SOL_TUNNEL_1_1_1_1_8_11,
                    SOL_TUNNEL_1_1_1_1_8_8_1_AP,
                    SOL_TUNNEL_1_1_1_1_8_8_1 ,
                    SOL_TUNNEL_1_1_1_1_8_8_2_AP, 
                    SOL_TUNNEL_1_1_1_1_8_8_2     		)
             Select Distinct
			        Lpad(Nvl( SOL_TUNNEL_1_1_1_1_8_1, 83), 4, '0'),
                    g.SOL_TUNNEL_1_1_1_1_8_2,
                    SOL_TUNNEL_1_1_1_1_8_2_D,
--                    SOL_TUNNEL_1_1_1_1_8_3_AP,             --  AP=Y - fittizia per NYA
                    'Latitude ('|| Trim(To_Char(Trunc(LATITUDINE_ORIGINE, 7),'999.9999999'))|| ') + Longitude ('|| Trim(To_Char(Trunc(LONGITUDINE_ORIGINE, 7),'S999.9999999'))|| ') + km ('||Trim(To_Char(Trunc(SOL_TUNNEL_1_1_1_1_8_3, 3),'9990.999'))||')' SOL_TUNNEL_1_1_1_1_8_3,
--                    SOL_TUNNEL_1_1_1_1_8_4_AP,             --  AP=Y - fittizia per NYA
                    'Latitude ('|| Trim(To_Char(Trunc(LATITUDINE_DESTINAZIONE, 7),'999.9999999'))|| ') + Longitude ('|| Trim(To_Char(Trunc(LONGITUDINE_DESTINAZIONE, 7),'S999.9999999'))|| ') + km ('||Trim(To_Char(Trunc(SOL_TUNNEL_1_1_1_1_8_4, 3),'9990.999'))||')' SOL_TUNNEL_1_1_1_1_8_4,
--                    SOL_TUNNEL_1_1_1_1_8_7_AP,             -- AP=Y - fittizia per NYA
                    Trunc(SOL_TUNNEL_1_1_1_1_8_7),               --01/10/2015 da test CUI è emerso che deve essere un intero
--->                    PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8 (SOL_TRACK_1_1_1_1_2_5) SOL_TUNNEL_1_1_1_1_8_8_AP,            
                    SOL_TUNNEL_1_1_1_1_8_8_AP,            
                    Trunc(SOL_TUNNEL_1_1_1_1_8_8),
                    PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_9 (SOL_TUNNEL_1_1_1_1_8_7) SOL_TUNNEL_1_1_1_1_8_9_AP,             --modificato da   AP=Y a dipende dalla lunghezza della galleria 
--                    Case When PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_10(SOL_TUNNEL_1_1_1_1_8_7) = 'N' and SOL_TUNNEL_1_1_1_1_8_9 = 'N' 
--					     Then Null
--					     Else SOL_TUNNEL_1_1_1_1_8_9
--					End SOL_TUNNEL_1_1_1_1_8_9,
                    SOL_TUNNEL_1_1_1_1_8_9,
                    PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_10 (SOL_TUNNEL_1_1_1_1_8_7) SOL_TUNNEL_1_1_1_1_8_10_AP,
                    SOL_TUNNEL_1_1_1_1_8_10,
                    PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_11 (SOL_TUNNEL_1_1_1_1_8_7, Upper(SOL_TUNNEL_1_1_1_1_8_10)) SOL_TUNNEL_1_1_1_1_8_11_AP,      --    17/05/2016 reinserito con eliminazione NA In INE e aggiunta di NC come valore ammissibile
--    17/05/2016 reinserito con eliminazione NA In INE e aggiunta di NC come valore ammissibile
--                    GetAP ('1.1.1.1.8.11', 0, SOL_TUNNEL_1_1_1_1_8_11) SOL_TUNNEL_1_1_1_1_8_11_AP,            --charStrg anomala
                    GetPARValue ('1.1.1.1.8.11', 0, SOL_TUNNEL_1_1_1_1_8_11) SOL_TUNNEL_1_1_1_1_8_11,
--->                    PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8_1 (SOL_TRACK_1_1_1_1_2_5) SOL_TUNNEL_1_1_1_1_8_8_1_AP,   
                    SOL_TUNNEL_1_1_1_1_8_8_1_AP,   
                    SOL_TUNNEL_1_1_1_1_8_8_1,
					PKG_RINF_APPLICABILITA.GetAP_1_1_1_1_8_8_2  SOL_TUNNEL_1_1_1_1_8_8_2_AP, 
                    SOL_TUNNEL_1_1_1_1_8_8_2     
               From Rinf_Staging_Evo.CLASSE_R25350_TR g,
                   (Select SOL_TUNNEL_1_1_1_1_8_2, 
				           LONGITUDINE_ORIGINE, 
					       LATITUDINE_ORIGINE, 
					       KM_INIZIO,
                           LONGITUDINE_DESTINAZIONE, 
						   LATITUDINE_DESTINAZIONE, 
						   KM_DESTINAZIONE
                      From Rinf_Anagrafiche_Evo.GALLERIE_DIRAMATE
                     Where SOL_TUNNEL_1_1_1_1_8_2 = l_sol_track(i).ID_TUNNEL
                       And rownum = 1
					  ) d,
					Rinf_lavorazione_evo.binari_corsa_sol	  b,				
                    Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL rg
              Where g.SOL_TUNNEL_1_1_1_1_8_2 = l_sol_track(i).ID_TUNNEL
                And rg.SOL_TRACK_1_1_1_0_0_1  = b.SOL_TRACK_1_1_1_0_0_1
--                And rg.SOL_TRACK_1_1_1_0_0_1 not in ('TR5474-BC-BC01', 'TR5474-BC-BC02')
                And rg.SOL_TUNNEL_1_1_1_1_8_2 = g.SOL_TUNNEL_1_1_1_1_8_2;
	--

      EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT   Loop 
--				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                                      || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                                      || ' Codice errore: ORA-'|| SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring :='Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_SOL_TR'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_BRANCHED_TUN - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
END SetAcquisitionSOL_BRANCHED_TUN;
--
-- ------------------------------------------------------------------------------------------------   
--                    PROCEDURE SetAcquisitionSOL_TK_TUNNEL_EC
--                       DICHIARAZIONI_GALLERIE_BIN_SOL
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetAcquisitionSOL_TK_TUNNEL_EC (n_acquisizione       Number,
                                             p_error          Out Number  )    Is
      i             Number;
      sqlstring     Varchar2 (3000);
      TYPE dtp_sol_rt IS RECORD
      (  ID_SOL      Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_TUNNEL   Rinf_Staging_Evo.CLASSE_R25350_TR.SOL_TUNNEL_1_1_1_1_8_2%Type,
         ID_DTP      Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type   );
      TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
      L_SOL_TRACK   dtp_sol_t;
   BEGIN
      p_error := 0;

        Select Distinct Null            id_sol,
               l.SOL_TUNNEL_1_1_1_1_8_2 id_tunnel,
               Null                     id_dtp
          Bulk Collect Into             l_sol_track
          From Rinf_Staging_Evo.CLASSE_R25350_TR_MULTIPLA b,
               Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL l
         Where l.SOL_TUNNEL_1_1_1_1_8_2 = b.IDENTIFICATIVO_GALLERIA
           And CODICE_CARATTERISTICA In ('R25350_TR_0050', 'R25350_TR_0060', 'R25350_TR_0051', 'R25350_TR_0061')
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento DICHIARAZIONI GALLERIE DEI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA');
         Dbms_Output.Put_Line ( 'Caricamento DICHIARAZIONI GALLERIE DEI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA');
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale DICHIARAZIONI GALLERIE DEI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA da caricare: ' || TO_CHAR (l_sol_track.COUNT));
         Dbms_Output.Put_Line ( 'Totale DICHIARAZIONI GALLERIE DEI BINARI DI CIRCOLAZIONE DELLE SEZIONI DI LINEA da caricare: ' || TO_CHAR (l_sol_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, ' ' );
--
         Forall i In 1 .. l_sol_track.COUNT SAVE EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_BIN_SOL 
			    (  SOL_TUNNEL_1_1_1_1_8_2,
                   TIPO_DICHIARAZIONE,
                   SOL_TUNNEL_1_1_1_1_8_5O6_AP,
                   SOL_TUNNEL_1_1_1_1_8_5O6,
                   KM_INIZIO,
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO   )
             Select 
			       appl.IDENTIFICATIVO_GALLERIA,
                   'EC',
                   appl.VALORE_CARATTERISTICA,
                   Nvl(val.VALORE_CARATTERISTICA, ' '),
                   Nvl(KM_INIZIO, 0),
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO
              From (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_GALLERIA,
                           VALORE_CARATTERISTICA
                      From Rinf_Staging_Evo.CLASSE_R25350_TR_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R25350_TR_0051')
					) appl,
                   (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_GALLERIA,
                           VALORE_CARATTERISTICA,
                           KM_INIZIO,
                           KM_FINE,
-- 29/01/2018 Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 1)
                                Else LATITUDINE_INIZIO
                           End LATITUDINE_INIZIO,
                           Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 2)
                                Else LONGITUDINE_INIZIO
                           End LONGITUDINE_INIZIO,
                           Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                               Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 1)
                               Else LATITUDINE_FINE
                           End LATITUDINE_FINE,
                           Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 2)
                                Else LONGITUDINE_FINE
                           End LONGITUDINE_FINE,
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 3)
                                Else 0
                           End FLAG_CALCOLATO
                      From Rinf_Staging_Evo.CLASSE_R25350_TR_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R25350_TR_0050')
				    ) val
              Where appl.IDENTIFICATIVO_GALLERIA = l_sol_track(i).ID_TUNNEL
                And appl.IDENTIFICATIVO_GALLERIA = val.IDENTIFICATIVO_GALLERIA(+)
--
             Union
--
            Select appl.IDENTIFICATIVO_GALLERIA,
                   'EI',
                   appl.VALORE_CARATTERISTICA,
                   Nvl(val.VALORE_CARATTERISTICA, ' '),
                   Nvl(KM_INIZIO,0),
                   KM_FINE,
                   LATITUDINE_INIZIO,
                   LONGITUDINE_INIZIO,
                   LATITUDINE_FINE,
                   LONGITUDINE_FINE,
                   FLAG_CALCOLATO
              From (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_GALLERIA,
                           VALORE_CARATTERISTICA
                      From Rinf_Staging_Evo.CLASSE_R25350_TR_MULTIPLA
                     Where CODICE_CARATTERISTICA In ('R25350_TR_0061')
					) appl,
                   (Select CODICE_CARATTERISTICA,
                           IDENTIFICATIVO_GALLERIA,
                           VALORE_CARATTERISTICA,
                           KM_INIZIO,
                           KM_FINE,
-- 29/01/2018 Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 1)
                                Else LATITUDINE_INIZIO
                           End LATITUDINE_INIZIO,
                           Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 2)
                                Else LONGITUDINE_INIZIO
                           End LONGITUDINE_INIZIO,
                           Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                               Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 1)
                               Else LATITUDINE_FINE
                           End LATITUDINE_FINE,
                           Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 2)
                                Else LONGITUDINE_FINE
                           End LONGITUDINE_FINE,
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 3)
                                Else 0
                           End FLAG_CALCOLATO
                      From  Rinf_Staging_Evo.CLASSE_R25350_TR_MULTIPLA
                     Where  CODICE_CARATTERISTICA In ('R25350_TR_0060')
					) val
             Where appl.IDENTIFICATIVO_GALLERIA = l_sol_track(i).ID_TUNNEL
               And appl.IDENTIFICATIVO_GALLERIA = val.IDENTIFICATIVO_GALLERIA(+);
--
      EXCEPTION
         When OTHERS Then
            IF SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                     || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol
                                      || ' TUNNEL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel
                                      || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_tunnel || ''',''R25350_MULTIPLA - INF'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop ;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_TUNNEL_EC - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--
   END SetAcquisitionSOL_TK_TUNNEL_EC;
