-- ------------------------------------------------------------------------------------------------   
--                     PROCEDURE SetAcquisitionSOL_TK_PROFILE
--               Gradiente o Livellette    -   (PAR_1_1_1_1_3_6_gradiente)
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetAcquisitionSOL_TK_PROFILE (n_acquisizione       Number, 
                                         p_error          Out Number  )  Is
   i           Number;
   sqlstring   Varchar2 (5000);
   TYPE dtp_sol_rt IS RECORD
   (  ID_DTP        Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type,
      ID_SOL        Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
      ID_BINARIO    Rinf_Staging_Evo.CLASSE_S23300.IDENTIFICATIVO_BINARIO%Type,
      N_KM_INIZIO   Rinf_Staging_Evo.CLASSE_S23300.KM_INIZIO%Type   );
   TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
   L_DTP_SOL   dtp_sol_t;
 BEGIN
   p_error := 0;
--   
   PKG_RINF_ACQUISIZIONI.SetPulisciSOL_TK_PROFILE (n_caricamento, n_acquisizione, data_caricamento, data_scarico, p_error);
--
   If p_error = 0 Then
--   
        Select s.CODICE_DTP            id_dtp,
               s.SEDE_TECNICA          id_sol,
               B.SOL_TRACK_1_1_1_0_0_1 id_binario,
               p.KM_INIZIO             n_km_inizio
          Bulk Collect Into            l_dtp_sol
-- Ho sostituito la tabella Rinf_Staging_Evo.CLASSE_S23300 con quella dove ho eliminato le chiavi duplicate
          From Rinf_Staging_Evo.CLASSE_S23300_PULITA p, 
               Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA s
         Where p.IDENTIFICATIVO_BINARIO = b.SOL_TRACK_1_1_1_0_0_1
           And b.SEDE_TECNICA = s.SEDE_TECNICA
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> ' || 'Caricamento PROFILO DI GRADIENTE DEI BINARI DI CIRCOLAZIONE DELLE SdL');
         Dbms_Output.Put_Line ('Caricamento PROFILO DI GRADIENTE DEI BINARI DI CIRCOLAZIONE DELLE SdL');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale PROFILO DI GRADIENTE DEI BINARI DI CIRCOLAZIONE DELLE SdL da caricare: ' || To_Char(l_dtp_sol.COUNT));
         Dbms_Output.Put_Line ( 'Totale PROFILO DI GRADIENTE DEI BINARI DI CIRCOLAZIONE DELLE SdL da caricare: ' || To_Char(l_dtp_sol.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, ' ');
--
         Forall i In 1 .. l_dtp_sol.COUNT SAVE EXCEPTIONS
--		 
           Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_1_3_6_GRADIENTE 
			    ( SOL_TRACK_1_1_1_0_0_1,
                  KM_INIZIO,
                  KM_FINE,
                  PENDENZA )
           Select IDENTIFICATIVO_BINARIO,
                  KM_INIZIO,
                  KM_FINE,
                  PENDENZA
             From Rinf_Staging_Evo.CLASSE_S23300_PULITA
            Where IDENTIFICATIVO_BINARIO = l_dtp_sol(i).ID_BINARIO
              And KM_INIZIO = l_dtp_sol(i).N_KM_INIZIO;
--      
	  EXCEPTION
         When OTHERS Then
            If SQLCODE = -24381  Then
               Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line ( 'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT  Loop 
--				 
                  Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,
                        'DTP: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                     || ' BINARIO: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                     || ' KM INIZIO: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).n_km_inizio
                     || ' Errore: ' || SQLERRM (-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ( 'DTP: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp
                                      || ' BINARIO: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario
                                      || ' KM INIZIO: ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).n_km_inizio
                                      || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);
--					 
                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE, CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_sol || ''',';
                  sqlstring := sqlstring || '''' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_binario || ' - ' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).n_km_inizio || ''',''S23300'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_dtp_sol (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).id_dtp || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;

               End Loop;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_PROFILE.1 - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
   Else
      p_error := SQLCODE;
      Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_PROFILE.1 - Errore: ' || Substr(SQLERRM, 1, 300));
   End If;
--  
 END SetAcquisitionSOL_TK_PROFILE;
--
-- ------------------------------------------------------------------------------------------------   
--                          PROCEDURE SetAcquisitionSOL_TK_CAT_LINEA 
--                          categoria della linea  (PAR_1_1_1_1_2_2_CAT_LINEA)
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetAcquisitionSOL_TK_CAT_LINEA (n_acquisizione       Number,                   
                                           p_error          Out Number  )   Is
      i             Number;
      TYPE dtp_sol_rt IS RECORD
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOl_TRACK_1_1_1_0_0_1%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type   );
      TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
      l_sol_track   dtp_sol_t;
      sqlstring     Varchar2 (3000);
   BEGIN
      p_error := 0;
--  INFRASTRUTTURA
        Select Distinct 
		       s.SEDE_TECNICA        id_sol,
               SOl_TRACK_1_1_1_0_0_1 id_binario,
               s.CODICE_DTP          id_dtp
          Bulk Collect Into          l_sol_track
          From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA c,
               Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA s
         Where s.SEDE_TECNICA = b.SEDE_TECNICA
           And SOl_TRACK_1_1_1_0_0_1 = c.IDENTIFICATIVO_BINARIO
           And Upper(VALORE_CARATTERISTICA) <> 'NA'
           And CODICE_CARATTERISTICA ='R16000_TR_0060'
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento PARAMETRO CATEGORIA LINEA DELLE SEZIONI DI LINEA, VISTA INFRASTRUTTURA');
         Dbms_Output.Put_Line ('Caricamento PARAMETRO CATEGORIA LINEA DELLE SEZIONI DI LINEA, VISTA INFRASTRUTTURA');
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale VALORI PARAMETRO CATEGORIA LINEA DELLE SEZIONI DI LINEA, VISTA INFRASTRUTTURA da caricare: ' || To_Char(l_sol_track.COUNT));
         Dbms_Output.Put_Line ('Totale VALORI PARAMETRO CATEGORIA LINEA DELLE SEZIONI DI LINEA, VISTA INFRASTRUTTURA da caricare: ' || To_Char(l_sol_track.COUNT));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' '  );
--
         Forall i In 1 .. l_sol_track.COUNT SAVE EXCEPTIONS

            Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_1_2_2_CAT_LINEA 
			             ( SOL_TRACK_1_1_1_0_0_1,
                           SOL_TRACK_1_1_1_1_2_2,
                           KM_INIZIO,
                           KM_FINE,
                           --SOL_TRACK_1_1_1_1_2_2_AP
                           LATITUDINE_INIZIO,
                           LONGITUDINE_INIZIO,
                           LATITUDINE_FINE,
                           LONGITUDINE_FINE,
                           FLAG_CALCOLATO    )                                                                            --ipotizzato che ci arrivi NA
                    Select val.IDENTIFICATIVO_BINARIO,
                           --Decode(val.VALORE_CARATTERISTICA, 'NA', Null, val.VALORE_CARATTERISTICA),
                           VALORE_CARATTERISTICA,
                           KM_INIZIO,
                           KM_FINE,
                           --Decode(val.VALORE_CARATTERISTICA,'NA','N','Y')
                                -- 29/01/2018 Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 1)
                                Else LATITUDINE_INIZIO
                           End LATITUDINE_INIZIO,
                           Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 2)
                                Else LONGITUDINE_INIZIO
                           End LONGITUDINE_INIZIO,
                           Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                               Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 1)
                               Else LATITUDINE_FINE
                           End LATITUDINE_FINE,
                           Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 2)
                                Else LONGITUDINE_FINE
                           End LONGITUDINE_FINE,
                           Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                                Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 3)
                                Else 0
                           End FLAG_CALCOLATO
                      From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA val
                     Where val.IDENTIFICATIVO_BINARIO = l_sol_track(i).ID_BINARIO
                       And val.CODICE_CARATTERISTICA = 'R16000_TR_0060'
                       And Upper(VALORE_CARATTERISTICA) <> 'NA';
