 Procedure SetAcquisitionSOL_TK_CAP_CAR (n_acquisizione       Number,                   
                                         p_error          Out Number  )   Is
      i             Number;
	  sqlstring     Varchar2 (3000);
      TYPE dtp_sol_rt IS RECORD
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOl_TRACK_1_1_1_0_0_1%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type   );
      TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
      L_SOL_TRACK   dtp_sol_t;
   BEGIN
      p_error := 0;
--  parametro del sottosistema INFRASTRUTTURA
        Select Distinct 
		       s.SEDE_TECNICA         id_sol,
               SOl_TRACK_1_1_1_0_0_1  id_binario,
               s.CODICE_DTP           id_dtp
          Bulk Collect Into l_sol_track
          From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA c,
               Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA s
         Where s.SEDE_TECNICA = b.SEDE_TECNICA
           And SOl_TRACK_1_1_1_0_0_1 = c.IDENTIFICATIVO_BINARIO
           And CODICE_CARATTERISTICA = 'R16000_TR_0080'
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,'--------------------------------> '|| 'Caricamento PARAMETRO CAPACITA CARICO DELLE SEZIONI DI LINEA, VISTA INFRASTRUTTURA');
