                     End FLAG_CALCOLATO
                From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA
               Where IDENTIFICATIVO_BINARIO = l_sol_track(i).ID_BINARIO
                 And CODICE_CARATTERISTICA = 'R16000_TR_0080';
