         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
--
         Forall i In 1 .. L_SOL_TRACK.Count Save EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_3_5_3_SIST_PRE_PROT
			  ( SOL_TRACK_1_1_1_0_0_1,
                SOL_TRACK_1_1_1_3_5_3,
                KM_INIZIO,
                KM_FINE,
                LATITUDINE_INIZIO,
                LONGITUDINE_INIZIO,
                LATITUDINE_FINE,
                LONGITUDINE_FINE,
                FLAG_CALCOLATO
--                SOL_TRACK_1_1_1_3_5_3_AP    
                )                                              
           Select 
			    val.IDENTIFICATIVO_BINARIO,
                --Decode(val.VALORE_CARATTERISTICA,'NA',Null,val.VALORE_CARATTERISTICA),
                VALORE_CARATTERISTICA,
                KM_INIZIO,
                KM_FINE,
-- Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 1)
                     Else LATITUDINE_INIZIO
                End LATITUDINE_INIZIO,
                Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 2)
                     Else LONGITUDINE_INIZIO
                End LONGITUDINE_INIZIO,
                Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 1)
                     Else LATITUDINE_FINE
                End LATITUDINE_FINE,
                Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 2)
                     Else LONGITUDINE_FINE
                End LONGITUDINE_FINE,
                Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 3)
                     Else 0
                End FLAG_CALCOLATO
--				Decode(val.VALORE_CARATTERISTICA,'NA','N','Y')                      -- ? VERIFICARE
          From  Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA val
          Where val.IDENTIFICATIVO_BINARIO = l_sol_track (i).ID_BINARIO
            And val.CODICE_CARATTERISTICA = 'R16000_TR_0693';
--            And Upper(VALORE_CARATTERISTICA) <> 'NA';                                 -- ci arriva NA da INE?
--
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,  'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line (  'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT Loop 
--			   
                  Pkg_Rinf_Utility.SETLINEINTOFILE (  id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL
                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ('DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP
                                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL
                                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO
                                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);

                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO || ''',''R16000_TR_MULTIPLA - CCS'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SETACQUISOL_TK_SIST_PRE_PROT - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SETACQUISOL_TK_SIST_PRE_PROT;
--
-- ------------------------------------------------------------------------------------------------   
--              PROCEDURE SETACQUISOL_TK_SISTRILTRAIN 
-- CTD_TCCheckDocRef /Document with the procedure(s) related to the type of track circuits declared in 1.1.1.3.7.1.2 
-- Documento riportante la/le procedura/e relativa/e ai tipi di sistema di rilevamento del treno di cui al punto 1.1.1.3.7.1.2
-- 1.1.1.3.7.1.3 - PAR_1_1_1_3_7_1_3_SISTRILTRAIN -  parametro del sottosistema CONTROLLO-COMANDO E SEGNALAMENTO 
-- Il parametro è applicabile quando il parametro 1.1.1.3.7.1.2 è valorizzato
-- Dato che non viene valorizzato dal territorio, quindi da In.Rete gli si impone il valore presente in Rinf_anagrafiche_evo.DOMINIO_PARAMETRO
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SETACQUISOL_TK_SISTRILTRAIN (n_acquisizione       Number,                   
                                       p_error          Out Number )   Is
      i             Number;
      sqlstring     Varchar2 (3000);
      Type dtp_sol_rt Is Record
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOl_TRACK_1_1_1_0_0_1%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type  );
      Type dtp_sol_t Is Table Of dtp_sol_rt;
      L_SOL_TRACK   dtp_sol_t;
-- 	  
	  cursor cur_docu is 
	     select CODIFICA_VALORE
          From  Rinf_Anagrafiche_Evo.DOMINIO_PARAMETRO val
          Where codice_parametro = 326;
--
   BEGIN
      p_error := 0;
      Select Distinct 
		       s.SEDE_TECNICA          id_sol,
               SOl_TRACK_1_1_1_0_0_1   id_binario,
               s.CODICE_DTP            id_dtp
          Bulk Collect Into L_SOL_TRACK
          From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA s
         Where s.SEDE_TECNICA = b.SEDE_TECNICA
		   And SOL_TRACK_1_1_1_3_7_1_3_AP = 'Y'               --> aggiunto per selezionare solo i binari "applicabili"
         Order by s.SEDE_TECNICA, SOl_TRACK_1_1_1_0_0_1;

--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,'--------------------------------> '|| 'Caricamento Parametro 1.1.1.3.7.1.3 - CTD_TCCheckDocRef "Documento tipi di sistema di rilevamento del treno" Delle Sezioni Di Linea, Vista CCS');
         Dbms_Output.Put_Line ( 'Caricamento Parametro 1.1.1.3.7.1.3 - CTD_TCCheckDocRef "Documento tipi di sistema di rilevamento del treno" Delle Sezioni Di Linea, Vista CCS');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Valori Parametro 1.1.1.3.7.1.3 - CTD_TCCheckDocRef "Documento tipi di sistema di rilevamento del treno" da caricare: ' || To_Char(L_SOL_TRACK.Count));
         Dbms_Output.Put_Line ( 'Totale Valori Parametro 1.1.1.3.7.1.3 - CTD_TCCheckDocRef "Documento tipi di sistema di rilevamento del treno" da caricare: ' || To_Char(L_SOL_TRACK.Count));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
--
        For rec_docu In cur_docu Loop 

--
          Forall i In 1 .. L_SOL_TRACK.Count Save EXCEPTIONS 
--		 
               Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_3_7_1_3_SISTRILTRAIN
		        ( SOL_TRACK_1_1_1_0_0_1,
                  SOL_TRACK_1_1_1_3_7_1_3   )                                              
               Values
		       (   l_sol_track (i).ID_BINARIO,
                   rec_docu.CODIFICA_VALORE  );
--
       End Loop;

--
      EXCEPTION
         When NO_DATA_FOUND Then
		    Null;
         When OTHERS  Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,  'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line (  'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT Loop 
--			   
                  Pkg_Rinf_Utility.SETLINEINTOFILE (  id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL
                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ('DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP
                                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL
                                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO
                                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);

                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO || ''',''R16000_TR_MULTIPLA - CCS'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SETACQUISOL_TK_SISTRILTRAIN - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      End;
--	  
   END SETACQUISOL_TK_SISTRILTRAIN;

