-- ------------------------------------------------------------------------------------------------   
--              PROCEDURE SETACQUISOL_TK_CARMIN_ASSE 
-- CTD_ MinAxleLoadByVehicleCat  / Minimum permitted axle load per category of Vehicle 
-- Carico minimo consentito per asse per categoria di veicoli
-- 1.1.1.3.7.11.1 - PAR_1_1_1_3_7_11_1_CARMIN_ASSE -  parametro del sottosistema CONTROLLO-COMANDO E SEGNALAMENTO 
-- Il parametro è applicabile quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” è 
--[rilevatore di ruota] o [circuito di binario]
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SETACQUISOL_TK_CARMIN_ASSE (n_acquisizione       Number,                   
                                             p_error          Out Number )   Is
      i             Number;
      sqlstring     Varchar2 (3000);
      Type dtp_sol_rt Is Record
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOl_TRACK_1_1_1_0_0_1%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type  );
      Type dtp_sol_t Is Table Of dtp_sol_rt;
      L_SOL_TRACK   dtp_sol_t;
   BEGIN
      p_error := 0;
      Select Distinct 
		       s.SEDE_TECNICA          id_sol,
               SOl_TRACK_1_1_1_0_0_1   id_binario,
               s.CODICE_DTP            id_dtp
          Bulk Collect Into L_SOL_TRACK
          From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA c,
               Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA s
         Where s.SEDE_TECNICA = b.SEDE_TECNICA
           And SOl_TRACK_1_1_1_0_0_1 = c.IDENTIFICATIVO_BINARIO
--           And Upper(VALORE_CARATTERISTICA) <> 'NA'
           And CODICE_CARATTERISTICA = 'R16000_TR_0822'        --> PARAMETRO assegnato da In.Rete il 02/10/2020
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,'--------------------------------> '|| 'Caricamento Parametro 1.1.1.3.7.11.1 - CTD_ MinAxleLoadByVehicleCat "Carico minimo consentito per asse per categoria di veicoli" Delle Sezioni Di Linea, Vista CCS');
         Dbms_Output.Put_Line ( 'Caricamento Parametro 1.1.1.3.7.11.1 - CTD_ MinAxleLoadByVehicleCat "Carico minimo consentito per asse per categoria di veicoli" Delle Sezioni Di Linea, Vista CCS');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Valori Parametro 1.1.1.3.7.11.1 - CTD_ MinAxleLoadByVehicleCat "Carico minimo consentito per asse per categoria di veicoli" da caricare: ' || To_Char(L_SOL_TRACK.Count));
         Dbms_Output.Put_Line ( 'Totale Valori Parametro 1.1.1.3.7.11.1 - CTD_ MinAxleLoadByVehicleCat "Carico minimo consentito per asse per categoria di veicoli" da caricare: ' || To_Char(L_SOL_TRACK.Count));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
--
         Forall i In 1 .. L_SOL_TRACK.Count Save EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_3_7_11_1_CARMIN_ASSE
			  ( SOL_TRACK_1_1_1_0_0_1,
                SOL_TRACK_1_1_1_3_7_11_1,
                KM_INIZIO,
                KM_FINE,
                LATITUDINE_INIZIO,
                LONGITUDINE_INIZIO,
                LATITUDINE_FINE,
                LONGITUDINE_FINE,
                FLAG_CALCOLATO
                )                                              
           Select 
			    val.IDENTIFICATIVO_BINARIO,
                Decode(val.VALORE_CARATTERISTICA,'NA',Null, '10','40', val.VALORE_CARATTERISTICA),   -- modifica del 22/07/2021 per gestire la modifica del codice da '10' a '40'
--                VALORE_CARATTERISTICA,
                KM_INIZIO,
                KM_FINE,
-- Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 1)
                     Else LATITUDINE_INIZIO
                End LATITUDINE_INIZIO,
                Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 2)
                     Else LONGITUDINE_INIZIO
                End LONGITUDINE_INIZIO,
                Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 1)
                     Else LATITUDINE_FINE
                End LATITUDINE_FINE,
                Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 2)
                     Else LONGITUDINE_FINE
                End LONGITUDINE_FINE,
                Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 3)
                     Else 0
                End FLAG_CALCOLATO
          From  Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA val
          Where val.IDENTIFICATIVO_BINARIO = l_sol_track (i).ID_BINARIO
            And val.CODICE_CARATTERISTICA = 'R16000_TR_0822';
--            And Upper(VALORE_CARATTERISTICA) <> 'NA';                                 -- ci arriva NA da INE?
--
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,  'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line (  'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT Loop 
--			   
                  Pkg_Rinf_Utility.SETLINEINTOFILE (  id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL
                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ('DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP
                                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL
                                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO
                                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);

                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO || ''',''R16000_TR_MULTIPLA - CCS'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SETACQUISOL_TK_CARMIN_ASSE - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SETACQUISOL_TK_CARMIN_ASSE;
--
-- ------------------------------------------------------------------------------------------------   
--              PROCEDURE SETACQUISOL_TK_NORME_DOC 
-- RUL_LocalRulesOrRestrictionsDocRef /Reference of the documentsDocuments regarding the rules or restrictions of a strictly local nature available by the IM 
-- Documenti relativi a norme e restrizioni di natura strettamente locale messi a disposizione dal GI
-- 1.1.1.4.2 - PAR_1_1_1_4_2_NORME_DOC -  parametro del sottosistema NORME E RESTRIZIONI 
-- Il parametro è applicabile quando il valore del parametro 1.1.1.4.1“Esistenza di norme e restrizioni di natura strettamente locale” è [S].
-- ------------------------------------------------------------------------------------------------   
--

 Procedure SETACQUISOL_TK_NORME_DOC (n_acquisizione       Number,                   
                                           p_error          Out Number )   Is
      i             Number;
      sqlstring     Varchar2 (3000);
      Type dtp_sol_rt Is Record
      (  ID_SOL       Rinf_Staging_Evo.CLASSE_R13000.SEDE_TECNICA%Type,
         ID_BINARIO   Rinf_Staging_Evo.CLASSE_R16000_TR.SOl_TRACK_1_1_1_0_0_1%Type,
         ID_DTP       Rinf_Staging_Evo.CLASSE_R13000.CODICE_DTP%Type  );
      Type dtp_sol_t Is Table Of dtp_sol_rt;
      L_SOL_TRACK   dtp_sol_t;
   BEGIN
      p_error := 0;
      Select Distinct 
		       s.SEDE_TECNICA          id_sol,
               SOl_TRACK_1_1_1_0_0_1   id_binario,
               s.CODICE_DTP            id_dtp
          Bulk Collect Into L_SOL_TRACK
          From Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA c,
               Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
               Rinf_Lavorazione_Evo.SEZIONI_LINEA s
         Where s.SEDE_TECNICA = b.SEDE_TECNICA
           And SOl_TRACK_1_1_1_0_0_1 = c.IDENTIFICATIVO_BINARIO
           And Upper(VALORE_CARATTERISTICA) <> 'NA'
           And CODICE_CARATTERISTICA = 'R16000_TR_nnnn'        --> AGGIORNARE IL PARAMETRO assegnato da In.Rete
         Order by 1;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,'--------------------------------> '|| 'Caricamento Parametro 1.1.1.4.2 - RUL_LocalRulesOrRestrictionsDocRef "Documenti relativi a norme e restrizioni" Delle Sezioni Di Linea, Vista Norme e Restrizioni');
         Dbms_Output.Put_Line ( 'Caricamento Parametro 1.1.1.4.2 - RUL_LocalRulesOrRestrictionsDocRef "Documenti relativi a norme e restrizioni" Delle Sezioni Di Linea, Vista Norme e Restrizioni');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Totale Valori Parametro 1.1.1.4.2 - RUL_LocalRulesOrRestrictionsDocRef "Documenti relativi a norme e restrizioni" da caricare: ' || To_Char(L_SOL_TRACK.Count));
         Dbms_Output.Put_Line ( 'Totale Valori Parametro 1.1.1.4.2 - RUL_LocalRulesOrRestrictionsDocRef "Documenti relativi a norme e restrizioni" da caricare: ' || To_Char(L_SOL_TRACK.Count));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, ' ' );
--
         Forall i In 1 .. L_SOL_TRACK.Count Save EXCEPTIONS
--		 
            Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_4_2_NORME_DOC
			  ( SOL_TRACK_1_1_1_0_0_1,
                SOL_TRACK_1_1_1_4_2,
                KM_INIZIO,
                KM_FINE,
                LATITUDINE_INIZIO,
                LONGITUDINE_INIZIO,
                LATITUDINE_FINE,
                LONGITUDINE_FINE,
                FLAG_CALCOLATO
--                SOL_TRACK_1_1_1_4_2_AP    
                )                                              
           Select 
			    val.IDENTIFICATIVO_BINARIO,
                --Decode(val.VALORE_CARATTERISTICA,'NA',Null,val.VALORE_CARATTERISTICA),
                VALORE_CARATTERISTICA,
                KM_INIZIO,
                KM_FINE,
-- Inserito il calcolo delle coordinate del LAM In caso non arrivino da IN.RETE
                Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 1)
                     Else LATITUDINE_INIZIO
                End LATITUDINE_INIZIO,
                Case When LONGITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 2)
                     Else LONGITUDINE_INIZIO
                End LONGITUDINE_INIZIO,
                Case When LATITUDINE_FINE Is Null And KM_FINE Is Not Null
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 1)
                     Else LATITUDINE_FINE
                End LATITUDINE_FINE,
                Case When LONGITUDINE_FINE Is Null And KM_FINE Is Not Null
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_FINE, 2)
                     Else LONGITUDINE_FINE
                End LONGITUDINE_FINE,
                Case When LATITUDINE_INIZIO Is Null And KM_INIZIO <> 0
                     Then GetLatLonFromKm(l_sol_track(i).ID_SOL, KM_INIZIO, 3)
                     Else 0
                End FLAG_CALCOLATO
--				Decode(val.VALORE_CARATTERISTICA,'NA','N','Y')                      -- ? VERIFICARE
          From  Rinf_Staging_Evo.CLASSE_R16000_TR_MULTIPLA val
          Where val.IDENTIFICATIVO_BINARIO = l_sol_track (i).ID_BINARIO
            And val.CODICE_CARATTERISTICA = 'R16000_TR_nnnn'                          -->AGGIORNARE
            And Upper(VALORE_CARATTERISTICA) <> 'NA';                                 -- ci arriva NA da INE?
--
      EXCEPTION
         When OTHERS  Then
            If SQLCODE = -24381 Then
               Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,  'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
               Dbms_Output.Put_Line (  'Totale Errori: ' || SQL%BULK_EXCEPTIONS.COUNT);
--
               For indx In 1 .. SQL%BULK_EXCEPTIONS.COUNT Loop 
--			   
                  Pkg_Rinf_Utility.SETLINEINTOFILE (  id_file,
                        'DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP
                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL
                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO
                     || ' Errore: ' || SQLERRM(-SQL%BULK_EXCEPTIONS (indx).ERROR_CODE));
--					 
                  Dbms_Output.Put_Line ('DTP: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP
                                     || ' SOL: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL
                                     || ' BINARIO: ' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO
                                     || ' Codice errore: ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE);

                  sqlstring := 'Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE (CODICE_ACQUISIZIONE, CODICE_SOL_PO, SEDE_TECNICA, CLASSE,CODICE_ERRORE, CODICE_DTP)';
                  sqlstring := sqlstring || 'VALUES ( ';
                  sqlstring := sqlstring || n_acquisizione || ',''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_SOL || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_BINARIO || ''',''R16000_TR_MULTIPLA - Norme e Restrizioni'', ';
                  sqlstring := sqlstring || '''ORA-' || SQL%BULK_EXCEPTIONS (indx).ERROR_CODE || ''',';
                  sqlstring := sqlstring || '''' || l_sol_track (SQL%BULK_EXCEPTIONS (indx).ERROR_INDEX).ID_DTP || ''')';
--
                  EXECUTE IMMEDIATE sqlstring;
--				  
               End Loop;
            Else
               p_error := SQLCODE;
               Dbms_Output.Put_Line ('SETACQUISOL_TK_NORME_DOC - Errore: ' || Substr(SQLERRM, 1, 300));
            End If;
      END;
--	  
   END SETACQUISOL_TK_NORME_DOC;

--
-- ------------------------------------------------------------------------------------------------   
--                                         PROCEDURE SetAcquisitionSOL
--   procedura per l'esecuzione delle altre procedure relative ai parametri delle SOL in sequenza
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetAcquisitionSOL (n_acquisizione Number, p_error Out Number) Is
     i   Number;
  BEGIN
      i := 1;
      p_error := 0;
--
      SetAcquisitionSOL_SOL (n_acquisizione, p_error); --1
--
      IF p_error = 0 Then --1
           COMMIT;
           SetAcquisitionSOL_TRACK (n_acquisizione, p_error);  --2
--
           IF p_error = 0 Then  --2
                COMMIT;
                SetAcquisitionSOL_TRACK_INF_EC (n_acquisizione, p_error); --3
--
                IF p_error = 0 Then  --3
                     COMMIT; 
                     SetAcquisitionSOL_TRACK_ENE_EC (n_acquisizione, p_error);  --4
--                 
                     IF p_error = 0 Then  --4
                        COMMIT;
                        SetAcquisitionSOL_TRACK_CCS_EC (n_acquisizione, p_error);  --5
--                 
                        IF p_error = 0 Then  --5
                           COMMIT;
                           SetAcquisitionSOL_TRACK_TUNNEL (n_acquisizione, p_error);  --6
--                 
                           IF p_error = 0 Then  --6
                              COMMIT;
                              SetAcquisitionSOL_BRANCHED_TUN (n_acquisizione, p_error);  --7
--                 
                              IF p_error = 0 Then  --7
                                 COMMIT;
                                 SetAcquisitionSOL_TK_TUNNEL_EC (n_acquisizione, p_error);  --8
--                 
                                 IF p_error = 0 Then  --8
                                    COMMIT;
                                    SetAcquisitionSOL_TK_PROFILE (n_acquisizione, p_error);  --9
--                 
                                    IF p_error = 0 Then --9
                                       COMMIT;
                                       SetAcquisitionSOL_TK_CAT_LINEA (n_acquisizione, p_error);  --10
--                 
                                       IF p_error = 0 Then --10
                                          COMMIT;
                                          SetAcquisitionSOL_TK_CAP_CAR (n_acquisizione, p_error);  --11
--                 
                                          IF p_error = 0 Then  --11
                                              COMMIT;
                                              SetAcquisitionSOL_TK_CASSE_M (n_acquisizione, p_error);  --12
--
                                              IF p_error = 0 Then  --12
                                                  COMMIT;
                                                  SetAcquisitionSOL_TK_SEMI_R (n_acquisizione, p_error);  --13
--
                                                  IF p_error = 0 Then  --13
                                                  COMMIT;
                                                  SetAcquisitionSOL_TK_GSM_R (n_acquisizione, p_error);  --14
-->

                                                IF p_error = 0 Then  --14
                                                    COMMIT;
                                                    SetAcquiSOL_TK_LOCAVERSPECEC (n_acquisizione, p_error);  --15
                                                IF p_error = 0 Then  --15
                                                    COMMIT;
                                                    SETACQUISOL_TK_LOCA_SIST_RTB (n_acquisizione, p_error);  --16
                                                IF p_error = 0 Then   --16
                                                    COMMIT;
                                                    SetAcquisitionSOL_TK_COMP_ETCS (n_acquisizione, p_error);  --17
                                                IF p_error = 0 Then   --17
                                                    COMMIT;
                                                    SETACQUISOL_TK_RETI_GSM_R (n_acquisizione, p_error);  --18
                                                IF p_error = 0 Then  --18
                                                    COMMIT;
                                                    SETACQUISOL_TK_RADIO_VOCE (n_acquisizione, p_error);  --19
                                                IF p_error = 0 Then --19
                                                    COMMIT;
                                                    SETACQUISOL_TK_RADIO_DATI (n_acquisizione, p_error);  --20
                                                IF p_error = 0 Then --20
                                                    COMMIT;
                                                    SETACQUISOL_TK_SIST_PRE_PROT (n_acquisizione, p_error);  --21
                                                IF p_error = 0 Then  --21
                                                    COMMIT;
                                                    SETACQUISOL_TK_SISTRILTRAIN (n_acquisizione, p_error);  --22
                                                IF p_error = 0 Then  --22
                                                    COMMIT;
                                                    SETACQUISOL_TK_CARMIN_ASSE (n_acquisizione, p_error);  --23
--                                                IF p_error = 0 Then  --23
--                                                    COMMIT;
--                                                    SETACQUISOL_TK_NORME_DOC (n_acquisizione, p_error);   --24
-->
                                          IF p_error = 0 Then  --24
                                             COMMIT;
                                             SetAcquisitionOP_FermataTunnel (n_acquisizione,p_error);  --25
--
                                             IF p_error = 0 Then  --25
                                                COMMIT;
											 Else 
											     Dbms_Output.Put_Line ('SetAcquisitionOP_FermataTunnel - Errore');   --25
												 Rollback;
                                             END IF; --25
--> 
--										  Else 
--											   Dbms_Output.Put_Line ('SETACQUISOL_TK_NORME_DOC - Errore');   --24
--											   Rollback;
--                                                 END IF;  --24
										  Else 
											   Dbms_Output.Put_Line ('SETACQUISOL_TK_CARMIN_ASSE - Errore');  --23
											   Rollback;

                                                 END IF;  --23
										  Else 
											   Dbms_Output.Put_Line ('SETACQUISOL_TK_SISTRILTRAIN - Errore');   --22
											   Rollback;
                                                 END IF;  --22
										  Else  
											   Dbms_Output.Put_Line ('SETACQUISOL_TK_SIST_PRE_PROT - Errore');  --21
											   Rollback;

                                                 END IF;  --21
										  Else 
											   Dbms_Output.Put_Line ('SETACQUISOL_TK_RADIO_DATI - Errore');   --20
											   Rollback;

                                                 END IF;  --20
										  Else 
											   Dbms_Output.Put_Line ('SETACQUISOL_TK_RADIO_VOCE - Errore');  --19
											   Rollback;

                                                 END IF;  --19
										  Else 
											   Dbms_Output.Put_Line ('SETACQUISOL_TK_RETI_GSM_R - Errore');  --18
											   Rollback;

                                                 END IF; --18
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_COMP_ETCS - Errore');  --17
											   Rollback;
                                                 END IF;  --17
										  Else 
											   Dbms_Output.Put_Line ('SETACQUISOL_TK_LOCA_SIST_RTB  - Errore');  --16
											   Rollback;
                                                 END IF;  --16
										  Else 
											   Dbms_Output.Put_Line ('SetAcquiSOL_TK_LOCAVERSPECEC - Errore');   --15
											   Rollback;
                                                 END IF;  --15

										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_GSM_R  - Errore');  --14
											   Rollback;
                                        END IF;  --14
-->
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_SEMI_R - Errore'); --13
											   Rollback;
                                       END IF;  --13
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_CASSE_M  - Errore');  --12
											   Rollback;
                                    END IF;   --12
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_CAP_CAR - Errore');  --11
											   Rollback;
                                 END IF;    --11
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_CAT_LINEA - Errore');  --10
											   Rollback;
                              END IF;  --10
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_PROFILE - Errore'); --9
											   Rollback;
                           END IF;  --9
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TK_TUNNEL_EC - Errore');  --8
											   Rollback;
                        END IF;  --8
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_BRANCHED_TUN - Errore');   --7
											   Rollback;											  
                     END IF; --7
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_TUNNEL - Errore');  --6
											   Rollback;
                  END IF; --6
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_CCS_EC - Errore');  --5
											   Rollback;
               END IF;  --5
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_ENE_EC - Errore');  --4
											   Rollback;
            END IF;  --4
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK_INF_EC - Errore'); --3
											   Rollback;
         END IF;  --3
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_TRACK - Errore');   --2
											   Rollback;
      END IF; --2
										  Else 
											   Dbms_Output.Put_Line ('SetAcquisitionSOL_SOL - Errore');  --1
											   Rollback;
   END IF; --1
--   
 EXCEPTION
   When OTHERS
   Then
      p_error := SQLCODE;
      Dbms_Output.Put_Line ('SetAcquisitionSOL - Errore: ' || Substr(SQLERRM, 1, 300));
 END SetAcquisitionSOL;
--
-- ------------------------------------------------------------------------------------------------   
--                             PROCEDURE GetLoadedDataAvailableID
-- ------------------------------------------------------------------------------------------------   

 Procedure GetLoadedDataAvailableID (n_codice           Out Number,
                                     data_caricamento   Out Date,
                                     data_scarico       Out Date )   Is
     n_conta   Number;
	 ultimo_caricamento Number;
--
 Begin
  Select Max(CODICE_CARICAMENTO) into ultimo_caricamento 
   From  Rinf_Staging_Evo.ANAG_CARICAMENTI
   Where codice_esito = 1;

   Select CODICE_CARICAMENTO, DATA_CARICAMENTO, DATA_SCARICO
     Into n_codice, data_caricamento, data_scarico
     From Rinf_Staging_Evo.ANAG_CARICAMENTI
    Where CODICE_CARICAMENTO = ultimo_caricamento;     
--
   Select Count(*) Into n_conta From  Rinf_Staging_Evo.GIS_LOCA_RETE;
--  
   If n_conta > 0  Then
      Select Max(LO_ALLINEAMENTO_INRETE)  Into DATA_MDR_GIS
        From Rinf_Staging_Evo.GIS_LOCA_RETE;
   Else  --15/11/2017 Gestione Storicizzazione GIS
      Select Max(DATA_RIFERIMENTO)   Into DATA_MDR_GIS
        From Rinf_Gis_Evo.ANAG_MDR;
   End If;
--   
   EXCEPTION
      When NO_DATA_FOUND Then
         n_codice := Null;
         data_caricamento := Null;
         data_mdr_gis := Null;
 END GetLoadedDataAvailableID;
--
-- ------------------------------------------------------------------------------------------------   
--              PROCEDURE SetLoadedDataNotAvailableID 
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetLoadedDataNotAvailableID (n_codice       Number,
                                          p_error    Out Number )    Is
   BEGIN
      p_error := 0;
--
      Update Rinf_Staging_Evo.ANAG_CARICAMENTI
         Set DATA_ACQUISIZIONE = Sysdate
       Where  CODICE_CARICAMENTO = n_codice;
--	   
   EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetLoadedDataNotAvailableID - Errore: ' || Substr(SQLERRM, 1, 300));
   END SetLoadedDataNotAvailableID;
--
-- ------------------------------------------------------------------------------------------------   
--                            PROCEDURE SetLogOfAcquisition
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetLogOfAcquisition (n_caricamento          Number,
                                data_caricamento       Date,
                                data_scarico           Date,
                                p_error            Out Number )   Is
      TYPE dtp_ogg_rt IS RECORD
      (  ID_DTP     Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
         C_SOL_OP   Varchar2 (300),
         D_SOL_OP   Varchar2 (500)  );
      TYPE dtp_ogg_t IS TABLE OF dtp_ogg_rt;
      L_DTP_OGG   dtp_ogg_t;
--
   BEGIN
      p_error := 0;
--
        Select a.CODICE_DTP ID_DTP, a.CONTEGGIO C_SOL_OP, Null
          Bulk Collect Into l_dtp_ogg
          From ( Select  CODICE_DTP,
                         'Numero Punti Operativi: ' || COUNT (*) conteggio
                    From Rinf_Staging_Evo.CLASSE_R03000
                   Group By CODICE_DTP
                 Union
                  Select  CODICE_DTP,
                          'Numero Sezioni di Linea: ' || COUNT (*) conteggio
                     From Rinf_Staging_Evo.CLASSE_R13000
                    Group By CODICE_DTP
				) a
      Order by 1, 2;
--
      nome_file := 'AcquisitionStep2_' || To_Char(n_caricamento) || '_' || To_Char(data_caricamento, 'DDMMYYYY') || '.log';
--
      id_file := Pkg_Rinf_Utility.SETFILELOG (nome_file, 'RINF_DIR', data_caricamento);
--
      Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file, 'Acquisizione dati (Step 2), relativo al caricamento numero '
                                                  || To_Char(n_caricamento)
                                                  || ' del '
                                                  || To_Char(DATA_CARICAMENTO, 'DD/MM/YYYY')
                                                  || ', scarico dati del '
                                                  || To_Char(DATA_SCARICO, 'DD/MM/YYYY')
                                                  || ', Modello GIS relativo ai dati del '
                                                  || To_Char(DATA_MDR_GIS, 'DD/MM/YYYY')
									    );
--
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,' ');
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,'--------------------------------> '|| 'Conteggio oggetti presenti nell''area di Staging');
--
      For i In 1 .. l_dtp_ogg.COUNT   Loop 

            Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'DTP: '|| l_dtp_ogg(i).ID_DTP || '       ' || l_dtp_ogg(i).C_SOL_OP);

      End Loop ;
--	  
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,' ');
-- -----------------------------------------------------------------------
-- 04/05/2015 Conteggio oggetti effettivi che vengono considerati nel RINF
-- -----------------------------------------------------------------------
-- Punti Operativi (OP)
      Select a.CODICE_DTP ID_DTP, a.CONTEGGIO C_SOL_OP, Null
        Bulk Collect Into l_dtp_ogg
        From (  Select CODICE_DTP, 'Numero Punti Operativi: ' || Count(*) conteggio
                  From Rinf_Staging_Evo.CLASSE_R03000
                 Where(STATO_SISTEMA = 'CREA'
                   And STATO_UTENTE = 'ESER IPIC'
                   And TIPO_LOCALITA_CONFINE In ('NO', 'AL', 'AF')
                   And CODICE_DTP <> 'DG00'  )
                    Or 
				      (STATO_SISTEMA = 'CREA'
                   And Upper(STATO_UTENTE) In ('ESER IPIC', 'CONC IPIC', 'MODI IPIC')
                   And TIPO_LOCALITA_CONFINE In ('NA', 'RE')
					   )
                   Or 
				      (STATO_SISTEMA = 'CREA'
                   And Upper(STATO_UTENTE) In ('CONC IPIC', 'MODI IPIC')
                   And TIPO_LOCALITA_CONFINE = 'AF'
					   ) --aggiunti i Border Point
               Group By CODICE_DTP
-- Tratte (SoL)
              Union
               Select CODICE_DTP, 'Numero Sezioni di Linea: ' || COUNT (*) conteggio
                 From Rinf_Staging_Evo.CLASSE_R13000
                Where STATO_SISTEMA =  'CREA'
                  And STATO_UTENTE  =  'ESER IPIC'
                  And CODICE_DTP   <>  'DG00'
               Group By CODICE_DTP
			  ) a
     Order by 1, 2;
--
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, ' ');
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '--------------------------------> '||
                                                'Conteggio oggetti dell''area di Staging che verranno caricati nell''area di lavorazione del RINF');
--
      For i In 1 .. l_dtp_ogg.COUNT Loop 
--
            Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'DTP: ' || l_dtp_ogg(i).ID_DTP || '       ' || l_dtp_ogg(i).C_SOL_OP);
--
      End Loop ;
--
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, ' ');
-- ---------------------------------------------------------------------------------------------------	  
-- 04/05/2015 Conteggio oggetti presenti nell''area Controllati che devono essere eliminati perchè non più In esercizio
-- ---------------------------------------------------------------------------------------------------
      Select a.CODICE_DTP id_dtp, a.CONTEGGIO c_sol_op, Null
          Bulk Collect Into l_dtp_ogg
          From (  Select CODICE_DTP,
                         'Numero Punti Operativi: ' || Count(*) conteggio
                    From  Rinf_Controllati_Evo.PUNTI_OPERATIVI p,
                          Rinf_Staging_Evo.CLASSE_ELIMINATI e
                    Where e.SEDE_TECNICA = p.SEDE_TECNICA
                    Group By CODICE_DTP
                Union
                  Select CODICE_DTP,
                         'Numero Sezioni di Linea: ' || Count(*) conteggio
                    From  Rinf_Controllati_Evo.SEZIONI_LINEA p,
                          Rinf_Staging_Evo.CLASSE_ELIMINATI e
                    Where e.SEDE_TECNICA = p.SEDE_TECNICA
                    Group By CODICE_DTP
				) a
           Order by 1, 2;
--
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, ' ');
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '--------------------------------> '||
                                        'Conteggio oggetti presenti nell''area controllati che devono essere eliminati perchè non più In esercizio');
--
      For i In 1 .. l_dtp_ogg.COUNT  Loop 
--
            Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'DTP: '|| l_dtp_ogg(i).ID_DTP || '       ' || l_dtp_ogg(i).C_SOL_OP);
--
      End Loop ;
--
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,' ');
-- ---------------------------------------------------------------------------------------
--25/05/2016 Elenco oggetti presenti nell''area Controllati che devono essere eliminati perchè non più In esercizio
-- ---------------------------------------------------------------------------------------
      Select a.CODICE_DTP id_dtp, a.SEDE_TECNICA c_Sol_Op, a.DEFINIZIONE d_Sol_Op
          Bulk Collect Into l_dtp_ogg
          From (  Select CODICE_DTP, p.SEDE_TECNICA, DEFINIZIONE
                    From Rinf_Controllati_Evo.PUNTI_OPERATIVI p,
                         Rinf_Staging_Evo.CLASSE_ELIMINATI e
                   Where e.SEDE_TECNICA = p.SEDE_TECNICA
                 Union
                  Select  CODICE_DTP,p.SEDE_TECNICA,DEFINIZIONE
                    From  Rinf_Controllati_Evo.SEZIONI_LINEA p,
                          Rinf_Staging_Evo.CLASSE_ELIMINATI e
                    Where e.SEDE_TECNICA = p.SEDE_TECNICA) a
      Order by 1, 2;
--
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, ' ');
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '--------------------------------> '||
                                        'Elenco oggetti presenti nell''area controllati che devono essere eliminati perchè non più In esercizio');
--
      For i In 1 .. l_dtp_ogg.COUNT  Loop 
--
            Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'DTP: ' || l_dtp_ogg(i).ID_DTP || '       ' || l_dtp_ogg(i).C_SOL_OP || '       ' || l_dtp_ogg(i).D_SOL_OP);
--
      End Loop ;
--	  
---->
-- ---------------------------------------------------------------------------------
--24/07/2023 Elenco oggetti presenti nel REGISTRO che dovevano essere eliminati perchè non più In esercizio nelle precedenti acquisizioni
-- ma che non è stato possibile per la mancata Autorizzazione di DCO
-- ----------------------------------------------------------------------------------
      Select a.CODICE_DTP id_dtp, a.SEDE_TECNICA c_Sol_Op, a.DEFINIZIONE d_Sol_Op
          Bulk Collect Into l_dtp_ogg
          From (  Select p.CODICE_DTP, p.SEDE_TECNICA, p.DEFINIZIONE
                    From Rinf_Controllati_Evo.PUNTI_OPERATIVI p,
                         Rinf_Anagrafiche_Evo.REGISTRO_SEDI_ELIMINATE_NUOVE e
                   Where e.SEDE_TECNICA = p.SEDE_TECNICA 
				     And e.CODICE_VERSIONE = (select max(codice_versione) from Rinf_Pubblicati_evo.VERSIONE_RINF)
					 And e.FLAG_TIPO = -1
            		 And e.FLAG_STATO_FINALE = 0
                 Union
	              Select  p.CODICE_DTP, p.SEDE_TECNICA, p.DEFINIZIONE
                    From  Rinf_Controllati_Evo.SEZIONI_LINEA p,
                          Rinf_Anagrafiche_Evo.REGISTRO_SEDI_ELIMINATE_NUOVE e
                    Where e.SEDE_TECNICA = p.SEDE_TECNICA
				      And e.CODICE_VERSIONE = (select max(codice_versione) from Rinf_Pubblicati_evo.VERSIONE_RINF)
					 And e.FLAG_TIPO = -1
            		 And e.FLAG_STATO_FINALE = 0
            	) a
		Where a.SEDE_TECNICA not in (Select SEDE_TECNICA From Rinf_Staging_Evo.CLASSE_ELIMINATI)
      Order by 1, 2;
--
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, ' ');
--      DBMS_OUTPUT.Put_Line(' ');
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '--------------------------------> '||
--      DBMS_OUTPUT.Put_Line('--------------------------------> '||
                                        'Elenco oggetti presenti nel REGISTRO che dovevano essere eliminati nella precedente acquisizione ma, che DCO non aveva Autorizzato');

      For i In 1 .. l_dtp_ogg.COUNT  Loop 
--	  
            Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'DTP: ' || l_dtp_ogg(i).ID_DTP || '       ' || l_dtp_ogg(i).C_SOL_OP || '       ' || l_dtp_ogg(i).D_SOL_OP);
--            DBMS_OUTPUT.Put_Line( 'DTP: '|| l_dtp_ogg(i).ID_DTP || '       ' || l_dtp_ogg(i).C_SOL_OP);
      End Loop ;	
---->	
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,' ');
--
   EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetLogOfAcquisition - Errore: ' || Substr(SQLERRM, 1, 300));
  END SetLogOfAcquisition;
--
-- ------------------------------------------------------------------------------------------------   
--                          PROCEDURE SetNewAcquisitionID
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetNewAcquisitionID (n_caricamento        Number,
                                  n_acquisizione   Out Number,
                                  p_error          Out Number )   Is
   BEGIN
      p_error := 0;
--
      Select Max(CODICE_ACQUISIZIONE) + 1   Into n_acquisizione
        From Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI;
--
      n_acquisizione := Nvl(n_acquisizione, 1);
--
      Insert Into Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI 
	             ( CODICE_ACQUISIZIONE,
                   DATA_ACQUISIZIONE,
                   CODICE_CARICAMENTO,
                   CODICE_DSS   )
         Values (  n_acquisizione,
                   Sysdate,
                   n_caricamento,
                   1            );
   EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetNewAcquisitionID - Errore: ' || Substr(SQLERRM, 1, 300));
   END SetNewAcquisitionID;
--
-- ------------------------------------------------------------------------------------------------   
--                             PROCEDURE SetOutInvalidOP
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetOutInvalidOP (id_op Varchar2, p_error Out Number)    Is
   BEGIN
     p_error := 0;
--
     Delete From Rinf_Lavorazione_Evo.PAR_1_2_1_0_2_1_CAT_TEN_PO         --multivalore 082 agosto
           Where PO_TRACK_1_2_1_0_0_2 In 
		        (Select b.PO_TRACK_1_2_1_0_0_2
                   From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                        Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                  Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2 
				    And r.SEDE_TECNICA = id_op
				 );
--
     Delete From Rinf_Lavorazione_Evo.PAR_1_2_1_0_2_2_CAT_LINEA           --multivalore 082 agosto
           Where PO_TRACK_1_2_1_0_0_2 In 
		        (Select b.PO_TRACK_1_2_1_0_0_2
                   From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                        Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                  Where r.PO_TRACK_1_2_1_0_0_2=b.PO_TRACK_1_2_1_0_0_2 
				    And r.SEDE_TECNICA = id_op
				 );
--
     Delete From Rinf_Lavorazione_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL          --multivalore 082 agosto
           Where PO_TR_PLATFORM_1_2_1_0_6_2 In
                (Select PO_TR_PLATFORM_1_2_1_0_6_2
                   From Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
                  Where Nvl (BINARIO_1, 'NullO') In
                             (Select b.PO_TRACK_1_2_1_0_0_2
                                From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                                     Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                               Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                                 And r.SEDE_TECNICA = id_op
							  )
                     Or Nvl (BINARIO_2, 'NullO') In
                             (Select b.PO_TRACK_1_2_1_0_0_2
                                From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                                     Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                               Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                                 And r.SEDE_TECNICA = id_op
							  )
                     Or Nvl (BINARIO_3, 'NullO') In
                             (Select b.PO_TRACK_1_2_1_0_0_2
                                From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                                     Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                               Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                                 And r.SEDE_TECNICA = id_op
							  )
                     Or Nvl (BINARIO_4, 'NullO') In
                             (Select b.PO_TRACK_1_2_1_0_0_2
                                From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                                     Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                               Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                                 And r.SEDE_TECNICA = id_op
						      )
				);
--
     Delete From Rinf_Lavorazione_Evo.PAR_1_2_2_0_0_3_CAT_TEN_SD                         --multivalore 082 agosto
           Where PO_SD_1_2_2_0_0_2 In 
		        (Select PO_SD_1_2_2_0_0_2
                   From Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO
                  Where SEDE_TECNICA = id_op);
-- Binario Raccordo
     Delete From Rinf_Lavorazione_Evo.REL_GALLERIE_RACCORDO_PO
           Where PO_SD_1_2_2_0_0_2 In 
			     (Select PO_SD_1_2_2_0_0_2
                    From Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO
                   Where SEDE_TECNICA = id_op
				  );
--
     Delete From Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_SD_PO
           Where PO_SD_TUNNEL_1_2_2_0_5_2 In
                (Select PO_SD_TUNNEL_1_2_2_0_5_2
                   From Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_SD_PO
                 Minus
                 Select PO_SD_TUNNEL_1_2_2_0_5_2
                   From Rinf_Lavorazione_Evo.REL_GALLERIE_RACCORDO_PO
				 );
--
     Delete From Rinf_Lavorazione_Evo.GALLERIE_RACCORDO_PO
           Where PO_SD_TUNNEL_1_2_2_0_5_2 In
                (Select PO_SD_TUNNEL_1_2_2_0_5_2
                   From Rinf_Lavorazione_Evo.GALLERIE_RACCORDO_PO
                 Minus
                 Select PO_SD_TUNNEL_1_2_2_0_5_2
                   From Rinf_Lavorazione_Evo.REL_GALLERIE_RACCORDO_PO
				 );
--
     Delete From Rinf_Lavorazione_Evo.DICHIARAZIONI_RACCORDO_PO
           Where PO_SD_1_2_2_0_0_2 In 
		        (Select PO_SD_1_2_2_0_0_2
                   From Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO
                  Where SEDE_TECNICA = id_op
				 );
--
     Delete From Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO
           Where SEDE_TECNICA = id_op;

-- BINARI DI CIRCOLAZIONE
-- Delete From  Rinf_Lavorazione_Evo.DICHIARAZIONI_MARCIAP_BIN_PO;
     Delete From Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
           Where BINARIO_1 In
                  (Select b.PO_TRACK_1_2_1_0_0_2
                     From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                          Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                    Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                      And r.SEDE_TECNICA = id_op
				   )
              Or BINARIO_2 In
                  (Select b.PO_TRACK_1_2_1_0_0_2
                     From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                          Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                    Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                      And r.SEDE_TECNICA = id_op
				   )
              Or BINARIO_3 In 
			      (Select b.PO_TRACK_1_2_1_0_0_2
                     From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                          Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                    Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                      And r.SEDE_TECNICA = id_op
				   )
              Or BINARIO_4 In 
	              (Select b.PO_TRACK_1_2_1_0_0_2
                           From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                                Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                          Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                            And r.SEDE_TECNICA = id_op
	        	   );
--
     Delete From Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO
           Where PO_TRACK_1_2_1_0_0_2 In
       (Select b.PO_TRACK_1_2_1_0_0_2
          From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
               Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
         Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
           And r.SEDE_TECNICA = id_op);

     Delete From Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_BIN_PO
           Where PO_TR_TUNNEL_1_2_1_0_5_2 In
         (Select PO_TR_TUNNEL_1_2_1_0_5_2
            From Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_BIN_PO
           Minus
          Select PO_TR_TUNNEL_1_2_1_0_5_2
            From Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO
		   );
--
    Delete From  Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO
            Where PO_TR_TUNNEL_1_2_1_0_5_2 In
          (Select PO_TR_TUNNEL_1_2_1_0_5_2
             From Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO
           Minus
           Select PO_TR_TUNNEL_1_2_1_0_5_2
             From Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO
		   );


     Delete From Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_PO
           Where PO_TRACK_1_2_1_0_0_2 In
         (Select b.PO_TRACK_1_2_1_0_0_2
            From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                 Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
           Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
             And r.SEDE_TECNICA = id_op
           );
--Eliminazione tabella di relazione binari-po
     Delete From Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA
           Where SEDE_TECNICA = id_op;
--
--Non posso eliminare tutti i binari, ma solo quelli non associati ad alcuna località
     Delete From Rinf_Lavorazione_Evo.BINARI_CORSA_PO
           Where PO_TRACK_1_2_1_0_0_2 In
           ( Select PO_TRACK_1_2_1_0_0_2 From  Rinf_Lavorazione_Evo.BINARI_CORSA_PO
             Minus
             Select PO_TRACK_1_2_1_0_0_2 From  Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA
			);
/*
-- Nuovo Parametro Reg.2019/777
     Delete From Rinf_Lavorazione_Evo.PAR_1_2_3_2_DOC_norme 
           Where SEDE_TECNICA = id_op;
*/
--
-- TAF TAP 08/02/2017
     Delete From Rinf_Lavorazione_Evo.PAR_1_2_0_0_0_3_TAF_TAP
           Where SEDE_TECNICA = id_op;

--Punti Operativi
     Delete From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
           Where SEDE_TECNICA = id_op;
--
  EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetOutInvalidOP - Errore: ' || Substr(SQLERRM, 1, 300));
--
  END SetOutInvalidOP;
