         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetOutInvalidSOL - Errore: ' || Substr(SQLERRM, 1, 300));
 END SetOutInvalidSOL;
--
-- ------------------------------------------------------------------------------------------------   
--                                 PROCEDURE SetOutSOlWithoutTrack
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetOutSOlWithoutTrack(tipo_sol Varchar2, p_error Out Number)     Is
      TYPE dtp_ogg_rt IS RECORD
      (  ID_DTP     Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
         C_SOL_OP   Varchar2 (300),
         D_SOL_OP   Varchar2 (500)      );
      TYPE dtp_ogg_t IS TABLE OF dtp_ogg_rt;
      l_dtp_ogg   dtp_ogg_t;
--	  
   BEGIN
       p_error := 0;
       Select s.CODICE_DTP      id_dtp, 
	          s.SEDE_TECNICA    c_sol_op, 
			  s.DEFINIZIONE     d_sol_op
         Bulk Collect Into       l_dtp_ogg
         From Rinf_Lavorazione_Evo.SEZIONI_LINEA s,
              Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b
        Where s.SOL_1_1_0_0_0_6 = tipo_sol 
		  And s.SEDE_TECNICA = b.SEDE_TECNICA (+)
     Group By s.CODICE_DTP, s.SEDE_TECNICA, s.DEFINIZIONE
     Having Count(b.SOL_TRACK_1_1_1_0_0_1) = 0
     Order by 1,2;
--
     Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '   ');
--
      For i In 1 .. l_dtp_ogg.COUNT  Loop 
--	  
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Sezione di Linea  '
            || Case When tipo_sol='R' Then 'Regular' Else 'Link' End ||' senza binari: '
            || l_dtp_ogg (i).ID_DTP   || '       '
            || l_dtp_ogg (i).C_SOL_OP || '       '
            || l_dtp_ogg (i).D_SOL_OP );
-- -------------------			
-- SetOutInvalidSOL
         SetOutInvalidSOL (l_dtp_ogg (i).C_SOL_OP, p_error);

         If p_error <> 0  Then
            Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Errore: Eliminazione Sezione di Linea  '
               ||Case When tipo_sol='R' Then 'Regular' Else 'Link' End ||' senza binari: '
               || l_dtp_ogg(i).ID_DTP   || '       '
               || l_dtp_ogg(i).C_SOL_OP || '       '
               || l_dtp_ogg(i).D_SOL_OP );
         Else --08/07/2016 Inserito record In SCARTI_ACQUISIZIONE per reportistica sugli oggetti non acquisiti
               Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE
                        (  CODICE_ACQUISIZIONE,
                           CODICE_SOL_PO,
                           NOME_SOL_PO,
                           SEDE_TECNICA,
                           NOME_SEDE_TECNICA,
                           CLASSE,
                           CODICE_ERRORE,
                           CODICE_DTP   )
                      Select
                           n_acquisizione ,
                           l.SEDE_TECNICA id_tratta,
                           l.DEFINIZIONE desc_tratta,
                           l.SEDE_TECNICA id_tratta,
                           l.DEFINIZIONE desc_tratta,
                           'CLASSE_R13000',
                           'Sezione di Linea  '|| Case When tipo_sol = 'R' Then 'Regular' Else 'Link' End ||' senza binari ',
                           l.CODICE_DTP id_dtp
                      From Rinf_Staging_Evo.CLASSE_R13000 l
                     Where l.SEDE_TECNICA = l_dtp_ogg(i).C_SOL_OP;
         End If;
      End Loop ;
--	  
    EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetOutSOlWithoutTrack - Errore:  ' || Substr(SQLERRM, 1, 300));
 END SetOutSOlWithoutTrack;
--
-- ------------------------------------------------------------------------------------------------   
--                             PROCEDURE SetOutInvalidObject
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetOutInvalidObject (n_acquisizione Number, p_error Out Number)    Is
      TYPE dtp_ogg_rt IS RECORD
      (  id_dtp     Rinf_Staging_Evo.CLASSE_R03000.CODICE_DTP%Type,
         c_sol_op   Varchar2 (300),
         d_sol_op   Varchar2 (500)   );
      TYPE dtp_ogg_t IS TABLE OF dtp_ogg_rt;
      L_DTP_OGG   dtp_ogg_t;
   BEGIN
      p_error := 0;

      Select Distinct d.CODICE_DTP id_dtp, a.c_sol_op, a.d_sol_op
        Bulk Collect Into l_dtp_ogg
        From (Select CODICE_SOL_PO c_sol_op, o.DEFINIZIONE d_sol_op
                From Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE,
                     Rinf_Staging_Evo.CLASSE_R03000 o
               Where CODICE_ACQUISIZIONE = n_acquisizione
                 And o.SEDE_TECNICA = CODICE_SOL_PO
                 And CODICE_SOL_PO Is Not Null
                 And CODICE_SOL_PO Like 'LO%'
             Union
              Select o.SEDE_TECNICA, o.DEFINIZIONE
                From Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE s,
                     Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA b,
                     Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO l,
                     Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o
               Where CODICE_ACQUISIZIONE = n_acquisizione
                 And CODICE_SOL_PO Is Null
                 And B.IDENTIFICATIVO_GALLERIA = S.SEDE_TECNICA
                 And l.PO_SD_1_2_2_0_0_2 = b.VALORE_CARATTERISTICA
                 And l.SEDE_TECNICA = o.SEDE_TECNICA
                 And CODICE_CARATTERISTICA = 'R25350_LO_3010'
             Union
              Select o.SEDE_TECNICA, o.DEFINIZIONE
                From Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE s,
                     Rinf_Staging_Evo.CLASSE_R25350_LO_MULTIPLA b,
                     Rinf_Lavorazione_Evo.BINARI_CORSA_PO l,
                     Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r,
                     Rinf_Lavorazione_Evo.PUNTI_OPERATIVI o
               Where CODICE_ACQUISIZIONE = n_acquisizione
                 And CODICE_SOL_PO Is Null
                 And B.IDENTIFICATIVO_GALLERIA = S.SEDE_TECNICA
                 And l.PO_TRACK_1_2_1_0_0_2 = b.VALORE_CARATTERISTICA
                 And r.SEDE_TECNICA = o.SEDE_TECNICA
                 And l.PO_TRACK_1_2_1_0_0_2 = r.PO_TRACK_1_2_1_0_0_2
                 And CODICE_CARATTERISTICA = 'R25350_LO_3010'
			  ) a,
              Rinf_Staging_Evo.CLASSE_R03000 d
        Where a.c_sol_op = d.SEDE_TECNICA (+)
        Order by 1,2;
--
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '   ');
--
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '--------------------------------> Elenco Punti Operativi e Sezioni di Linea non acquisiti   ');
      Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '   ');

      For i In 1 .. l_dtp_ogg.COUNT Loop 
--
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Punto Operativo non valido: '
            || l_dtp_ogg(i).ID_DTP   || '       '
            || l_dtp_ogg(i).C_SOL_OP || '       '
            || l_dtp_ogg (i).d_sol_op );
--
            Dbms_Output.Put_Line ('Eliminazione Oggetti DTP: ' || l_dtp_ogg(i).ID_DTP || '       ' || l_dtp_ogg(i).C_SOL_OP);
-- ----------------------------------------------------		
-- SetOutInvalidOP 	
-- ----------------------------------------------------		
         SetOutInvalidOP (l_dtp_ogg(i).C_SOL_OP, p_error);
--
         If p_error <> 0 Then
            Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Errore: Eliminazione Oggetti DTP: '
               || l_dtp_ogg(i).ID_DTP   || '       '
               || l_dtp_ogg(i).C_SOL_OP || '       '
               || l_dtp_ogg(i).D_SOL_OP );
--
         End If;
      End Loop ;
--
      Select d.CODICE_DTP id_dtp, a.C_SOL_OP, a.D_SOL_OP
        Bulk Collect Into l_dtp_ogg
        From (Select CODICE_SOL_PO c_sol_op,t.DEFINIZIONE d_sol_op
                From Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE,
                     Rinf_Staging_Evo.CLASSE_R13000 t
               Where CODICE_ACQUISIZIONE = n_acquisizione
                 And t.SEDE_TECNICA = CODICE_SOL_PO
                 And CODICE_SOL_PO Is Not Null
                 And CODICE_SOL_PO Like 'TR%'
            Union
              Select o.SEDE_TECNICA, o.DEFINIZIONE
                From Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE s,
                     Rinf_Staging_Evo.CLASSE_R25350_TR_MULTIPLA b,
                     Rinf_Lavorazione_Evo.BINARI_CORSA_SOL l,
                     Rinf_Lavorazione_Evo.SEZIONI_LINEA o
               Where CODICE_ACQUISIZIONE = n_acquisizione
                 And CODICE_SOL_PO Is Null
                 And b.IDENTIFICATIVO_GALLERIA = s.SEDE_TECNICA
                 And l.SOL_TRACK_1_1_1_0_0_1 = b.VALORE_CARATTERISTICA
                 And l.SEDE_TECNICA = o.SEDE_TECNICA
                 And CODICE_CARATTERISTICA = 'R25350_TR_3010'
			  ) a,
             Rinf_Staging_Evo.CLASSE_R13000 d
        Where a.C_SOL_OP = d.SEDE_TECNICA (+)
        Order by 1,2;
--
     Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '   ');

      For i In 1 .. l_dtp_ogg.COUNT Loop
--
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Sezione di Linea non valida: '
            || l_dtp_ogg(i).ID_DTP   || '       '
            || l_dtp_ogg(i).C_SOL_OP || '       '
            || l_dtp_ogg(i).D_SOL_OP );
--			
            Dbms_Output.Put_Line ('Eliminazione Oggetti DTP: ' || l_dtp_ogg(i).ID_DTP || '       ' || l_dtp_ogg(i).C_SOL_OP);
-- ----------------------------------------------------		
--  SetOutInvalidSOL
-- ----------------------------------------------------		
         SetOutInvalidSOL (l_dtp_ogg(i).C_SOL_OP, p_error);
--
         If p_error <> 0 Then
            Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Errore: Eliminazione Oggetti DTP: '
               || l_dtp_ogg(i).ID_DTP  || '       '
               || l_dtp_ogg(i).C_SOL_OP|| '       '
               || l_dtp_ogg(i).D_SOL_OP );
         End If;
      End Loop ;
--
     Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '   ');
--
   EXCEPTION
      When OTHERS  Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetOutInvalidObject - Errore: ' || Substr(SQLERRM, 1, 300));
--
   END SetOutInvalidObject;
--
-- ------------------------------------------------------------------------------------------------   
--               PROCEDURE SetAcquisitionResult
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetAcquisitionResult (n_acquisizione Number, n_esito Number)   Is
   BEGIN
      Update Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI
         Set CODICE_ESITO = n_esito
       Where CODICE_ACQUISIZIONE = n_acquisizione;
--
   END SetAcquisitionResult;
--
-- ------------------------------------------------------------------------------------------------   
--                    PROCEDURE SetRegistryValidObject
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetRegistryValidObject (n_acquisizione       Number,
                                     p_error          Out Number )   Is
      n_buoni    Number;
      n_scarti   Number;
   BEGIN
      p_error := 0;
--
      Insert Into Rinf_Lavorazione_Evo.OGGETTI_ACQUISITI 
	           (CODICE_ACQUISIZIONE,
                CODICE_SOL_PO,
                DESCRIZIONE,
                CODICE_DTP
				)
         Select n_acquisizione,
                SEDE_TECNICA,
                DEFINIZIONE,
                CODICE_DTP
           From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
        Union
         Select n_acquisizione,
                SEDE_TECNICA,
                DEFINIZIONE,
                CODICE_DTP
           From Rinf_Lavorazione_Evo.SEZIONI_LINEA;
--
      Select COUNT (*)
        Into n_buoni
        From Rinf_Lavorazione_Evo.OGGETTI_ACQUISITI
       Where CODICE_ACQUISIZIONE = n_acquisizione;

      Select COUNT (Distinct CODICE_SOL_PO)
        Into n_scarti
        From Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE
       Where CODICE_ACQUISIZIONE = n_acquisizione;
--	   
       Dbms_Output.Put_Line ('n_buoni:  ' || n_buoni);
       Dbms_Output.Put_Line ('n_scarti: ' || n_scarti);
-- --------------------------------------------------
--     SetAcquisitionResult
-- --------------------------------------------------
--
      SetAcquisitionResult ( n_acquisizione,
                             Case
                                When n_buoni > 0 And n_scarti = 0  Then 1
                                When n_buoni > 0 And n_scarti > 0  Then 2
                                When n_buoni = 0 And n_scarti >= 0 Then 0
                             End);
--		 
   EXCEPTION
      When OTHERS Then
         SetAcquisitionResult (n_acquisizione, 0);
--
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetRegistryValidObject - Errore: ' || Substr(SQLERRM, 1, 300));
--
  END SetRegistryValidObject;
--   
-- ------------------------------------------------------------------------------------------------   
--                          PROCEDURE SetObjectOutGerarchy
-- ------------------------------------------------------------------------------------------------   
--   
 Procedure SetObjectOutGerarchy (n_acquisizione Number, p_error Out Number) Is
 TYPE dtp_sol_rt IS RECORD
      ( CODICE_SOL_PO       Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE.CODICE_SOL_PO%Type     ,
        SEDE_TECNICA        Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE.SEDE_TECNICA%Type      ,
        NOME_SEDE_TECNICA   Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE.NOME_SEDE_TECNICA%Type ,
        CLASSE              Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE.CLASSE%Type            ,
        CODICE_Errore       Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE.CODICE_ERRORE%Type     );
      TYPE dtp_sol_t IS TABLE OF dtp_sol_rt;
      L_DTP_SOL   dtp_sol_t;
--	  
 BEGIN
  p_error := 0;

-- OP TRACK
     Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE
        (  CODICE_ACQUISIZIONE,
           CODICE_SOL_PO,
           NOME_SOL_PO,
           SEDE_TECNICA,
           NOME_SEDE_TECNICA,
           CLASSE,
           CODICE_ERRORE,
           CODICE_DTP   )
     Select
           n_acquisizione ,
           l.SEDE_TECNICA id_localita,
           Null desc_localita,
           PO_TRACK_1_2_1_0_0_2 id_binario,
           PO_TRACK_1_2_1_0_0_2_D desc_binario,
           'CLASSE_R16000L',
           'ORA-02291: Manca la località di riferimento (binario di corsa senza PO padre)',
           Null id_dtp
      From Rinf_Staging_Evo.CLASSE_R16000_LO b,
           Rinf_Staging_Evo.CLASSE_R03000 l
     Where l.SEDE_TECNICA = b.SEDE_TECNICA
       And PO_TRACK_1_2_1_0_0_2 Is Not Null
       And STATO_SISTEMA = 'CREA' 
       And STATO_UTENTE = 'ESER IPIC'
       And l.SEDE_TECNICA In
         ( Select SEDE_TECNICA From Rinf_Staging_Evo.CLASSE_R16000_LO  
		     Where PO_TRACK_1_2_1_0_0_2 Is Not Null
           Minus
           Select SEDE_TECNICA From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
          );
-- -----------------------
-- OP SIDING
      Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE
        (  CODICE_ACQUISIZIONE,
           CODICE_SOL_PO,
           NOME_SOL_PO,
           SEDE_TECNICA,
           NOME_SEDE_TECNICA,
           CLASSE,
           CODICE_ERRORE,
           CODICE_DTP  )
       Select
           n_acquisizione ,
           l.SEDE_TECNICA id_localita,
           Null desc_localita,
           PO_SD_1_2_2_0_0_2 id_binario,
           PO_SD_1_2_2_0_0_2_D desc_binario,
           'CLASSE_R16100',
           'ORA-02291: Manca la località di riferimento (binario di raccordo senza LO padre)',
           Null id_dtp
      From Rinf_Staging_Evo.CLASSE_R16100 b,
           Rinf_Staging_Evo.CLASSE_R03000 l
     Where PO_SD_1_2_2_0_0_2 Is Not Null 
	   And l.SEDE_TECNICA = b.SEDE_TECNICA 
	   And STATO_SISTEMA = 'CREA' 
	   And STATO_UTENTE = 'ESER IPIC' 
	   And Substr(PO_SD_1_2_2_0_0_2, 8,2) Not In ('AF','SM') 
	   And l.SEDE_TECNICA In
          (Select SEDE_TECNICA From Rinf_Staging_Evo.CLASSE_R16100 Where PO_SD_1_2_2_0_0_2 Is Not Null
            Minus
           Select  SEDE_TECNICA From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
          );
--
-- SOL TRACK
    Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE
        (  CODICE_ACQUISIZIONE,
           CODICE_SOL_PO,
           NOME_SOL_PO,
           SEDE_TECNICA,
           NOME_SEDE_TECNICA,
           CLASSE,
           CODICE_ERRORE,
           CODICE_DTP )
       Select
           n_acquisizione ,
           SEDE_TECNICA id_tratta,
           DEFINIZIONE desc_tratta,
           SEDE_TECNICA id_tratta,
           DEFINIZIONE desc_tratta,
           'CLASSE_R13000',
           'ORA-02291: La località di inizio o di fine non è valorizzata',
           CODICE_DTP id_dtp
      From Rinf_Staging_Evo.CLASSE_R13000 b
     Where (LOCALITA_INIZIO Is Null Or LOCALITA_FINE Is Null)  --14/07/2016 mancavano le parentesi che racchiudevano l'OR. Nel rapporto di acquisizione finivano trata In CREA- ESER
       And STATO_SISTEMA = 'CREA' 
       And STATO_UTENTE  = 'ESER IPIC' ;
--
    Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE
        (  CODICE_ACQUISIZIONE,
           CODICE_SOL_PO,
           NOME_SOL_PO,
           SEDE_TECNICA,
           NOME_SEDE_TECNICA,
           CLASSE,
           CODICE_ERRORE,
           CODICE_DTP  )
      Select
           n_acquisizione ,
           SEDE_TECNICA id_tratta,
           DEFINIZIONE desc_tratta,
           SEDE_TECNICA id_tratta,
           DEFINIZIONE desc_tratta,
           'CLASSE_R13000',
           'ORA-02291: Manca la località di inizio nell''anagrafica delle località',
           CODICE_DTP id_dtp
      From Rinf_Staging_Evo.CLASSE_R13000 b
     Where SEDE_TECNICA Is Not Null 
	   And STATO_SISTEMA = 'CREA' 
	   And STATO_UTENTE  = 'ESER IPIC' 
	   And LOCALITA_INIZIO In
          (Select LOCALITA_INIZIO From Rinf_Staging_Evo.CLASSE_R13000 Where SEDE_TECNICA Is Not Null
            Minus
           Select SEDE_TECNICA From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
           );
--
    Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE
        (  CODICE_ACQUISIZIONE,
           CODICE_SOL_PO,
           NOME_SOL_PO,
           SEDE_TECNICA,
           NOME_SEDE_TECNICA,
           CLASSE,
           CODICE_ERRORE,
           CODICE_DTP  )
       Select
           n_acquisizione ,
           SEDE_TECNICA id_tratta,
           DEFINIZIONE desc_tratta,
           SEDE_TECNICA id_tratta,
           DEFINIZIONE desc_tratta,
           'CLASSE_R13000',
           'ORA-02291: Manca la località di fine nell''anagrafica delle località',
           CODICE_DTP id_dtp
      From Rinf_Staging_Evo.CLASSE_R13000 b
     Where SEDE_TECNICA Is Not Null 
	   And STATO_SISTEMA = 'CREA' 
	   And STATO_UTENTE  = 'ESER IPIC' 
	   And LOCALITA_FINE In
          (Select LOCALITA_FINE From Rinf_Staging_Evo.CLASSE_R13000 Where SEDE_TECNICA Is Not Null
            Minus
           Select  SEDE_TECNICA From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
           );
--
    Insert Into Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE
        (  CODICE_ACQUISIZIONE,
           CODICE_SOL_PO,
           NOME_SOL_PO,
           SEDE_TECNICA,
           NOME_SEDE_TECNICA,
           CLASSE,
           CODICE_ERRORE,
           CODICE_DTP   )
       Select
           n_acquisizione ,
           t.SEDE_TECNICA id_tratta,
           Null desc_tratta,
           SOL_TRACK_1_1_1_0_0_1 id_binario,
           SOL_TRACK_1_1_1_0_0_1_D desc_binario,
           'CLASSE_R16000T',
           'ORA-02291: Manca la tratta di riferimento (binario di corsa senza SOL padre)',
           Null id_dtp
      From Rinf_Staging_Evo.CLASSE_R16000_TR b,
           Rinf_Staging_Evo.CLASSE_R13000 t
     Where SOL_TRACK_1_1_1_0_0_1 Is Not Null 
       And t.SEDE_TECNICA = b.SEDE_TECNICA 
	   And STATO_SISTEMA = 'CREA' 
	   And STATO_UTENTE  = 'ESER IPIC' 
	   And t.SEDE_TECNICA In
           (Select SEDE_TECNICA From Rinf_Staging_Evo.CLASSE_R16000_TR Where SOL_TRACK_1_1_1_0_0_1 Is Not Null
              Minus
            Select SEDE_TECNICA From Rinf_Lavorazione_Evo.SEZIONI_LINEA
            );
-- Scrittura file di log
    Select CODICE_SOL_PO,
           SEDE_TECNICA, 
		   NOME_SEDE_TECNICA, 
		   CLASSE, 
		   CODICE_ERRORE
           Bulk Collect Into L_DTP_SOL
      From Rinf_Lavorazione_Evo.SCARTI_ACQUISIZIONE
     Where Codice_acquisizione = n_acquisizione 
	   And Substr(codice_errore, 1, 9) = 'ORA-02291'
     Order by CODICE_SOL_PO,SEDE_TECNICA;
--
      BEGIN
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '--------------------------------> ' || 'Controlli Gerarchici (relazioni figli-padri)' );
         Dbms_Output.Put_Line ('Oggetti che non hanno superato i controlli gerarchici (figli senza padri) ');
--
         Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, 'Totale oggetti che non hanno superato i controlli gerarchici (figli senza padri): '|| To_Char(L_DTP_SOL.Count));
--
         Dbms_Output.Put_Line ('Totale Oggetti Scartati  (figli senza padri): ' || To_Char(L_DTP_SOL.Count));
         Pkg_Rinf_Utility.SETLINEINTOFILE ( id_file,' '               );
--
         For  i In 1 .. L_DTP_SOL.Count   Loop 
--
            Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,
            RPAD(i, 4, ' ') || ':  Codice SOL/OP: '|| L_DTP_SOL(i).CODICE_SOL_PO||
            ' Codice Sede Tecnica: '|| L_DTP_SOL(i).SEDE_TECNICA||
            ' Definizione Sede Tecnica: '|| L_DTP_SOL(i).NOME_SEDE_TECNICA||
            ' Classe: '|| L_DTP_SOL(i).CLASSE||
            ' Errore: '|| L_DTP_SOL(i).CODICE_Errore );
--			
            Dbms_Output.Put_Line (
            ' Codice SOL/OP: '|| L_DTP_SOL(i).CODICE_SOL_PO||
            ' Codice Sede Tecnica: '|| L_DTP_SOL(i).SEDE_TECNICA||
            ' Definizione Sede Tecnica: '|| L_DTP_SOL(i).NOME_SEDE_TECNICA||
            ' Classe: '|| L_DTP_SOL(i).CLASSE||
            ' Errore: '|| L_DTP_SOL(i).CODICE_Errore );
        End Loop ;
      End;
--	
   EXCEPTION -- aggiunto 
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetObjectOutGerarchy - Errore: ' || Substr(SQLERRM, 1, 300));
--
 END SetObjectOutGerarchy;
--
-- ------------------------------------------------------------------------------------------------   
--                          PROCEDURE SetTenClassificationSOLTrack
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetTenClassificationSOLTrack(p_error Out Number)    Is
  BEGIN
  p_error:=0;

  Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_1_2_1_CAT_TEN_SOL
            (SOL_TRACK_1_1_1_0_0_1,  SOL_TRACK_1_1_1_1_2_1)
    Select Distinct SOL_TRACK_1_1_1_0_0_1, 30                              --Part of the TEN-T Core Passenger Network
      From  Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
            Rinf_Anagrafiche_Evo.ANAG_LINEE_TENT l,
            Rinf_Anagrafiche_Evo.LINEA_TENT_TRATTE r,
            Rinf_Anagrafiche_Evo.TRATTE_PIC t
      Where l.FLAG_AV = 1 
        And l.CODICE_GIURISDIZIONE = r.CODICE_GIURISDIZIONE 
        And b.SEDE_TECNICA = t.SEDE_TECNICA 
        And t.CODICE_TRATTA_PIC = r.CODICE_TRATTA_PIC 
        And l.DATA_SCADENZA Is Null; --		And t.DATA_SCADENZA Is Null;

  Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_1_2_1_CAT_TEN_SOL
             (SOL_TRACK_1_1_1_0_0_1,  SOL_TRACK_1_1_1_1_2_1)
       Select Distinct SOL_TRACK_1_1_1_0_0_1, 20                                  --Part of the TEN-T Core Freight Network
         From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
              Rinf_Anagrafiche_Evo.ANAG_LINEE_TENT l,
              Rinf_Anagrafiche_Evo.LINEA_TENT_TRATTE r,
              Rinf_Anagrafiche_Evo.TRATTE_PIC t
        Where l.FLAG_CORE = 1 
		  And l.CODICE_GIURISDIZIONE = r.CODICE_GIURISDIZIONE 
          And b.SEDE_TECNICA = t.SEDE_TECNICA 
          And t.CODICE_TRATTA_PIC = r.CODICE_TRATTA_PIC 
          And l.DATA_SCADENZA Is Null; -- And t.DATA_SCADENZA Is Null;

  Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_1_2_1_CAT_TEN_SOL
             (SOL_TRACK_1_1_1_0_0_1,  SOL_TRACK_1_1_1_1_2_1)
       Select Distinct SOL_TRACK_1_1_1_0_0_1, 10                                    --TEN-T Comprehensive Network
         From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
              Rinf_Anagrafiche_Evo.ANAG_LINEE_TENT l,
              Rinf_Anagrafiche_Evo.LINEA_TENT_TRATTE r,
              Rinf_Anagrafiche_Evo.TRATTE_PIC t
        Where(l.FLAG_CORE = 0 Or l.FLAG_AV = 0) 
		  And l.CODICE_GIURISDIZIONE = r.CODICE_GIURISDIZIONE 
		  And b.SEDE_TECNICA = t.SEDE_TECNICA 
		  And t.CODICE_TRATTA_PIC = r.CODICE_TRATTA_PIC 
		  And l.DATA_SCADENZA Is Null; --   And t.DATA_SCADENZA Is Null;

  Insert Into Rinf_Lavorazione_Evo.PAR_1_1_1_1_2_1_CAT_TEN_SOL
            (SOL_TRACK_1_1_1_0_0_1, SOL_TRACK_1_1_1_1_2_1)
       Select Distinct SOL_TRACK_1_1_1_0_0_1,  40                                         --Off Ten
         From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL
        Where SEDE_TECNICA In
      (Select SEDE_TECNICA From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL
          Minus
       Select b.SEDE_TECNICA
         From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b,
              Rinf_Anagrafiche_Evo.ANAG_LINEE_TENT l,
              Rinf_Anagrafiche_Evo.LINEA_TENT_TRATTE r,
              Rinf_Anagrafiche_Evo.TRATTE_PIC t
        Where l.CODICE_GIURISDIZIONE = r.CODICE_GIURISDIZIONE 
		  And b.SEDE_TECNICA = t.SEDE_TECNICA 
		  And t.CODICE_TRATTA_PIC = r.CODICE_TRATTA_PIC 
		  And l.DATA_SCADENZA Is Null  
		  --and t.DATA_SCADENZA Is Null
	   );
--26/01/2017 E' necessario recuperare la classificazione delle categoria TEN dei binari di fermata dai binari di corsa SOL
  Insert Into Rinf_Lavorazione_Evo.PAR_1_2_1_0_2_1_CAT_TEN_PO 
             (
              PO_TRACK_1_2_1_0_0_2,
              PO_TRACK_1_2_1_0_2_1,
              KM_INIZIO,
              KM_FINE,
              LATITUDINE_INIZIO,
              LONGITUDINE_INIZIO,
              LATITUDINE_FINE,
              LONGITUDINE_FINE,
              FLAG_CALCOLATO
			  )
    Select Distinct SOL_TRACK_1_1_1_0_0_1,
                    SOL_TRACK_1_1_1_1_2_1,
                    KM_INIZIO,
                    KM_FINE,
                    Null LATITUDINE_INIZIO,
                    Null LONGITUDINE_INIZIO,
                    Null LATITUDINE_FINE,
                    Null LONGITUDINE_FINE,
                    0 FLAG_CALCOLATO
          From Rinf_Lavorazione_Evo.PAR_1_1_1_1_2_1_CAT_TEN_SOL c,
               Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
         Where r.PO_TRACK_1_2_1_0_0_2 = c.SOL_TRACK_1_1_1_0_0_1
           And (SOL_TRACK_1_1_1_0_0_1, SOL_TRACK_1_1_1_1_2_1) In
                  (Select SOL_TRACK_1_1_1_0_0_1, SOL_TRACK_1_1_1_1_2_1
                     From Rinf_Lavorazione_Evo.PAR_1_1_1_1_2_1_CAT_TEN_SOL c,
                          Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
                    Where r.PO_TRACK_1_2_1_0_0_2 = c.SOL_TRACK_1_1_1_0_0_1
                       Minus
                   Select PO_TRACK_1_2_1_0_0_2, PO_TRACK_1_2_1_0_2_1
                     From  Rinf_Lavorazione_Evo.PAR_1_2_1_0_2_1_CAT_TEN_PO);
-- 
     EXCEPTION
       When OTHERS Then
          p_error := SQLCODE;
          Dbms_Output.Put_Line ('SetTenClassificationSOLTrac - Errore: ' || Substr(SQLERRM, 1, 300));
 END SetTenClassificationSOLTrack;


-- ************************************************************************************************
-- ------------------------------------------------------------------------------------------------   
--                     PROCEDURE RunAcquisitionStep2
--                         ACQUISIZIONE STEP 2
-- ------------------------------------------------------------------------------------------------   
--
 Procedure RunAcquisitionStep2 (p_error Out Number)  Is
   n_conta   Number;
  BEGIN
   p_error := 0;
--   
   GetLoadedDataAvailableID (n_caricamento, data_caricamento, data_scarico);
   Dbms_Output.Put_Line ('codice caricamento: ' || n_caricamento);
--   
--  14/12/2016 per il caricamento dei dati dei sistemi esterni (PIC) che hanno un intervallo di validità, è necessario sostituire la data
--  di riferimento da SYSDATE con la data della fotografia del DWH, che coincide con l'ultimo giorno del mese precedente a quello della fornitura dati.
    data_riferimento := Last_Day(Add_Months(data_scarico, -1) );
--
   If n_caricamento Is Not Null Then
--   
      SetSOLClear (p_error);
--
      SetOPClear (p_error);
--
      SetNewAcquisitionID (n_caricamento, n_acquisizione, p_error);
--
      SetLogOfAcquisition (n_caricamento,  data_caricamento,  data_scarico,  p_error);

      If p_error = 0 Then
--  MDR GIS
         PKG_RINF_ACQUISIZIONI.SetGISAcquisition (p_error);
--
         If p_error = 0 Then
--  Anagrafiche INE
            PKG_RINF_ACQUISIZIONI.SetINEAnagrafiche (data_riferimento, p_error);
--
            If p_error = 0 Then                -- 11/02/2016 inserito il controllo dell'Errore: perchè non era gestito
--  Caricamento Dati PIC
               PKG_RINF_ACQUISIZIONI.SetPICAcquisition (data_riferimento, p_error);
--
               If p_error = 0 Then             -- 11/02/2016 inserito il controllo dell'Errore: perchè non era gestito
--  Caricamento Dati ROMAN
                  PKG_RINF_ACQUISIZIONI.SetRomanAcquisition (data_riferimento, p_error);
--
                  If p_error = 0 Then          -- 11/02/2016 inserito il controllo dell'Errore: perchè non era gestito
                     Select COUNT (*) Into n_conta
                      From  Rinf_Staging_Evo.CLASSE_R03000;
-- Caricamento Dati In.Rete 2000 (OP)
                        If n_conta > 0 Then
                             SetAcquisitionOP (n_acquisizione, p_error);
--
                             SetOutInvalidObject (n_acquisizione, p_error);
                        End If;
--
                        Select COUNT (*) Into n_conta
                         From  Rinf_Staging_Evo.CLASSE_R13000;
-- Caricamento Dati In.Rete 2000 (SOL)
                        If n_conta > 0 Then
                           SetAcquisitionSOL (n_acquisizione, p_error);
--
                           SetOutInvalidObject (n_acquisizione, p_error);
--  Aggiorno la tabella PAR_1_1_1_1_2_1_CAT_TEN_SOL che legge i dati da PIC 08/07/2015
--  26/01/2017 Inserisce nella tabella PAR_1_2_1_0_2_1_CAT_TEN_PO i valori dei binari di fermata
                           SetTenClassificationSOLTrack (p_error);
                        End If;
-- 					    
                        If p_error = 0  Then
                            SetObjectOutGerarchy (n_acquisizione, p_error);
--
                            SetOutInvalidObject (n_acquisizione, p_error);
--
                            If p_error = 0  Then
--  Gestione tratte senza binari 
                               Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,
                                  '--------------------------------> Elenco Sezioni di Linea Regular eliminate perchè senza binari   ');
                               SetOutSOlWithoutTrack ('R', p_error);
--                          
                               Pkg_Rinf_Utility.SETLINEINTOFILE (id_file, '  ');
--                          
                               Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,
                                  '--------------------------------> Elenco Sezioni di Linea Link eliminate perchè senza binari   ');
                               SetOutSOlWithoutTrack ('L', p_error);
--->
                               If p_error = 0 Then
--
                                  Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,
 --   Dbms_Output.Put_Line(
  '--------------------------------> Elenco Punti Operativi di nuova istituzione non ancora presenti nel Rinf');
--
                                   NuoviOP (p_error);
--
                               End If;
--							  
                               If p_error = 0 Then

                                   Pkg_Rinf_Utility.SETLINEINTOFILE (id_file,
--    Dbms_Output.Put_Line(
	'--------------------------------> Elenco Sezioni di Linea di nuova istituzione non ancora presenti nel Rinf');
                                   NuoveSOL (p_error);
-- 
                               End If;
---->							  
                               If p_error = 0 Then
--
                                    SetRegistryValidObject (n_acquisizione, p_error);
--  Anche se l'acquisizione è Andata male, devo aggiornare la data nella tabella Rinf_Staging_Evo.ANAG_CARICAMENTI
--  in modo che lo step 2 non possa ripartire sugli stessi dati.
--
                                    SetLoadedDataNotAvailableID (n_caricamento, p_error);
                               End If;
                            End If;
                        Else
                            SetAcquisitionResult (n_acquisizione, 0);
                        End If;
--  
                      UTL_FILE.Fclose (id_file);
--  07/06/2016 aggiunto il parametro del CODICE_LOG per gestire nella stessa tabella anche i log di pulizia
--
                      Pkg_Rinf_Securefile_V082.PUTLOGOFACQUISITION (n_acquisizione, 2, 'log',  nome_file );
                      UTL_FILE.Fremove ('RINF_DIR', nome_file);
                  Else
                      Dbms_Output.Put_Line ('Non ci sono caricamenti disponibili');
                  End If;
               Else
                  Dbms_Output.Put_Line ('RunAcquisitionStep2 - Errore: acquisizione dati PIC');
               End If;
            Else
               Dbms_Output.Put_Line ('RunAcquisitionStep2 - Errore: acquisizione dati ROMAN/ASTER');
            End If;
         Else
            Dbms_Output.Put_Line ('RunAcquisitionStep2 - Errore: acquisizione dati INE');
         End If;
      Else
         Dbms_Output.Put_Line ('RunAcquisitionStep2 - Errore: acquisizione dati GIS');
      End If;
   End If;
--
   --26/05/2016 inserito per assicurare la chiusura dei log In caso di errore
   If p_error <> 0 Then
      UTL_FILE.Fclose (id_file);
      Pkg_Rinf_Securefile_V082.PutLogOfAcquisition (n_acquisizione, 2, 'log', nome_file);
      UTL_FILE.Fremove ('RINF_DIR', nome_file);
--
      SetAcquisitionResult (n_acquisizione, 0);
      SetLoadedDataNotAvailableID (n_caricamento, p_error);
--
   End If;
--
 EXCEPTION
   When OTHERS Then
      p_error := SQLCODE;
      Dbms_Output.Put_Line ('RunAcquisitionStep2 - Errore: ' || Substr(Sqlerrm, 1, 300));
      UTL_FILE.Fclose (id_file);
      Pkg_Rinf_Securefile_V082.PutLogOfAcquisition (n_acquisizione, 1, 'log', nome_file);
      UTL_FILE.Fremove ('RINF_DIR', nome_file);
--	  
      SetAcquisitionResult (n_acquisizione, 0);
--	  
      SetLoadedDataNotAvailableID (n_caricamento, p_error);
--
 END RunAcquisitionStep2;
--
-- ------------------------------------------------------------------------------------------------   
--                             GetAcquiredDataAvailableID
--                          --------- CONTROLLO --------------
-- ------------------------------------------------------------------------------------------------   

 Procedure GetAcquiredDataAvailableID (p_codice_acquisizione   Out Number,
                                       p_data_acquisizione     Out Date) Is 
   BEGIN
--execute immediate 'ALTER SESSION SET NLS_DATE_FORMAT=''dd/mm/yyyy''';
      Select CODICE_ACQUISIZIONE, DATA_ACQUISIZIONE
-- Select CODICE_ACQUISIZIONE, to_date (to_char(DATA_ACQUISIZIONE, 'dd/mm/yyyy hh24:mi:ss', 'NLS_DATE_LANGUAGE=''ENGLISH'''),  'dd/mm/yyyy hh24:mi:ss', 'NLS_DATE_LANGUAGE=''ENGLISH''')
        Into p_codice_acquisizione, p_data_acquisizione
        From Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI
             Where DATA_ACQUISIZIONE In
       (Select Max(DATA_ACQUISIZIONE) From Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI)
               And CODICE_ESITO > 0
               And CODICE_ACQUISIZIONE In
           (Select CODICE_ACQUISIZIONE
              From Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI
            Minus
            Select CODICE_ACQUISIZIONE From Rinf_Lavorazione_Evo.CONTROLLO_DATI
		   );
-->
--     Dbms_Output.Put_Line ('p_codice_acquisizione; ' || p_codice_acquisizione);
--     Dbms_Output.Put_Line ('p_data_acquisizione: ' || p_data_acquisizione);
--     Dbms_Output.Put_Line ('data_acquisizione_FORMAT: ' || to_char(p_data_acquisizione, 'DD/MM/YYYY hh24:mi:ss'));
-->
   EXCEPTION
      When OTHERS Then
         p_codice_acquisizione := Null;
         p_data_acquisizione := Null;
  END GetAcquiredDataAvailableID;
--
-- ------------------------------------------------------------------------------------------------   
--                          PROCEDURE GetCountOfAcquiredObject
-- ------------------------------------------------------------------------------------------------   
--
   Procedure GetCountOfAcquiredObject (p_codice_acquisizione   In     Number,
                                       p_cursor                Out    empcur )    Is
   BEGIN
      Open p_cursor For
           Select CODICE_ACQUISIZIONE,
                  DATA_ACQUISIZIONE,
                  CODICE_DTP,
                  DTP,
                  OP_DA_CONTROLLARE,
                  SOL_DA_CONTROLLARE
             From V_OGGETTI_DA_CONTROLLARE_V082
            Where CODICE_ACQUISIZIONE = p_codice_acquisizione
         Order by CODICE_DTP;
--
   END GetCountOfAcquiredObject;
--
-- ------------------------------------------------------------------------------------------------   
--                                PROCEDURE SetNewControlID
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetNewControlID (n_acquisizione       Number,
                              n_controllo      Out Number,
                              p_error          Out Number )    Is
   BEGIN
      p_error := 0;
--
      Select Max(CODICE_CONTROLLO) + 1 Into n_controllo
        From Rinf_Lavorazione_Evo.CONTROLLO_DATI;
--
      n_controllo := Nvl (n_controllo, 1);
--
      Insert Into Rinf_Lavorazione_Evo.CONTROLLO_DATI 
	               (CODICE_CONTROLLO,
                    DATA_CONTROLLO,
                    CODICE_ACQUISIZIONE,
                    CODICE_MODALITA,
                    DATA_RIFERIMENTO  )
           Values (n_controllo,
                   Sysdate,
                   n_acquisizione,
                   0,
                   data_riferimento
				   );
--				   
--   Dbms_Output.Put_Line ('controllo ' || n_controllo);
   EXCEPTION
      When NO_DATA_FOUND Then
         Insert Into Rinf_Lavorazione_Evo.CONTROLLO_DATI 
		             (CODICE_CONTROLLO,
                      DATA_CONTROLLO,
                      CODICE_ACQUISIZIONE,
                      CODICE_MODALITA,
                      DATA_RIFERIMENTO )
              Values (n_controllo,
                      Sysdate,
                      1,
                      0,
                      data_riferimento
					  );
--
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetNewControlID - Errore: ' || Substr(SQLERRM, 1, 300));
--
   END SetNewControlID;
--
-- ------------------------------------------------------------------------------------------------   
--                                PROCEDURE SetControlResult
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetControlResult (p_codice_controllo   In  Number,
                              p_error              Out Number )    Is
   BEGIN
      p_error := 0;
--
      Update Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI c
         Set CODICE_ESITO =
                (  Select Min(CODICE_ESITO)
                     From Rinf_Lavorazione_Evo.DETTAGLIO_CONTROLLATI d
                    Where CODICE_CONTROLLO = p_codice_controllo
                      And D.CODICE_SOL_PO = C.CODICE_SOL_PO
                 Group By CODICE_SOL_PO
				 )
       Where CODICE_CONTROLLO = p_codice_controllo;
--
   EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0, 'Errore: Oracle. Elaborazione controlli. Codice Controllo: '
                                        || p_codice_controllo||' - SetControlResult. Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null,  p_errlog);
  END SetControlResult;
--
-- ------------------------------------------------------------------------------------------------   
--                               PROCEDURE SetOLDOPClear 
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetOLDOPClear (p_Sede_Tecnica In  Varchar2, 
                            p_error        Out Number )    Is
    BEGIN
      p_error := 0;
--
     Delete  From  Rinf_Controllati_Evo.CORRIDOIO_PO  Where SEDE_TECNICA = p_Sede_Tecnica;
DBMS_OUTPUT.PUT_LINE ('delete CORRIDOIO_PO');
     Delete  From  Rinf_Controllati_Evo.LINEE_TENT_PO Where SEDE_TECNICA = p_Sede_Tecnica;
DBMS_OUTPUT.PUT_LINE ('delete LINEE_TENT_PO');
     Delete  From  Rinf_Controllati_Evo.LINEA_COMM_PO Where SEDE_TECNICA = p_Sede_Tecnica;
DBMS_OUTPUT.PUT_LINE ('delete LINEA_COMM_PO');
--
     Delete From  Rinf_Controllati_Evo.PAR_1_2_1_0_2_1_CAT_TEN_PO            --multipla 082 agosto
            Where PO_TRACK_1_2_1_0_0_2 In
        (Select b.PO_TRACK_1_2_1_0_0_2
             From Rinf_Controllati_Evo.BINARI_CORSA_PO b,
                  Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r
            Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
              And r.SEDE_TECNICA = p_Sede_Tecnica
		);
DBMS_OUTPUT.PUT_LINE ('delete PAR_1_2_1_0_2_1_CAT_TEN_PO');

     Delete From  Rinf_Controllati_Evo.PAR_1_2_1_0_2_2_CAT_LINEA            --multipla 082 agosto
            Where PO_TRACK_1_2_1_0_0_2 In
        (Select b.PO_TRACK_1_2_1_0_0_2
             From Rinf_Controllati_Evo.BINARI_CORSA_PO b,
                  Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r
            Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
              And r.SEDE_TECNICA = p_Sede_Tecnica
	    );
DBMS_OUTPUT.PUT_LINE ('delete PAR_1_2_1_0_2_2_CAT_LINEA');

     Delete From  Rinf_Controllati_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL                         --multivalore 082 agosto
            Where PO_TR_PLATFORM_1_2_1_0_6_2 In 
		(Select PO_TR_PLATFORM_1_2_1_0_6_2
           From Rinf_Controllati_Evo.MARCIAPIEDI_BINARI_PO
          Where Nvl(BINARIO_1, 'NullO') In 
		        (Select b.PO_TRACK_1_2_1_0_0_2
                   From Rinf_Controllati_Evo.BINARI_CORSA_PO b,
                        Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r
                  Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                    And r.SEDE_TECNICA = p_Sede_Tecnica
				)
             Or Nvl(BINARIO_2, 'NullO') In 
			   (Select b.PO_TRACK_1_2_1_0_0_2
                   From  Rinf_Controllati_Evo.BINARI_CORSA_PO b,
                         Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r
                   Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                     And r.SEDE_TECNICA = p_Sede_Tecnica
			    )
             Or Nvl(BINARIO_3, 'NullO') In 
			   (Select b.PO_TRACK_1_2_1_0_0_2
                  From Rinf_Controllati_Evo.BINARI_CORSA_PO b,
                       Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r
                 Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                   And r.SEDE_TECNICA = p_Sede_Tecnica
				)
             Or Nvl(BINARIO_4, 'NullO') In 
			   (Select b.PO_TRACK_1_2_1_0_0_2
   			      From Rinf_Controllati_Evo.BINARI_CORSA_PO b,
                       Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r
                 Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                   And r.SEDE_TECNICA = p_Sede_Tecnica
				)
	    );
DBMS_OUTPUT.PUT_LINE ('delete PAR_1_2_1_0_6_3_CAT_TEN_PL');
--
