-- ------------------------------------------------------------------------------------------------   
--                              PROCEDURE SetOLDOPUpdate
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetOLDOPUpdate (p_Sede_Tecnica       In     Varchar2,
                             p_codice_controllo   In     Number,
                             p_error              Out    Number )    Is
   BEGIN
      p_error := 0;
--
      UPDATE Rinf_Controllati_Evo.PUNTI_OPERATIVI
         SET (CODICE_MIR,
              --CODICE_PIC,
              DEFINIZIONE,
              STATO_SISTEMA,
              STATO_UTENTE,
              --DATA_INIZIO_VALIDITA,
              --DATA_FINE_VALIDITA,
              LOCALITA_CONTENITORE,
              KM_INIZIO,
              PO_1_2_0_0_0_2,
              PO_1_2_0_0_0_3_AP,
              PO_1_2_0_0_0_4,
              PO_1_2_0_0_0_6,
-->  Campi relativi ai nuovi parametri introdotti dal Reg.2019/777
			  PO_1_2_0_0_0_4_1_AP ,
              PO_1_2_0_0_0_4_1 ,
              PO_1_2_3_1_AP ,
              PO_1_2_3_1  ,
              PO_1_2_3_2_AP ,
-->
              LATITUDINE,
              LONGITUDINE,
              CODICE_LINEA_TECNICA,
              CODICE_DTP,
              CODICE_UT,
              NUOVA_CLASSIFICAZIONE_STAZIONE, --nuova 082
              CODICE_CONTROLLO,
              TIPO_LOCALITA_CONFINE,
              GRUPPO_AUTORIZZATIVO,
              CACHE_FIELD) =
                (Select CODICE_MIR,
                        --CODICE_PIC,
                        DEFINIZIONE,
                        STATO_SISTEMA,
                        STATO_UTENTE,
                        --DATA_INIZIO_VALIDITA,
                        --DATA_FINE_VALIDITA,
                        LOCALITA_CONTENITORE,
                        KM_INIZIO,
                        PO_1_2_0_0_0_2,
                        PO_1_2_0_0_0_3_AP,
                        PO_1_2_0_0_0_4,
                        PO_1_2_0_0_0_6,
-->  Campi relativi ai nuovi parametri introdotti dal Reg.2019/777
			            Nvl(PO_1_2_0_0_0_4_1_AP, 'NYA') ,
                        decode (PO_1_2_0_0_0_4_1, 'NA', Null, PO_1_2_0_0_0_4_1),
                        Nvl(PO_1_2_3_1_AP, 'NYA') ,
                        PO_1_2_3_1  ,
                        Nvl(PO_1_2_3_2_AP, 'NYA') ,
-->
                        LATITUDINE,
                        LONGITUDINE,
                        CODICE_LINEA_TECNICA,
                        CODICE_DTP,
                        CODICE_UT,
                        NUOVA_CLASSIFICAZIONE_STAZIONE, --nuova 082
                        p_codice_controllo,
                        TIPO_LOCALITA_CONFINE,
                        GRUPPO_AUTORIZZATIVO,
                        Null
                   From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
                  Where SEDE_TECNICA = p_Sede_Tecnica)
       Where SEDE_TECNICA = p_Sede_Tecnica;
--
         DBMS_OUTPUT.PUT_LINE ('Aggiornato Rinf_Controllati_Evo.PUNTI_OPERATIVI: '||p_Sede_Tecnica);

   EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG ( 0, 'SetOLDOPUpdate - Elaborazione controlli. Codice Controllo: '
                                         || p_codice_controllo||' - Sede Tecnica '||p_Sede_Tecnica||'. Codice Errore: ' ||Sqlcode||' - '||Sqlerrm,
                                         Null, p_errlog);
         DBMS_OUTPUT.PUT_LINE ('SetOLDOPUpDate - Errore ' || SUBSTR (SQLERRM, 1, 300));
   END SetOLDOPUpDate;

