                        --SOL_1_1_0_0_0_2,                      --da PIC LINEE_COMM
                        --SOL_1_1_0_0_0_2_D,
                        SOL_1_1_0_0_0_3,
                        SOL_1_1_0_0_0_4,
                        SOL_1_1_0_0_0_5,
                        SOL_1_1_0_0_0_6,
