-- ------------------------------------------------------------------------------------------------   
--                                  FUNCTION GetLinkObject
--    funzione che ritorna 1 se la località o la tratta sono oggetti fittizi, 0 altrimenti
-- ------------------------------------------------------------------------------------------------   

   Function GetLinkObject (p_Sede_Tecnica In Varchar2)
      RETURN Number   Is
      n_link   Number;
   BEGIN
      If p_Sede_Tecnica Like 'LO%'
      Then
         Select Decode (LOCALITA_CONTENITORE, Null, 0, 1)
           Into n_link
           From Rinf_Lavorazione_Evo.PUNTI_OPERATIVI
          Where SEDE_TECNICA = p_Sede_Tecnica;
      Else
         Select Decode (LOCALITA_CONTENITORE, Null, 0, 1)
           Into n_link
           From Rinf_Lavorazione_Evo.SEZIONI_LINEA
          Where SEDE_TECNICA = p_Sede_Tecnica;
      End If;
--
      RETURN n_link;
   END GetLinkObject;
--
-- ------------------------------------------------------------------------------------------------   
--                                       FUNCTION GetNYA
--   dice che il parametro è NYA (1) o no (0 = OBBLIGATORIO)
--   E' stata modificata rispetto alla vecchia versione per leggere dalla tabella SINTESI_CONTROLLI
--   per cercare di velocizzare l'operazione di scrittura dall'area di lavorazione all'area controllati
-- ------------------------------------------------------------------------------------------------   
--
  Function GetNYA (p_controllo Number, p_parametro Varchar2, p_Sede_Tecnica Varchar2)    
      RETURN    Number   Is
      n_value   Number;
      n_nya     Number;
   BEGIN
--
      Select NYA into n_nya 
	    From Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI  
	   Where NUMERO_PARAMETRO_MULTIPLO = p_parametro;
--
      Select Nvl(NYA, n_nya)
        Into n_value
        From Rinf_Lavorazione_Evo.SINTESI_CONTROLLI d
       Where d.CODICE_CONTROLLO = p_controllo 
	     And SEDE_TECNICA = p_Sede_Tecnica 
		 And NUMERO_PARAMETRO_MULTIPLO = p_parametro;
--
      RETURN n_value;
   EXCEPTION
      When NO_DATA_FOUND Then
      RETURN n_nya;
   END GetNYA;
--
-- ------------------------------------------------------------------------------------------------   
--                              FUNCTION GetNYA_OLD
--               dice che il parametro è NYA (1) o no (0 = OBBLIGATORIO)
-- ------------------------------------------------------------------------------------------------   
--  
   Function GetNYA_OLD (p_controllo Number, p_parametro Varchar2, p_Sede_Tecnica Varchar2)    
      RETURN   Number   Is
      n_value  Number;
      n_nya    Number;
   BEGIN

   Select NYA into n_nya From Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI Where NUMERO_PARAMETRO_MULTIPLO = p_parametro;

      Select Nvl(MAX(d.NYA),n_nya)
        INTO n_value
        From Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI c,
             Rinf_Lavorazione_Evo.DETTAGLIO_CONTROLLATI d
       Where C.CODICE_PARAMETRO = D.CODICE_PARAMETRO 
	     And d.CODICE_CONTROLLO = p_controllo 
		 And NUMERO_PARAMETRO_MULTIPLO = p_parametro 
		 And SEDE_TECNICA = p_Sede_Tecnica;
--
      RETURN n_value;
   EXCEPTION
      When NO_DATA_FOUND Then
      RETURN n_nya;
   END GetNYA_OLD;
-- -------------------------------------------------------------------------------------------   
--                             FUNCTION GetAPCorridoio
--  se una SOL o OP appartengono a un Corridoio (PIC) ritorna 'Y', altrimenti ritorna 'N'
-- -------------------------------------------------------------------------------------------   
   Function GetAPCorridoio (p_Sede_Tecnica Varchar2)    
     RETURN Varchar2    Is
      n_value  Number;
   BEGIN
--
   If Substr(p_Sede_Tecnica, 1, 2) = 'TR' Then
       Select count(*) into n_value
         From  Rinf_Anagrafiche_Evo.CORRIDOIO_TRATTE l,
               Rinf_Anagrafiche_Evo.TRATTE_PIC t,
               Rinf_Controllati_Evo.SEZIONI_LINEA s
         Where s.SEDE_TECNICA = t.SEDE_TECNICA 
           And l.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC 
           And t.SEDE_TECNICA = p_Sede_Tecnica 
           And l.DATA_SCADENZA Is Null  and t.DATA_SCADENZA Is Null;
   Else
         Select count(*) into n_value
         From  Rinf_Anagrafiche_Evo.CORRIDOIO_LOCALITA l,
               Rinf_Anagrafiche_Evo.LOCALITA_PIC t,
               Rinf_Controllati_Evo.PUNTI_OPERATIVI s
         Where s.SEDE_TECNICA = t.COD_LOCALITA_IN_RETE 
           And l.CODICE_LOCALITA_PIC = t.CODICE_LOCALITA_PIC 
           And t.COD_LOCALITA_IN_RETE = p_Sede_Tecnica 
           And l.DATA_SCADENZA Is Null  and t.DATA_SCADENZA Is Null;
   End If;
--   
   If n_value = 0 Then
         RETURN 'N';
   Else
         RETURN 'Y';
   End If;
--
      EXCEPTION
          When NO_DATA_FOUND Then
               RETURN 'N';
 END GetAPCorridoio;
--
-- ------------------------------------------------------------------------------------------------   
--                          PROCEDURE SetNEWOPHierarchy
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetNEWOPHierarchy (p_Sede_Tecnica   In     Varchar2,
                                p_controllo      In     Number,
                                p_error          Out    Number )   Is

   BEGIN
      p_error := 0;
-- --------------------------------------------------------------------------------------
--  BINARI CORSA
--         Aggiorno i dati dei binari già presenti per essere sicura che siano gli ultimi
 begin
   Update Rinf_Controllati_Evo.BINARI_CORSA_PO c
     Set (PO_TRACK_1_2_1_0_0_1,
          PO_TRACK_1_2_1_0_0_2_D,
          PO_TRACK_1_2_1_0_2_1_AP,
          PO_TRACK_1_2_1_0_2_2_AP,
          PO_TRACK_1_2_1_0_2_3_AP,
          PO_TRACK_1_2_1_0_3_1_AP,
          PO_TRACK_1_2_1_0_3_1,
          PO_TRACK_1_2_1_0_3_2_AP,
          PO_TRACK_1_2_1_0_3_2,
          PO_TRACK_1_2_1_0_3_3_AP,
          PO_TRACK_1_2_1_0_3_3,
-->  Campi relativi ai nuovi parametri introdotti dal Reg.2019/777 
          PO_TRACK_1_2_1_0_3_4_AP ,
          PO_TRACK_1_2_1_0_3_4_SUP,
          PO_TRACK_1_2_1_0_3_4_INF,
          PO_TRACK_1_2_1_0_3_5_AP ,
          PO_TRACK_1_2_1_0_3_5_A  ,
          PO_TRACK_1_2_1_0_3_5_B  ,
          PO_TRACK_1_2_1_0_3_6_AP ,
          PO_TRACK_1_2_1_0_3_6    ,
-->		
          PO_TRACK_1_2_1_0_4_1_AP,
          PO_TRACK_1_2_1_0_4_1
		 )   =
  (Select PO_TRACK_1_2_1_0_0_1,
          PO_TRACK_1_2_1_0_0_2_D,
          Decode(GetNYA(p_controllo, '1.2.1.0.2.1', b.PO_TRACK_1_2_1_0_0_2), 1, 'NYA', 'Y') PO_TRACK_1_2_1_0_2_1_AP,
          Decode(GetNYA(p_controllo, '1.2.1.0.2.2', b.PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_2_2_AP) PO_TRACK_1_2_1_0_2_2_AP,
          Decode(GetNYA(p_controllo, '1.2.1.0.2.3', b.PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_2_3_AP) PO_TRACK_1_2_1_0_2_3_AP, --8/11/2016 eliminata la chiamata a GetAPCorridoio perchè sovrascrive l'applicabilità corretta che tiene conto dei binari di fermata
          Decode(GetNYA(p_controllo, '1.2.1.0.3.1', b.PO_TRACK_1_2_1_0_0_2), 1, 'NYA', 'Y') PO_TRACK_1_2_1_0_3_1_AP,
          PO_TRACK_1_2_1_0_3_1,                                                 
          Decode(GetNYA(p_controllo, '1.2.1.0.3.2', b.PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_3_2_AP) PO_TRACK_1_2_1_0_3_2_AP,
          PO_TRACK_1_2_1_0_3_2,                                                 
          Decode(GetNYA(p_controllo, '1.2.1.0.3.3', b.PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_3_3_AP) PO_TRACK_1_2_1_0_3_3_AP,
          PO_TRACK_1_2_1_0_3_3,
--> Campi relativi ai nuovi parametri introdotti dal Reg.2019/777 
          Decode(GetNYA(p_controllo, '1.2.1.0.3.4.SUP', b.PO_TRACK_1_2_1_0_0_2), 1, 'NYA', 'Y') PO_TRACK_1_2_1_0_3_4_AP ,
          PO_TRACK_1_2_1_0_3_4_SUP,
          PO_TRACK_1_2_1_0_3_4_INF,
          Decode(GetNYA(p_controllo, '1.2.1.0.3.5.A', b.PO_TRACK_1_2_1_0_0_2), 1, 'N', PO_TRACK_1_2_1_0_3_5_AP) PO_TRACK_1_2_1_0_3_5_AP,
          PO_TRACK_1_2_1_0_3_5_A,
          PO_TRACK_1_2_1_0_3_5_B,
          Decode(GetNYA(p_controllo, '1.2.1.0.3.6', b.PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_3_6_AP) PO_TRACK_1_2_1_0_3_6_AP,
          PO_TRACK_1_2_1_0_3_6,
-->      
          Decode(GetNYA(p_controllo, '1.2.1.0.4.1', b.PO_TRACK_1_2_1_0_0_2), 1, 'NYA', 'Y') PO_TRACK_1_2_1_0_4_1_AP,
          PO_TRACK_1_2_1_0_4_1             -- =[1435]
     From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
          Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
    Where b.PO_TRACK_1_2_1_0_0_2 = r.PO_TRACK_1_2_1_0_0_2
      And b.PO_TRACK_1_2_1_0_0_2 = c.PO_TRACK_1_2_1_0_0_2
      And r.SEDE_TECNICA = p_Sede_Tecnica
   )
    Where  c.PO_TRACK_1_2_1_0_0_2 In
   (Select a.PO_TRACK_1_2_1_0_0_2
      From Rinf_Controllati_Evo.BINARI_CORSA_PO a,
           Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA d
     Where a.PO_TRACK_1_2_1_0_0_2 = d.PO_TRACK_1_2_1_0_0_2
       And d.SEDE_TECNICA = p_Sede_Tecnica );
--  dbms_output.put_line ('update BINARI_CORSA_PO ');
--
   Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore Aggiornamento Rinf_Controllati_Evo.Binari_Corsa_Po: ' || Substr (Sqlerrm, 1, 300));
    End;

-- Inserisco i binari non presenti
  begin
      Insert Into Rinf_Controllati_Evo.BINARI_CORSA_PO 
	           (PO_TRACK_1_2_1_0_0_1,
                PO_TRACK_1_2_1_0_0_2,
                PO_TRACK_1_2_1_0_0_2_D,
                PO_TRACK_1_2_1_0_2_1_AP,     --  AP=Y - FITTIZIA PER NYA
                --PO_TRACK_1_2_1_0_2_1,          --IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO
                PO_TRACK_1_2_1_0_2_2_AP,           --
                --PO_TRACK_1_2_1_0_2_2,              --IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO
                PO_TRACK_1_2_1_0_2_3_AP,     --  AP=Y - FITTIZIA PER NYA
                --PO_TRACK_1_2_1_0_2_3,          --da tabella relazione TRATTE_CORRIDOI
                PO_TRACK_1_2_1_0_3_1_AP,     --  AP=Y - FITTIZIA PER NYA
                PO_TRACK_1_2_1_0_3_1,
                PO_TRACK_1_2_1_0_3_2_AP,                --0.82 AGOSTO
                PO_TRACK_1_2_1_0_3_2,
                PO_TRACK_1_2_1_0_3_3_AP,                --0.82 AGOSTO
                PO_TRACK_1_2_1_0_3_3,
-->  Campi relativi ai nuovi parametri introdotti dal Reg.2019/777  
                PO_TRACK_1_2_1_0_3_4_AP ,
                PO_TRACK_1_2_1_0_3_4_SUP,
                PO_TRACK_1_2_1_0_3_4_INF,
                PO_TRACK_1_2_1_0_3_5_AP ,
                PO_TRACK_1_2_1_0_3_5_A  ,
                PO_TRACK_1_2_1_0_3_5_B  ,
                PO_TRACK_1_2_1_0_3_6_AP ,
                PO_TRACK_1_2_1_0_3_6    ,
-->	
                PO_TRACK_1_2_1_0_4_1_AP,         --  AP=Y - FITTIZIA PER NYA
                PO_TRACK_1_2_1_0_4_1
                )
         Select PO_TRACK_1_2_1_0_0_1,
                PO_TRACK_1_2_1_0_0_2,
                PO_TRACK_1_2_1_0_0_2_D,
                Decode(GetNYA(p_controllo, '1.2.1.0.2.1', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', 'Y') PO_TRACK_1_2_1_0_2_1_AP,     --  AP=Y - FITTIZIA PER NYA
                --PO_TRACK_1_2_1_0_2_1,
                Decode(GetNYA(p_controllo, '1.2.1.0.2.2', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_2_2_AP) PO_TRACK_1_2_1_0_2_2_AP,           --
                --PO_TRACK_1_2_1_0_2_2,              --IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO
                Decode(GetNYA(p_controllo, '1.2.1.0.2.3', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_2_3_AP) PO_TRACK_1_2_1_0_2_3_AP, --8/11/2016 eliminata la chiamata a GetAPCorridoio perchè sovrascrive l'applicabilità corretta che tiene conto dei binari di fermata
                --PO_TRACK_1_2_1_0_2_3,
                Decode(GetNYA(p_controllo, '1.2.1.0.3.1', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', 'Y') PO_TRACK_1_2_1_0_3_1_AP,     --  AP=Y - FITTIZIA PER NYA
                PO_TRACK_1_2_1_0_3_1,
                Decode(GetNYA(p_controllo, '1.2.1.0.3.2', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_3_2_AP) PO_TRACK_1_2_1_0_3_2_AP,                --0.82 AGOSTO
                PO_TRACK_1_2_1_0_3_2,
                Decode(GetNYA(p_controllo, '1.2.1.0.3.3', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_3_3_AP) PO_TRACK_1_2_1_0_3_3_AP,                --0.82 AGOSTO
                PO_TRACK_1_2_1_0_3_3,
-->  Campi relativi ai nuovi parametri introdotti dal Reg.2019/777 
                Decode(GetNYA(p_controllo, '1.2.1.0.3.4.SUP', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', 'Y') PO_TRACK_1_2_1_0_3_4_AP ,
                PO_TRACK_1_2_1_0_3_4_SUP,
                PO_TRACK_1_2_1_0_3_4_INF,
                Decode(GetNYA(p_controllo, '1.2.1.0.3.5.A', PO_TRACK_1_2_1_0_0_2), 1, 'N', PO_TRACK_1_2_1_0_3_5_AP) PO_TRACK_1_2_1_0_3_5_AP,
                PO_TRACK_1_2_1_0_3_5_A,
                PO_TRACK_1_2_1_0_3_5_B,
                Decode(GetNYA(p_controllo, '1.2.1.0.3.6', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_3_6_AP) PO_TRACK_1_2_1_0_3_6_AP,
                PO_TRACK_1_2_1_0_3_6,
-->	
                Decode(GetNYA(p_controllo, '1.2.1.0.4.1', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', 'Y') PO_TRACK_1_2_1_0_4_1_AP,         --  AP=Y - FITTIZIA PER NYA
                PO_TRACK_1_2_1_0_4_1
           From Rinf_Lavorazione_Evo.BINARI_CORSA_PO
          Where PO_TRACK_1_2_1_0_0_2 In
                (Select a.PO_TRACK_1_2_1_0_0_2
                   From Rinf_Lavorazione_Evo.BINARI_CORSA_PO a,
                        Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA d
                  Where a.PO_TRACK_1_2_1_0_0_2 = d.PO_TRACK_1_2_1_0_0_2
                    And d.SEDE_TECNICA = p_Sede_Tecnica
                Minus
                 Select a.PO_TRACK_1_2_1_0_0_2
                   From Rinf_Controllati_Evo.BINARI_CORSA_PO a,
                        Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA d  --ATTENZIONE! la tabella di relazione deve essere quella dello schema Lavorazione perchè quella di Controllati non è ancora riempita
                  Where a.PO_TRACK_1_2_1_0_0_2 = d.PO_TRACK_1_2_1_0_0_2
                    And d.SEDE_TECNICA = p_Sede_Tecnica 	);
--
-- dbms_output.put_line ('insert BINARI_CORSA_PO : ');
   Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.BINARI_CORSA_PO: ' || Substr (Sqlerrm, 1, 300));
    End;

-- --------------------------------------------------------------------------------------
--   Relazione Binari di Corsa e PO - REL_PO_BINARI_CORSA 
--
 begin
    Insert Into Rinf_Controllati_Evo.REL_PO_BINARI_CORSA  
           	  (PO_TRACK_1_2_1_0_0_2, 
			   SEDE_TECNICA)
       Select r.PO_TRACK_1_2_1_0_0_2, 
	          r.SEDE_TECNICA
         From Rinf_Controllati_Evo.BINARI_CORSA_PO b,
              Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r
        Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2 
		  And r.SEDE_TECNICA = p_Sede_Tecnica
	 Minus                                                            ---> aggiunto
		  Select PO_TRACK_1_2_1_0_0_2, 
	              SEDE_TECNICA
         From Rinf_Controllati_Evo.REL_PO_BINARI_CORSA ;
-- dbms_output.put_line ('insert REL_PO_BINARI_CORSA' );

  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.REL_PO_BINARI_CORSA : ' || Substr (Sqlerrm, 1, 300));
    End;
-- --------------------------------------------------------------------------------------
-- Dichiarazioni Binari Corsa DICHIARAZIONI_BINARIO_PO 
--
 begin
    Insert Into Rinf_Controllati_Evo.DICHIARAZIONI_BINARIO_PO (
                PO_TRACK_1_2_1_0_0_2,
                TIPO_DICHIARAZIONE,
                PO_TRACK_1_2_1_0_1_1O2_AP,
                PO_TRACK_1_2_1_0_1_1O2,
                KM_INIZIO,
                KM_FINE,
                LATITUDINE_INIZIO,
                LONGITUDINE_INIZIO,
                LATITUDINE_FINE,
                LONGITUDINE_FINE,
                FLAG_CALCOLATO)
         Select PO_TRACK_1_2_1_0_0_2,
                TIPO_DICHIARAZIONE,
               Case
                  When TIPO_DICHIARAZIONE = 'EC' Then
                     Decode(GetNYA (p_controllo, '1.2.1.0.1.1', PO_TRACK_1_2_1_0_0_2), 1, 'NYA',PO_TRACK_1_2_1_0_1_1O2_AP)
                  Else
                     Decode(GetNYA (p_controllo, '1.2.1.0.1.2', PO_TRACK_1_2_1_0_0_2), 1, 'NYA', PO_TRACK_1_2_1_0_1_1O2_AP)
                End
                PO_TRACK_1_2_1_0_1_1O2_AP,
                PO_TRACK_1_2_1_0_1_1O2,
                KM_INIZIO,
                KM_FINE,
                LATITUDINE_INIZIO,
                LONGITUDINE_INIZIO,
                LATITUDINE_FINE,
                LONGITUDINE_FINE,
                FLAG_CALCOLATO
          From  Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_PO
          Where PO_TRACK_1_2_1_0_0_2 In
                     (Select a.PO_TRACK_1_2_1_0_0_2
--                        From Rinf_Controllati_Evo.BINARI_CORSA_PO a,
                        From Rinf_Lavorazione_Evo.BINARI_CORSA_PO a,
--                             Rinf_Controllati_Evo.REL_PO_BINARI_CORSA d                        --******* Modifica del 15/01
                             Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA d
                       Where a.PO_TRACK_1_2_1_0_0_2 = d.PO_TRACK_1_2_1_0_0_2
                         And d.SEDE_TECNICA = p_Sede_Tecnica)
            And (PO_TRACK_1_2_1_0_0_2,
                 TIPO_DICHIARAZIONE,
                 PO_TRACK_1_2_1_0_1_1O2,
                 KM_INIZIO) In
                     (Select PO_TRACK_1_2_1_0_0_2,
                             TIPO_DICHIARAZIONE,
                             PO_TRACK_1_2_1_0_1_1O2,
                             KM_INIZIO
                        From Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_PO
                      Minus
                      Select PO_TRACK_1_2_1_0_0_2,
                             TIPO_DICHIARAZIONE,
                             PO_TRACK_1_2_1_0_1_1O2,
                             KM_INIZIO
                        From Rinf_Controllati_Evo.DICHIARAZIONI_BINARIO_PO);
-- dbms_output.put_line ('insert DICHIARAZIONI_BINARIO_PO' );
  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.DICHIARAZIONI_BINARIO_PO : ' || Substr (Sqlerrm, 1, 300));
    End;
-- --------------------------------------------------------------------------------------
--                 GALLERIE_BINARI_PO
-- --------------------------------------------------------------------------------------
  begin

    Update Rinf_Controllati_Evo.GALLERIE_BINARI_PO e
       Set  (PO_TR_TUNNEL_1_2_1_0_5_2_D,
             PO_TR_TUNNEL_1_2_1_0_5_5_AP,         --0.82 AGOSTO DA RICONTROLLARE
             PO_TR_TUNNEL_1_2_1_0_5_5,
             PO_TR_TUNNEL_1_2_1_0_5_6_AP,         --  AP=Y - FITTIZIA PER NYA
             PO_TR_TUNNEL_1_2_1_0_5_6,
             PO_TR_TUNNEL_1_2_1_0_5_7_AP,
             PO_TR_TUNNEL_1_2_1_0_5_7,
             PO_TR_TUNNEL_1_2_1_0_5_8_AP,
             PO_TR_TUNNEL_1_2_1_0_5_8,
			 PO_TR_TUNNEL_1_2_1_0_5_9_AP,        -- Reg.2019/777
             PO_TR_TUNNEL_1_2_1_0_5_9 			 -- Reg.2019/777 
			 ) =
     (Select PO_TR_TUNNEL_1_2_1_0_5_2_D,
             Decode (GetNYA(p_controllo, '1.2.1.0.5.5', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', 'Y') PO_TR_TUNNEL_1_2_1_0_5_5_AP,         --0.82 AGOSTO DA RICONTROLLARE
             PO_TR_TUNNEL_1_2_1_0_5_5,
             Decode (GetNYA(p_controllo, '1.2.1.0.5.6', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_6_AP) PO_TR_TUNNEL_1_2_1_0_5_6_AP,         
             PO_TR_TUNNEL_1_2_1_0_5_6,
             Decode (GetNYA(p_controllo, '1.2.1.0.5.7', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_7_AP) PO_TR_TUNNEL_1_2_1_0_5_7_AP,
             PO_TR_TUNNEL_1_2_1_0_5_7,
             Decode (GetNYA(p_controllo, '1.2.1.0.5.8', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_8_AP) PO_TR_TUNNEL_1_2_1_0_5_8_AP,
             PO_TR_TUNNEL_1_2_1_0_5_8,
             Decode (GetNYA(p_controllo, '1.2.1.0.5.9', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_9_AP) PO_TR_TUNNEL_1_2_1_0_5_9_AP,          -- Reg.2019/777
--            'NYA' PO_TR_TUNNEL_1_2_1_0_5_9_AP,          -- Reg.2019/777
             PO_TR_TUNNEL_1_2_1_0_5_9           -- Reg.2019/777
        From Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO a
       Where a.PO_TR_TUNNEL_1_2_1_0_5_2 = e.PO_TR_TUNNEL_1_2_1_0_5_2
	  )
    Where PO_TR_TUNNEL_1_2_1_0_5_2 In
                   (Select g.PO_TR_TUNNEL_1_2_1_0_5_2
                      From Rinf_Controllati_Evo.GALLERIE_BINARI_PO g,
--                           Rinf_Controllati_Evo.REL_GALLERIE_BINARI_PO bg,
--                           Rinf_Controllati_Evo.BINARI_CORSA_PO b,
--                           Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r
                           Rinf_lavorazione_Evo.REL_GALLERIE_BINARI_PO bg,
                           Rinf_lavorazione_Evo.BINARI_CORSA_PO b,
                           Rinf_lavorazione_Evo.REL_PO_BINARI_CORSA r
                     Where g.PO_TR_TUNNEL_1_2_1_0_5_2 = bg.PO_TR_TUNNEL_1_2_1_0_5_2
                       And bg.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                       And r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                       And r.SEDE_TECNICA = p_Sede_Tecnica);
--
 dbms_output.put_line ('update GALLERIE_BINARI_PO ');
  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore aggiornamento Rinf_Controllati_Evo.GALLERIE_BINARI_PO: ' || Substr (Sqlerrm, 1, 300));
    End;

-- Inserisco le nuove gallerie
--     
 begin
         Insert Into Rinf_Controllati_Evo.GALLERIE_BINARI_PO 
               (PO_TR_TUNNEL_1_2_1_0_5_1,
                PO_TR_TUNNEL_1_2_1_0_5_2,
                PO_TR_TUNNEL_1_2_1_0_5_2_D,
                PO_TR_TUNNEL_1_2_1_0_5_5_AP,            -- 0.82 AGOSTO DA RICONTROLLARE
                PO_TR_TUNNEL_1_2_1_0_5_5,
                PO_TR_TUNNEL_1_2_1_0_5_6_AP,            -- AP=Y - FITTIZIA PER NYA
                PO_TR_TUNNEL_1_2_1_0_5_6,
                PO_TR_TUNNEL_1_2_1_0_5_7_AP,
                PO_TR_TUNNEL_1_2_1_0_5_7,
                PO_TR_TUNNEL_1_2_1_0_5_8_AP,
                PO_TR_TUNNEL_1_2_1_0_5_8,
                PO_TR_TUNNEL_1_2_1_0_5_9_AP,            -- Reg.2019/777
                PO_TR_TUNNEL_1_2_1_0_5_9)               -- Reg.2019/777
         Select PO_TR_TUNNEL_1_2_1_0_5_1,
                PO_TR_TUNNEL_1_2_1_0_5_2,
                PO_TR_TUNNEL_1_2_1_0_5_2_D,
                Decode (GetNYA(p_controllo, '1.2.1.0.5.5', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', 'Y') PO_TR_TUNNEL_1_2_1_0_5_5_AP,         --0.82 AGOSTO DA RICONTROLLARE
                PO_TR_TUNNEL_1_2_1_0_5_5,
                Decode (GetNYA(p_controllo, '1.2.1.0.5.6', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_6_AP) PO_TR_TUNNEL_1_2_1_0_5_6_AP,         
                PO_TR_TUNNEL_1_2_1_0_5_6,
                Decode (GetNYA(p_controllo, '1.2.1.0.5.7', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_7_AP ) PO_TR_TUNNEL_1_2_1_0_5_7_AP,
                PO_TR_TUNNEL_1_2_1_0_5_7,
                Decode (GetNYA(p_controllo, '1.2.1.0.5.8', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_8_AP ) PO_TR_TUNNEL_1_2_1_0_5_8_AP,
                PO_TR_TUNNEL_1_2_1_0_5_8,
                Decode (GetNYA(p_controllo, '1.2.1.0.5.9', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_9_AP ) PO_TR_TUNNEL_1_2_1_0_5_9_AP, -- Reg.2019/777
--                'NYA'  PO_TR_TUNNEL_1_2_1_0_5_9_AP,  -- Reg.2019/777
                PO_TR_TUNNEL_1_2_1_0_5_9          -- Reg.2019/777
           From Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO
          Where PO_TR_TUNNEL_1_2_1_0_5_2 In
                   (Select g.PO_TR_TUNNEL_1_2_1_0_5_2
                      From Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO g,
                           Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO bg,
--                           Rinf_Controllati_Evo.BINARI_CORSA_PO b,
--                           Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r                  -- *****
                           Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
                           Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r                    -- *****
                     Where g.PO_TR_TUNNEL_1_2_1_0_5_2 = bg.PO_TR_TUNNEL_1_2_1_0_5_2
                       And bg.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                       And r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                       And r.SEDE_TECNICA = p_Sede_Tecnica
                     Minus
                     Select PO_TR_TUNNEL_1_2_1_0_5_2 
					   From Rinf_Controllati_Evo.GALLERIE_BINARI_PO 
					); 
-- 20/03/2015 devo eliminare le gallerire già inserite In anagrafica perchè appartenneti anche ad altre località
--
 dbms_output.put_line ('insert GALLERIE_BINARI_PO ');
