-- dbms_output.put_line ('p_Sede_Tecnica: '||p_Sede_Tecnica);

  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.GALLERIE_BINARI_PO: ' || Substr (Sqlerrm, 1, 300));
    End;

-- --------------------------------------------------------------------------------------
-- Dichiarazioni Gallerie Binari Di Circolazione - DICHIARAZIONI_GALLERIE_BIN_PO
-- 23/03/2015 Aggiorno i dati delle dichiarazioni delle gallerie già presenti, per essere sicura che i dati siano gli ultimi
 begin 
   Update Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_BIN_PO e
      Set (PO_TR_TUNNEL_1_2_1_0_5_3O4_AP, 
	       KM_FINE, 
		   LATITUDINE_INIZIO, 
		   LONGITUDINE_INIZIO, 
		   LATITUDINE_FINE, 
		   LONGITUDINE_FINE, 
		   FLAG_CALCOLATO    ) =
         (Select Case When TIPO_DICHIARAZIONE = 'EC' Then 
		              Decode(GetNYA(p_controllo, '1.2.1.0.5.3', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_3O4_AP)
                 Else Decode(GetNYA(p_controllo, '1.2.1.0.5.4', PO_TR_TUNNEL_1_2_1_0_5_2), 1, 'NYA', PO_TR_TUNNEL_1_2_1_0_5_3O4_AP)
                 End PO_TR_TUNNEL_1_2_1_0_5_3O4_AP,
                 KM_FINE,
                 LATITUDINE_INIZIO,
                 LONGITUDINE_INIZIO,
                 LATITUDINE_FINE,
                 LONGITUDINE_FINE,
                 FLAG_CALCOLATO
            From Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_BIN_PO d
           Where e.PO_TR_TUNNEL_1_2_1_0_5_2   = d.PO_TR_TUNNEL_1_2_1_0_5_2           
             And e.TIPO_DICHIARAZIONE         = d.TIPO_DICHIARAZIONE                
             And e.PO_TR_TUNNEL_1_2_1_0_5_3O4 = d.PO_TR_TUNNEL_1_2_1_0_5_3O4        
             And e.KM_INIZIO                  = d.KM_INIZIO
		  )
      Where (PO_TR_TUNNEL_1_2_1_0_5_2, TIPO_DICHIARAZIONE, PO_TR_TUNNEL_1_2_1_0_5_3O4, KM_INIZIO) In
   (Select g.PO_TR_TUNNEL_1_2_1_0_5_2, TIPO_DICHIARAZIONE, PO_TR_TUNNEL_1_2_1_0_5_3O4, KM_INIZIO
        From Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_BIN_PO g,
--             Rinf_Controllati_Evo.REL_GALLERIE_BINARI_PO bg,                    -- *****
             Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO bg,                      -- *****
             Rinf_Controllati_Evo.BINARI_CORSA_PO b,
--             Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r                         -- *****
             Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r                           -- *****
       Where g.PO_TR_TUNNEL_1_2_1_0_5_2 = bg.PO_TR_TUNNEL_1_2_1_0_5_2
         And bg.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
         And r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
         And r.SEDE_TECNICA = p_Sede_Tecnica );
--
-- dbms_output.put_line ('update DICHIARAZIONI_GALLERIE_BIN_PO ' );
  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore aggiornamento Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_BIN_PO : ' || Substr (Sqlerrm, 1, 300));
    End;

-- Inserisco le nuove dichiarazioni
 begin
      Insert Into Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_BIN_PO 
	           (PO_TR_TUNNEL_1_2_1_0_5_2,
                TIPO_DICHIARAZIONE,
                PO_TR_TUNNEL_1_2_1_0_5_3O4_AP,
                PO_TR_TUNNEL_1_2_1_0_5_3O4,
                KM_INIZIO,
                KM_FINE,
                LATITUDINE_INIZIO,
                LONGITUDINE_INIZIO,
                LATITUDINE_FINE,
                LONGITUDINE_FINE,
                FLAG_CALCOLATO)
         Select PO_TR_TUNNEL_1_2_1_0_5_2,
                TIPO_DICHIARAZIONE,
                Case When TIPO_DICHIARAZIONE='EC' Then 
				     Decode(GetNYA(p_controllo, '1.2.1.0.5.3', PO_TR_TUNNEL_1_2_1_0_5_2), 1,'NYA', PO_TR_TUNNEL_1_2_1_0_5_3O4_AP)
                Else Decode(GetNYA(p_controllo, '1.2.1.0.5.4', PO_TR_TUNNEL_1_2_1_0_5_2), 1,'NYA', PO_TR_TUNNEL_1_2_1_0_5_3O4_AP)
                End PO_TR_TUNNEL_1_2_1_0_5_3O4_AP,
                PO_TR_TUNNEL_1_2_1_0_5_3O4,
                KM_INIZIO,
                KM_FINE,
                LATITUDINE_INIZIO,
                LONGITUDINE_INIZIO,
                LATITUDINE_FINE,
                LONGITUDINE_FINE,
                FLAG_CALCOLATO
           From Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_BIN_PO
          Where PO_TR_TUNNEL_1_2_1_0_5_2 In
                   (Select g.PO_TR_TUNNEL_1_2_1_0_5_2
                      From Rinf_Lavorazione_Evo.GALLERIE_BINARI_PO g,
                           Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO bg,
--                           Rinf_Controllati_Evo.BINARI_CORSA_PO b,                     
                           Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,                     
--                           Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r                 -- *****
                           Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r                    -- *****
                     Where g.PO_TR_TUNNEL_1_2_1_0_5_2 = bg.PO_TR_TUNNEL_1_2_1_0_5_2
                       And bg.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                       And r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                       And r.SEDE_TECNICA = p_Sede_Tecnica
					)
           And (PO_TR_TUNNEL_1_2_1_0_5_2, TIPO_DICHIARAZIONE, PO_TR_TUNNEL_1_2_1_0_5_3O4, KM_INIZIO) In
           (Select PO_TR_TUNNEL_1_2_1_0_5_2, TIPO_DICHIARAZIONE, PO_TR_TUNNEL_1_2_1_0_5_3O4, KM_INIZIO
              From Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_BIN_PO
           Minus
           Select PO_TR_TUNNEL_1_2_1_0_5_2, TIPO_DICHIARAZIONE, PO_TR_TUNNEL_1_2_1_0_5_3O4, KM_INIZIO 
		     From Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_BIN_PO 	);
--
-- dbms_output.put_line ('insert DICHIARAZIONI_GALLERIE_BIN_PO');
  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_BIN_PO : ' || Substr (Sqlerrm, 1, 300));
    End;

