 begin 
      Insert Into Rinf_Controllati_Evo.REL_GALLERIE_BINARI_PO 
	             (PO_TR_TUNNEL_1_2_1_0_5_2, PO_TRACK_1_2_1_0_0_2)
           Select PO_TR_TUNNEL_1_2_1_0_5_2, PO_TRACK_1_2_1_0_0_2
             From Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO
            Where PO_TRACK_1_2_1_0_0_2 In
                 (Select b.PO_TRACK_1_2_1_0_0_2
--                    From Rinf_Controllati_Evo.BINARI_CORSA_PO b,
                    From Rinf_Lavorazione_Evo.BINARI_CORSA_PO b,
--                         Rinf_Controllati_Evo.REL_PO_BINARI_CORSA r                  -- *****
                         Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA r                    -- *****
                   Where r.PO_TRACK_1_2_1_0_0_2 = b.PO_TRACK_1_2_1_0_0_2
                     And r.SEDE_TECNICA = p_Sede_Tecnica
			      )
              And (PO_TR_TUNNEL_1_2_1_0_5_2, PO_TRACK_1_2_1_0_0_2) In
                  (Select PO_TR_TUNNEL_1_2_1_0_5_2, PO_TRACK_1_2_1_0_0_2 
				     From Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_PO
                  Minus
                   Select PO_TR_TUNNEL_1_2_1_0_5_2,PO_TRACK_1_2_1_0_0_2 
				     From Rinf_Controllati_Evo.REL_GALLERIE_BINARI_PO
				   );
