                           Decode(greatest (GetNYA(p_controllo,  '1.2.2.0.3.3.A', PO_SD_1_2_2_0_0_2) , GetNYA(p_controllo,  '1.2.2.0.3.3.B', PO_SD_1_2_2_0_0_2) ), 1, 'NYA', PO_SD_1_2_2_0_3_3_AP) PO_SD_1_2_2_0_3_3_AP,  
--> 
                           Decode(PO_SD_1_2_2_0_3_3_A, 999, Null, PO_SD_1_2_2_0_3_3_A) PO_SD_1_2_2_0_3_3_A,
                           Decode(PO_SD_1_2_2_0_3_3_B, 999, Null, PO_SD_1_2_2_0_3_3_B) PO_SD_1_2_2_0_3_3_B,
--
                           Decode(GetNYA(p_controllo, '1.2.2.0.4.1', PO_SD_1_2_2_0_0_2), 1, 'NYA', 'Y') PO_SD_1_2_2_0_4_1_AP,            --  AP=Y - FITTIZIA PER NYA
                           PO_SD_1_2_2_0_4_1, 
                           Decode(GetNYA(p_controllo, '1.2.2.0.4.2', PO_SD_1_2_2_0_0_2), 1, 'NYA', 'Y') PO_SD_1_2_2_0_4_2_AP,            --  AP=Y - FITTIZIA PER NYA
                           PO_SD_1_2_2_0_4_2,
                           Decode(GetNYA(p_controllo, '1.2.2.0.4.3', PO_SD_1_2_2_0_0_2), 1, 'NYA', 'Y') PO_SD_1_2_2_0_4_3_AP,            --  AP=Y - FITTIZIA PER NYA
                           PO_SD_1_2_2_0_4_3,
                           Decode(GetNYA(p_controllo, '1.2.2.0.4.4', PO_SD_1_2_2_0_0_2), 1, 'NYA', 'Y') PO_SD_1_2_2_0_4_4_AP,            --  AP=Y - FITTIZIA PER NYA
                           PO_SD_1_2_2_0_4_4,
                           Decode(GetNYA(p_controllo, '1.2.2.0.4.5', PO_SD_1_2_2_0_0_2), 1, 'NYA', 'Y') PO_SD_1_2_2_0_4_5_AP,            --  AP=Y - FITTIZIA PER NYA
                           PO_SD_1_2_2_0_4_5,
                           Decode(GetNYA(p_controllo, '1.2.2.0.4.6', PO_SD_1_2_2_0_0_2), 1, 'NYA', 'Y') PO_SD_1_2_2_0_4_6_AP,            --  AP=Y - FITTIZIA PER NYA
                           PO_SD_1_2_2_0_4_6,
-->
