 						   Decode(GetNYA(p_controllo, '1.2.2.0.6.1', PO_SD_1_2_2_0_0_2), 1, 'N', PO_SD_1_2_2_0_6_1_AP) PO_SD_1_2_2_0_6_1_AP,            -- Reg.2019/777
						   PO_SD_1_2_2_0_6_1,                                                                                            -- Reg.2019/777
-->
                           SEDE_TECNICA
                      From Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO
                     Where SEDE_TECNICA = p_Sede_Tecnica;
