 begin 
      Insert Into Rinf_Controllati_Evo.DICHIARAZIONI_RACCORDO_PO (
                     PO_SD_1_2_2_0_0_2,
                     TIPO_DICHIARAZIONE,
                     PO_SD_1_2_2_0_1_1O2_AP,
                     PO_SD_1_2_2_0_1_1O2,
                     KM_INIZIO,
                     KM_FINE,
                     LATITUDINE_INIZIO,
                     LONGITUDINE_INIZIO,
                     LATITUDINE_FINE,
                     LONGITUDINE_FINE,
                     FLAG_CALCOLATO)
              Select PO_SD_1_2_2_0_0_2,
                     TIPO_DICHIARAZIONE,
                     Case When TIPO_DICHIARAZIONE = 'EC' 
					      Then Decode(GetNYA(p_controllo, '1.2.2.0.1.1', PO_SD_1_2_2_0_0_2), 1, 'NYA', PO_SD_1_2_2_0_1_1O2_AP)
                          Else Decode(GetNYA(p_controllo, '1.2.2.0.1.2', PO_SD_1_2_2_0_0_2), 1, 'NYA', PO_SD_1_2_2_0_1_1O2_AP)
                     End PO_SD_1_2_2_0_1_1O2_AP,
                     PO_SD_1_2_2_0_1_1O2,
                     KM_INIZIO,
                     KM_FINE,
                     LATITUDINE_INIZIO,
                     LONGITUDINE_INIZIO,
                     LATITUDINE_FINE,
                     LONGITUDINE_FINE,
                     FLAG_CALCOLATO
                From Rinf_Lavorazione_Evo.DICHIARAZIONI_RACCORDO_PO
               Where PO_SD_1_2_2_0_0_2  In 
			        (Select PO_SD_1_2_2_0_0_2
--                       From Rinf_Controllati_Evo.BINARI_RACCORDO_PO
                       From Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO
                      Where SEDE_TECNICA = p_Sede_Tecnica
					 );
-- dbms_output.put_line ('insert DICHIARAZIONI_RACCORDO_PO ');
  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.DICHIARAZIONI_RACCORDO_PO : ' || Substr (Sqlerrm, 1, 300));
    End;

