-- Gallerie Binari Raccordo - GALLERIE_RACCORDO_PO
-- 24/03/2015 Aggiorno i dati delle gallerie già presenti
  begin
      Update Rinf_Controllati_Evo.GALLERIE_RACCORDO_PO e
         Set (             PO_SD_TUNNEL_1_2_2_0_5_2_D,
                           PO_SD_TUNNEL_1_2_2_0_5_5_AP,         --RICONTROLLARE 0.82 AGOSTO
                           PO_SD_TUNNEL_1_2_2_0_5_5,
                           PO_SD_TUNNEL_1_2_2_0_5_6_AP,         --  AP=Y - FITTIZIA PER NYA
                           PO_SD_TUNNEL_1_2_2_0_5_6,
                           PO_SD_TUNNEL_1_2_2_0_5_7_AP,
                           PO_SD_TUNNEL_1_2_2_0_5_7,
                           PO_SD_TUNNEL_1_2_2_0_5_8_AP,
                           PO_SD_TUNNEL_1_2_2_0_5_8
			  ) =
               (Select     PO_SD_TUNNEL_1_2_2_0_5_2_D,
                           Decode(GetNYA(p_controllo, '1.2.2.0.5.5', PO_SD_TUNNEL_1_2_2_0_5_2), 1, 'NYA', 'Y') PO_SD_TUNNEL_1_2_2_0_5_5_AP,         --RICONTROLLARE 0.82 AGOSTO
                           PO_SD_TUNNEL_1_2_2_0_5_5,
                           Decode(GetNYA(p_controllo, '1.2.2.0.5.6', PO_SD_TUNNEL_1_2_2_0_5_2), 1, 'NYA', PO_SD_TUNNEL_1_2_2_0_5_6_AP) PO_SD_TUNNEL_1_2_2_0_5_6_AP,  
                           PO_SD_TUNNEL_1_2_2_0_5_6,
                           Decode(GetNYA(p_controllo, '1.2.2.0.5.7', PO_SD_TUNNEL_1_2_2_0_5_2), 1, 'NYA', PO_SD_TUNNEL_1_2_2_0_5_7_AP) PO_SD_TUNNEL_1_2_2_0_5_7_AP,
                           PO_SD_TUNNEL_1_2_2_0_5_7,
                           Decode(GetNYA(p_controllo, '1.2.2.0.5.8', PO_SD_TUNNEL_1_2_2_0_5_2), 1, 'NYA', PO_SD_TUNNEL_1_2_2_0_5_8_AP) PO_SD_TUNNEL_1_2_2_0_5_8_AP,
                           PO_SD_TUNNEL_1_2_2_0_5_8
                     From  Rinf_Lavorazione_Evo.GALLERIE_RACCORDO_PO i
                     Where i.PO_SD_TUNNEL_1_2_2_0_5_2 = e.PO_SD_TUNNEL_1_2_2_0_5_2
				)
          Where PO_SD_TUNNEL_1_2_2_0_5_2 In
                   (Select g.PO_SD_TUNNEL_1_2_2_0_5_2
                      From Rinf_Controllati_Evo.GALLERIE_RACCORDO_PO g,
--                           Rinf_Controllati_Evo.REL_GALLERIE_RACCORDO_PO bg,
--                           Rinf_Controllati_Evo.BINARI_RACCORDO_PO b
                           Rinf_Lavorazione_Evo.REL_GALLERIE_RACCORDO_PO bg,
                           Rinf_Lavorazione_Evo.BINARI_RACCORDO_PO b
                     Where g.PO_SD_TUNNEL_1_2_2_0_5_2 = bg.PO_SD_TUNNEL_1_2_2_0_5_2
                       And bg.PO_SD_1_2_2_0_0_2 = b.PO_SD_1_2_2_0_0_2
                       And b.SEDE_TECNICA = p_Sede_Tecnica	);
--
-- dbms_output.put_line ('update GALLERIE_RACCORDO_PO' );
  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore aggiornamento Rinf_Controllati_Evo.GALLERIE_RACCORDO_PO : ' || Substr (Sqlerrm, 1, 300));
    End;

