 begin 
      Update Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_SD_PO e
         Set (PO_SD_TUNNEL_1_2_2_0_5_3O4_AP,
              KM_FINE,
              LATITUDINE_INIZIO,
              LONGITUDINE_INIZIO,
              LATITUDINE_FINE,
              LONGITUDINE_FINE,
              FLAG_CALCOLATO
			  ) =
       (Select Case When TIPO_DICHIARAZIONE = 'EC' 
	                Then Decode(GetNYA(p_controllo, '1.2.1.0.5.3', PO_SD_TUNNEL_1_2_2_0_5_2), 1, 'NYA', PO_SD_TUNNEL_1_2_2_0_5_3O4_AP)
                    Else Decode(GetNYA(p_controllo, '1.2.1.0.5.4', PO_SD_TUNNEL_1_2_2_0_5_2), 1, 'NYA', PO_SD_TUNNEL_1_2_2_0_5_3O4_AP)
               End PO_SD_TUNNEL_1_2_2_0_5_3O4_AP,
                    KM_FINE,
                    LATITUDINE_INIZIO,
                    LONGITUDINE_INIZIO,
                    LATITUDINE_FINE,
                    LONGITUDINE_FINE,
                    FLAG_CALCOLATO
               From Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_SD_PO i
              Where e.PO_SD_TUNNEL_1_2_2_0_5_2 = i.PO_SD_TUNNEL_1_2_2_0_5_2  
			    And e.TIPO_DICHIARAZIONE = i.TIPO_DICHIARAZIONE    
				And e.PO_SD_TUNNEL_1_2_2_0_5_3O4 = i.PO_SD_TUNNEL_1_2_2_0_5_3O4 
				And e.KM_INIZIO = i.KM_INIZIO
		)
         Where (PO_SD_TUNNEL_1_2_2_0_5_2,   TIPO_DICHIARAZIONE,   PO_SD_TUNNEL_1_2_2_0_5_3O4,   KM_INIZIO )    In
      (Select g.PO_SD_TUNNEL_1_2_2_0_5_2, g.TIPO_DICHIARAZIONE, g.PO_SD_TUNNEL_1_2_2_0_5_3O4, g.KM_INIZIO
         From Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_SD_PO g,
