--
-- ------------------------------------------------------------------------------------------------   
--                                PROCEDURE SetPreparaOPPlat
-- Questa procedura elimina i dati dei binari di corsa dei marciapiedi che non sono presenti nell'anagrafica Rinf_Controllati_Evo.BINARI_CORSA_PO
-- per evitare che si verificano errori di chiave esterna nel cariamento dei marciapiedi
-- ------------------------------------------------------------------------------------------------   
--  
 Procedure SetPreparaOPPlat    Is
   BEGIN
--
--- Eliminzione binari non presenti nell'anagrafica dei binari di corsa PO
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Set BINARIO_1 = Null
      Where  BINARIO_1 In
     (Select BINARIO_1 From Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
       Minus
      Select b.PO_TRACK_1_2_1_0_0_2 From Rinf_Controllati_Evo.BINARI_CORSA_PO b);
--
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Set BINARIO_2 = Null
      Where BINARIO_2 In
   (Select BINARIO_2 From Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
     Minus
    Select b.PO_TRACK_1_2_1_0_0_2 From Rinf_Controllati_Evo.BINARI_CORSA_PO b);
--
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Set BINARIO_3 = Null
      Where BINARIO_3 In
    (Select BINARIO_3 From  Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Minus
     Select b.PO_TRACK_1_2_1_0_0_2 From Rinf_Controllati_Evo.BINARI_CORSA_PO b);
--
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Set BINARIO_4 = Null
      Where BINARIO_4 In
    (Select BINARIO_4 From Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Minus
     Select b.PO_TRACK_1_2_1_0_0_2 From Rinf_Controllati_Evo.BINARI_CORSA_PO b);
--
--- Shifting dei codici dei binari
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Set BINARIO_1 = BINARIO_2,
          BINARIO_2 = Null
    Where BINARIO_1 Is Null And BINARIO_2 Is Not Null;
--   
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Set BINARIO_1 = BINARIO_3,
          BINARIO_3 = Null
    Where BINARIO_1 Is Null And BINARIO_3 Is Not Null;
--   
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO            --aggiunto da Alessio 28/10/2016
      Set BINARIO_1 = BINARIO_4,
          BINARIO_4 = Null
    Where BINARIO_1 Is Null And BINARIO_4 Is Not Null;
--   
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Set BINARIO_2 = BINARIO_3,
          BINARIO_3 = Null
    Where BINARIO_1 Is Not Null And BINARIO_2 Is Null And BINARIO_3 Is Not Null;
--   
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Set BINARIO_2 = BINARIO_4,
          BINARIO_4 = Null
    Where BINARIO_1 Is Not Null And BINARIO_2 Is Null And BINARIO_4 Is Not Null;           --aggiunto da Alessio 28/10/2016
--   
   Update Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
      Set BINARIO_3 = BINARIO_4,
          BINARIO_4 = Null
   Where BINARIO_1 Is Not Null And BINARIO_2 Is Not Null And BINARIO_3 Is  Null And BINARIO_4 Is Not Null;
--
 END SetPreparaOPPlat;
--
-- ------------------------------------------------------------------------------------------------   
--                            PROCEDURE SetOPHierarchyPlat (Marciapiedi)
--  Questa procedura elimina dai campi BINARIO_1, BIANRIO_2, BINARIO_3 e BIANRIO_4 i valori dei binari di corsa che non sono presenti 
--  nell'anagrafica Rinf_Controllati_Evo.BINARI_CORSA_PO
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetOPHierarchyPlat (p_controllo   In  Number,  
                               p_error       Out Number )    Is
   BEGIN
--
    SetPreparaOPPlat;
--
  begin 
      Insert Into Rinf_Controllati_Evo.MARCIAPIEDI_BINARI_PO 
	             (PO_TR_PLATFORM_1_2_1_0_6_1,
                  PO_TR_PLATFORM_1_2_1_0_6_2,
