           Select PO_TR_PLATFORM_1_2_1_0_6_1,
                  PO_TR_PLATFORM_1_2_1_0_6_2,
                  PO_TR_PLATFORM_1_2_1_0_6_2_D,  --nuovo 082
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.3', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y') PO_TR_PLATFORM_1_2_1_0_6_3_AP,         --  AP=Y - FITTIZIA PER NYA
                  --PO_TR_PLATFORM_1_2_1_0_6_3,
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.4.B1', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y') PO_TR_PLAT_1_2_1_0_6_4_B1_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_4_B1, --nuovo 082
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.4.B2', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y')PO_TR_PLAT_1_2_1_0_6_4_B2_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_4_B2, --nuovo 082
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.4.B3', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y')PO_TR_PLAT_1_2_1_0_6_4_B3_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_4_B3, --nuovo 082
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.4.B4', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y')PO_TR_PLAT_1_2_1_0_6_4_B4_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_4_B4, --nuovo 082
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.5.B1', PO_TR_PLATFORM_1_2_1_0_6_2), 1,'NYA','Y')PO_TR_PLAT_1_2_1_0_6_5_B1_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_5_B1, --nuovo 082
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.5.B2', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y')PO_TR_PLAT_1_2_1_0_6_5_B2_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_5_B2, --nuovo 082
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.5.B3', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y')PO_TR_PLAT_1_2_1_0_6_5_B3_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_5_B3, --nuovo 082
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.5.B4', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y')PO_TR_PLAT_1_2_1_0_6_5_B4_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_5_B4, --nuovo 082
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.6', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y')PO_TR_PLATFORM_1_2_1_0_6_6_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_6,
                  Decode(GetNYA(p_controllo, '1.2.1.0.6.7', PO_TR_PLATFORM_1_2_1_0_6_2), 1, 'NYA', 'Y')PO_TR_PLATFORM_1_2_1_0_6_7_AP,         --  AP=Y - FITTIZIA PER NYA
                  PO_TR_PLATFORM_1_2_1_0_6_7,
                  BINARIO_1, --nuovo 082
                  BINARIO_2, --nuovo 082
                  BINARIO_3, --082
                  BINARIO_4
             From Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO b
            Where PO_TR_PLATFORM_1_2_1_0_6_2 In
          (Select PO_TR_PLATFORM_1_2_1_0_6_2 
		     From Rinf_Lavorazione_Evo.MARCIAPIEDI_BINARI_PO
            Minus
           Select PO_TR_PLATFORM_1_2_1_0_6_2 
			 From Rinf_Controllati_Evo.MARCIAPIEDI_BINARI_PO	);
-- dbms_output.put_line ('Insert MARCIAPIEDI_BINARI_PO ');
  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.MARCIAPIEDI_BINARI_PO: ' || Substr (Sqlerrm, 1, 300));
    End;
--
-- PAR_1_2_1_0_6_3_CAT_TEN_PL                                                                                         multivalore 082 agosto
-- 09/05/2016 Questa valorizzaizone è stata spostata dalla procedura SetNewOPGerarchy, pechè le categorie devono essere valorizzate a valle dei marciapiedi
  begin 
      Insert Into Rinf_Controllati_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL 
	             (PO_TR_PLATFORM_1_2_1_0_6_2,
