             From Rinf_Lavorazione_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL c,
                  Rinf_Controllati_Evo.MARCIAPIEDI_BINARI_PO p
            Where C.PO_TR_PLATFORM_1_2_1_0_6_2 = p.PO_TR_PLATFORM_1_2_1_0_6_2
              And (c.PO_TR_PLATFORM_1_2_1_0_6_2, PO_TR_PLATFORM_1_2_1_0_6_3) In
             (Select PO_TR_PLATFORM_1_2_1_0_6_2, PO_TR_PLATFORM_1_2_1_0_6_3
                From Rinf_Lavorazione_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL
             Minus
              Select PO_TR_PLATFORM_1_2_1_0_6_2, PO_TR_PLATFORM_1_2_1_0_6_3
                From Rinf_Controllati_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL
			  );
