  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.PAR_1_2_1_0_6_3_CAT_TEN_PL: ' || Substr (Sqlerrm, 1, 300));
    End;

 EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0,
                                       'SetOPHierarchyPlat - Elaborazione controlli. Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null, p_errlog);
         Dbms_Output.Put_Line ('SetOPHierarchyPlat - Errore: ' || Substr(SQLERRM, 1, 300));
 END SetOPHierarchyPlat;
--
-- ------------------------------------------------------------------------------------------------   
--                         PROCEDURE SetOPGeographicArea
-- ------------------------------------------------------------------------------------------------   
--
 PROCEDURE SetOPGeographicArea(p_Sede_Tecnica   In     Varchar2,
                               p_error          Out    Number )   Is
   BEGIN
      p_error := 0;
--
--  Linea_Comm_Po
--
    Delete From Rinf_Controllati_Evo.LINEA_COMM_PO Where SEDE_TECNICA = p_Sede_Tecnica;
       Dbms_Output.Put_Line ('delete LINEA_COMM_PO');
--
    Insert Into Rinf_Controllati_Evo.LINEA_COMM_PO 
	      (CODICE_GIURISDIZIONE, SEDE_TECNICA, KM_INIZIO)
    Select Distinct CODICE_GIURISDIZIONE, s.SEDE_TECNICA, s.KM_INIZIO
     From  Rinf_Anagrafiche_Evo.LINEA_COMM_LOCALITA l,
           Rinf_Anagrafiche_Evo.LOCALITA_PIC t,
           Rinf_Controllati_Evo.PUNTI_OPERATIVI s
     Where s.SEDE_TECNICA = t.COD_LOCALITA_IN_RETE 
       And l.CODICE_LOCALITA_PIC = t.CODICE_LOCALITA_PIC 
       And t.COD_LOCALITA_IN_RETE = p_Sede_Tecnica 
	   And l.DATA_SCADENZA Is Null; -- and t.DATA_SCADENZA Is Null;

       Dbms_Output.Put_Line ('Insert LINEA_COMM_PO');
--
--  Corridoio
--
    Delete From Rinf_Controllati_Evo.CORRIDOIO_PO Where SEDE_TECNICA = p_Sede_Tecnica;

       Dbms_Output.Put_Line ('delete CORRIDOIO_PO');
--
    Insert Into Rinf_Controllati_Evo.CORRIDOIO_PO (CODICE_CORRIDOIO, SEDE_TECNICA)
    Select Distinct CODICE_GIURISDIZIONE, s.SEDE_TECNICA
     From  Rinf_Anagrafiche_Evo.CORRIDOIO_LOCALITA l,
           Rinf_Anagrafiche_Evo.LOCALITA_PIC t,
           Rinf_Controllati_Evo.PUNTI_OPERATIVI s
     Where s.SEDE_TECNICA = t.COD_LOCALITA_IN_RETE 
       And l.CODICE_LOCALITA_PIC = t.CODICE_LOCALITA_PIC 
       And t.COD_LOCALITA_IN_RETE = p_Sede_Tecnica 
       And l.DATA_SCADENZA Is Null; -- and t.DATA_SCADENZA Is Null;

       Dbms_Output.Put_Line ('insert CORRIDOIO_PO');

--
-- Linea Ten
--
    Delete From Rinf_Controllati_Evo.LINEE_TENT_PO Where SEDE_TECNICA = p_Sede_Tecnica;
--	
       Dbms_Output.Put_Line ('delete LINEE_TENT_PO');

    Insert Into Rinf_Controllati_Evo.LINEE_TENT_PO 
	       (CODICE_LINEA_TENT, SEDE_TECNICA)
    Select Distinct CODICE_GIURISDIZIONE, s.SEDE_TECNICA
      From Rinf_Anagrafiche_Evo.LINEA_TENT_LOCALITA l,
--           Rinf_Anagrafiche_Evo.TRATTE_PIC t,
           Rinf_Anagrafiche_Evo.LOCALITA_PIC t,
           Rinf_Controllati_Evo.PUNTI_OPERATIVI s
     Where s.SEDE_TECNICA = t.COD_LOCALITA_IN_RETE 
       And l.CODICE_LOCALITA_PIC = t.CODICE_LOCALITA_PIC 
       And t.COD_LOCALITA_IN_RETE = p_Sede_Tecnica 
       And l.DATA_SCADENZA Is Null; --  and t.DATA_SCADENZA Is Null;

       Dbms_Output.Put_Line ('insert LINEE_TENT_PO ');

--
-- 18/07/2016 la valorizzazione del codice TAF/TAP è stata spostata qui dalla procedura SetNewOPHierarchy
-- perchè quest'ultima non viene invocata per le località che hanno il campo LOCALITA_CONTENITORE valorizzato
-- pertanto queste località non avevano il codice TAF/TAP valorizzato.
-- PAR_1_2_0_0_0_3_TAF_TAP
     Insert Into Rinf_Controllati_Evo.PAR_1_2_0_0_0_3_TAF_TAP 
	             (SEDE_TECNICA, PO_1_2_0_0_0_3, KM_INIZIO, KM_FINE)
           Select SEDE_TECNICA, PO_1_2_0_0_0_3, KM_INIZIO, KM_FINE
             From Rinf_Lavorazione_Evo.PAR_1_2_0_0_0_3_TAF_TAP
            Where SEDE_TECNICA = p_Sede_Tecnica;
--
       Dbms_Output.Put_Line ('insert PAR_1_2_0_0_0_3_TAF_TAP - fine');

  EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0, 'SetOPGeographicArea - Elaborazione controlli - Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null, p_errlog);
        Dbms_Output.Put_Line ('SetOPGeographicArea - Errore: ' || Substr(SQLERRM, 1, 300));
 END SetOPGeographicArea;
--
-- ------------------------------------------------------------------------------------------------   
--                               PROCEDURE SetSolGeographicArea
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetSolGeographicArea(p_Sede_Tecnica   In  Varchar2,
                                  p_error          Out Number )   Is
   BEGIN
      p_error := 0;

-- LINEA_COMM_SOL
    Delete From Rinf_Controllati_Evo.LINEA_COMM_SOL Where SEDE_TECNICA = p_Sede_Tecnica;
--
    Insert Into Rinf_Controllati_Evo.LINEA_COMM_SOL 
	      (CODICE_GIURISDIZIONE, SEDE_TECNICA, KM_INIZIO, KM_FINE)
    Select Distinct CODICE_GIURISDIZIONE, t.SEDE_TECNICA, s.KM_INIZIO, s.KM_FINE
     From Rinf_Anagrafiche_Evo.LINEA_COMM_TRATTE l,
          Rinf_Anagrafiche_Evo.TRATTE_PIC t,
          Rinf_Controllati_Evo.SEZIONI_LINEA s
    Where s.SEDE_TECNICA = t.SEDE_TECNICA 
      And l.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC 
      And t.SEDE_TECNICA = p_Sede_Tecnica 
      And l.DATA_SCADENZA Is Null; -- and t.DATA_SCADENZA Is Null;
--
-- CORRIDOIO_SOL
    Delete From Rinf_Controllati_Evo.CORRIDOIO_SOL Where SEDE_TECNICA = p_Sede_Tecnica;
--
    Insert Into Rinf_Controllati_Evo.CORRIDOIO_SOL 
	     (CODICE_CORRIDOIO, SEDE_TECNICA)
    Select Distinct CODICE_GIURISDIZIONE, s.SEDE_TECNICA
     From Rinf_Anagrafiche_Evo.CORRIDOIO_TRATTE l,
          Rinf_Anagrafiche_Evo.TRATTE_PIC t,
          Rinf_Controllati_Evo.SEZIONI_LINEA s
    Where s.SEDE_TECNICA = t.SEDE_TECNICA 
      And l.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC 
      And t.SEDE_TECNICA = p_Sede_Tecnica 
      And l.DATA_SCADENZA Is Null;  -- and t.DATA_SCADENZA Is Null;
--
-- Linea Ten
    Delete From Rinf_Controllati_Evo.LINEE_TENT_SOL Where SEDE_TECNICA = p_Sede_Tecnica;
--
	Insert Into Rinf_Controllati_Evo.LINEE_TENT_SOL 
	      (CODICE_LINEA_TENT, SEDE_TECNICA)
    Select Distinct CODICE_GIURISDIZIONE,s.SEDE_TECNICA
     From Rinf_Anagrafiche_Evo.LINEA_TENT_TRATTE l,
          Rinf_Anagrafiche_Evo.TRATTE_PIC t,
          Rinf_Controllati_Evo.SEZIONI_LINEA s
    Where s.SEDE_TECNICA = t.SEDE_TECNICA 
      And l.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC 
      And t.SEDE_TECNICA = p_Sede_Tecnica 
      And l.DATA_SCADENZA Is Null; -- and t.DATA_SCADENZA Is Null;
--
-- LINEA_FCL_SOL
    Delete From Rinf_Controllati_Evo.LINEA_FCL_SOL Where SEDE_TECNICA = p_Sede_Tecnica;
--
    Insert Into Rinf_Controllati_Evo.LINEA_FCL_SOL 
	     (CODICE_LINEA_FCL, SEDE_TECNICA)
    Select Distinct A.CODICE_LINEA_FCL,SEDE_TECNICA
     From Rinf_Anagrafiche_Evo.ANAG_LINEA_FCL a,
          Rinf_Anagrafiche_Evo.LINEA_FCL_TRATTE_ROMAN l,
          Rinf_Anagrafiche_Evo.TRATTE_ROMAN r,
          Rinf_Anagrafiche_Evo.TRATTE_PIC t
    Where a.CODICE_LINEA_FCL = l.CODICE_LINEA_FCL 
      And l.CODICE_TRATTA_ROMAN = r.CODICE_TRATTA_ROMAN
      And r.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC 
      And SEDE_TECNICA = p_Sede_Tecnica 
      And Nvl(a.DAT_FINE_VAL, To_Date('01012999', 'DDMMYYYY')) >= data_riferimento     --22/02/2016 inserita condizione per evitare di caricare le FCL scadute
      And l.DATA_SCADENZA Is Null  --and t.DATA_SCADENZA Is Null And
      And a.DATA_SCADENZA Is Null;
--
-- FASCICOLO_SOL
    Delete From Rinf_Controllati_Evo.FASCICOLO_SOL Where SEDE_TECNICA = p_Sede_Tecnica;
--
    Insert Into Rinf_Controllati_Evo.FASCICOLO_SOL 
	     (CODICE_FASCICOLO, SEDE_TECNICA)
    Select Distinct S.CODICE_FASCICOLO, T.SEDE_TECNICA
     From Rinf_Anagrafiche_Evo.LINEA_FCL_TRATTE_ROMAN l,
          Rinf_Anagrafiche_Evo.TRATTE_ROMAN r,
          Rinf_Anagrafiche_Evo.TRATTE_PIC t,
          Rinf_Anagrafiche_Evo.FASCICOLO_LINEE_FCL s
    Where l.CODICE_TRATTA_ROMAN = r.CODICE_TRATTA_ROMAN 
      And r.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC 
      And s.CODICE_LINEA_FCL = l.CODICE_LINEA_FCL 
      And t.SEDE_TECNICA = p_Sede_Tecnica 
      And l.DATA_SCADENZA Is Null -- and t.DATA_SCADENZA Is Null And
      And s.DATA_SCADENZA Is Null;
--
   EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG ( 0,'SetSolGeographicArea - Elaborazione controlli. Codice Errore: ' ||Sqlcode||' - '||Sqlerrm, Null, p_errlog);
 END SetSolGeographicArea;
--
-- ------------------------------------------------------------------------------------------------   
--                               PROCEDURE SetNEWSoLHierarchyTrack
-- ------------------------------------------------------------------------------------------------   
-- 
 Procedure SetNEWSoLHierarchyTrack (p_Sede_Tecnica   In  Varchar2,
                                    p_controllo      In  Number,
                                    p_error          Out Number )   Is
   BEGIN
      p_error := 0;
-- --------------------------------------------------------------------------------------	  
-- Binari di circolazione delle Tratte - BINARI_CORSA_SOL
      Insert Into Rinf_Controllati_Evo.BINARI_CORSA_SOL (
                  SOL_TRACK_1_1_1_0_0_1,
                  SOL_TRACK_1_1_1_0_0_1_D,
                  SOL_TRACK_1_1_1_0_0_2,
                  SOL_TRACK_1_1_1_1_2_1_AP,        --  AP=Y - FITTIZIA PER NYA
--                  SOL_TRACK_1_1_1_1_2_1,         --sospeso TEN SOL TRACK da PIC
                  SOL_TRACK_1_1_1_1_2_2_AP,          --
--                  SOL_TRACK_1_1_1_1_2_2,                 --IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO
                  SOL_TRACK_1_1_1_1_2_3_AP,
--                  SOL_TRACK_1_1_1_1_2_3,
                  SOL_TRACK_1_1_1_1_2_4_AP,        --  AP=Y - FITTIZIA PER NYA
--                  SOL_TRACK_1_1_1_1_2_4,     ----IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO
                  SOL_TRACK_1_1_1_1_2_5_AP,        --  AP=Y - FITTIZIA PER NYA
                  SOL_TRACK_1_1_1_1_2_5,
                  SOL_TRACK_1_1_1_1_2_6_AP,        --  AP=Y - FITTIZIA PER NYA
                  SOL_TRACK_1_1_1_1_2_6,
                  SOL_TRACK_1_1_1_1_2_7_AP,        --  AP=Y - FITTIZIA PER NYA
                  SOL_TRACK_1_1_1_1_2_7,
                  SOL_TRACK_1_1_1_1_2_8_AP,        --  AP=Y - FITTIZIA PER NYA
                  SOL_TRACK_1_1_1_1_2_8,
                  SOL_TRACK_1_1_1_1_3_1_AP,        --  AP=Y - FITTIZIA PER NYA
                  SOL_TRACK_1_1_1_1_3_1,
                  SOL_TRACK_1_1_1_1_3_2_AP,         --0.82 AGOSTO
                  SOL_TRACK_1_1_1_1_3_2,
                  SOL_TRACK_1_1_1_1_3_3_AP,         --errata su AG 0.82 AGOSTO
                  SOL_TRACK_1_1_1_1_3_3,
                  SOL_TRACK_1_1_1_1_3_4_AP,          --
--                  SOL_TRACK_1_1_1_1_3_4,             ----IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO
                  SOL_TRACK_1_1_1_1_3_5_AP,          --
--                  SOL_TRACK_1_1_1_1_3_5,             ----IN TABELLA A PARTE: VALORE MULTIPLO 0.82 AGOSTO
