           From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL  a,
                (Select Distinct t.SEDE_TECNICA,
                                 Listagg(  'FL ' || To_Char(f.FASCICOLO_LINEA), ', ')  Within Group (Order By t.SEDE_TECNICA) as FASCICOLO
                            From RINF_CONTROLLATI_EVO.FASCICOLO_SOL t,
                                 RINF_ANAGRAFICHE_EVO.ANAG_FASCICOLO_LINEE f,
                                 RINF_ANAGRAFICHE_EVO.ANAG_CONTESTO_GEO c
                           Where c.codice_contesto = 10
                             And f.CODICE_FASCICOLO = t.CODICE_FASCICOLO
                             And FLAG_DISPARI = 1
                        group by t.SEDE_TECNICA)  b
          where a.SEDE_TECNICA = b.SEDE_TECNICA (+)
            And a.SEDE_TECNICA = p_Sede_Tecnica;
--
   EXCEPTION
      When OTHERS  Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0,
            'SetNEWSoLHierarchyTrack - Elaborazione controlli. Codice Controllo: '|| p_controllo||' - Codice Errore: ' ||SQLCODE||' - '||SQLERRM,
                                        Null, p_errlog);
         Dbms_Output.Put_Line ('SetNEWSoLHierarchyTrack - Errore: ' || Substr(SQLERRM, 1, 300));
 END SetNEWSoLHierarchyTrack;
