                     Null   SOL_TRACK_1_1_1_3_3_3_3,
                     'N'    SOL_TRACK_1_1_1_3_3_4_AP,
                     Null   SOL_TRACK_1_1_1_3_3_4,
                     'N'    SOL_TRACK_1_1_1_3_3_5_AP,
                     'N'    SOL_TRACK_1_1_1_3_3_6_AP,
                     Null   SOL_TRACK_1_1_1_3_3_6,
                     'N'    SOL_TRACK_1_1_1_3_3_7_AP,
                     Null   SOL_TRACK_1_1_1_3_3_7,
                     'N'    SOL_TRACK_1_1_1_3_3_8_AP,
                     Null   SOL_TRACK_1_1_1_3_3_8,
                     'N'    SOL_TRACK_1_1_1_3_3_9_AP,
                     'N'    SOL_TRACK_1_1_1_3_3_10_AP,
                     'N'    SOL_TRACK_1_1_1_3_5_3_AP,
                     'N'    SOL_TRACK_1_1_1_3_7_1_1_AP,
                     Null   SOL_TRACK_1_1_1_3_7_1_1,
                     'N'    SOL_TRACK_1_1_1_3_7_1_2_AP,
                     Null   SOL_TRACK_1_1_1_3_7_1_2,
                     'N'    SOL_TRACK_1_1_1_3_7_1_3_AP,
                     'N'    SOL_TRACK_1_1_1_3_7_1_4_AP,
                     Null   SOL_TRACK_1_1_1_3_7_1_4,
                     'N'    SOL_TRACK_1_1_1_3_11_1_AP,
                     'N'    SOL_TRACK_1_1_1_3_11_2_AP,
                     Null   SOL_TRACK_1_1_1_3_11_2,
                     'N'    SOL_TRACK_1_1_1_3_11_3_AP ,
                     Null   SOL_TRACK_1_1_1_3_11_3	,
/* modifica del 25/05/2021 su indicazione di V. Autiero
                     Nvl2(SOL_TRACK_1_1_1_4_1, SOL_TRACK_1_1_1_4_1_AP, 'NYA') SOL_TRACK_1_1_1_4_1_AP,
                            SOL_TRACK_1_1_1_4_1,                      
                     Nvl2(SOL_TRACK_1_1_1_4_1,  SOL_TRACK_1_1_1_4_2_AP, 'NYA') SOL_TRACK_1_1_1_4_2_AP
*/
                     'N'  SOL_TRACK_1_1_1_4_1_AP,        
                     Null SOL_TRACK_1_1_1_4_1,
                     'N'  SOL_TRACK_1_1_1_4_2_AP      
             From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL
            Where SEDE_TECNICA = p_Sede_Tecnica;
