-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SetNEWSoLHierarchy
-- ------------------------------------------------------------------------------------------------
--
 Procedure SetNEWSoLHierarchy (p_Sede_Tecnica   In   Varchar2,
                               p_controllo      In   Number,
                               p_error          Out  Number )   Is
      s_tipo_tratta Varchar2(1);
  BEGIN
      p_error := 0;
--
      Select SOL_1_1_0_0_0_6 Into s_tipo_tratta 
	   From  Rinf_Controllati_Evo.SEZIONI_LINEA
       Where SEDE_TECNICA = p_Sede_Tecnica;
--
--  Se una tratta è di tipo Link vengono caricati solo i binari con due parametri e tutti gli altri a AP = N
--  N.B: Se le SoL sono di tipologia “Link” tutti i parametri di binario sono “NON APPLICABILI”
      If s_tipo_tratta = 'L' Then
--	  
         SetNEWSoLHierarchyTrackLink (p_Sede_Tecnica, p_controllo, p_error);
--
      Else

-- --------------------------------------------------------------------------------------
-- Binari Corsa
-- --------------------------------------------------------------------------------------
--
         SetNEWSoLHierarchyTrack (p_Sede_Tecnica, p_controllo, p_error);
--
-- --------------------------------------------------------------------------------------
-- Dichiarazioni Binari Corsa - DICHIARAZIONI_BINARIO_SOL_INF
-- --------------------------------------------------------------------------------------
--
        begin
         Insert Into Rinf_Controllati_Evo.DICHIARAZIONI_BINARIO_SOL_INF
                   ( SOL_TRACK_1_1_1_0_0_1,
                     TIPO_DICHIARAZIONE,
                     SOL_TRACK_1_1_1_1_1_1O2_AP,
                     SOL_TRACK_1_1_1_1_1_1O2,
                     KM_INIZIO,
                     KM_FINE,
                     LATITUDINE_INIZIO,
                     LONGITUDINE_INIZIO,
                     LATITUDINE_FINE,
                     LONGITUDINE_FINE,
                     FLAG_CALCOLATO	)
             Select SOL_TRACK_1_1_1_0_0_1,
                     TIPO_DICHIARAZIONE,
                     Case When TIPO_DICHIARAZIONE = 'EC'  
					      Then Decode(GetNYA(p_controllo, '1.1.1.1.1.1', SOL_TRACK_1_1_1_0_0_1), 1, 'NYA', SOL_TRACK_1_1_1_1_1_1O2_AP)
                          Else Decode(GetNYA(p_controllo, '1.1.1.1.1.2', SOL_TRACK_1_1_1_0_0_1), 1, 'NYA', SOL_TRACK_1_1_1_1_1_1O2_AP)
                     End SOL_TRACK_1_1_1_1_1_1O2_AP,
                     SOL_TRACK_1_1_1_1_1_1O2,
                     KM_INIZIO,
                     KM_FINE,
                     LATITUDINE_INIZIO,
                     LONGITUDINE_INIZIO,
                     LATITUDINE_FINE,
                     LONGITUDINE_FINE,
                     FLAG_CALCOLATO
                From Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_SOL_INF
               Where SOL_TRACK_1_1_1_0_0_1 In
                   (Select SOL_TRACK_1_1_1_0_0_1
                      From Rinf_Controllati_Evo.BINARI_CORSA_SOL
                     Where SEDE_TECNICA = p_Sede_Tecnica	);
 Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.DICHIARAZIONI_BINARIO_SOL_INF: ' || Substr (Sqlerrm, 1, 300));
    End;

--
-- --------------------------------------------------------------------------------------
-- Dichiarazioni Binari Corsa - DICHIARAZIONI_BINARIO_SOL_ENE
-- --------------------------------------------------------------------------------------
--
  begin 
         Insert Into Rinf_Controllati_Evo.DICHIARAZIONI_BINARIO_SOL_ENE 
		           ( SOL_TRACK_1_1_1_0_0_1,
                     TIPO_DICHIARAZIONE,
                     SOL_TRACK_1_1_1_2_1_1O2_AP,
                     SOL_TRACK_1_1_1_2_1_1O2,
                     KM_INIZIO,
                     KM_FINE,
                     LATITUDINE_INIZIO,
                     LONGITUDINE_INIZIO,
                     LATITUDINE_FINE,
                     LONGITUDINE_FINE,
                     FLAG_CALCOLATO )
             Select SOL_TRACK_1_1_1_0_0_1,
                    TIPO_DICHIARAZIONE,
                    Case When TIPO_DICHIARAZIONE = 'EC' Then  
					          Decode(GetNYA(p_controllo, '1.1.1.2.1.1', SOL_TRACK_1_1_1_0_0_1), 1, 'NYA', SOL_TRACK_1_1_1_2_1_1O2_AP)
                         Else Decode(GetNYA(p_controllo, '1.1.1.2.1.2', SOL_TRACK_1_1_1_0_0_1), 1, 'NYA', SOL_TRACK_1_1_1_2_1_1O2_AP)
                    End SOL_TRACK_1_1_1_2_1_1O2_AP,
                    SOL_TRACK_1_1_1_2_1_1O2,
                    KM_INIZIO,
                    KM_FINE,
                    LATITUDINE_INIZIO,
                    LONGITUDINE_INIZIO,
                    LATITUDINE_FINE,
                    LONGITUDINE_FINE,
                    FLAG_CALCOLATO
               From Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_SOL_ENE
              Where SOL_TRACK_1_1_1_0_0_1 In
                   (Select SOL_TRACK_1_1_1_0_0_1
                      From Rinf_Controllati_Evo.BINARI_CORSA_SOL
                     Where SEDE_TECNICA = p_Sede_Tecnica   );
 Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.DICHIARAZIONI_BINARIO_SOL_ENE: ' || Substr (Sqlerrm, 1, 300));
    End;

