-- Dichiarazioni Binari Corsa - DICHIARAZIONI_BINARIO_SOL_CCS
-- --------------------------------------------------------------------------------------
--
  begin 
         Insert Into Rinf_Controllati_Evo.DICHIARAZIONI_BINARIO_SOL_CCS 
		           ( SOL_TRACK_1_1_1_0_0_1,
                     TIPO_DICHIARAZIONE,
