-- Gallerie - GALLERIE_BINARI_SOL
-- 24/03/2015 Aggiorno i dati delle gallerie già presenti
-- --------------------------------------------------------------------------------------
--
  begin 
         Update Rinf_Controllati_Evo.GALLERIE_BINARI_SOL  e
                  Set ( SOL_TUNNEL_1_1_1_1_8_2_D,
                        SOL_TUNNEL_1_1_1_1_8_3_AP,             --  AP=Y - Fittizia Per NYA
                        SOL_TUNNEL_1_1_1_1_8_3,
                        SOL_TUNNEL_1_1_1_1_8_4_AP,             --  AP=Y - Fittizia Per NYA
                        SOL_TUNNEL_1_1_1_1_8_4,
                        SOL_TUNNEL_1_1_1_1_8_7_AP,             --  Ricontrollare 0.82 Agosto
                        SOL_TUNNEL_1_1_1_1_8_7,
                        SOL_TUNNEL_1_1_1_1_8_8_AP,             --  Modificata con il Reg.2019/777
                        SOL_TUNNEL_1_1_1_1_8_8,
                        SOL_TUNNEL_1_1_1_1_8_9_AP,             
                        SOL_TUNNEL_1_1_1_1_8_9,
                        SOL_TUNNEL_1_1_1_1_8_10_AP,
                        SOL_TUNNEL_1_1_1_1_8_10,
                        SOL_TUNNEL_1_1_1_1_8_11_AP,
                        SOL_TUNNEL_1_1_1_1_8_11,
                        SOL_TUNNEL_1_1_1_1_8_8_1_AP,
                        SOL_TUNNEL_1_1_1_1_8_8_1,              --   Nuovo parametro REg.2019/777
                        SOL_TUNNEL_1_1_1_1_8_8_2_AP,           --  [AP=N]
                        SOL_TUNNEL_1_1_1_1_8_8_2               --   Nuovo parametro REg.2019/777 
					  ) =
               (  Select
                        SOL_TUNNEL_1_1_1_1_8_2_D,
                        Decode(GetNYA(p_controllo, '1.1.1.1.8.3', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', 'Y') SOL_TUNNEL_1_1_1_1_8_3_AP,      --  AP=Y - Fittizia Per NYA
                        SOL_TUNNEL_1_1_1_1_8_3,
                        Decode(GetNYA(p_controllo, '1.1.1.1.8.4', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', 'Y') SOL_TUNNEL_1_1_1_1_8_4_AP,       --  AP=Y - Fittizia Per NYA
                        SOL_TUNNEL_1_1_1_1_8_4,
                        Decode(GetNYA(p_controllo, '1.1.1.1.8.7', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', 'Y') SOL_TUNNEL_1_1_1_1_8_7_AP,       --RICONTROLLARE 0.82 AGOSTO
                        SOL_TUNNEL_1_1_1_1_8_7,
--->                        Decode(GetNYA(p_controllo, '1.1.1.1.8.8', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_8_AP) SOL_TUNNEL_1_1_1_1_8_8_AP,       --  AP=Y - Fittizia Per NYA
                        SOL_TUNNEL_1_1_1_1_8_8_AP,       --  AP=Y - Fittizia Per NYA
                        SOL_TUNNEL_1_1_1_1_8_8,
                        Decode(GetNYA(p_controllo, '1.1.1.1.8.9', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_9_AP) SOL_TUNNEL_1_1_1_1_8_9_AP,       --  AP=Y - Fittizia Per NYA
                        SOL_TUNNEL_1_1_1_1_8_9,
                        Decode(GetNYA(p_controllo, '1.1.1.1.8.10', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_10_AP) SOL_TUNNEL_1_1_1_1_8_10_AP,
                        SOL_TUNNEL_1_1_1_1_8_10,
                        Decode(GetNYA(p_controllo, '1.1.1.1.8.11', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_11_AP ) SOL_TUNNEL_1_1_1_1_8_11_AP,
                        SOL_TUNNEL_1_1_1_1_8_11,
--->                        Decode(GetNYA(p_controllo, '1.1.1.1.8.8.1', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_8_1_AP ) SOL_TUNNEL_1_1_1_1_8_8_1_AP,
                        SOL_TUNNEL_1_1_1_1_8_8_1_AP,
                        SOL_TUNNEL_1_1_1_1_8_8_1,
                        Decode(GetNYA(p_controllo, '1.1.1.1.8.8.2', SOL_TUNNEL_1_1_1_1_8_2), 1, 'N', SOL_TUNNEL_1_1_1_1_8_8_2_AP ) SOL_TUNNEL_1_1_1_1_8_8_2_AP,
                        SOL_TUNNEL_1_1_1_1_8_8_2
                   From Rinf_Lavorazione_Evo.GALLERIE_BINARI_SOL  i
                  Where e.SOL_TUNNEL_1_1_1_1_8_2 = i.SOL_TUNNEL_1_1_1_1_8_2
	            )
                Where SOL_TUNNEL_1_1_1_1_8_2 In
            (Select g.SOL_TUNNEL_1_1_1_1_8_2
              From Rinf_Controllati_Evo.GALLERIE_BINARI_SOL g,
--                   Rinf_Controllati_Evo.REL_GALLERIE_BINARI_SOL bg,              questa tabella ha il record relativo al tunnel in esame cancellato
                   Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL bg,
                   Rinf_Controllati_Evo.BINARI_CORSA_SOL b
             Where g.SOL_TUNNEL_1_1_1_1_8_2 = bg.SOL_TUNNEL_1_1_1_1_8_2
               And bg.SOL_TRACK_1_1_1_0_0_1 = b.SOL_TRACK_1_1_1_0_0_1
               And b.SEDE_TECNICA = p_Sede_Tecnica
	         );
--
 Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore aggiornamento Rinf_Controllati_Evo.GALLERIE_BINARI_SOL: ' || Substr (Sqlerrm, 1, 300));
    End;
