                      SOL_TUNNEL_1_1_1_1_8_3,
                      Decode(GetNYA(p_controllo, '1.1.1.1.8.4', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', 'Y') SOL_TUNNEL_1_1_1_1_8_4_AP,             --  AP=Y - FITTIZIA PER NYA
                      SOL_TUNNEL_1_1_1_1_8_4,
                      Decode(GetNYA(p_controllo, '1.1.1.1.8.7', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', 'Y') SOL_TUNNEL_1_1_1_1_8_7_AP,             --RICONTROLLARE 0.82 AGOSTO
                      SOL_TUNNEL_1_1_1_1_8_7,
