                      SOL_TUNNEL_1_1_1_1_8_8_AP,             --  AP=Y - FITTIZIA PER NYA
                      SOL_TUNNEL_1_1_1_1_8_8,
                      Decode(GetNYA(p_controllo, '1.1.1.1.8.9', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_9_AP) SOL_TUNNEL_1_1_1_1_8_9_AP,             --  AP=Y - FITTIZIA PER NYA
                      SOL_TUNNEL_1_1_1_1_8_9,
                      Decode(GetNYA(p_controllo, '1.1.1.1.8.10', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_10_AP) SOL_TUNNEL_1_1_1_1_8_10_AP,
                      SOL_TUNNEL_1_1_1_1_8_10,
                      Decode(GetNYA(p_controllo, '1.1.1.1.8.11', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_11_AP) SOL_TUNNEL_1_1_1_1_8_11_AP,
                      SOL_TUNNEL_1_1_1_1_8_11,
