                           Rinf_Controllati_Evo.BINARI_CORSA_SOL b
                     Where g.SOL_TUNNEL_1_1_1_1_8_2 = bg.SOL_TUNNEL_1_1_1_1_8_2
                       And bg.SOL_TRACK_1_1_1_0_0_1 = b.SOL_TRACK_1_1_1_0_0_1
                       And b.SEDE_TECNICA = p_Sede_Tecnica
                   Minus
                     Select SOL_TUNNEL_1_1_1_1_8_2 From  Rinf_Controllati_Evo.GALLERIE_BINARI_SOL  );
  Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.GALLERIE_BINARI_SOL: ' || Substr (Sqlerrm, 1, 300));
