-- --------------------------------------------------------------------------------------
-- Dichiarazione Gallerie - DICHIARAZIONI_GALLERIE_BIN_SOL
-- 24/03/2015 Aggiorno le dichiarazioni già presenti 
-- --------------------------------------------------------------------------------------
--
  begin 
         Update Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_BIN_SOL e
            Set ( SOL_TUNNEL_1_1_1_1_8_5O6_AP, 
			      KM_FINE,LATITUDINE_INIZIO, 
				  LONGITUDINE_INIZIO, 
				  LATITUDINE_FINE, 
				  LONGITUDINE_FINE, 
				  FLAG_CALCOLATO
				 ) =
         (Select Case When TIPO_DICHIARAZIONE = 'EC' 
				      Then Decode(GetNYA(p_controllo, '1.1.1.1.8.5', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_5O6_AP)
                      Else Decode(GetNYA(p_controllo, '1.1.1.1.8.6', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_5O6_AP)
                  End SOL_TUNNEL_1_1_1_1_8_5O6_AP,
                      KM_FINE,
                      LATITUDINE_INIZIO,
                      LONGITUDINE_INIZIO,
                      LATITUDINE_FINE,
                      LONGITUDINE_FINE,
                      FLAG_CALCOLATO
                 From Rinf_Lavorazione_Evo.DICHIARAZIONI_GALLERIE_BIN_SOL i
                Where e.SOL_TUNNEL_1_1_1_1_8_2 = i.SOL_TUNNEL_1_1_1_1_8_2 
		          And e.TIPO_DICHIARAZIONE = i.TIPO_DICHIARAZIONE 
			      And e.SOL_TUNNEL_1_1_1_1_8_5O6 = i.SOL_TUNNEL_1_1_1_1_8_5O6 
			      And e.KM_INIZIO = i.KM_INIZIO
			)
           Where (SOL_TUNNEL_1_1_1_1_8_2,   TIPO_DICHIARAZIONE,   SOL_TUNNEL_1_1_1_1_8_5O6,   KM_INIZIO ) In
        (Select g.SOL_TUNNEL_1_1_1_1_8_2, g.TIPO_DICHIARAZIONE, g.SOL_TUNNEL_1_1_1_1_8_5O6, g.KM_INIZIO
           From Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_BIN_SOL g,
                Rinf_Controllati_Evo.REL_GALLERIE_BINARI_SOL bg,
                Rinf_Controllati_Evo.BINARI_CORSA_SOL b
          Where g.SOL_TUNNEL_1_1_1_1_8_2 = bg.SOL_TUNNEL_1_1_1_1_8_2
            And bg.SOL_TRACK_1_1_1_0_0_1 = b.SOL_TRACK_1_1_1_0_0_1
            And b.SEDE_TECNICA = p_Sede_Tecnica
		 );
--
 Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore aggiornamento Rinf_Controllati_Evo.DICHIARAZIONI_GALLERIE_BIN_SOL: ' || Substr (Sqlerrm, 1, 300));
    End;

