		          ( SOL_TUNNEL_1_1_1_1_8_2, SOL_TRACK_1_1_1_0_0_1, SOL_TUNNEL_1_1_1_1_8_8_AP, SOL_TUNNEL_1_1_1_1_8_8_1_AP )
             Select SOL_TUNNEL_1_1_1_1_8_2, 
			        SOL_TRACK_1_1_1_0_0_1, 
--			        Decode(GetNYA(p_controllo, '1.1.1.1.8.8', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_8_AP) SOL_TUNNEL_1_1_1_1_8_8_AP, 
--			        Decode(GetNYA(p_controllo, '1.1.1.1.8.8.1', SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_8_1_AP) SOL_TUNNEL_1_1_1_1_8_8_1_AP 
        Decode(GetNYA_tunnel(p_controllo, '1.1.1.1.8.8',   substr(SOL_TRACK_1_1_1_0_0_1, 1, 6), SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_8_AP) SOL_TUNNEL_1_1_1_1_8_8_AP, 
        Decode(GetNYA_tunnel(p_controllo, '1.1.1.1.8.8.1', substr(SOL_TRACK_1_1_1_0_0_1, 1 ,6), SOL_TUNNEL_1_1_1_1_8_2), 1, 'NYA', SOL_TUNNEL_1_1_1_1_8_8_1_AP) SOL_TUNNEL_1_1_1_1_8_8_1_AP 
              From  Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL
              Where SOL_TRACK_1_1_1_0_0_1 In
            (Select SOL_TRACK_1_1_1_0_0_1
               From Rinf_Controllati_Evo.BINARI_CORSA_SOL
              Where SEDE_TECNICA = p_Sede_Tecnica 	 );

--
 Exception
     When Others Then
           Dbms_Output.Put_Line ('Errore inserimento Rinf_Controllati_Evo.REL_GALLERIE_BINARI_SOL: ' || Substr (Sqlerrm, 1, 300));
    End;
