--  
--
-- ------------------------------------------------------------------------------------------------   
--                                PROCEDURE SetDeleteOLDObject
--   Eliminazione delle SOL e OP che hanno cambiato stato, non sono piu' In "CREA-ESER"
--   Sono gli oggetti contenuti In Rinf_Staging_Evo.CLASSE_ELIMINATI
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetDeleteOLDObject (p_codice_controllo   In   Number,
                                p_error              Out  Number )  Is
  Type dtp_ogg_rt Is Record
      (
         id_sol_op            Varchar2 (6),
         definizione          Varchar2(100),
         stato_sistema_n      Varchar2 (50),
         stato_utente_n       Varchar2 (50),
         stato_sistema_o      Varchar2 (50),
         stato_utente_o       Varchar2 (50),
         codice_controllo_o   Number,
         codice_dtp           Varchar2(10),
         codice_linea_tecnica Varchar2(10)
      );
  Type l_SEDE_TECNICA Is Table Of dtp_ogg_rt;
       l_dtp_ogg  l_SEDE_TECNICA;
--	   
  BEGIN
  p_error:=0;
--
  Select distinct
         e.SEDE_TECNICA, 
         s.DEFINIZIONE, 
		 e.STATO_SISTEMA, 
		 e.STATO_UTENTE, 
		 s.STATO_SISTEMA,
         s.STATO_UTENTE, 
		 s.CODICE_CONTROLLO, 
		 s.CODICE_DTP, 
		 s.CODICE_LINEA_TECNICA
    Bulk Collect Into l_dtp_ogg
    From Rinf_Staging_Evo.CLASSE_ELIMINATI e,
         Rinf_Controllati_Evo.SEZIONI_LINEA s
   Where s.SEDE_TECNICA = e.SEDE_TECNICA
---
   Union 
 Select distinct
         e.SEDE_TECNICA, 
         s.DEFINIZIONE, 
		 e.STATO_SISTEMA, 
		 e.STATO_UTENTE, 
		 s.STATO_SISTEMA,
         s.STATO_UTENTE, 
		 s.CODICE_CONTROLLO, 
		 s.CODICE_DTP, 
		 s.CODICE_LINEA_TECNICA
	From Rinf_Anagrafiche_Evo.REGISTRO_SEDI_ELIMINATE_NUOVE e,
	     Rinf_Controllati_Evo.SEZIONI_LINEA s
   Where s.SEDE_TECNICA = e.SEDE_TECNICA
	 And e.CODICE_VERSIONE = (select max(CODICE_VERSIONE) from Rinf_Pubblicati_evo.VERSIONE_RINF)
	 And e.FLAG_TIPO = -1 
	 And e.FLAG_STATO_FINALE = 0;  
--
    For i In 1 .. l_dtp_ogg.Count   Loop 
--> ciclo sulle soL eliminate 
        SetOLDSOLClear (l_dtp_ogg(i).ID_SOL_OP, p_error);
--
        If p_error = 0 Then
             Delete From  Rinf_Controllati_Evo.SEZIONI_LINEA Where SEDE_TECNICA = l_dtp_ogg(i).ID_SOL_OP;
--
             Insert Into Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI
                 ( CODICE_CONTROLLO, 
				   CODICE_SOL_PO, 
				   CODICE_DTP, 
				   CODICE_LINEA_TECNICA )
           Values (p_codice_controllo, 
		           l_dtp_ogg(i).ID_SOL_OP, 
		           l_dtp_ogg(i).CODICE_DTP, 
		           l_dtp_ogg(i).CODICE_LINEA_TECNICA );
--
         PKG_RINF_CONTROLLO_PAR_V082.SetControlDetails
		        (p_codice_controllo,
                 l_dtp_ogg(i).ID_SOL_OP,
                 l_dtp_ogg(i).ID_SOL_OP,
                 4,  --Mancando il codice SOL, abbiamo utilizzato il primo numero parametro utile (località di inizio tratta)
                 l_dtp_ogg(i).DEFINIZIONE,
                 0,                       --1, esito da "Positivo" a "Negativo"  del 2024/06
                 11,
                 'La Sezione di Linea è stata eliminata dal momento che non è più In esercizio ',
                 l_dtp_ogg(i).STATO_SISTEMA_N||' '||l_dtp_ogg(i).STATO_UTENTE_N ,
                 l_dtp_ogg(i).STATO_SISTEMA_O||' '||l_dtp_ogg(i).STATO_UTENTE_O,
                 l_dtp_ogg(i).CODICE_CONTROLLO_O, 0 );
        End If;
--> fine ciclo sulle SoL
    End Loop ;
--
   Select distinct
          e.SEDE_TECNICA, 
          s.DEFINIZIONE, 
		  e.STATO_SISTEMA, 
		  e.STATO_UTENTE,
          s.STATO_SISTEMA, 
		  s.STATO_UTENTE, 
		  s.CODICE_CONTROLLO, 
		  s.CODICE_DTP, 
		  s.CODICE_LINEA_TECNICA
     Bulk Collect Into l_dtp_ogg
     From Rinf_Staging_Evo.CLASSE_ELIMINATI e,
          Rinf_Controllati_Evo.PUNTI_OPERATIVI s
    Where s.SEDE_TECNICA = e.SEDE_TECNICA 
	  And e.SEDE_TECNICA In
    (Select SEDE_TECNICA From Rinf_Staging_Evo.CLASSE_ELIMINATI
      Minus
       (Select localita_inizio From Rinf_Controllati_Evo.SEZIONI_LINEA
          Union
        Select localita_fine From Rinf_Controllati_Evo.SEZIONI_LINEA
	    )
    )
	    Union 
 Select distinct
         e.SEDE_TECNICA, 
         s.DEFINIZIONE, 
		 e.STATO_SISTEMA, 
		 e.STATO_UTENTE, 
		 s.STATO_SISTEMA,
         s.STATO_UTENTE, 
		 s.CODICE_CONTROLLO, 
		 s.CODICE_DTP, 
		 s.CODICE_LINEA_TECNICA
	From Rinf_anagrafiche_evo.REGISTRO_SEDI_ELIMINATE_NUOVE e,
	     Rinf_Controllati_Evo.PUNTI_OPERATIVI s
   Where s.SEDE_TECNICA = e.SEDE_TECNICA
	 And e.CODICE_VERSIONE = (select max(codice_versione) from Rinf_Pubblicati_evo.VERSIONE_RINF)
	 And e.FLAG_TIPO = -1 
	 And e.FLAG_STATO_FINALE = 0
	  And e.SEDE_TECNICA Not In
       (Select localita_inizio From Rinf_Controllati_Evo.SEZIONI_LINEA
          Union
        Select localita_fine From Rinf_Controllati_Evo.SEZIONI_LINEA
	    ) ;

--->
--
    For i In 1 .. l_dtp_ogg.COUNT   Loop 
--
--> ciclo sui PO da eliminare
--
        SetOLDOPClear (l_dtp_ogg(i).ID_SOL_OP, p_error);
--		
        If p_error = 0 Then
             Delete From  Rinf_Controllati_Evo.PUNTI_OPERATIVI Where SEDE_TECNICA = l_dtp_ogg (i).ID_SOL_OP;
--
             Insert Into Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI
                        (CODICE_CONTROLLO, 
						 CODICE_SOL_PO,
						 CODICE_DTP, 
						 CODICE_LINEA_TECNICA)
                 Values (p_codice_controllo, 
				         l_dtp_ogg(i).ID_SOL_OP, 
						 l_dtp_ogg(i).CODICE_DTP, 
						 l_dtp_ogg(i).CODICE_LINEA_TECNICA );
--
              PKG_RINF_CONTROLLO_PAR_V082.SetControlDetails
		       ( p_codice_controllo,
                 l_dtp_ogg(i).ID_SOL_OP,
                 l_dtp_ogg(i).ID_SOL_OP,
                 215,                          -- abbiamo utilizzato il primo numero parametro utile (codice località)
                 l_dtp_ogg(i).DEFINIZIONE,
                 0,                       --1, esito da "Positivo" a "Negativo"  del 2024/06
				 11,
                 'Il Punto Operativo è stato eliminato dal momento che non è più In esercizio ',
                 l_dtp_ogg(i).STATO_SISTEMA_N||' '||l_dtp_ogg(i).STATO_UTENTE_N ,
                 l_dtp_ogg(i).STATO_SISTEMA_O||' '||l_dtp_ogg(i).STATO_UTENTE_O,
                 l_dtp_ogg(i).CODICE_CONTROLLO_O ,
				 0 );
--
        End If;
--> fine ciclo sui PO
     End Loop ;
--
  EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG ( 0, 'SetDeleteOLDObject - Elaborazione controlli. Codice Controllo: '
                                         || p_codice_controllo||' - Codice Errore: ' ||SQLCODE||' - '||SQLERRM,  Null, p_errlog);
  END SetDeleteOLDObject;
--  
-- ------------------------------------------------------------------------------------------------   
--                                PROCEDURE SetNEWControlOP
-- ------------------------------------------------------------------------------------------------   
--
  Procedure SetNEWControlOP (p_codice_controllo   In  Number,
                             p_error              Out Number )   Is
      TYPE dtp_ogg_rt IS RECORD
         ( id_sol_op    Varchar2 (6),
           id_stato     Varchar2 (2) );
      TYPE dtp_ogg_t IS TABLE OF dtp_ogg_rt;
           l_dtp_ogg   dtp_ogg_t;
   BEGIN
      p_error := 0;
--
      Pkg_Rinf_Utility.SETPROCESSSTATUS 
	  (  v_trans,
         'Inizio pubblicazione dei Punti Operativi che hanno superato i controlli',
         8,
         14,
         0,
         1,
         1,
         0  );
--
      Select SEDE_TECNICA, STATO
        Bulk Collect Into l_dtp_ogg
        From ( (Select  CODICE_SOL_PO SEDE_TECNICA, 'UP' stato
                  From  Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI
                 Where  CODICE_CONTROLLO = p_codice_controllo
                   And  CODICE_SOL_PO Like 'LO%'
                   And  CODICE_ESITO = 1
                Intersect
                Select SEDE_TECNICA, 'UP'
                  From  Rinf_Controllati_Evo.PUNTI_OPERATIVI
				)
             Union
               (Select  CODICE_SOL_PO SEDE_TECNICA, 'IN' stato
                  From  Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI
                 Where  CODICE_CONTROLLO = p_codice_controllo
                   And  CODICE_SOL_PO Like 'LO%'
                   And  CODICE_ESITO = 1
               Minus
                (Select SEDE_TECNICA, 'IN'
                  From  Rinf_Controllati_Evo.PUNTI_OPERATIVI
                Union
                 Select SEDE_TECNICA, 'IN' 
			      From  Rinf_Staging_Evo.CLASSE_ELIMINATI
				 )
				)
			 );

      Pkg_Rinf_Utility.SETPROCESSSTATUS 
       ( v_trans,
         'Eliminazione dei dati dei Punti Operativi già presenti nell''area dei controllati',
         9,
         14,
         1,
         l_dtp_ogg.COUNT,
         1,
         0 );
      Pkg_Rinf_Utility.SETPROCESSSTATUS 
        (v_trans,
         'Pubblicazione nell''area dei controllati dei nuovi dati dei Punti Operativi che hanno superato i controlli',
         10,
         14,
         1,
         l_dtp_ogg.COUNT,
         1,
         0);
--
      For i In 1 .. l_dtp_ogg.COUNT Loop 
--
         If l_dtp_ogg (i).id_stato = 'UP' Then
                Pkg_Rinf_Utility.SETPROCESSSTATUS 
                 ( v_trans,
                   'Eliminazione dei dati dei Punti Operativi già presenti nell''area dei controllati',
                   9,
                   14,
                   i,
                   l_dtp_ogg.COUNT,
                   1,
                   1 );
--             
                SetOLDOPClear (l_dtp_ogg(i).ID_SOL_OP, p_error);
--             
                SetOLDOPUpdate (l_dtp_ogg(i).ID_SOL_OP, p_codice_controllo, p_error);
--			
         Else
               SetNEWOP (l_dtp_ogg(i).ID_SOL_OP, p_codice_controllo, p_error);
         End If;
--
         SetOPGeographicArea (l_dtp_ogg(i).ID_SOL_OP, p_error);
--		 
         If getLinkObject (l_dtp_ogg(i).ID_SOL_OP) = 0 Then
                Pkg_Rinf_Utility.SETPROCESSSTATUS 
                 ( v_trans,
                   'Pubblicazione nell''area dei controllati dei nuovi dati dei Punti Operativi che hanno superato i controlli',
                   10,
                   14,
                   i,
                   l_dtp_ogg.COUNT,
                   1,
                   1 );
--
            SetNEWOPHierarchy (l_dtp_ogg(i).ID_SOL_OP, p_codice_controllo, p_error);
         End If;
--
      End Loop ;
--
-- ------------------------------------------------------------------------------------------------   
-- Il caricamento dei marciapiedi è stato estrapolato dal caricamento della gerarchie per singola tratta.
-- Viene effettuato massivamente a valle e dopo una pulizia dei codici dei binari, per garantire l'integrità referenziale 
-- con l'anagrafica dei binari di corsa
-- ------------------------------------------------------------------------------------------------   
--
   SetOPHierarchyPlat(p_codice_controllo,p_error);
--
  EXCEPTION
      When OTHERS  Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0,  'SetNEWControlOP. - Elaborazione controlli. Codice Controllo: '
                                  || p_codice_controllo||' - Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null, p_errlog);
         Dbms_Output.Put_Line ('Errore: ' || Substr (SQLERRM, 1, 300));
 END SetNEWControlOP;
--
-- ------------------------------------------------------------------------------------------------   
--                       PROCEDURE SetChangeOPResult
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetChangeOPResult (p_codice_controllo   In  Number,
                             p_error              Out  Number )  Is
   TYPE dtp_ogg_rt IS RECORD
   ( SEDE_TECNICA   Varchar2(6),
     conta_ogg      Number  );
   TYPE l_SEDE_TECNICA IS TABLE OF dtp_ogg_rt;
        l_dtp_ogg      l_SEDE_TECNICA;
--
   TYPE l_Tratte_Inc_rt IS RECORD
   (
      SEDE_TECNICA   Varchar2 (6),
      definizione    Varchar2 (200)
   );
   TYPE l_Tratte IS TABLE OF l_Tratte_Inc_rt;
        l_Tratte_Inc   l_Tratte;
--
   n_contalinea   Number;
--
 BEGIN
     --25/09/2015
     --Ci possono essere dei parametri delle OP, che sebbene corretti, non siano coerenti con i ripsettivi parametri delle SOL incidenti le OP.
     --Uno di questi parametri è la linea commerciale.
     --Una OP deve avere almeno tutte le linee commerciali delle SOL incidenti.
     --Questo problema è emerso durante il processo di validazione della CUI per la località Novare FNM.
     --Le due tratte incidenti Novara FNM hanno linee commerciali C24, AV/AC3-AV/AC4. Novara FNM, non presente nelle nostre anagrafiche PIC,
     --ha la linea fittizia 0000. Il processo di validazione ha evidenziato questa anomalia, scartando il file xml.

-- CONTROLLO LINEA COMMERCIALE
     Select CODICE_LOCALITA, Count(linea)
       Bulk Collect Into l_dtp_ogg
       From ( 
	           (Select p.LOCALITA_INIZIO CODICE_LOCALITA, Replace(CODICE, ' ', '') linea
                 From (Select SEDE_TECNICA, CODICE
                         From Rinf_Lavorazione_Evo.V_MDR_LINEE_COMMERCIALI
                        Where CODICE_CONTESTO = 5
					   ) v,
                       Rinf_Lavorazione_Evo.SEZIONI_LINEA p,
                       Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI o
                 Where p.SEDE_TECNICA = v.SEDE_TECNICA
                   And CODICE_SOL_PO = p.SEDE_TECNICA
                   And CODICE_ESITO = 1
               Union
                Select p.LOCALITA_FINE, Replace(CODICE, ' ', '') linea
                 From (Select SEDE_TECNICA, CODICE
                         From Rinf_Lavorazione_Evo.V_MDR_LINEE_COMMERCIALI
                        Where CODICE_CONTESTO = 5
					   ) v,
                      Rinf_Lavorazione_Evo.SEZIONI_LINEA p,
                      Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI o
                Where p.SEDE_TECNICA = v.SEDE_TECNICA
                  And CODICE_SOL_PO = p.SEDE_TECNICA
                  And CODICE_ESITO = 1
			   )
             Minus
             (Select p.SEDE_TECNICA, Replace(CODICE, ' ', '') linea
                From (Select SEDE_TECNICA, CODICE
                        From  Rinf_Lavorazione_Evo.V_MDR_LINEE_COMMERCIALI
                       Where  CODICE_CONTESTO = 5
					  ) v,
                     Rinf_Lavorazione_Evo.PUNTI_OPERATIVI p,
                     Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI o
               Where p.SEDE_TECNICA = v.SEDE_TECNICA
                 And CODICE_SOL_PO = p.SEDE_TECNICA
                 And CODICE_ESITO = 1
				 )
		    ) linee_comm
   GROUP BY CODICE_LOCALITA;
--
   For i In 1 .. l_dtp_ogg.COUNT  Loop 
         Select SEDE_TECNICA, DEFINIZIONE
           Bulk Collect Into l_Tratte_Inc
           From Rinf_Lavorazione_Evo.SEZIONI_LINEA s,
                Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI o
          Where CODICE_SOL_PO = s.SEDE_TECNICA
            And CODICE_ESITO = 1
            And ( LOCALITA_INIZIO = l_dtp_ogg(i).SEDE_TECNICA  or  LOCALITA_FINE = l_dtp_ogg(i).SEDE_TECNICA);

      Loop 
          For j In 1 .. l_Tratte_Inc.COUNT  Loop 
--		 
            Select Count(linea)  Into n_contalinea
              From (Select Replace(CODICE, ' ', '') linea
                     From (Select SEDE_TECNICA, CODICE
                             From Rinf_Lavorazione_Evo.V_MDR_LINEE_COMMERCIALI
                            Where CODICE_CONTESTO = 5
						   ) v,
                           Rinf_Lavorazione_Evo.SEZIONI_LINEA p
                     Where p.SEDE_TECNICA = v.SEDE_TECNICA
                       And p.SEDE_TECNICA = l_Tratte_Inc(j).SEDE_TECNICA
                    Minus
                    (Select Replace(CODICE, ' ', '') linea
                       From (Select SEDE_TECNICA, CODICE
                               From Rinf_Lavorazione_Evo.V_MDR_LINEE_COMMERCIALI
                              Where  CODICE_CONTESTO = 5
							 ) v,
                            Rinf_Lavorazione_Evo.PUNTI_OPERATIVI p
                      Where p.SEDE_TECNICA = v.SEDE_TECNICA
                        And p.SEDE_TECNICA = l_dtp_ogg(i).SEDE_TECNICA)
					) linee_comm;
--
            If n_contalinea > 0  Then
--
                    Update Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI
                       Set CODICE_ESITO = 0
                     Where CODICE_CONTROLLO = p_codice_controllo
                       And CODICE_SOL_PO = l_Tratte_Inc(j).SEDE_TECNICA;
--                 
                    PKG_RINF_CONTROLLO_PAR_V082.SetControlDetails 
					(  p_codice_controllo,
                       l_Tratte_Inc(j).SEDE_TECNICA,
                       l_Tratte_Inc(j).SEDE_TECNICA,
                       2,                                          -- Parametro della linea commerciale
                       l_Tratte_Inc(j).DEFINIZIONE,
                       0,                                          -- Esito negativo
                       17,
                          'La Sezione di Linea ha superato tutti i controlli, ma non può essere validata perchè la località estrema '
                       || l_dtp_ogg(i).SEDE_TECNICA
                       || ' non contiene le linee commerciali della tratta',
                          'Linee commerciali non presenti nella località '
                       || l_dtp_ogg (i).SEDE_TECNICA,
                       Null,
                       Null,
                       0
					 );
            End If;
         End Loop ;
      End Loop ;
   End Loop ;
--
 END SetChangeOPResult;
--
-- ------------------------------------------------------------------------------------------------   
--                       PROCEDURE SetChangeSOLResult
--  questa procedura aggiorna l'esito di una tratta da positivo a negativo se la tratta  è positiva 
--  ma una delle località estreme è negativa e la località non è già presente nell'area controllati
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetChangeSOLResult (p_codice_controllo   In     Number,
                               p_error              Out    Number )   Is
    TYPE dtp_ogg_rt IS RECORD
      (  SEDE_TECNICA      Varchar2 (6),
         DEFINIZIONE       Varchar2(100),
         LOCALITA_INIZIO   Varchar2 (20),
         LOCALITA_FINE     Varchar2 (20)   );
    TYPE l_SEDE_TECNICA IS TABLE OF dtp_ogg_rt;
         l_dtp_ogg    l_SEDE_TECNICA;
 BEGIN
  p_error:=0;
  Dbms_Output.Put_Line ('Aggiorno stato tratte valide ma con località estreme non valide');
    --UPDATE Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI
    --SET CODICE_ESITO = 0
    --Where     CODICE_CONTROLLO = p_codice_controllo
    --AND CODICE_SOL_PO LIKE 'TR%'
    --AND CODICE_ESITO = 1
    --AND CODICE_SOL_PO IN
    --(
    --(Select SEDE_TECNICA From  Rinf_Lavorazione_Evo.SEZIONI_LINEA t,
    --Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI ct,
    --Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI ci
    --Where 
    --ct.CODICE_SOL_PO=t.SEDE_TECNICA
    --AND  ci.CODICE_SOL_PO=t.LOCALITA_INIZIO
    --AND ct.CODICE_ESITO = 1
    --AND ci.CODICE_ESITO = 0
    --AND ct.CODICE_CONTROLLO = p_codice_controllo
    --AND ci.CODICE_CONTROLLO = p_codice_controllo
    --Union
    --Select SEDE_TECNICA From  Rinf_Lavorazione_Evo.SEZIONI_LINEA t,
    --Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI ct,
    --Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI cf
    --Where 
    --ct.CODICE_SOL_PO=t.SEDE_TECNICA
    --AND  cf.CODICE_SOL_PO=t.LOCALITA_FINE
    --AND ct.CODICE_ESITO = 1
    --AND cf.CODICE_ESITO = 0
    --AND ct.CODICE_CONTROLLO = p_codice_controllo
    --AND cf.CODICE_CONTROLLO = p_codice_controllo)
    --MINUS
    --Select t.SEDE_TECNICA From  Rinf_Lavorazione_Evo.SEZIONI_LINEA t,
    --Rinf_Controllati_Evo.PUNTI_OPERATIVI i,
    --Rinf_Controllati_Evo.PUNTI_OPERATIVI f
    --Where 
    --i.SEDE_TECNICA=T.LOCALITA_INIZIO
    --AND f.SEDE_TECNICA=T.LOCALITA_FINE
    --);

--- modifica del 17/09/2015 per inserie In DETTAGLIO_CONTROLLATI il record della tratta che viene scartata.
  Select SEDE_TECNICA, DEFINIZIONE, LOCALITA_INIZIO, LOCALITA_FINE
    Bulk Collect Into l_dtp_ogg
    From Rinf_Lavorazione_Evo.SEZIONI_LINEA
   Where SEDE_TECNICA in
    (
       (Select SEDE_TECNICA 
	      From Rinf_Lavorazione_Evo.SEZIONI_LINEA t,
               Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI ct,
               Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI ci
         Where ct.CODICE_SOL_PO = t.SEDE_TECNICA
           And ci.CODICE_SOL_PO = t.LOCALITA_INIZIO
           And ct.CODICE_ESITO = 1
           And ci.CODICE_ESITO = 0
           And ct.CODICE_CONTROLLO = p_codice_controllo
           And ci.CODICE_CONTROLLO = p_codice_controllo
       Union
        Select SEDE_TECNICA 
		  From Rinf_Lavorazione_Evo.SEZIONI_LINEA t,
               Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI ct,
               Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI cf
         Where ct.CODICE_SOL_PO = t.SEDE_TECNICA
           And cf.CODICE_SOL_PO = t.LOCALITA_FINE
           And ct.CODICE_ESITO = 1
           And cf.CODICE_ESITO = 0
           And ct.CODICE_CONTROLLO = p_codice_controllo
           And cf.CODICE_CONTROLLO = p_codice_controllo
		)
       Minus
        Select t.SEDE_TECNICA 
		  From Rinf_Lavorazione_Evo.SEZIONI_LINEA t,
               Rinf_Controllati_Evo.PUNTI_OPERATIVI i,
               Rinf_Controllati_Evo.PUNTI_OPERATIVI f
         Where i.SEDE_TECNICA = t.LOCALITA_INIZIO
           And f.SEDE_TECNICA = t.LOCALITA_FINE
    );
--  
  For i In 1 .. l_dtp_ogg.COUNT   Loop 
--
      Update Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI
         Set CODICE_ESITO = 0
       Where CODICE_CONTROLLO = p_codice_controllo
         And CODICE_SOL_PO = l_dtp_ogg(i).SEDE_TECNICA;
--
         PKG_RINF_CONTROLLO_PAR_V082.SetControlDetails
		       ( p_codice_controllo,
                 l_dtp_ogg(i).SEDE_TECNICA,
                 l_dtp_ogg(i).SEDE_TECNICA,
                 4,                              -- Mancando il codice SOL, abbiamo utilizzato il primo numero parametro utile (località di inizio tratta)
                 l_dtp_ogg(i).DEFINIZIONE,
                 0,                              -- Esito negativo
                 16,
                 'La Sezione di Linea non può essere validata perchè almeno una delle due località estreme non ha superato i controlli.',   --18/05/2016 modifca messaggio come da mail Schillaci
                 'località inizio: '||l_dtp_ogg(i).LOCALITA_INIZIO||' - località fine: '||l_dtp_ogg(i).LOCALITA_FINE,
                 Null,
                 Null,
				 0 );
    End Loop ;
--
 EXCEPTION
      When OTHERS   Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0, 'SetChangeSOLResult - Elaborazione controlli. Codice Controllo: '
                                     || p_codice_controllo||' - Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null, p_errlog);
         Dbms_Output.Put_Line ('SetChangeSOLResult - Errore: ' || Substr(SQLERRM, 1, 300));
 END SetChangeSOLResult;
--
-- ------------------------------------------------------------------------------------------------   
--                                    PROCEDURE SetNEWControlSOL 
-- ------------------------------------------------------------------------------------------------   
--
   Procedure SetNEWControlSOL (p_codice_controllo   In  Number,
                               p_error              Out Number )   Is
      TYPE dtp_ogg_rt IS RECORD
      ( id_sol_op    Varchar2 (6),
         id_stato    Varchar2 (2)    );
      TYPE dtp_ogg_t IS TABLE OF dtp_ogg_rt;
      l_dtp_ogg   dtp_ogg_t;
   BEGIN
      p_error := 0;
--
      Pkg_Rinf_Utility.SETPROCESSSTATUS 
       ( v_trans,
         'Inizio pubblicazione delle Sezioni di Linea che hanno superato i controlli',
         11,
         14,
         0,
         1,
         1,
         0 );
--
      Select SEDE_TECNICA, STATO
        Bulk Collect Into l_dtp_ogg
        From ( 
		         (Select CODICE_SOL_PO SEDE_TECNICA, 'UP' stato
                    From Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI
                   Where CODICE_CONTROLLO = p_codice_controllo
                     And CODICE_SOL_PO Like 'TR%'
                     And CODICE_ESITO = 1
                Intersect
                  Select SEDE_TECNICA, 'UP' 
				    From Rinf_Controllati_Evo.SEZIONI_LINEA
				   )
               Union
                 (Select CODICE_SOL_PO SEDE_TECNICA, 'IN' stato
                    From Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI
                   Where CODICE_CONTROLLO = p_codice_controllo
                     And CODICE_SOL_PO Like 'TR%'
                     And CODICE_ESITO = 1
                 Minus
                  (Select SEDE_TECNICA, 'IN' 
			 	     From Rinf_Controllati_Evo.SEZIONI_LINEA
                   Union
                   Select SEDE_TECNICA, 'IN' 
				     From Rinf_Staging_Evo.CLASSE_ELIMINATI
				   )
				 )
			  );
--
      Pkg_Rinf_Utility.SETPROCESSSTATUS 
       ( v_trans,
         'Eliminazione dei dati delle Sezioni di Linea già presenti nell''area dei controllati',
         12,
         14,
         1,
         l_dtp_ogg.COUNT,
         1,
         0 );
--
      Pkg_Rinf_Utility.SETPROCESSSTATUS 
       ( v_trans,
         'Pubblicazione nell''area dei controllati dei nuovi dati delle Sezioni di Linea che hanno superato i controlli',
         13,
         14,
         1,
         l_dtp_ogg.COUNT,
         1,
         0 );
  Dbms_Output.Put_Line ('controllo passo 2 : ' || p_codice_controllo);
--
      For i In 1 .. l_dtp_ogg.COUNT  Loop 
--
            If l_dtp_ogg(i).ID_STATO = 'UP'  Then
               Pkg_Rinf_Utility.SETPROCESSSTATUS 
                     ( v_trans,
                       'Eliminazione dei dati delle Sezioni di Linea già presenti nell''area dei controllati',
                       12,
                       14,
                       i,
                       l_dtp_ogg.COUNT,
                       1,
                       1 );
--
               SetOLDSoLClear (l_dtp_ogg(i).ID_SOL_OP, p_error);
--
               SetOLDSoLUpdate (l_dtp_ogg(i).ID_SOL_OP, p_codice_controllo, p_error);
--
            Else
               SetNEWSoL (l_dtp_ogg(i).ID_SOL_OP, p_codice_controllo, p_error);
            End If;
--
       SetSolGeographicArea(l_dtp_ogg(i).ID_SOL_OP, p_error);
--

-- Modifica del 13/03/2015: i link devono avere i binari
--         IF getLinkObject (l_dtp_ogg (i).id_sol_op) = 0
--         Then
--            Pkg_Rinf_Utility.SETPROCESSSTATUS (
--               v_trans,
--               'Pubblicazione nell''area dei controllati dei nuovi dati delle Sezioni di Linea che hanno superato i controlli',
--               13,
--               14,
--               i,
--               l_dtp_ogg.COUNT,
--               1,
--               1);
--
--            SetNEWSoLHierarchy (l_dtp_ogg (i).id_sol_op,p_codice_controllo, p_error);
--         END IF;

       SetNEWSoLHierarchy (l_dtp_ogg(i).ID_SOL_OP, p_codice_controllo, p_error);
--
      End Loop ;
--	  
   EXCEPTION
      When OTHERS  Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0, 'SetNEWControlSOL - Elaborazione controlli. Codice Controllo: '
                                  || p_codice_controllo||' - Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null, p_errlog);
         Dbms_Output.Put_Line ('SetNEWControlSOL - Errore: ' || Substr(SQLERRM, 1, 300));
  END SetNEWControlSOL;
--   
-- ------------------------------------------------------------------------------------------------   
--  PROCEDURE SetRapportoControlli --> Modificato con il controllo della data di validità per i parametri validi
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetRapportoControlli(n_codice_controllo In  Number, 
                                p_error            Out Number )   Is
   BEGIN
    p_error :=0;
--
    Insert Into Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI 
	          ( CODICE_CONTROLLO,
                CODICE_DTP,
                NOME_DTP,
                CODICE_UT,
                CODICE_SOL_PO,
                NOME_SOL_OP,
                CODICE_ERA,
                SEDE_TECNICA,
                NOME_SEDE_TECNICA,
                CODICE_PARAMETRO,
                NUMERO_PARAMETRO,
                DEFINIZIONE_PARAMETRO,
                SIGLA_VISTA,
                CODICE_ESITO,
                ESITO,
                CODICE_TIPO_CONTROLLO,
                DEFINIZIONE_TIPO_CONTROLLO,
                ANOMALIA,
                VALORE_NUOVO,
                DATA_CONTROLLO_NUOVO,
                DATA_ACQUISIZIONE_NUOVO,
                VALORE_PRECEDENTE,
                DATA_CONTROLLO_PRECEDENTE,
                DATA_ACQUISIZIONE_PRECEDENTE,
                SIGLA_TIPO_DEPOSITARIO,
                TIPO_DEPOSITARIO,
                ESITO_CONTROLLO,
                DESCRIZIONE_ESITO )
         Select D.CODICE_CONTROLLO,
                o.codice_dtp,
                DTP.DESCRIZIONE  nome_dtp,
                sol_op.CODICE_UT,
                d.CODICE_SOL_PO,
                SOL_OP.DEFINIZIONE  nome_sol_op,
                'IT' || Substr(OP_INIZIO.CODICE_MIR, 2) || ' - ' || 'IT' || Substr(OP_FINE.CODICE_MIR, 2) codice_era,
                d.SEDE_TECNICA,
                D.DEFINIZIONE  nome_SEDE_TECNICA,
                p.CODICE_PARAMETRO,
                p.NUMERO_PARAMETRO,
                p.DESCRIZIONE DEFINIZIONE_PARAMETRO,
                v.SIGLA_VISTA,
                e.CODICE_ESITO,
                E.DESCRIZIONE ESITO,
                A.CODICE_TIPO_CONTROLLO,
                A.DEFINIZIONE  Definizione_tipo_controllo,
                d.ANOMALIA,
                Nvl(d.VALUE_NEW, ' ')  VALORE_NUOVO,
                ko.DATA_CONTROLLO  DATA_CONTROLLO_NUOVO,
                A_KO.DATA_ACQUISIZIONE  DATA_ACQUISIZIONE_NUOVO,
                d.VALUE_OK  VALORE_PRECEDENTE,
                OK.DATA_CONTROLLO  DATA_CONTROLLO_PRECEDENTE,
                A_OK.DATA_ACQUISIZIONE  DATA_ACQUISIZIONE_PRECEDENTE,
                t.SIGLA_TIPO_DEPOSITARIO,
                t.DESCRIZIONE  TIPO_DEPOSITARIO,
                Case When d.CODICE_ESITO = 1 And d.ANOMALIA Is Not Null Then 0
                     Else d.CODICE_ESITO
                End ESITO_CONTROLLO,
                Nvl(d.ANOMALIA,A.DEFINIZIONE) DESCRIZIONE_ESITO
           From Rinf_Lavorazione_Evo.DETTAGLIO_CONTROLLATI d,
                Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI o,
                Rinf_Lavorazione_Evo.ANAG_TIPO_CONTROLLO a,
                Rinf_Lavorazione_Evo.CONTROLLO_DATI ko,
                Rinf_Lavorazione_Evo.CONTROLLO_DATI ok,
                Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI a_ko,
                Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI a_ok,
                Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI p,
                Rinf_Anagrafiche_Evo.VISTE_PARAMETRI v,
                Rinf_Anagrafiche_Evo.ANAG_ESITO e,
                Rinf_Sicurezza_Evo.ANAG_TIPO_DEPOSITARIO t,
                Rinf_Anagrafiche_Evo.ANAG_DTP dtp,
                Rinf_Lavorazione_Evo.SEZIONI_LINEA sol_op,
                Rinf_Lavorazione_Evo.PUNTI_OPERATIVI op_inizio,
                Rinf_Lavorazione_Evo.PUNTI_OPERATIVI op_fine
          Where d.CODICE_CONTROLLO = n_codice_controllo
            And d.CODICE_CONTROLLO = KO.CODICE_CONTROLLO(+)
            And d.CODICE_CONTROLLO_OK = OK.CODICE_CONTROLLO(+)
            And D.CODICE_CONTROLLO = O.CODICE_CONTROLLO
            And D.CODICE_SOL_PO = o.CODICE_SOL_PO
            And o.CODICE_SOL_PO = sol_op.SEDE_TECNICA
            And SOL_OP.LOCALITA_INIZIO = op_inizio.SEDE_TECNICA
            And SOL_OP.LOCALITA_FINE = op_fine.SEDE_TECNICA
            And o.codice_dtp = dtp.codice_dtp
            And KO.CODICE_ACQUISIZIONE = a_ko.CODICE_ACQUISIZIONE(+)
            And OK.CODICE_ACQUISIZIONE = a_OK.CODICE_ACQUISIZIONE(+)
            And D.CODICE_TIPO_CONTROLLO = A.CODICE_TIPO_CONTROLLO
            And p.CODICE_PARAMETRO = d.CODICE_PARAMETRO
            And p.CODICE_VISTA = v.CODICE_VISTA
            And e.CODICE_ESITO = d.CODICE_ESITO
            And p.CODICE_TIPO_DEPOSITARIO = t.CODICE_TIPO_DEPOSITARIO
--
            And ko.DATA_CONTROLLO between p.data_inizio_validita and p.data_fine_validita
--
        Union
         Select D.CODICE_CONTROLLO,
                o.codice_dtp,
                DTP.DESCRIZIONE  Nome_Dtp,
                SOL_OP.CODICE_UT,
                d.CODICE_SOL_PO,
                SOL_OP.DEFINIZIONE  nome_sol_op,
                'IT' || Substr(SOL_OP.CODICE_MIR, 2) Codice_Era,
                d.SEDE_TECNICA,
                D.DEFINIZIONE  Nome_Sede_Tecnica,
                p.CODICE_PARAMETRO,
                p.NUMERO_PARAMETRO,
                p.DESCRIZIONE  Definizione_Parametro,
                v.SIGLA_VISTA,
                e.CODICE_ESITO,
                E.DESCRIZIONE ESITO,
                A.CODICE_TIPO_CONTROLLO,
                A.DEFINIZIONE  Definizione_tipo_controllo,
                d.ANOMALIA,
                Nvl(d.VALUE_NEW, ' ') Valore_Nuovo,
                ko.DATA_CONTROLLO   Data_Controllo_Nuovo,
                A_KO.DATA_ACQUISIZIONE Data_Acquisizione_Nuovo,
                d.VALUE_OK Valore_Precedente,
                OK.DATA_CONTROLLO Data_Controllo_Precedente,
                A_OK.DATA_ACQUISIZIONE Data_Acquisizione_Precedente,
                t.SIGLA_TIPO_DEPOSITARIO,
                t.DESCRIZIONE Tipo_Depositario,
                Case When d.CODICE_ESITO=1 And d.ANOMALIA Is Not Null Then 0
                     Else d.CODICE_ESITO
                End ESITO_CONTROLLO,
                Nvl(d.ANOMALIA,A.DEFINIZIONE) DESCRIZIONE_ESITO
           From Rinf_Lavorazione_Evo.DETTAGLIO_CONTROLLATI d,
                Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI o,
                Rinf_Lavorazione_Evo.ANAG_TIPO_CONTROLLO a,
                Rinf_Lavorazione_Evo.CONTROLLO_DATI ko,
                Rinf_Lavorazione_Evo.CONTROLLO_DATI ok,
                Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI a_ko,
                Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI a_ok,
                RINF_ANAGRAFICHE_EVO.CATALOGO_PARAMETRI p,
                RINF_ANAGRAFICHE_EVO.VISTE_PARAMETRI v,
                RINF_ANAGRAFICHE_EVO.ANAG_ESITO e,
                RINF_SICUREZZA_EVO.ANAG_TIPO_DEPOSITARIO t,
                RINF_ANAGRAFICHE_EVO.ANAG_DTP dtp,
                Rinf_Lavorazione_Evo.PUNTI_OPERATIVI sol_op
          Where d.CODICE_CONTROLLO = n_codice_controllo
            And d.CODICE_CONTROLLO = KO.CODICE_CONTROLLO(+)
            And d.CODICE_CONTROLLO_OK = OK.CODICE_CONTROLLO(+)
            And D.CODICE_CONTROLLO = O.CODICE_CONTROLLO
            And D.CODICE_SOL_PO = o.CODICE_SOL_PO
            And o.CODICE_SOL_PO = sol_op.SEDE_TECNICA
            And o.codice_dtp = dtp.codice_dtp
            And Ko.CODICE_ACQUISIZIONE = a_ko.CODICE_ACQUISIZIONE(+)
            And OK.CODICE_ACQUISIZIONE = a_OK.CODICE_ACQUISIZIONE(+)
            And D.CODICE_TIPO_CONTROLLO = A.CODICE_TIPO_CONTROLLO
            And p.CODICE_PARAMETRO = d.CODICE_PARAMETRO
            And p.CODICE_VISTA = v.CODICE_VISTA
            And e.CODICE_ESITO = d.CODICE_ESITO
            And p.CODICE_TIPO_DEPOSITARIO = t.CODICE_TIPO_DEPOSITARIO
--
            And ko.DATA_CONTROLLO between p.data_inizio_validita and p.data_fine_validita
--
        Union                                            --19/01/2016 abbiamo inserito la Select che recupera gli oggetti eliminati (CLASSE_ELIMINATI)
         Select D.CODICE_CONTROLLO,
                o.codice_dtp,
                DTP.DESCRIZIONE Nome_Dtp,
                Null CODICE_UT,
                d.CODICE_SOL_PO,
                d.DEFINIZIONE Nome_Sol_Op,
                '-' codice_era,
                d.SEDE_TECNICA,
                D.DEFINIZIONE Nome_Sede_Tecnica,
                p.CODICE_PARAMETRO,
                p.NUMERO_PARAMETRO,
                p.DESCRIZIONE Definizione_Parametro,
                v.SIGLA_VISTA,
                e.CODICE_ESITO,
                E.DESCRIZIONE ESITO,
                A.CODICE_TIPO_CONTROLLO,
                A.DEFINIZIONE Definizione_Tipo_Controllo,
                d.ANOMALIA,
                Nvl(d.VALUE_NEW, ' ') Valore_Nuovo,
                ko.DATA_CONTROLLO Data_Controllo_Nuovo,
                A_KO.DATA_ACQUISIZIONE Data_Acquisizione_Nuovo,
                d.VALUE_OK Valore_Precedente,
                OK.DATA_CONTROLLO Data_Controllo_Precedente,
                A_OK.DATA_ACQUISIZIONE Data_Acquisizione_Precedente,
                t.SIGLA_TIPO_DEPOSITARIO,
                t.DESCRIZIONE Tipo_Depositario,
                Case When d.CODICE_ESITO =1 And d.ANOMALIA Is Not Null Then 0
                     Else d.CODICE_ESITO
                End ESITO_CONTROLLO,
                Nvl(d.ANOMALIA,A.DEFINIZIONE) Descrizione_Esito
           From Rinf_Lavorazione_Evo.DETTAGLIO_CONTROLLATI d,
                Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI o,
                Rinf_Lavorazione_Evo.ANAG_TIPO_CONTROLLO a,
                Rinf_Lavorazione_Evo.CONTROLLO_DATI ko,
                Rinf_Lavorazione_Evo.CONTROLLO_DATI ok,
                Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI a_ko,
                Rinf_Lavorazione_Evo.ACQUISIZIONE_DATI a_ok,
                RINF_ANAGRAFICHE_EVO.CATALOGO_PARAMETRI p,
                RINF_ANAGRAFICHE_EVO.VISTE_PARAMETRI v,
                RINF_ANAGRAFICHE_EVO.ANAG_ESITO e,
                RINF_SICUREZZA_EVO.ANAG_TIPO_DEPOSITARIO t,
                RINF_ANAGRAFICHE_EVO.ANAG_DTP dtp,
                Rinf_Staging_Evo.CLASSE_ELIMINATI sol_op
          Where d.CODICE_CONTROLLO = n_codice_controllo
            And d.CODICE_CONTROLLO = KO.CODICE_CONTROLLO(+)
            And d.CODICE_CONTROLLO_OK = OK.CODICE_CONTROLLO(+)
            And D.CODICE_CONTROLLO = O.CODICE_CONTROLLO
            And D.CODICE_SOL_PO = o.CODICE_SOL_PO
            And o.CODICE_SOL_PO = sol_op.SEDE_TECNICA
            And o.codice_dtp = dtp.codice_dtp
            And KO.CODICE_ACQUISIZIONE = a_ko.CODICE_ACQUISIZIONE(+)
            And OK.CODICE_ACQUISIZIONE = a_OK.CODICE_ACQUISIZIONE(+)
            And D.CODICE_TIPO_CONTROLLO = A.CODICE_TIPO_CONTROLLO
            And p.CODICE_PARAMETRO = d.CODICE_PARAMETRO
            And p.CODICE_VISTA = v.CODICE_VISTA
            And e.CODICE_ESITO = d.CODICE_ESITO
            And p.CODICE_TIPO_DEPOSITARIO = t.CODICE_TIPO_DEPOSITARIO
--
            And ko.DATA_CONTROLLO between p.data_inizio_validita and p.data_fine_validita;
--
    Insert Into Rinf_Lavorazione_Evo.SINTESI_RAPPORTO_CONTROLLI
              ( CODICE_CONTROLLO,
                CODICE_DTP,
                DTP,
                SIGLA_TIPO_DEPOSITARIO,
                TIPO_OGGETTO,
                CODICE_SOL_PO,
                DESCRIZIONE,
                CODICE_XML,
                CODICE_ESITO,
                ESITO,
                ERRORI_GEN,
                ERRORI_INF,
                ERRORI_ENE,
                ERRORI_CCS,
                TOTALE_ERRORI )
         Select c.CODICE_CONTROLLO,
                c.CODICE_DTP,
                c.NOME_DTP DTP,
                c.SIGLA_TIPO_DEPOSITARIO,
                'Sezione di Linea' Tipo_Oggetto,
                c.CODICE_SOL_PO,
                sol_op.DEFINIZIONE Descrizione,
                   'IT' || Substr (OP_INIZIO.CODICE_MIR, 2)|| ' - ' || 'IT'|| Substr (OP_FINE.CODICE_MIR, 2) Codice_Xml,
                c.CODICE_ESITO,
                c.ESITO,
                Nvl (ERRORI_GEN, 0) ERRORI_GEN,
                Nvl (ERRORI_INF, 0) ERRORI_INF,
                Nvl (ERRORI_ENE, 0) ERRORI_ENE,
                Nvl (ERRORI_CCS, 0) ERRORI_CCS,
                Nvl (ERRORI_GEN, 0) + Nvl (ERRORI_INF, 0) + Nvl (ERRORI_ENE, 0) + Nvl (ERRORI_CCS, 0) Totale_Errori
          From (Select Distinct
                  o.CODICE_CONTROLLO,
                  o.CODICE_SOL_PO,
                  d.CODICE_ESITO,
                  Decode (d.CODICE_ESITO, 0, 'Negativo',  1, 'Positivo') Esito,
                  o.CODICE_DTP,
                  o.NOME_DTP,
                  --o.CODICE_TIPO_DEPOSITARIO,
                  o.SIGLA_TIPO_DEPOSITARIO
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI o,
                  Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI d
            Where o.CODICE_CONTROLLO = d.CODICE_CONTROLLO
              And o.CODICE_SOL_PO = d.CODICE_SOL_PO
			    ) c,
                Rinf_Lavorazione_Evo.SEZIONI_LINEA sol_op,
                Rinf_Lavorazione_Evo.PUNTI_OPERATIVI op_inizio,
                Rinf_Lavorazione_Evo.PUNTI_OPERATIVI op_fine,
               (Select CODICE_CONTROLLO,
                       CODICE_SOL_PO,
                       SIGLA_VISTA,
                       SIGLA_TIPO_DEPOSITARIO,
                       COUNT (*) Errori_Gen
                  From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
                 Where SIGLA_VISTA = 'GEN' 
				   And ESITO_CONTROLLO = 0
                 Group By CODICE_CONTROLLO,
                          CODICE_SOL_PO,
                          SIGLA_VISTA,
                          SIGLA_TIPO_DEPOSITARIO
				 ) err_gen,
               (Select CODICE_CONTROLLO,
                       CODICE_SOL_PO,
                       SIGLA_VISTA,
                       SIGLA_TIPO_DEPOSITARIO,
                       COUNT (*) Errori_Inf
                  From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
                 Where SIGLA_VISTA = 'INF' 
				   And ESITO_CONTROLLO = 0
              Group By CODICE_CONTROLLO,
                       CODICE_SOL_PO,
                       SIGLA_VISTA,
                       SIGLA_TIPO_DEPOSITARIO
				) err_inf,
               (Select CODICE_CONTROLLO,
                       CODICE_SOL_PO,
                       SIGLA_VISTA,
                       SIGLA_TIPO_DEPOSITARIO,
                       COUNT (*) Errori_Ene
                  From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
                 Where SIGLA_VISTA = 'ENE' 
				   And ESITO_CONTROLLO = 0
              Group By CODICE_CONTROLLO,
                       CODICE_SOL_PO,
                       SIGLA_VISTA,
                       SIGLA_TIPO_DEPOSITARIO
				) err_ene,
               (Select CODICE_CONTROLLO,
                       CODICE_SOL_PO,
                       SIGLA_VISTA,
                       SIGLA_TIPO_DEPOSITARIO,
                       COUNT (*) Errori_Ccs
                  From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
                 Where SIGLA_VISTA = 'CCS' 
				   And ESITO_CONTROLLO = 0
              Group By CODICE_CONTROLLO,
                       CODICE_SOL_PO,
                       SIGLA_VISTA,
                       SIGLA_TIPO_DEPOSITARIO
			    ) err_ccs,
               (Select CODICE_CONTROLLO,
                       CODICE_SOL_PO,
                       SIGLA_TIPO_DEPOSITARIO,
                       COUNT (*) Superati
                  From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
                 Where ESITO_CONTROLLO = 1
              GROUP BY CODICE_CONTROLLO, 
			           CODICE_SOL_PO, 
					   SIGLA_TIPO_DEPOSITARIO
				) s
    Where     c.CODICE_CONTROLLO = n_codice_controllo
          And c.CODICE_SOL_PO = SOL_OP.SEDE_TECNICA
          And SOL_OP.LOCALITA_INIZIO = op_inizio.SEDE_TECNICA(+)
          And SOL_OP.LOCALITA_FINE = op_fine.SEDE_TECNICA(+)
          And c.CODICE_CONTROLLO = err_gen.CODICE_CONTROLLO(+)
          And c.CODICE_SOL_PO = err_gen.CODICE_SOL_PO(+)
          And c.SIGLA_TIPO_DEPOSITARIO = err_gen.SIGLA_TIPO_DEPOSITARIO(+)
          And c.CODICE_CONTROLLO = err_inf.CODICE_CONTROLLO(+)
          And c.CODICE_SOL_PO = err_inf.CODICE_SOL_PO(+)
          And c.SIGLA_TIPO_DEPOSITARIO = err_inf.SIGLA_TIPO_DEPOSITARIO(+)
          And c.CODICE_CONTROLLO = err_ene.CODICE_CONTROLLO(+)
          And c.CODICE_SOL_PO = err_ene.CODICE_SOL_PO(+)
          And c.SIGLA_TIPO_DEPOSITARIO = err_ene.SIGLA_TIPO_DEPOSITARIO(+)
          And c.CODICE_CONTROLLO = err_ccs.CODICE_CONTROLLO(+)
          And c.CODICE_SOL_PO = err_ccs.CODICE_SOL_PO(+)
          And c.SIGLA_TIPO_DEPOSITARIO = err_ccs.SIGLA_TIPO_DEPOSITARIO(+)
          And c.CODICE_CONTROLLO = s.CODICE_CONTROLLO(+)
          And c.CODICE_SOL_PO = s.CODICE_SOL_PO(+)
          And c.SIGLA_TIPO_DEPOSITARIO = s.SIGLA_TIPO_DEPOSITARIO(+)
          And   Nvl (ERRORI_GEN, -1) + Nvl (ERRORI_INF, -1) + Nvl (ERRORI_ENE, -1) + Nvl (ERRORI_CCS, -1) + Nvl (SUPERATI, -1) <> -5
   Union
    Select c.CODICE_CONTROLLO,
           c.CODICE_DTP,
           c.NOME_DTP DTP,
           c.SIGLA_TIPO_DEPOSITARIO,
           'Punto Operativo' Tipo_Oggetto,
           c.CODICE_SOL_PO,
           sol_op.DEFINIZIONE Descrizione,
           'IT' || Substr (sol_op.CODICE_MIR, 2) Codice_Xml,
           c.CODICE_ESITO,
           c.ESITO,
           Nvl (ERRORI_GEN, 0) ERRORI_GEN,
           Nvl (ERRORI_INF, 0) ERRORI_INF,
           Nvl (ERRORI_ENE, 0) ERRORI_ENE,
           Nvl (ERRORI_CCS, 0) ERRORI_CCS,
           Nvl (ERRORI_GEN, 0) + Nvl (ERRORI_INF, 0) + Nvl (ERRORI_ENE, 0) + Nvl (ERRORI_CCS, 0) Totale_Errori
     From (Select Distinct
                  o.CODICE_CONTROLLO,
                  o.CODICE_SOL_PO,
                  d.CODICE_ESITO,
                  Decode (d.CODICE_ESITO, 0, 'Negativo', 1, 'Positivo') Esito,
                  o.CODICE_DTP,
                  O.NOME_DTP,
                  --o.CODICE_TIPO_DEPOSITARIO,
                  o.SIGLA_TIPO_DEPOSITARIO
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI o,
                  Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI d
            Where o.CODICE_CONTROLLO = d.CODICE_CONTROLLO
              And o.CODICE_SOL_PO = d.CODICE_SOL_PO
		  ) c,
          Rinf_Lavorazione_Evo.PUNTI_OPERATIVI sol_op,
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Errori_Gen
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where SIGLA_VISTA = 'GEN' 
			  And ESITO_CONTROLLO = 0
         Group By CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_VISTA,
                  SIGLA_TIPO_DEPOSITARIO
		   ) err_gen,
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Errori_Inf
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where SIGLA_VISTA = 'INF' 
			  And ESITO_CONTROLLO = 0
         Group By CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_VISTA,
                  SIGLA_TIPO_DEPOSITARIO
			) err_inf,
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Errori_Ene
            From  Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where SIGLA_VISTA = 'ENE' 
			  And ESITO_CONTROLLO = 0
         Group By CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_VISTA,
                  SIGLA_TIPO_DEPOSITARIO
		   ) err_ene,
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Errori_Ccs
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where SIGLA_VISTA = 'CCS' 
			  And ESITO_CONTROLLO = 0
         Group By CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_VISTA,
                  SIGLA_TIPO_DEPOSITARIO
			) err_ccs,
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Superati
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where ESITO_CONTROLLO = 1
         Group By CODICE_CONTROLLO, 
		          CODICE_SOL_PO, 
				  SIGLA_TIPO_DEPOSITARIO
			) s
     Where c.CODICE_CONTROLLO = n_codice_controllo
       And c.CODICE_SOL_PO = SOL_OP.SEDE_TECNICA
       And c.CODICE_CONTROLLO = err_gen.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = err_gen.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = err_gen.SIGLA_TIPO_DEPOSITARIO(+)
       And c.CODICE_CONTROLLO = err_inf.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = err_inf.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = err_inf.SIGLA_TIPO_DEPOSITARIO(+)
       And c.CODICE_CONTROLLO = err_ene.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = err_ene.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = err_ene.SIGLA_TIPO_DEPOSITARIO(+)
       And c.CODICE_CONTROLLO = err_ccs.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = err_ccs.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = err_ccs.SIGLA_TIPO_DEPOSITARIO(+)
       And c.CODICE_CONTROLLO = s.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = s.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = s.SIGLA_TIPO_DEPOSITARIO(+)
       And  Nvl (ERRORI_GEN, -1) + Nvl (ERRORI_INF, -1) + Nvl (ERRORI_ENE, -1) + Nvl (ERRORI_CCS, -1) + Nvl (SUPERATI, -1) <> -5

-- da aggiungere all'istruzione Insert con CLASSE_ELIMINATI (correggere anche il valore di Esito) 2024/06
---->
  Union 
--
    Select c.CODICE_CONTROLLO,
           c.CODICE_DTP,
           c.NOME_DTP DTP,
           c.SIGLA_TIPO_DEPOSITARIO,
           Case Substr(c.CODICE_SOL_PO, 1, 2) When 'LO' 
		                                      Then 'Punto Operativo' 
		                                      Else 'Sezione di Linea' 
		   End Tipo_Oggetto,
           c.CODICE_SOL_PO,
		   Case Substr(c.CODICE_SOL_PO, 1, 2) When 'LO' 
		                                      Then op.DEFINIZIONE 
		                                      Else Sol.DEFINIZIONE 
		   End Descrizione,
           Null , -- 'IT' || Substr (op.CODICE_MIR, 2) Codice_Xml,
           c.CODICE_ESITO,
           c.ESITO,
           Nvl (ERRORI_GEN, 0) ERRORI_GEN,
           Nvl (ERRORI_INF, 0) ERRORI_INF,
           Nvl (ERRORI_ENE, 0) ERRORI_ENE,
           Nvl (ERRORI_CCS, 0) ERRORI_CCS,
           Nvl (ERRORI_GEN, 0) + Nvl (ERRORI_INF, 0) + Nvl (ERRORI_ENE, 0) + Nvl (ERRORI_CCS, 0) Totale_Errori
     From (Select Distinct
                  o.CODICE_CONTROLLO,
                  o.CODICE_SOL_PO,
                  d.CODICE_ESITO,
                  Decode (d.CODICE_ESITO, 0, 'Negativo', 1, 'Positivo') Esito,
                  o.CODICE_DTP,
                  O.NOME_DTP,
                  --o.CODICE_TIPO_DEPOSITARIO,
                  o.SIGLA_TIPO_DEPOSITARIO
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI o,
                  Rinf_Lavorazione_Evo.OGGETTI_CONTROLLATI d
            Where o.CODICE_CONTROLLO = d.CODICE_CONTROLLO
              And o.CODICE_SOL_PO = d.CODICE_SOL_PO
		  ) c,
--->
            Rinf_Staging_Evo.CLASSE_ELIMINATI sol_op,
			Rinf_Pubblicati_Evo.PUNTI_OPERATIVI op,
			Rinf_Pubblicati_Evo.SEZIONI_LINEA sol,
--->
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Errori_Gen
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where SIGLA_VISTA = 'GEN' 
			  And ESITO_CONTROLLO = 0
         Group By CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_VISTA,
                  SIGLA_TIPO_DEPOSITARIO
		   ) err_gen,
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Errori_Inf
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where SIGLA_VISTA = 'INF' 
			  And ESITO_CONTROLLO = 0
         Group By CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_VISTA,
                  SIGLA_TIPO_DEPOSITARIO
			) err_inf,
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Errori_Ene
            From  Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where SIGLA_VISTA = 'ENE' 
			  And ESITO_CONTROLLO = 0
         Group By CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_VISTA,
                  SIGLA_TIPO_DEPOSITARIO
		   ) err_ene,
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Errori_Ccs
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where SIGLA_VISTA = 'CCS' 
			  And ESITO_CONTROLLO = 0
         Group By CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_VISTA,
                  SIGLA_TIPO_DEPOSITARIO
			) err_ccs,
          (Select CODICE_CONTROLLO,
                  CODICE_SOL_PO,
                  SIGLA_TIPO_DEPOSITARIO,
                  COUNT (*) Superati
             From Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI
            Where ESITO_CONTROLLO = 1
         Group By CODICE_CONTROLLO, 
		          CODICE_SOL_PO, 
				  SIGLA_TIPO_DEPOSITARIO
			) s
     Where c.CODICE_CONTROLLO = n_codice_controllo
       And c.CODICE_SOL_PO = Sol_Op.SEDE_TECNICA
       And c.CODICE_CONTROLLO = err_gen.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = err_gen.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = err_gen.SIGLA_TIPO_DEPOSITARIO(+)
       And c.CODICE_CONTROLLO = err_inf.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = err_inf.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = err_inf.SIGLA_TIPO_DEPOSITARIO(+)
       And c.CODICE_CONTROLLO = err_ene.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = err_ene.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = err_ene.SIGLA_TIPO_DEPOSITARIO(+)
       And c.CODICE_CONTROLLO = err_ccs.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = err_ccs.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = err_ccs.SIGLA_TIPO_DEPOSITARIO(+)
       And c.CODICE_CONTROLLO = s.CODICE_CONTROLLO(+)
       And c.CODICE_SOL_PO = s.CODICE_SOL_PO(+)
       And c.SIGLA_TIPO_DEPOSITARIO = s.SIGLA_TIPO_DEPOSITARIO(+)
--->
       And ( op.codice_versione = (select max(codice_versione) from Rinf_Pubblicati_Evo.VERSIONE_RINF)
	    Or  sol.codice_versione = (select max(codice_versione) from Rinf_Pubblicati_Evo.VERSIONE_RINF) )
	   And Sol_Op.SEDE_TECNICA = op.SEDE_TECNICA (+)
	   And Sol_Op.SEDE_TECNICA = sol.SEDE_TECNICA (+)
--->
       And  Nvl (ERRORI_GEN, -1) + Nvl (ERRORI_INF, -1) + Nvl (ERRORI_ENE, -1) + Nvl (ERRORI_CCS, -1) + Nvl (SUPERATI, -1) <> -5;

--
   EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0,'SetRapportoControlli - Elaborazione controlli. Codice Controllo: '
                                    || n_codice_controllo||' - Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null, p_errlog);
         Dbms_Output.Put_Line ('SetRapportoControlli - Errore: ' || Substr(SQLERRM, 1, 300));
   END SetRapportoControlli;
--   
-- ------------------------------------------------------------------------------------------------   
--                   PROCEDURE SetSintesiControlli
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetSintesiControlli(n_codice_controllo In Number, p_error Out Number)   Is
   BEGIN
   p_error:=0;
--   
   Insert Into Rinf_Lavorazione_Evo.SINTESI_CONTROLLI 
            (CODICE_CONTROLLO, SEDE_TECNICA, CODICE_PARAMETRO, NUMERO_PARAMETRO_MULTIPLO, CODICE_ESITO, NYA)
      Select CODICE_CONTROLLO,
             SEDE_TECNICA,
             c.CODICE_PARAMETRO,
             NUMERO_PARAMETRO_MULTIPLO,
             Min(CODICE_ESITO),
             Max(d.NYA)
        From Rinf_Lavorazione_Evo.DETTAGLIO_CONTROLLATI d,
             Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI c
       Where c.CODICE_PARAMETRO = d.CODICE_PARAMETRO 
	     And d.CODICE_CONTROLLO = n_codice_controllo
    Group By CODICE_CONTROLLO, SEDE_TECNICA, c.CODICE_PARAMETRO, NUMERO_PARAMETRO_MULTIPLO;
  EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0, 'SetSintesiControlli - Elaborazione controlli. Codice Controllo: '
         || n_codice_controllo||' - SetSintesiControlli. Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null, p_errlog);
         Dbms_Output.Put_Line ('Errore: ' || Substr(SQLERRM, 1, 300));
 END SetSintesiControlli;
--   
-- ------------------------------------------------------------------------------------------------   
--                                  PROCEDURE SetMDRGeographicArea   
-- ------------------------------------------------------------------------------------------------   
--
 Procedure SetMDRGeographicArea(p_codice_controllo In  Number,
                                p_error            Out Number )   Is
   BEGIN
      p_error := 0;
--
-- Linea_Comm_Sol
--
    Insert Into Rinf_Lavorazione_Evo.LINEA_COMM_SOL (CODICE_GIURISDIZIONE, SEDE_TECNICA, CODICE_CONTROLLO, KM_INIZIO, KM_FINE)
    Select Distinct CODICE_GIURISDIZIONE, t.SEDE_TECNICA, p_codice_controllo, s.KM_INIZIO, s.KM_FINE
     From Rinf_Anagrafiche_Evo.LINEA_COMM_TRATTE l,
          Rinf_Anagrafiche_Evo.TRATTE_PIC t,
          Rinf_Lavorazione_Evo.SEZIONI_LINEA s
    Where s.SEDE_TECNICA = t.SEDE_TECNICA 
      And l.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC 
      And l.DATA_SCADENZA Is Null; --  and t.DATA_SCADENZA Is Null;
--
-- Corridoio_Sol
--
    Insert Into Rinf_Lavorazione_Evo.CORRIDOIO_SOL (CODICE_CORRIDOIO, SEDE_TECNICA, CODICE_CONTROLLO)
    Select Distinct CODICE_GIURISDIZIONE, s.SEDE_TECNICA, p_codice_controllo
     From Rinf_Anagrafiche_Evo.CORRIDOIO_TRATTE l,
          Rinf_Anagrafiche_Evo.TRATTE_PIC t,
          Rinf_Lavorazione_Evo.SEZIONI_LINEA s
    Where s.SEDE_TECNICA = t.SEDE_TECNICA 
      And l.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC 
      And l.DATA_SCADENZA Is Null; --  and t.DATA_SCADENZA Is Null;
--
--Linea Ten
--
    Insert Into Rinf_Lavorazione_Evo.LINEE_TENT_SOL(CODICE_LINEA_TENT, SEDE_TECNICA,CODICE_CONTROLLO)
    Select Distinct CODICE_GIURISDIZIONE, s.SEDE_TECNICA, p_codice_controllo
     From  Rinf_Anagrafiche_Evo.LINEA_TENT_TRATTE l,
           Rinf_Anagrafiche_Evo.TRATTE_PIC t,
           Rinf_Lavorazione_Evo.SEZIONI_LINEA s
     Where s.SEDE_TECNICA = t.SEDE_TECNICA 
       And l.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC 
       And l.DATA_SCADENZA Is Null; --  and t.DATA_SCADENZA Is Null;
--
-- Linea_Fcl_Sol - 17/02/2016 codice modificato perchè non venivano valorizzate le località di inzio e di fine, 
--                            perdendo l'associazione tra località e linee fcl
--
    Insert Into Rinf_Lavorazione_Evo.LINEA_FCL_SOL (CODICE_LINEA_FCL, SEDE_TECNICA, LOCALITA_INIZIO, LOCALITA_FINE, CODICE_CONTROLLO)
    Select Distinct a.CODICE_LINEA_FCL, t.SEDE_TECNICA, LOCALITA_INIZIO, LOCALITA_FINE, p_codice_controllo
     From  Rinf_Anagrafiche_Evo.ANAG_LINEA_FCL a,
           Rinf_Anagrafiche_Evo.LINEA_FCL_TRATTE_ROMAN l,
           Rinf_Anagrafiche_Evo.TRATTE_ROMAN r,
           Rinf_Anagrafiche_Evo.TRATTE_PIC t,
           Rinf_Lavorazione_Evo.SEZIONI_LINEA s
     Where a.CODICE_LINEA_FCL = l.CODICE_LINEA_FCL 
       And l.CODICE_TRATTA_ROMAN = r.CODICE_TRATTA_ROMAN 
       And r.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC
       And t.SEDE_TECNICA = s.SEDE_TECNICA
       And l.DATA_SCADENZA Is Null  --and t.DATA_SCADENZA Is Null And
       And a.DATA_SCADENZA Is Null;
--
--  Fascicolo_Sol
--
    Insert Into Rinf_Lavorazione_Evo.FASCICOLO_SOL (CODICE_FASCICOLO, SEDE_TECNICA, CODICE_CONTROLLO)
    Select Distinct s.CODICE_FASCICOLO, t.SEDE_TECNICA, p_codice_controllo
     From Rinf_Anagrafiche_Evo.LINEA_FCL_TRATTE_ROMAN l,
          Rinf_Anagrafiche_Evo.TRATTE_ROMAN r,
          Rinf_Anagrafiche_Evo.TRATTE_PIC t,
          Rinf_Anagrafiche_Evo.FASCICOLO_LINEE_FCL s,
          Rinf_Lavorazione_Evo.SEZIONI_LINEA i
    Where l.CODICE_TRATTA_ROMAN = r.CODICE_TRATTA_ROMAN 
      And r.CODICE_TRATTA_PIC = t.CODICE_TRATTA_PIC
      And S.CODICE_LINEA_FCL = l.CODICE_LINEA_FCL 
      And t.SEDE_TECNICA = i.SEDE_TECNICA 
      And l.DATA_SCADENZA Is Null -- and t.DATA_SCADENZA Is Null And
      And s.DATA_SCADENZA Is Null;
--
--  OP
--
    Insert Into Rinf_Lavorazione_Evo.LINEA_COMM_PO (CODICE_GIURISDIZIONE, SEDE_TECNICA, KM_INIZIO, CODICE_CONTROLLO)
    Select Distinct CODICE_GIURISDIZIONE, s.SEDE_TECNICA, s.km_inizio, p_codice_controllo
     From  Rinf_Anagrafiche_Evo.LINEA_COMM_LOCALITA l,
           Rinf_Anagrafiche_Evo.LOCALITA_PIC t,
           Rinf_Lavorazione_Evo.PUNTI_OPERATIVI s
    Where  s.SEDE_TECNICA = t.COD_LOCALITA_IN_RETE
       And l.CODICE_LOCALITA_PIC = t.CODICE_LOCALITA_PIC 
       And t.COD_LOCALITA_IN_RETE = s.SEDE_TECNICA 
       And l.DATA_SCADENZA Is Null; -- and t.DATA_SCADENZA Is Null;
--
-- Corridoio
--
    Insert Into Rinf_Lavorazione_Evo.CORRIDOIO_PO (CODICE_CORRIDOIO, SEDE_TECNICA, CODICE_CONTROLLO)
    Select Distinct CODICE_GIURISDIZIONE, s.SEDE_TECNICA, p_codice_controllo
     From  Rinf_Anagrafiche_Evo.CORRIDOIO_LOCALITA l,
           Rinf_Anagrafiche_Evo.LOCALITA_PIC t,
           Rinf_Lavorazione_Evo.PUNTI_OPERATIVI s
     Where s.SEDE_TECNICA = t.COD_LOCALITA_IN_RETE 
       And l.CODICE_LOCALITA_PIC = t.CODICE_LOCALITA_PIC 
       And t.COD_LOCALITA_IN_RETE = s.SEDE_TECNICA 
       And l.DATA_SCADENZA Is Null; -- and t.DATA_SCADENZA Is Null;
--
--  Linea Ten
--
    Insert Into Rinf_Lavorazione_Evo.LINEE_TENT_PO (CODICE_LINEA_TENT, SEDE_TECNICA, CODICE_CONTROLLO)
    Select Distinct CODICE_GIURISDIZIONE, s.SEDE_TECNICA, p_codice_controllo
     From  Rinf_Anagrafiche_Evo.LINEA_TENT_LOCALITA l,
--           Rinf_Anagrafiche_Evo.TRATTE_PIC t,
           Rinf_Anagrafiche_Evo.LOCALITA_PIC t,
           Rinf_Lavorazione_Evo.PUNTI_OPERATIVI s
    Where  s.SEDE_TECNICA = t.COD_LOCALITA_IN_RETE 
       And l.CODICE_LOCALITA_PIC = t.CODICE_LOCALITA_PIC 
       And t.COD_LOCALITA_IN_RETE = s.SEDE_TECNICA 
       And l.DATA_SCADENZA Is Null; -- and t.DATA_SCADENZA Is Null;
--
    EXCEPTION
      When OTHERS  Then
         p_error := SQLCODE;
         Pkg_Rinf_Utility.SetNewLOG (0, 'Errore: Oracle. Elaborazione controlli. Codice Controllo: '
                                    || p_codice_controllo||' - SetMDRGeographicArea. Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null, p_errlog);
  END SetMDRGeographicArea;
--   
