--                   HAVING COUNT (*) > 1)
--Order by LOCALITA_INIZIO, LOCALITA_FINE,t.SEDE_TECNICA;
--l_tratte l_cur%ROWTYPE;


   TR_PREC        Varchar2(6);
   LO_IN_PREC      Varchar2(6);
