--               WITH test AS (Select LINEA_COMM From DUAL)
--                   Select LO_IN_CORR,
--                             REGEXP_Substr (LINEA_COMM,
--                                            '[^ ]+',
--                                            1,
--                                            ROWNUM)
--                          || '-'
--                          || LT_CORR,
--                          REGEXP_Substr (LINEA_COMM,
--                                            '[^ ]+',
--                                            1,
--                                            ROWNUM)
--                             split
--                     From test
--               CONNECT BY LEVEL <= LENGTH (REGEXP_REPLACE (LINEA_COMM, '[^ ]+')) + 1;
--            Insert Into Rinf_Lavorazione_Evo.LINEA_TRIPLETTA(SEDE_TECNICA, CODICE_LINEA,LINEA_ORIGINE)
--            WITH test AS (Select LINEA_COMM From DUAL)
--                   Select LO_FIN_CORR,
--                             REGEXP_Substr (LINEA_COMM,
--                                            '[^ ]+',
--                                            1,
--                                            ROWNUM)
--                          || '-'
--                          || LT_CORR,
--                          REGEXP_Substr (LINEA_COMM,
--                                            '[^ ]+',
--                                            1,
