--Tratte senza linea

   Insert Into Rinf_Lavorazione_Evo.LINEA_TRIPLETTA (SEDE_TECNICA,  CODICE_LINEA)
   Select SEDE_TECNICA, '0000'
     From Rinf_Controllati_Evo.SEZIONI_LINEA
    Where SEDE_TECNICA In
              (Select SEDE_TECNICA From  Rinf_Controllati_Evo.SEZIONI_LINEA
              Minus
              (Select SEDE_TECNICA
                 From Rinf_Controllati_Evo.V_SOL_CONTESTO_GEOGRAFICO
                Where  CODICE_CONTESTO = 5
               Union
               Select SEDE_TECNICA
                 From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                Where SEDE_TECNICA LIKE 'TR%'))
   Union
   Select LOCALITA_INIZIO, '0000'
     From Rinf_Controllati_Evo.SEZIONI_LINEA
    Where SEDE_TECNICA IN
             (Select SEDE_TECNICA From Rinf_Controllati_Evo.SEZIONI_LINEA
              Minus
              (Select SEDE_TECNICA
                 From  Rinf_Controllati_Evo.V_SOL_CONTESTO_GEOGRAFICO
                Where  CODICE_CONTESTO = 5
               Union
               Select SEDE_TECNICA
                 From  Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                Where SEDE_TECNICA LIKE 'TR%'))
   Union
   Select LOCALITA_FINE, '0000'
     From Rinf_Controllati_Evo.SEZIONI_LINEA
    Where SEDE_TECNICA IN
             (Select SEDE_TECNICA From  Rinf_Controllati_Evo.SEZIONI_LINEA
              MINUS
              (Select SEDE_TECNICA
                 From  Rinf_Controllati_Evo.V_SOL_CONTESTO_GEOGRAFICO
                Where  CODICE_CONTESTO = 5
               Union
               Select SEDE_TECNICA
                 From  Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                Where SEDE_TECNICA LIKE 'TR%'));
--
--  controllo triplette
--  inserisco la tripletta per le località di inizio che non hanno la linea della tratta
--
   Insert Into Rinf_Lavorazione_Evo.LINEA_TRIPLETTA (SEDE_TECNICA, CODICE_LINEA)
   Select t.SEDE_TECNICA, '0000'
     From Rinf_Controllati_Evo.SEZIONI_LINEA t,
          (Select t.SEDE_TECNICA, linea
             From Rinf_Controllati_Evo.sezioni_linea t,
                  (Select SEDE_TECNICA, CODICE linea
                     From Rinf_Controllati_Evo.V_SOL_CONTESTO_GEOGRAFICO
                    Where  CODICE_CONTESTO = 5
                   Union
                   Select SEDE_TECNICA, CODICE_LINEA
                     From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                    Where SEDE_TECNICA LIKE 'TR%') lc_t
            Where t.SEDE_TECNICA = lc_t.SEDE_TECNICA
           Minus
           (Select t.SEDE_TECNICA, lc_li.linea
              From  Rinf_Controllati_Evo.sezioni_linea t,
                   (Select SEDE_TECNICA, CODICE linea
                      From Rinf_Controllati_Evo.V_OP_CONTESTO_GEOGRAFICO
                     Where CODICE_CONTESTO = 5
                    Union
                    Select SEDE_TECNICA, CODICE_LINEA
                      From  Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                     Where SEDE_TECNICA LIKE 'LO%') lc_li
             Where lc_li.SEDE_TECNICA = t.localita_inizio)) l
    Where t.SEDE_TECNICA = l.SEDE_TECNICA
   Union
   Select t.LOCALITA_INIZIO, '0000'
     From  Rinf_Controllati_Evo.SEZIONI_LINEA t,
          (Select t.SEDE_TECNICA, linea
             From  Rinf_Controllati_Evo.sezioni_linea t,
                  (Select SEDE_TECNICA, CODICE linea
                     From  Rinf_Controllati_Evo.V_SOL_CONTESTO_GEOGRAFICO
                    Where  CODICE_CONTESTO = 5
                   Union
                   Select SEDE_TECNICA, CODICE_LINEA
                     From  Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                    Where SEDE_TECNICA LIKE 'TR%') lc_t
            Where t.SEDE_TECNICA = lc_t.SEDE_TECNICA
           Minus
           (Select t.SEDE_TECNICA, lc_li.linea
              From  Rinf_Controllati_Evo.sezioni_linea t,
                   (Select SEDE_TECNICA, CODICE linea
                      From  Rinf_Controllati_Evo.V_OP_CONTESTO_GEOGRAFICO
                     Where  CODICE_CONTESTO = 5
                    Union
                    Select SEDE_TECNICA, CODICE_LINEA
                      From  Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                     Where SEDE_TECNICA LIKE 'LO%') lc_li
             Where lc_li.SEDE_TECNICA = t.localita_inizio)) l
    Where t.SEDE_TECNICA = l.SEDE_TECNICA
   Union
   Select t.LOCALITA_FINE, '0000'
     From  Rinf_Controllati_Evo.SEZIONI_LINEA t,
          (Select t.SEDE_TECNICA, linea
             From  Rinf_Controllati_Evo.sezioni_linea t,
                  (Select SEDE_TECNICA, CODICE linea
                     From Rinf_Controllati_Evo.V_SOL_CONTESTO_GEOGRAFICO
                    Where CODICE_CONTESTO = 5
                   Union
                   Select SEDE_TECNICA, CODICE_LINEA
                     From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                    Where SEDE_TECNICA LIKE 'TR%') lc_t
            Where t.SEDE_TECNICA = lc_t.SEDE_TECNICA
           MINUS
           (Select t.SEDE_TECNICA, lc_li.linea
              From  Rinf_Controllati_Evo.sezioni_linea t,
                   (Select SEDE_TECNICA, CODICE linea
                      From Rinf_Controllati_Evo.V_OP_CONTESTO_GEOGRAFICO
                     Where  CODICE_CONTESTO = 5
                    Union
                    Select SEDE_TECNICA, CODICE_LINEA
                      From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                     Where SEDE_TECNICA LIKE 'LO%') lc_li
             Where lc_li.SEDE_TECNICA = t.localita_inizio)) l
    Where t.SEDE_TECNICA = l.SEDE_TECNICA;
--
-- inserisco la tripletta per le località di fine che non hanno la linea della tratta

    Insert Into Rinf_Lavorazione_Evo.LINEA_TRIPLETTA (SEDE_TECNICA,
                                                     CODICE_LINEA)
    Select t.SEDE_TECNICA, '0000'
     From  Rinf_Controllati_Evo.SEZIONI_LINEA t,
          (Select t.SEDE_TECNICA, linea
             From  Rinf_Controllati_Evo.sezioni_linea t,
                  (Select SEDE_TECNICA, CODICE linea
                     From Rinf_Controllati_Evo.V_SOL_CONTESTO_GEOGRAFICO
                    Where CODICE_CONTESTO = 5
                   Union
                   Select SEDE_TECNICA, CODICE_LINEA
                     From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                    Where SEDE_TECNICA LIKE 'TR%') lc_t
            Where t.SEDE_TECNICA = lc_t.SEDE_TECNICA
           Minus
           (Select t.SEDE_TECNICA, lc_li.linea
              From  Rinf_Controllati_Evo.sezioni_linea t,
                   (Select SEDE_TECNICA, CODICE linea
                      From Rinf_Controllati_Evo.V_OP_CONTESTO_GEOGRAFICO
                     Where CODICE_CONTESTO = 5
                    Union
                    Select SEDE_TECNICA, CODICE_LINEA
                      From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                     Where SEDE_TECNICA LIKE 'LO%') lc_li
             Where lc_li.SEDE_TECNICA = t.localita_fine)) l
    Where t.SEDE_TECNICA = l.SEDE_TECNICA
   Union
   Select t.LOCALITA_INIZIO, '0000'
     From Rinf_Controllati_Evo.SEZIONI_LINEA t,
          (Select t.SEDE_TECNICA, linea
             From  Rinf_Controllati_Evo.sezioni_linea t,
                  (Select SEDE_TECNICA, CODICE linea
                     From Rinf_Controllati_Evo.V_SOL_CONTESTO_GEOGRAFICO
                    Where  CODICE_CONTESTO = 5
                   Union
                   Select SEDE_TECNICA, CODICE_LINEA
                     From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                    Where SEDE_TECNICA LIKE 'TR%') lc_t
            Where t.SEDE_TECNICA = lc_t.SEDE_TECNICA
           Minus
           (Select t.SEDE_TECNICA, lc_li.linea
              From Rinf_Controllati_Evo.sezioni_linea t,
                   (Select SEDE_TECNICA, CODICE linea
                      From Rinf_Controllati_Evo.V_OP_CONTESTO_GEOGRAFICO
                     Where  CODICE_CONTESTO = 5
                    Union
                    Select SEDE_TECNICA, CODICE_LINEA
                      From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                     Where SEDE_TECNICA LIKE 'LO%') lc_li
             Where lc_li.SEDE_TECNICA = t.localita_fine)) l
    Where t.SEDE_TECNICA = l.SEDE_TECNICA
   Union
   Select t.LOCALITA_FINE, '0000'
     From Rinf_Controllati_Evo.SEZIONI_LINEA t,
          (Select t.SEDE_TECNICA, linea
             From  Rinf_Controllati_Evo.sezioni_linea t,
                  (Select SEDE_TECNICA, CODICE linea
                     From Rinf_Controllati_Evo.V_SOL_CONTESTO_GEOGRAFICO
                    Where CODICE_CONTESTO = 5
                   Union
                   Select SEDE_TECNICA, CODICE_LINEA
                     From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                    Where SEDE_TECNICA LIKE 'TR%') lc_t
            Where t.SEDE_TECNICA = lc_t.SEDE_TECNICA
           Minus
           (Select t.SEDE_TECNICA, lc_li.linea
              From  Rinf_Controllati_Evo.sezioni_linea t,
                   (Select SEDE_TECNICA, CODICE linea
                      From Rinf_Controllati_Evo.V_OP_CONTESTO_GEOGRAFICO
                     Where CODICE_CONTESTO = 5
                    Union
                    Select SEDE_TECNICA, CODICE_LINEA
                      From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA
                     Where SEDE_TECNICA LIKE 'LO%') lc_li
             Where lc_li.SEDE_TECNICA = t.localita_fine)) l
    Where t.SEDE_TECNICA = l.SEDE_TECNICA;

--  Travaso nella tabella di RINF_CONTROLLATI_EVO i valori distinti
    Delete From  Rinf_Controllati_Evo.LINEA_TRIPLETTA;
--
    Insert Into Rinf_Controllati_Evo.LINEA_TRIPLETTA
    Select Distinct CODICE_LINEA, SEDE_TECNICA,LINEA_ORIGINE
    From Rinf_Lavorazione_Evo.LINEA_TRIPLETTA;
--
EXCEPTION
      When OTHERS Then
         Pkg_Rinf_Utility.SetNewLOG (0, 'SetLineeFittizie - Elaborazione controlli. - Codice Errore: ' ||SQLCODE||' - '||SQLERRM, Null, p_errlog);
END SetLineeFittizie;
--
-- ------------------------------------------------------------------------------------------------   
--                    Procedure RunCheck
-- ------------------------------------------------------------------------------------------------   
--
 Procedure RunCheck (p_codice_acquisizione   In     Number,
                     vtran_id                In     Varchar2,
                     p_error                 Out    Number )  Is
   n_codice_controllo   Number;
--   
BEGIN
   p_error := 0;
   v_trans := vtran_id;

   SetNewControlID (p_codice_acquisizione, n_codice_controllo, p_error);
--
   Pkg_Rinf_Utility.SETPROCESSSTATUS 
    ( v_trans,
         'Inizio elaborazione controlli. Codice Controllo: '
      || n_codice_controllo,
      1,
      14,
      0,
      1,
      1,
      0 );
--
   SetDeleteOLDObject (n_codice_controllo, p_error);
--
   If p_error = 0 Then
      Pkg_Rinf_Utility.SETPROCESSSTATUS 
       ( v_trans,
         'Inizio controlli dei parametri delle Sezioni di Linea',
         2,
         14,
         0,
         1,
         1,
         0 );
--
      PKG_RINF_CONTROLLO_PAR_V082.RunControlSOL (p_codice_acquisizione,
                                                 n_codice_controllo,
                                                 p_error);
      Dbms_Output.Put_Line ( 'Inizio controlli dei parametri delle Sezioni di Linea ' || p_error);
--
      Pkg_Rinf_Utility.SETPROCESSSTATUS 
       ( v_trans,
         'Fine controlli dei parametri delle Sezioni di Linea',
         3,
         14,
         0,
         1,
         1,
         0 );
--
      If p_error = 0 Then
         Pkg_Rinf_Utility.SETPROCESSSTATUS 
          ( v_trans,
            'Elaborazione dei risultati dei controlli dei parametri delle Sezioni di Linea',
            4,
            14,
            0,
            1,
            1,
            0 );
--
         SetControlResult (n_codice_controllo, p_error);
--
         Dbms_Output.Put_Line ('Elaborazione dei risultati dei controlli dei parametri delle Sezioni di Linea ' || p_error);
--
         Pkg_Rinf_Utility.SETPROCESSSTATUS 
          ( v_trans,
            'Inizio controlli dei parametri dei Punti Operativi',
            5,
            14,
            0,
            1,
            1,
            0 );
--
         PKG_RINF_CONTROLLO_PAR_V082.RunControlOP (p_codice_acquisizione,
                                                   n_codice_controllo,
                                                   p_error);
         Dbms_Output.Put_Line ('Inizio controlli dei parametri dei Punti Operativi ' || p_error);
--
         Pkg_Rinf_Utility.SETPROCESSSTATUS 
          ( v_trans,
            'Fine controlli dei parametri dei Punti Operativi',
            6,
            14,
            0,
            1,
            1,
            0 );
      End If;
--
      If p_error = 0 Then
         Pkg_Rinf_Utility.SETPROCESSSTATUS 
          ( v_trans,
            'Elaborazione dei risultati dei controlli dei parametri dei Punti Operativi',
            7,
            14,
            0,
            1,
            1,
            0 );
--
         SetControlResult (n_codice_controllo, p_error);
      End If;
--
-- 19/01/2016
--         Lanciamo di nuovo la procedura di eliminazione delle sedi tecniche non più valide (CLASSE_ELIMINATI)
--         perchè dopo il travaso da LAVORAZIONE a CONTROLLATI delle località che nella prima fase non potevano essere eliminate, perchè
--         estremi di una tratta valida, con i nuovi dati potrebbero essere cancellate (l'aggiornamento delle tratte potrebbe "liberare" delle località)
      If p_error = 0 Then
           SetDeleteOLDObject (n_codice_controllo, p_error);
      End If;

      If p_error = 0 Then
--  25/09/2015 da mettere In linea dopo la conferma da parte di RFI
--   SetChangeOPResult(n_codice_controllo,p_error);
--  18/09/2015 dal momento che questa procedura scrive In dettaglio controllati, è necessario che giri prima della valorizzazione
--  delle tabelle di sintesi
         SetChangeSOLResult (n_codice_controllo, p_error);
--
         SetSintesiControlli (n_codice_controllo, p_error);
         SetRapportoControlli (n_codice_controllo, p_error);
         SetMDRGeographicArea (n_codice_controllo, p_error);
         SetNEWControlOP (n_codice_controllo, p_error);
         SetNEWControlSOL (n_codice_controllo, p_error);
--->

-- 19/02/2024
--         Lanciamo di nuovo la procedura di eliminazione delle sedi tecniche non più valide (CLASSE_ELIMINATI)
--         perchè dopo il travaso da LAVORAZIONE a CONTROLLATI delle località che nella prima fase non potevano essere eliminate, perchè
--         estremi di una tratta valida, con i nuovi dati potrebbero essere cancellate (l'aggiornamento delle tratte potrebbe "liberare" delle località)
--
--    In questa posizione verranno cancellati gli OP che, una volta aggiornate le SOL, non sono più estremi di tratta
      If p_error = 0 Then
           SetDeleteOLDObject (n_codice_controllo, p_error);
      End If;

--->		 

--
--  15/07/2015
--  Inserisco le linee fittizie per garantire la tripletta della linea commerciale
--   e per risolvere i problemi di parallelismo delle tratte
--  SetLineeFittizie;
--  22/07/2016 per richiesta del cliente eliminate le linee fittizie, nel file xml le tratte parallele
--  vengono collassate In un'unica sezione di linea con tutti i binari delle tratte parallele
--         03/11/2016 Modificata la procedura SetLineeFittizie, è stata commentata la parte riguardo alle tratte parallele
--         è stata invece lasciata la parte che controlla la terna delle linee tra tratte-località inizio-località fine
         SetLineeFittizie;

--  10/11/2017 Gestione storicizzazione MDR GIS
         PKG_RINF_GIS_V2.SP_SET_VERSIONE_MDR(1,Null,p_error);
--
      End If;
   End If;
--
   Pkg_Rinf_Utility.SETPROCESSSTATUS 
    ( v_trans,
      'Fine elaborazione controlli. Codice Controllo: ' || n_codice_controllo,
      14,
      14,
      0,
      1,
      1,
      0 );
  EXCEPTION
     When OTHERS Then
        p_error := SQLCODE;
        Pkg_Rinf_Utility.SetNewLOG (0, 'RunCheck - Elaborazione controlli. Codice Controllo: '
                                    || n_codice_controllo || ' - Codice Errore: '|| SQLCODE|| ' - '|| SQLERRM, Null, p_errlog);
      Dbms_Output.Put_Line ('RunCheck - Errore: ' || Substr(SQLERRM, 1, 300));
 END RunCheck;
--
-- ------------------------------------------------------------------------------------------------   
--                                    PROCEDURE GetControlReportList
-- Questo elenco viene utilizzato nel menù Validazione --> Visualizza Rapporto --> Visualizza Raporti Precedenti
-- ------------------------------------------------------------------------------------------------   
--
  Procedure GetControlReportList (p_cursor Out empcur)    Is
   BEGIN
      OPEN p_cursor FOR
           Select CODICE_CONTROLLO,
                  DATA_CONTROLLO,
                  CODICE_ACQUISIZIONE,
                  MODALITA
             From V_CONTROLLO_DATI_V082
         Order by CODICE_CONTROLLO DESC;
  END GetControlReportList;
--
-- ------------------------------------------------------------------------------------------------   
--                                   PROCEDURE GetDetailOfControl 
-- Restituisce l'elenco completo per la visualizzazione del Rapporto Validazione Automatica se Amministratore (n_ruolo=1)
-- Altrimenti solo i dati di pertinenza. Modificata con la verifica dei parametri attivi alla data
-- ------------------------------------------------------------------------------------------------   
--
  Procedure GetDetailOfControl (p_codice_controllo   In     Number,
                                p_codice_utente      In     Varchar2,
                                p_cursor             Out    empcur )   Is
       n_ruolo Number;
   BEGIN
      Select Min(CODICE_RUOLO) into n_ruolo 
       From  Rinf_Sicurezza_Evo.UTENTE_RUOLI
   Where ID_UTENTE = PKG_RINF_SICUREZZA.GETUSERID(p_codice_utente);
--
   If n_ruolo = 1 Then
      Open p_cursor For
           Select Distinct c.CODICE_CONTROLLO,
                  c.CODICE_DTP,
                  c.DTP,
                  c.TIPO_OGGETTO,
                  c.CODICE_SOL_PO,
                  c.DESCRIZIONE,
                  c.CODICE_XML,
                  c.CODICE_ESITO,
                  c.ESITO,
                  SUM(NVL(c.ERRORI_GEN,0)) ERRORI_GEN,
                  SUM(NVL(c.ERRORI_INF,0)) ERRORI_INF,
                  SUM(NVL(c.ERRORI_ENE,0)) ERRORI_ENE,
                  SUM(NVL(c.ERRORI_CCS,0)) ERRORI_CCS,
                  SUM(NVL(c.TOTALE_ERRORI,0)) TOTALE_ERRORI
             From V_OGGETTI_CONTROLLATI_DEP_V082 c
            Where CODICE_CONTROLLO = p_codice_controllo
            group by c.CODICE_CONTROLLO,
                  c.CODICE_DTP,
                  c.DTP,
                  c.TIPO_OGGETTO,
                  c.CODICE_SOL_PO,
                  c.DESCRIZIONE,
                  c.CODICE_XML,
                  c.CODICE_ESITO,
                  c.ESITO
         Order by c.CODICE_DTP, c.TIPO_OGGETTO, c.CODICE_SOL_PO;
   Else
      Open p_cursor For
           Select Distinct c.CODICE_CONTROLLO,
                  c.CODICE_DTP,
                  c.DTP,
                  c.TIPO_OGGETTO,
                  c.CODICE_SOL_PO,
                  c.DESCRIZIONE,
                  c.CODICE_XML,
                  c.CODICE_ESITO,
                  c.ESITO,
                  c.ERRORI_GEN,
                  c.ERRORI_INF,
                  c.ERRORI_ENE,
                  c.ERRORI_CCS,
                  c.TOTALE_ERRORI
             From V_OGGETTI_CONTROLLATI_DEP_V082 c,
             (Select CODICE_DTP, CODICE_TIPO_DEPOSITARIO, SIGLA_TIPO_DEPOSITARIO
                From Rinf_Sicurezza_Evo.V_UTENTE_RUOLO r
               Where lower(CODICE_UTENTE) = lower(p_codice_utente)
                 And CODICE_RUOLO=5
             Union
              Select CODICE_DTP, CODICE_TIPO_DEPOSITARIO, SIGLA_TIPO_DEPOSITARIO
                From Rinf_Sicurezza_Evo.V_UTENTE_RUOLO r
               Where lower(CODICE_UTENTE) = lower(p_codice_utente)
                 And CODICE_RUOLO = 4
                 And r.CODICE_UT = '-1'
             Union
              Select u.CODICE_DTP, CODICE_TIPO_DEPOSITARIO, SIGLA_TIPO_DEPOSITARIO
                From Rinf_Sicurezza_Evo.V_UTENTE_RUOLO r,
                     Rinf_Anagrafiche_Evo.ANAG_UT u
               Where lower(CODICE_UTENTE) = lower(p_codice_utente)
                 And r.CODICE_UT = u.CODICE_UT
             And CODICE_RUOLO=4
             And r.CODICE_UT<>'-1'
			 ) p
           Where CODICE_CONTROLLO = p_codice_controllo
             And c.SIGLA_TIPO_DEPOSITARIO = P.SIGLA_TIPO_DEPOSITARIO
             And c.CODICE_DTP = Decode(p.CODICE_DTP, '-1', c.CODICE_DTP, p.CODICE_DTP)
        Order by c.CODICE_DTP, c.TIPO_OGGETTO, c.CODICE_SOL_PO;
   End If;
--         NOTA: codice_tipo_depositario = -1 è l'amministratore
--         CODICE_DTP = -1 l'utente vede l'intero territorio
  END GetDetailOfControl;
