-- ------------------------------------------------------------------------------------------------   
--                         FUNCTION GetIsNumber
-- ------------------------------------------------------------------------------------------------   
--
 Function GetIsNumber(stringa Varchar2) 
   RETURN Number  Is
   numero Number;
--    1: numerico, 0: stringa
 BEGIN
   Select To_Number(stringa) Into numero From Dual;
   RETURN 1;
--   
 EXCEPTION
     When NO_DATA_FOUND Then
       Null;
     When OTHERS Then
       RETURN 0;
 END GetIsNumber;
--
-- ------------------------------------------------------------------------------------------------   
--                        FUNCTION GetTranslateCondition
-- ------------------------------------------------------------------------------------------------   
--
  Function GetTranslateCondition(filter_type In Varchar2, filter_value In Varchar2, flag_numeric_column In Number, flag_numeric_value In Number)
    RETURN Varchar2  Is
        stringa_Where Varchar2(1000);
    BEGIN

    Select
      Case
        When filter_type='Contains'             Then ' LIKE ''%'||Upper(filter_value)||'%'''
        When filter_type='EndsWith'             Then ' LIKE ''%'||Upper(filter_value)||''''
        When filter_type='StartsWith'           Then ' LIKE '''||Upper(filter_value)||'%'''
        When filter_type='Equals'               And (flag_numeric_column=1 And flag_numeric_value=1) Then  '='||filter_value
        When filter_type='Equals'               And NOT (flag_numeric_column=1 And flag_numeric_value=1) Then '='''||Upper(filter_value)||''''
        When filter_type='GreaterThan'          And (flag_numeric_column=1 And flag_numeric_value=1)       Then '>'||filter_value
        When filter_type='GreaterThan'          And NOT (flag_numeric_column=1 And flag_numeric_value=1)       Then '>'''||Upper(filter_value)||''''
        When filter_type='GreaterThanOrEqual'   And (flag_numeric_column=1 And flag_numeric_value=1) Then '>='||filter_value
        When filter_type='GreaterThanOrEqual'   And NOT (flag_numeric_column=1 And flag_numeric_value=1) Then '>='''||Upper(filter_value)||''''
        When filter_type='LessThan'             And  (flag_numeric_column=1 And flag_numeric_value=1) Then '<'||filter_value
        When filter_type='LessThan'             And NOT (flag_numeric_column=1 And flag_numeric_value=1) Then '<'''||Upper(filter_value)||''''
        When filter_type='LessThanOrEqual'      And (flag_numeric_column=1 And flag_numeric_value=1) Then '<='||filter_value
        When filter_type='LessThanOrEqual'      And NOT (flag_numeric_column=1 And flag_numeric_value=1) Then '<='''||Upper(filter_value)||''''
        When filter_type='NotContains'          Then ' NOT LIKE ''%'||Upper(filter_value)||'%'''
        When filter_type='NotEquals'            And (flag_numeric_column=1 And flag_numeric_value=1) Then '<>'||filter_value
        When filter_type='NotEquals'            And NOT (flag_numeric_column=1 And flag_numeric_value=1) Then '<>'''||Upper(filter_value)||''''
        When filter_type='True'                 Then '=''1'''
        When filter_type='False'                Then '=''0'''
      End
        Into stringa_Where From Dual;
        RETURN stringa_Where ;
--
  END GetTranslateCondition;
--
-- ------------------------------------------------------------------------------------------------   
--                          FUNCTION GetWhereString
-- ------------------------------------------------------------------------------------------------   
--
 Function GetWhereString (column_to_filter In  Varchar2,
                           filter_type     In  Varchar2,
						   filter_value    In  Varchar2,
                           numeric_column_list Varchar2 )
   RETURN Varchar2   Is
      c_lista_Where sys_refcursor;
      stringa_Where Varchar2(30000);
      flag_colonna_numerica Number;     --0 no, 1 si
      flag_valore_numerico Number;      --0 no, 1 si
      TYPE terna_Where_rt IS RECORD
        ( Where_column       Varchar2(200),
          Where_filter       Varchar2(200),
          Where_value        Varchar2(1000)  );
      R_LISTA_WHERE    terna_Where_rt;
  BEGIN
--   
   Open c_lista_Where For
   With test As
    ( Select column_to_filter str_column, filter_type str_type, filter_value str_value  From Dual  )
    Select regexp_Substr(str_column, '[^;]+', 1, rownum) split, 
	       regexp_Substr(str_type,   '[^;]+', 1, rownum) split2,
	       regexp_Substr(str_value,  '[^;]+', 1, rownum) split3
      From test
    connect by level <= length (regexp_replace (str_column, '[^;]+'))  + 1;
    stringa_Where := ' ';
    Loop 
        Fetch c_lista_Where Into r_lista_Where;
        Exit When c_lista_Where %NOTFOUND;

-- Verifico che la colonna del filtro sia  numerica 1=si, 0=no
        Select Least(Instr(numeric_column_list, r_lista_Where.Where_column), 1) into flag_colonna_numerica From Dual;
-- Verifico che il valore da filtrare sia numerico
        flag_valore_numerico := GetIsNumber(r_lista_Where.Where_value);

-- 20/02/2017   inserito l'alias c.per superaro il problema della colonna ambigua
        stringa_Where := stringa_Where || ' Upper(c.' || r_lista_Where.Where_column|| ')' ||
		                                 GetTranslateCondition(r_lista_Where.Where_filter, r_lista_Where.Where_value, flag_colonna_numerica, flag_valore_numerico);
        stringa_Where := stringa_Where ||' And ';
    End Loop ;
--	
    stringa_Where := Substr(stringa_Where, 1, Length(stringa_Where )-5); 
    Dbms_Output.Put_Line(stringa_Where );
    RETURN stringa_Where ;
   END GetWhereString;
--
-- ------------------------------------------------------------------------------------------------   
--                      PROCEDURE GetDetailOfControl_Paging
-- Procedura che effettua il paging della maschera "visualizza rapporto"
-- restituisce le righe comprese tra n_star e n_end, se questi valori sono uguali a -1, restituisce l'intero recordset
-- nel parametro n_total restituisce il totale dei record che verificano la condizione di Where 
-- ------------------------------------------------------------------------------------------------   

 Procedure GetDetailOfControl_Paging (n_controllo        In     Number,
                                      column_to_filter   In     Varchar2,
                                      filter_type        In     Varchar2,
                                      filter_value       In     Varchar2,
                                      colonna_order      In     Varchar2,
                                      tipo_order         In     Varchar2,
                                      n_start            In     Number,
                                      n_end              In     Number,
                                      p_codice_utente    In     Varchar2,
                                      p_id_contesto      In     Number,
                                      p_val_contesto     In     Varchar2,
                                      n_total            Out    Number,
                                      p_cursor           Out    empcur )  Is
   sqlstringa             Varchar2 (32767);
   sqlstringa_conta       Varchar2 (32767);
   sqlstringa_record      Varchar2 (32767);
   sqlstringa_Where       Varchar2 (32767);
   sqlstringa_contesto    Varchar2 (32767);
   column_to_filter_new   Varchar2 (10000);
   filter_type_new        Varchar2 (10000);
   filter_value_new       Varchar2 (10000);
   n_ruolo                Number;
   c_conta                empcur;
   s_campi_numerici       Varchar2 (10000);
 BEGIN
   s_campi_numerici := 'CODICE_CONTROLLO, CODICE_ESITO, ERRORI_GEN, ERRORI_INF, ERRORI_ENE, ERRORI_CCS, TOTALE_ERRORI';

   Select Min(CODICE_RUOLO) into n_ruolo From Rinf_Sicurezza_Evo.UTENTE_RUOLI
    Where ID_UTENTE = PKG_RINF_SICUREZZA.GETUSERID(p_codice_utente);
--
   column_to_filter_new := Replace(column_to_filter, ';;', '; ;');
   filter_type_new := Replace(filter_type, ';;', '; ;');
   filter_value_new := Replace(filter_value, ';;', '; ;');
--   
   sqlstringa_record:='Select *  From ( ';
   sqlstringa_conta:='Select count(*) n_righe  From ( ';
 --  
   If  column_to_filter_new Is Not Null Then
       sqlstringa_Where := GetWhereString(column_to_filter_new, filter_type_new, filter_value_new, s_campi_numerici);
   Else
       sqlstringa_Where :='';
   End If;
--
   If  p_id_contesto Is Not Null Then
       sqlstringa_contesto:= ' And c.CODICE_SOL_PO In (Select SEDE_TECNICA From  Rinf_Lavorazione_Evo.V_MDR_CONTESTO_GEOGRAFICO ';
       sqlstringa_contesto:= sqlstringa_contesto||'Where  CODICE_CONTESTO='||p_id_contesto||'  And ';
       sqlstringa_contesto:= sqlstringa_contesto||' CODICE='''||p_val_contesto||''' And ';
       sqlstringa_contesto:= sqlstringa_contesto||' CODICE_CONTROLLO='||n_controllo||') ';
   Else
       sqlstringa_contesto:= '';
   End If;
--
   sqlstringa := ' Select CODICE_CONTROLLO,';
   sqlstringa := sqlstringa||' CODICE_DTP,             ';
   sqlstringa := sqlstringa||' DTP,                    ';
   sqlstringa := sqlstringa||' TIPO_OGGETTO,           ';
   sqlstringa := sqlstringa||' CODICE_SOL_PO,          ';
   sqlstringa := sqlstringa||' DESCRIZIONE,            ';
   sqlstringa := sqlstringa||' CODICE_XML,             ';
   sqlstringa := sqlstringa||' CODICE_ESITO,           ';
   sqlstringa := sqlstringa||' ESITO,                  ';
   sqlstringa := sqlstringa||' ERRORI_GEN,             ';
   sqlstringa := sqlstringa||' ERRORI_INF,             ';
   sqlstringa := sqlstringa||' ERRORI_ENE,             ';
   sqlstringa := sqlstringa||' ERRORI_CCS,             ';
   sqlstringa := sqlstringa||' TOTALE_ERRORI,          ';
   sqlstringa := sqlstringa||' row_Number() over        ';
   sqlstringa := sqlstringa||'(Order by '||colonna_order||' '||tipo_order||') rn ';
   sqlstringa := sqlstringa||' From (Select  c.CODICE_CONTROLLO,';
   sqlstringa := sqlstringa||' c.CODICE_DTP,                    ';
   sqlstringa := sqlstringa||' c.DTP,                           ';
   sqlstringa := sqlstringa||' c.TIPO_OGGETTO,                  ';
   sqlstringa := sqlstringa||' c.CODICE_SOL_PO,                 ';
   sqlstringa := sqlstringa||' c.DESCRIZIONE,                   ';
   sqlstringa := sqlstringa||' c.CODICE_XML,                    ';
   sqlstringa := sqlstringa||' c.CODICE_ESITO,                  ';
   sqlstringa := sqlstringa||' c.ESITO,                         ';
   sqlstringa := sqlstringa||' SUM(NVL(c.ERRORI_GEN,0)) ERRORI_GEN,';
   sqlstringa := sqlstringa||' SUM(NVL(c.ERRORI_INF,0)) ERRORI_INF,';
   sqlstringa := sqlstringa||' SUM(NVL(c.ERRORI_ENE,0)) ERRORI_ENE,';
   sqlstringa := sqlstringa||' SUM(NVL(c.ERRORI_CCS,0)) ERRORI_CCS,';
   sqlstringa := sqlstringa||' SUM(NVL(c.TOTALE_ERRORI,0)) TOTALE_ERRORI';

   If n_ruolo = 1 Then
       sqlstringa := sqlstringa||' From  Rinf_Lavorazione_Evo.SINTESI_RAPPORTO_CONTROLLI c    ';
       sqlstringa := sqlstringa||'Where  CODICE_CONTROLLO='||n_controllo;
       --sqlstringa := sqlstringa||sqlstringa_Where ;
       sqlstringa := sqlstringa||sqlstringa_contesto;
   Else
       sqlstringa := sqlstringa||' From  Rinf_Lavorazione_Evo.SINTESI_RAPPORTO_CONTROLLI c,                ';
       sqlstringa := sqlstringa||' (Select CODICE_DTP, CODICE_TIPO_DEPOSITARIO,SIGLA_TIPO_DEPOSITARIO   ';
       sqlstringa := sqlstringa||' From  RINF_SICUREZZA_EVO.V_UTENTE_RUOLO r                                 ';
       sqlstringa := sqlstringa||' Where lower(CODICE_UTENTE)=lower('''||p_codice_utente||''') ';
       sqlstringa := sqlstringa||' And CODICE_RUOLO=5                                                   ';
       sqlstringa := sqlstringa||' Union                                                                ';
       sqlstringa := sqlstringa||' Select CODICE_DTP, CODICE_TIPO_DEPOSITARIO,SIGLA_TIPO_DEPOSITARIO    ';
       sqlstringa := sqlstringa||' From  RINF_SICUREZZA_EVO.V_UTENTE_RUOLO r                                 ';
       sqlstringa := sqlstringa||' Where lower(CODICE_UTENTE)=lower('''||p_codice_utente||''') ';
       sqlstringa := sqlstringa||' And CODICE_RUOLO=4                                                   ';
       sqlstringa := sqlstringa||' And r.CODICE_UT=''-1'' ) p                                                ';
       sqlstringa := sqlstringa||' Where  CODICE_CONTROLLO='||n_controllo;
       sqlstringa := sqlstringa|| sqlstringa_contesto;
       sqlstringa := sqlstringa||' And  c.SIGLA_TIPO_DEPOSITARIO=P.SIGLA_TIPO_DEPOSITARIO               ';
       sqlstringa := sqlstringa||' And c.CODICE_DTP=Decode(p.CODICE_DTP,''-1'',c.CODICE_DTP,p.CODICE_DTP) ';
       sqlstringa := sqlstringa||' group by c.CODICE_CONTROLLO,                                         ';
       sqlstringa := sqlstringa||' c.CODICE_DTP,                                                        ';
       sqlstringa := sqlstringa||' c.DTP,                                                               ';
       sqlstringa := sqlstringa||' c.TIPO_OGGETTO,                                                      ';
       sqlstringa := sqlstringa||' c.CODICE_SOL_PO,                                                     ';
       sqlstringa := sqlstringa||' c.DESCRIZIONE,                                                       ';
       sqlstringa := sqlstringa||' c.CODICE_XML,                                                        ';
       sqlstringa := sqlstringa||' c.CODICE_ESITO,                                                      ';
       sqlstringa := sqlstringa||' c.ESITO                                                            ';
       sqlstringa := sqlstringa||' Union                                                            ';
       sqlstringa := sqlstringa||' Select  c.CODICE_CONTROLLO,';
       sqlstringa := sqlstringa||' c.CODICE_DTP,                    ';
       sqlstringa := sqlstringa||' c.DTP,                           ';
       sqlstringa := sqlstringa||' c.TIPO_OGGETTO,                  ';
       sqlstringa := sqlstringa||' c.CODICE_SOL_PO,                 ';
       sqlstringa := sqlstringa||' c.DESCRIZIONE,                   ';
       sqlstringa := sqlstringa||' c.CODICE_XML,                    ';
       sqlstringa := sqlstringa||' c.CODICE_ESITO,                  ';
       sqlstringa := sqlstringa||' c.ESITO,                         ';
       sqlstringa := sqlstringa||' SUM(NVL(c.ERRORI_GEN,0)) ERRORI_GEN,';
       sqlstringa := sqlstringa||' SUM(NVL(c.ERRORI_INF,0)) ERRORI_INF,';
       sqlstringa := sqlstringa||' SUM(NVL(c.ERRORI_ENE,0)) ERRORI_ENE,';
       sqlstringa := sqlstringa||' SUM(NVL(c.ERRORI_CCS,0)) ERRORI_CCS,';
       sqlstringa := sqlstringa||' SUM(NVL(c.TOTALE_ERRORI,0)) TOTALE_ERRORI';
       sqlstringa := sqlstringa||' From  Rinf_Lavorazione_Evo.SINTESI_RAPPORTO_CONTROLLI c,                ';
       sqlstringa := sqlstringa||' (Select CODICE_UT, CODICE_TIPO_DEPOSITARIO,SIGLA_TIPO_DEPOSITARIO    ';
       sqlstringa := sqlstringa||' From  RINF_SICUREZZA_EVO.V_UTENTE_RUOLO r                                 ';
       sqlstringa := sqlstringa||' Where lower(CODICE_UTENTE)=lower('''||p_codice_utente||''') ';
       sqlstringa := sqlstringa||' And CODICE_RUOLO=4                                                   ';
       sqlstringa := sqlstringa||' And r.CODICE_UT<>''-1'' ) p,                                                ';
       sqlstringa := sqlstringa||'(Select CODICE_UT, SEDE_TECNICA From  Rinf_Lavorazione_Evo.SEZIONI_LINEA ';
       sqlstringa := sqlstringa||' Union ';
       sqlstringa := sqlstringa||' Select CODICE_UT, SEDE_TECNICA From  Rinf_Lavorazione_Evo.PUNTI_OPERATIVI) ut ';
       sqlstringa := sqlstringa||' Where     CODICE_CONTROLLO = '||n_controllo;
       sqlstringa := sqlstringa||' And c.SIGLA_TIPO_DEPOSITARIO = P.SIGLA_TIPO_DEPOSITARIO ';
       sqlstringa := sqlstringa||' And ut.CODICE_UT = p.CODICE_UT ';
       sqlstringa := sqlstringa||' And ut.SEDE_TECNICA = C.CODICE_SOL_PO ';

   End If;
   sqlstringa := sqlstringa||' GROUP BY c.CODICE_CONTROLLO, ';
   sqlstringa := sqlstringa||' c.CODICE_DTP, ';
   sqlstringa := sqlstringa||' c.DTP, ';
   sqlstringa := sqlstringa||' c.TIPO_OGGETTO, ';
   sqlstringa := sqlstringa||' c.CODICE_SOL_PO, ';
   sqlstringa := sqlstringa||' c.DESCRIZIONE, ';
   sqlstringa := sqlstringa||' c.CODICE_XML, ';
   sqlstringa := sqlstringa||' c.CODICE_ESITO, ';
   sqlstringa := sqlstringa||' c.ESITO) c';
   If column_to_filter_new Is Not Null Then
       sqlstringa := sqlstringa||' Where '||sqlstringa_Where ;
   End If;
   sqlstringa := sqlstringa||')';
 ----------conteggio record
   sqlstringa_conta := sqlstringa_conta||sqlstringa; --per restituire il totale delle righe

   If n_start <> -1 And n_end <> -1 Then
       sqlstringa := sqlstringa||' Where rn between '||n_start ||' And '||n_end;
   End If;
   sqlstringa := sqlstringa||' Order by rn';
   sqlstringa_record := sqlstringa_record||sqlstringa;

   Dbms_Output.Put_Line(sqlstringa_record);
-- Dbms_Output.Put_Line(sqlstringa_conta);
--
   Open c_conta For sqlstringa_conta;
   Fetch c_conta Into n_total;
   Close c_conta;
--
   Open p_cursor For sqlstringa_record;
 END GetDetailOfControl_Paging;
--
-- ------------------------------------------------------------------------------------------------   
--                     PROCEDURE GetControlDetailsReport
--  Procedura che effettua il paging della maschera "visualizza rapporto"
--  restituisce le righe comprese tra n_star e n_end, se questi vaolri sono uguali a -1, restituisce l'intero recordset
--  nel parametro n_total restituisce il totale dei record che verificano la condizione di Where 

-- ------------------------------------------------------------------------------------------------   
--
 Procedure GetControlDetailsReport (n_controllo        In     Number,
                                    column_to_filter   In     Varchar2,
                                    filter_type        In     Varchar2,
                                    filter_value       In     Varchar2,
                                    colonna_order      In     Varchar2,
                                    tipo_order         In     Varchar2,
                                    n_start            In     Number,
                                    n_end              In     Number,
                                    p_codice_utente    In     Varchar2,
                                    p_id_contesto      In     Number,
                                    p_val_contesto     In     Varchar2,
                                    n_total            Out    Number,
                                    p_cursor           Out    empcur )   Is
   sqlstringa             Varchar2 (32767);
   sqlstringa_conta       Varchar2 (32767);
   sqlstringa_record      Varchar2 (32767);
   sqlstringa_contesto    Varchar2 (32767);
   column_to_filter_new   Varchar2 (10000);
   filter_type_new        Varchar2 (10000);
   filter_value_new       Varchar2 (10000);
   n_ruolo                Number;
   c_conta                empcur;
   s_campi_numerici       Varchar2 (10000);
  BEGIN
--
    s_campi_numerici:='CODICE_CONTROLLO, CODICE_PARAMETRO, CODICE_ESITO, CODICE_TIPO_CONTROLLO, ESITO_CONTROLLO';
--
    Select Min(CODICE_RUOLO) Into n_ruolo From Rinf_Sicurezza_Evo.UTENTE_RUOLI
     Where ID_UTENTE = PKG_RINF_SICUREZZA.GETUSERID(p_codice_utente);

    column_to_filter_new := Replace(column_to_filter, ';;', '; ;');
    filter_type_new := Replace(filter_type, ';;', '; ;');
    filter_value_new := Replace(filter_value, ';;', '; ;');
--    
    sqlstringa_conta := 'Select count(*) n_righe  From ( ';
--    
    If p_id_contesto Is Not Null Then
        sqlstringa_contesto := ' And c.CODICE_SOL_PO In (Select SEDE_TECNICA From  Rinf_Lavorazione_Evo.V_MDR_CONTESTO_GEOGRAFICO ';
        sqlstringa_contesto := sqlstringa_contesto||'Where  CODICE_CONTESTO='||p_id_contesto||'  And ';
        sqlstringa_contesto := sqlstringa_contesto||' CODICE='''||p_val_contesto||''' And ';
        sqlstringa_contesto := sqlstringa_contesto||' CODICE_CONTROLLO='||n_controllo||') ';
    Else
        sqlstringa_contesto := '';
    End If;
--    
    sqlstringa_record := 'Select *  From ( ';
    sqlstringa := sqlstringa||'Select c.CODICE_CONTROLLO,';
    sqlstringa := sqlstringa||'c.CODICE_DTP,             ';
    sqlstringa := sqlstringa||'c.NOME_DTP,               ';
    sqlstringa := sqlstringa||'c.CODICE_UT,             ';
    sqlstringa := sqlstringa||'c.CODICE_SOL_PO,          ';
    sqlstringa := sqlstringa||'c.NOME_SOL_OP,            ';
    sqlstringa := sqlstringa||'c.CODICE_ERA,             ';
    sqlstringa := sqlstringa||'c.SEDE_TECNICA,           ';
    sqlstringa := sqlstringa||'c.NOME_SEDE_TECNICA,      ';
    sqlstringa := sqlstringa||'c.CODICE_PARAMETRO,       ';
    sqlstringa := sqlstringa||'c.NUMERO_PARAMETRO,       ';
    sqlstringa := sqlstringa||'c.DEFINIZIONE_PARAMETRO,  ';
    sqlstringa := sqlstringa||'c.SIGLA_VISTA,            ';
    sqlstringa := sqlstringa||'c.CODICE_ESITO,           ';
    sqlstringa := sqlstringa||'c.ESITO_CONTROLLO,                  ';
    sqlstringa := sqlstringa||'c.CODICE_TIPO_CONTROLLO,  ';
    sqlstringa := sqlstringa||'c.DEFINIZIONE_TIPO_CONTROLLO,';
    sqlstringa := sqlstringa||'c.DESCRIZIONE_ESITO,';
    sqlstringa := sqlstringa||'c.VALORE_NUOVO, ';
    sqlstringa := sqlstringa||'c.DATA_CONTROLLO_NUOVO,        ';
    sqlstringa := sqlstringa||'c.DATA_ACQUISIZIONE_NUOVO,     ';
    sqlstringa := sqlstringa||'c.VALORE_PRECEDENTE,           ';
    sqlstringa := sqlstringa||'c.DATA_CONTROLLO_PRECEDENTE,   ';
    sqlstringa := sqlstringa||'c.DATA_ACQUISIZIONE_PRECEDENTE,';
    sqlstringa := sqlstringa||'c.SIGLA_TIPO_DEPOSITARIO,';
    sqlstringa := sqlstringa||'c.TIPO_DEPOSITARIO,      ';
    sqlstringa := sqlstringa||'row_Number() over        ';
    sqlstringa := sqlstringa||'(Order by '||colonna_order||' '||tipo_order||') rn ';
--    
    If n_ruolo = 1 Then
        sqlstringa := sqlstringa||'From  Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI c               ';
        sqlstringa := sqlstringa||'Where  CODICE_CONTROLLO='||n_controllo;
    Else
        sqlstringa := sqlstringa||'From  Rinf_Lavorazione_Evo.RAPPORTO_CONTROLLI c,               ';
        sqlstringa := sqlstringa||' (Select u.CODICE_DTP, u.CODICE_UT,CODICE_PARAMETRO';
        sqlstringa := sqlstringa||' From  RINF_SICUREZZA_EVO.V_UTENTE_RUOLO r,             ';
        sqlstringa := sqlstringa||' RINF_ANAGRAFICHE_EVO.ANAG_UT u,                  ';
        sqlstringa := sqlstringa||' RINF_ANAGRAFICHE_EVO.CATALOGO_PARAMETRI c        ';
        sqlstringa := sqlstringa||' Where lower(CODICE_UTENTE)=lower('''||p_codice_utente||''') ';
        sqlstringa := sqlstringa||' And R.CODICE_UT=U.CODICE_UT ';
        sqlstringa := sqlstringa||' And R.CODICE_UT<>''-1'' ';
        sqlstringa := sqlstringa||' And CODICE_RUOLO=4          ';
        sqlstringa := sqlstringa||' And c.CODICE_TIPO_DEPOSITARIO=r.CODICE_TIPO_DEPOSITARIO ';
        sqlstringa := sqlstringa||' Union ';
        sqlstringa := sqlstringa||' Select r.CODICE_DTP, r.CODICE_UT,CODICE_PARAMETRO';
        sqlstringa := sqlstringa||' From  RINF_SICUREZZA_EVO.V_UTENTE_RUOLO r,             ';
        sqlstringa := sqlstringa||' RINF_ANAGRAFICHE_EVO.CATALOGO_PARAMETRI c        ';
        sqlstringa := sqlstringa||' Where lower(CODICE_UTENTE)=lower('''||p_codice_utente||''') ';
        sqlstringa := sqlstringa||' And R.CODICE_UT=''-1'' ';
        sqlstringa := sqlstringa||' And CODICE_RUOLO=4          ';
        sqlstringa := sqlstringa||' And c.CODICE_TIPO_DEPOSITARIO=r.CODICE_TIPO_DEPOSITARIO ';
        sqlstringa := sqlstringa||' Union ';
        sqlstringa := sqlstringa||' Select CODICE_DTP, CODICE_UT, CODICE_PARAMETRO';
        sqlstringa := sqlstringa||' From  RINF_SICUREZZA_EVO.V_UTENTE_RUOLO r,         ';
        sqlstringa := sqlstringa||' RINF_ANAGRAFICHE_EVO.CATALOGO_PARAMETRI c    ';
        sqlstringa := sqlstringa||' Where lower(CODICE_UTENTE)=lower('''||p_codice_utente||''') ';
        sqlstringa := sqlstringa||' And CODICE_RUOLO=5 ';
        sqlstringa := sqlstringa||' And c.CODICE_TIPO_DEPOSITARIO=r.CODICE_TIPO_DEPOSITARIO) p, ';
        sqlstringa := sqlstringa||'(Select CODICE_UT, SEDE_TECNICA ';
        sqlstringa := sqlstringa||' From  Rinf_Lavorazione_Evo.SEZIONI_LINEA   ';
        sqlstringa := sqlstringa||' Union ';
        sqlstringa := sqlstringa||' Select CODICE_UT, SEDE_TECNICA ';
        sqlstringa := sqlstringa||' From  Rinf_Lavorazione_Evo.PUNTI_OPERATIVI) ut ';
        sqlstringa := sqlstringa||'Where  CODICE_CONTROLLO='||n_controllo;
        sqlstringa := sqlstringa||' And  c.CODICE_PARAMETRO=P.CODICE_PARAMETRO  ';
        sqlstringa := sqlstringa||' And UT.SEDE_TECNICA=C.CODICE_SOL_PO ';
        sqlstringa := sqlstringa||' And c.CODICE_DTP=Decode(p.CODICE_DTP,''-1'',c.CODICE_DTP,p.CODICE_DTP)';
        sqlstringa := sqlstringa||' And ut.CODICE_UT =DECODE (p.CODICE_UT,''-1'',ut.CODICE_UT, p.CODICE_UT)';
    End If;

    If column_to_filter_new Is Not Null Then
        sqlstringa := sqlstringa||' And '||GetWhereString(column_to_filter_new, filter_type_new, filter_value_new, s_campi_numerici);
    End If;
    sqlstringa := sqlstringa|| sqlstringa_contesto;
    sqlstringa := sqlstringa||') ';
-- ----------conteggio record
    sqlstringa_conta := sqlstringa_conta||sqlstringa;           -- per restituire il totale delle righe
--   
    If n_start <> -1 And n_end <> -1 Then                       -- Deve restituire solo un sottinsieme di righe
        sqlstringa:=sqlstringa||'Where rn between '||n_start ||' And '||n_end;
    End If;
    sqlstringa := sqlstringa||' Order by rn';
    sqlstringa_record := sqlstringa_record||sqlstringa;
--    
    Dbms_Output.Put_Line(sqlstringa_record);
    Dbms_Output.Put_Line('GetWhereString('||column_to_filter_new||','||filter_type_new||','||filter_value_new||','||s_campi_numerici);
--  Dbms_Output.Put_Line(sqlstringa_conta);
--    
    Open c_conta For sqlstringa_conta;
    Fetch c_conta Into n_total;
    Close c_conta;
--
    Open p_cursor For sqlstringa_record;
--
 END GetControlDetailsReport;
--
-- ------------------------------------------------------------------------------------------------   
--   PROCEDURE GetControlReportDetailsFailed --> adeguata con la data di validità del parametro
-- ------------------------------------------------------------------------------------------------   
--
 Procedure GetControlReportDetailsFailed (
                                            p_codice_controllo   In     Number,
                                            p_codice_utente      In     Varchar2,
                                            p_cursor             Out    empcur )   Is
      n_ruolo Number;
   BEGIN
--
   Select Min(CODICE_RUOLO) Into n_ruolo From  RINF_SICUREZZA_EVO.UTENTE_RUOLI
   Where ID_UTENTE = PKG_RINF_SICUREZZA.GETUSERID(p_codice_utente);
--
   If n_ruolo=1 Then
    Open p_cursor For
           Select c.CODICE_CONTROLLO,
                  c.CODICE_DTP,
                  c.NOME_DTP,
                  c.CODICE_SOL_PO,
                  c.NOME_SOL_OP,
                  c.CODICE_ERA,
                  c.SEDE_TECNICA,
                  c.NOME_SEDE_TECNICA,
                  c.CODICE_PARAMETRO,
                  c.NUMERO_PARAMETRO,
                  c.DEFINIZIONE_PARAMETRO,
                  c.SIGLA_VISTA,
                  c.CODICE_ESITO,
                  c.ESITO,
                  c.CODICE_TIPO_CONTROLLO,
                  c.DEFINIZIONE_TIPO_CONTROLLO,
                  c.ANOMALIA,
                  c.VALORE_ERRATO,
                  c.DATA_CONTROLLO_ERRATO,
                  c.DATA_ACQUISIZIONE_ERRATO,
                  c.VALORE_CORRETTO,
                  c.DATA_CONTROLLO_CORRETTO,
                  c.DATA_ACQUISIZIONE_CORRETTO,
                  c.SIGLA_TIPO_DEPOSITARIO,
                  c.TIPO_DEPOSITARIO
             From V_DETT_CONTROLLI_FALLITI_V082 c
            Where CODICE_CONTROLLO = p_codice_controllo
         Order by c.CODICE_DTP, c.CODICE_SOL_PO, c.NUMERO_PARAMETRO;
    Else
      Open p_cursor For
           Select Distinct
                  c.CODICE_CONTROLLO,
                  c.CODICE_DTP,
                  c.NOME_DTP,
                  c.CODICE_SOL_PO,
                  c.NOME_SOL_OP,
                  c.CODICE_ERA,
                  c.SEDE_TECNICA,
                  c.NOME_SEDE_TECNICA,
                  c.CODICE_PARAMETRO,
                  c.NUMERO_PARAMETRO,
                  c.DEFINIZIONE_PARAMETRO,
                  c.SIGLA_VISTA,
                  c.CODICE_ESITO,
                  c.ESITO,
                  c.CODICE_TIPO_CONTROLLO,
                  c.DEFINIZIONE_TIPO_CONTROLLO,
                  c.ANOMALIA,
                  c.VALORE_ERRATO,
                  c.DATA_CONTROLLO_ERRATO,
                  c.DATA_ACQUISIZIONE_ERRATO,
                  c.VALORE_CORRETTO,
                  c.DATA_CONTROLLO_CORRETTO,
                  c.DATA_ACQUISIZIONE_CORRETTO,
                  c.SIGLA_TIPO_DEPOSITARIO,
                  c.TIPO_DEPOSITARIO
             From V_DETT_CONTROLLI_FALLITI_V082 c,
             (Select u.CODICE_DTP, u.CODICE_UT, CODICE_PARAMETRO
                From Rinf_Sicurezza_Evo.V_UTENTE_RUOLO r,
                     Rinf_Anagrafiche_Evo.ANAG_UT u,
                     Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI c
               Where Lower(CODICE_UTENTE) = Lower(p_codice_utente)
                 And R.CODICE_UT = u.CODICE_UT
                 And R.CODICE_UT <> '-1'
                 And CODICE_RUOLO = 4
                 And c.CODICE_TIPO_DEPOSITARIO = r.CODICE_TIPO_DEPOSITARIO
              Union
              Select r.CODICE_DTP, r.CODICE_UT, CODICE_PARAMETRO
                From Rinf_Sicurezza_Evo.V_UTENTE_RUOLO r,
                     Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI c
               Where Lower(CODICE_UTENTE) = Lower(p_codice_utente)
                 And r.CODICE_UT = '-1'
                 And CODICE_RUOLO = 4
                 And c.CODICE_TIPO_DEPOSITARIO = r.CODICE_TIPO_DEPOSITARIO
              Union
               Select CODICE_DTP, CODICE_UT, CODICE_PARAMETRO
                 From Rinf_Sicurezza_Evo.V_UTENTE_RUOLO r,
                      Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI c
                Where Lower(CODICE_UTENTE) = Lower(p_codice_utente)
                  And CODICE_RUOLO = 5
                  And c.CODICE_TIPO_DEPOSITARIO = r.CODICE_TIPO_DEPOSITARIO
			   ) p
              Where CODICE_CONTROLLO = p_codice_controllo
                And c.CODICE_PARAMETRO=P.CODICE_PARAMETRO
                And c.CODICE_DTP = Decode(p.CODICE_DTP, '-1', c.CODICE_DTP, p.CODICE_DTP)
           Order by c.CODICE_DTP, c.CODICE_SOL_PO, c.NUMERO_PARAMETRO;
    End If;
--
   END GetControlReportDetailsFailed;
