-- ------------------------------------------------------------------------------------------------   
--      PROCEDURE GetControlReptDetDTPSucceded --> adeguata con la data di validità del parametro
-- ------------------------------------------------------------------------------------------------   
--
 Procedure GetControlReptDetDTPSucceded (
                                          p_codice_controllo   In     Number,
                                          p_codice_utente      In     Varchar2,
                                          p_cursor             Out    empcur )   Is
   n_ruolo Number;
   BEGIN
--
   Select Min(CODICE_RUOLO) Into n_ruolo From  RINF_SICUREZZA_EVO.UTENTE_RUOLI
    Where ID_UTENTE = PKG_RINF_SICUREZZA.GETUSERID(p_codice_utente);
--	
    If n_ruolo=1 Then
       Open p_cursor For
           Select c.CODICE_CONTROLLO,
                  c.CODICE_DTP,
                  c.NOME_DTP,
                  c.CODICE_SOL_PO,
                  c.NOME_SOL_OP,
                  c.CODICE_ERA,
                  c.SEDE_TECNICA,
                  c.NOME_SEDE_TECNICA,
                  c.CODICE_PARAMETRO,
                  c.NUMERO_PARAMETRO,
                  c.DEFINIZIONE_PARAMETRO,
                  c.SIGLA_VISTA,
                  c.CODICE_ESITO,
                  c.ESITO,
                  c.CODICE_TIPO_CONTROLLO,
                  c.DEFINIZIONE_TIPO_CONTROLLO,
                  c.DEFINIZIONE_TIPO_CONTROLLO ANOMALIA,
                  c.VALORE_NUOVO,
                  c.DATA_CONTROLLO_NUOVO,
                  c.DATA_ACQUISIZIONE_NUOVO,
                  c.VALORE_PRECEDENTE,
                  c.DATA_CONTROLLO_PRECEDENTE,
                  c.DATA_ACQUISIZIONE_PRECEDENTE,
                  c.SIGLA_TIPO_DEPOSITARIO,
                  c.TIPO_DEPOSITARIO
             From V_DETT_CONTROLLI_SUPERATI_V082 c
            Where CODICE_CONTROLLO = p_codice_controllo
         Order by c.CODICE_DTP, c.CODICE_SOL_PO, c.NUMERO_PARAMETRO;
   Else
      Open p_cursor For
           Select Distinct
                  c.CODICE_CONTROLLO,
                  c.CODICE_DTP,
                  c.NOME_DTP,
                  c.CODICE_SOL_PO,
                  c.NOME_SOL_OP,
                  c.CODICE_ERA,
                  c.SEDE_TECNICA,
                  c.NOME_SEDE_TECNICA,
                  c.CODICE_PARAMETRO,
                  c.NUMERO_PARAMETRO,
                  c.DEFINIZIONE_PARAMETRO,
                  c.SIGLA_VISTA,
                  c.CODICE_ESITO,
                  c.ESITO,
                  c.CODICE_TIPO_CONTROLLO,
                  c.DEFINIZIONE_TIPO_CONTROLLO,
                  c.DEFINIZIONE_TIPO_CONTROLLO ANOMALIA,
                  c.VALORE_NUOVO,
                  c.DATA_CONTROLLO_NUOVO,
                  c.DATA_ACQUISIZIONE_NUOVO,
                  c.VALORE_PRECEDENTE,
                  c.DATA_CONTROLLO_PRECEDENTE,
                  c.DATA_ACQUISIZIONE_PRECEDENTE,
                  c.SIGLA_TIPO_DEPOSITARIO,
                  c.TIPO_DEPOSITARIO
             From V_DETT_CONTROLLI_SUPERATI_V082 c,
             (Select u.CODICE_DTP, u.CODICE_UT,CODICE_PARAMETRO
                From Rinf_Sicurezza_Evo.V_UTENTE_RUOLO r,
                     Rinf_Anagrafiche_Evo.ANAG_UT u,
                     Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI c
               Where Lower(CODICE_UTENTE) = Lower(p_codice_utente)
                 And R.CODICE_UT = u.CODICE_UT
                 And R.CODICE_UT <> '-1'
                 And CODICE_RUOLO = 4
                 And c.CODICE_TIPO_DEPOSITARIO = r.CODICE_TIPO_DEPOSITARIO
              Union
               Select r.CODICE_DTP, r.CODICE_UT, CODICE_PARAMETRO
                 From Rinf_Sicurezza_Evo.V_UTENTE_RUOLO r,
                      Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI c
                Where Lower(CODICE_UTENTE) = Lower(p_codice_utente)
                  And R.CODICE_UT = '-1'
                  And CODICE_RUOLO = 4
                  And c.CODICE_TIPO_DEPOSITARIO = r.CODICE_TIPO_DEPOSITARIO
               Union
                Select CODICE_DTP, CODICE_UT, CODICE_PARAMETRO
                  From Rinf_Sicurezza_Evo.V_UTENTE_RUOLO r,
                       Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI c
                 Where Lower(CODICE_UTENTE) = Lower(p_codice_utente)
                   And CODICE_RUOLO = 5
                   And c.CODICE_TIPO_DEPOSITARIO = r.CODICE_TIPO_DEPOSITARIO
			  ) p
            Where CODICE_CONTROLLO = p_codice_controllo
              And c.CODICE_PARAMETRO = P.CODICE_PARAMETRO
              And c.CODICE_DTP = Decode(p.CODICE_DTP, '-1', c.CODICE_DTP, p.CODICE_DTP)
         Order by c.CODICE_DTP, c.CODICE_SOL_PO, c.NUMERO_PARAMETRO;
    End If;
--
   END GetControlReptDetDTPSucceded;

