-- ------------------------------------------------------------------------------------------------   
--                                       FUNCTION GetNYA
--   dice che il parametro è NYA (1) o no (0 = OBBLIGATORIO)
--   E' stata modificata rispetto alla vecchia versione per leggere dalla tabella SINTESI_CONTROLLI
--   per cercare di velocizzare l'operazione di scrittura dall'area di lavorazione all'area controllati
--   Funzione usata solo per i Tunnel, aggiunto Codice_Sol_Po come paramtero di input.
--   Data creazione 10/03/2021 
-- ------------------------------------------------------------------------------------------------   
--
  Function GetNYA_TUNNEL (p_controllo Number, p_parametro Varchar2, P_CodcieSolPo Varchar2, p_Sede_Tecnica Varchar2)    
      RETURN    Number   Is
      n_value   Number;
      n_nya     Number;
   BEGIN
--
      Select NYA into n_nya 
	    From Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI  
	   Where NUMERO_PARAMETRO_MULTIPLO = p_parametro;
--
      Select Nvl(c.NYA, n_nya)
        Into n_value
        From Rinf_Lavorazione_Evo.SINTESI_CONTROLLI d,
             Rinf_Lavorazione_Evo.DETTAGLIO_CONTROLLATI c 
       Where d.CODICE_CONTROLLO = p_controllo 
	     And d.SEDE_TECNICA = p_Sede_Tecnica
	     and d.SEDE_TECNICA = c.SEDE_TECNICA
	     and d.CODICE_CONTROLLO = c.CODICE_CONTROLLO
	     and c.CODICE_PARAMETRO = D.Codice_Parametro
	     and c.CODICE_SOL_PO =  P_CodcieSolPo
		 And NUMERO_PARAMETRO_MULTIPLO = p_parametro;
--
      RETURN n_value;
   EXCEPTION
      When NO_DATA_FOUND Then
      RETURN n_nya;
   END GetNYA_TUNNEL;

END PKG_RINF_CONTROLLO_v082;
/